INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f9c302a9', 'person', 'Marilyn Milos', 'Marilyn Milos is an American nurse and human rights advocate widely recognized as a pioneer of the modern intactivist movement. Her path toward advocacy began during her nursing education in the late 1970s, when witnessing a routine neonatal circumcision prompted her to investigate the ethical, medical, and anatomical aspects of the procedure. Dismayed by the pain experienced by infants and the lack of fully informed consent provided to parents, she dedicated her professional life to raising awareness about the natural function of the foreskin and the principle of bodily integrity.', '', '', 'champion', 'Founder of NOCIRC and pioneer of the modern international genital autonomy movement', 1, '[{"name": "Richard Steiner", "score": 8.82, "shared_docs": 4}, {"name": "Marin General Hospital", "score": 8.82, "shared_docs": 3}, {"name": "Tatiana Bertschinger", "score": 8.82, "shared_docs": 4}, {"name": "Sara Pitta", "score": 8.557, "shared_docs": 5}, {"name": "Van Lewis", "score": 8.498, "shared_docs": 4}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-13eafe79', 'person', 'John Harvey Kellogg', 'John Harvey Kellogg (1852–1943) was an American physician, nutritionist, inventor, and advocate for health reform, best known for his decades-long leadership of the Battle Creek Sanitarium in Michigan. A prominent proponent of ''biological living,'' Kellogg wrote extensively on dietetics, physical culture, and sexual hygiene, heavily infusing Victorian moral philosophy into his medical literature and clinical practices.

Within the history of genital cutting, Kellogg played a key role in popularizing routine infant circumcision in late 19th-century America as a preventative treatment for masturbation. In his influential 1888 work, *Plain Facts for Old and Young*, he argued that self-stimulation was a primary catalyst for physical and mental decline. To suppress sexual desire and prevent masturbation in boys, he advocated for circumcision without anesthesia, reasoning that the painful memory would serve as an effective deterrent. For young women, he similarly recommended applying carbolic acid to the clitoris to suppress arousal.

Kellogg''s writings heavily influenced the American medical establishment''s adoption of non-therapeutic circumcision during the late 19th and early 20th centuries. In contemporary sociological and intactivist discourse, Kellogg is widely cited as a central figure in the pathologization of normal human sexuality and the historical medicalization of routine infant genital alteration in North America.', '', '', 'critic', '19th-century American physician who promoted routine infant circumcision as a medical intervention against masturbation.', 1, '[{"name": "Hillary Clinton", "score": 9.668, "shared_docs": 2}, {"name": "Lewis Sayre", "score": 9.031, "shared_docs": 3}, {"name": "Frederick Hodges", "score": 8.031, "shared_docs": 3}, {"name": "NOCIRC", "score": 7.166, "shared_docs": 4}, {"name": "Royal Dutch Medical Association (KNMG)", "score": 6.931, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e11f9789', 'person', 'Lewis Sayre', 'Lewis Albert Sayre (1820–1900) was a prominent nineteenth-century American orthopedic surgeon, co-founder of Bellevue Hospital Medical College, and president of the American Medical Association. Widely celebrated during his lifetime for his pioneering contributions to trauma surgery and the treatment of spinal deformities, Sayre holds a crucial place in the history of Western medical practice.

In 1870, Sayre published influential clinical observations claiming that phimosis—a condition where the foreskin cannot be fully retracted—was a direct cause of reflex neurosis, partial paralysis, and hip disease in young boys. He hypothesized that physical irritation of the genitals exerted undue stress on the central nervous system, and advocated circumcision as a surgical remedy for a broad array of systemic and neurological ailments.

Sayre''s theories gained significant traction among American and British physicians, serving as a primary catalyst for the medicalization and widespread adoption of routine non-therapeutic infant and childhood circumcision in the English-speaking world. Although subsequent medical consensus rejected the concept of reflex neurosis, Sayre''s historical legacy remains central to understanding the institutional origins of routine neonatal circumcision.', '', '', 'critic', 'Nineteenth-century American surgeon who catalyzed the routine medicalization of circumcision by claiming it cured neurological disorders.', 0, '[{"name": "David Gollaher", "score": 9.768, "shared_docs": 2}, {"name": "Jonathan Hutchinson", "score": 9.446, "shared_docs": 2}, {"name": "John Harvey Kellogg", "score": 9.031, "shared_docs": 3}, {"name": "Sigmund Freud", "score": 8.68, "shared_docs": 2}, {"name": "NOCIRC", "score": 8.265, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f4bece7e', 'person', 'Edgar Schoen', 'Edgar J. Schoen (1925–2016) was an American pediatrician, researcher, and clinical professor of pediatrics at the University of California, San Francisco, who served for decades as the chief of pediatrics at Kaiser Permanente Medical Center in Oakland, California. He achieved national prominence in the late 1980s as the chairman of the American Academy of Pediatrics (AAP) Task Force on Circumcision. Under his leadership, the AAP issued a landmark 1989 policy statement that shifted the medical organization''s previous stance by concluding that routine newborn circumcision possessed demonstrated medical benefits.

Throughout his career, Schoen was one of the most vocal and uncompromising medical advocates for routine infant circumcision in North America. He frequently authored opinion pieces, academic studies, and public commentaries defending the procedure on public health grounds, citing reductions in the risk of urinary tract infections, penile cancer, and sexually transmitted diseases. He openly criticized opposition to circumcision, characterizing intactivist arguments regarding bodily integrity, sexual sensation, and consent as medically unfounded or emotionally driven.

Schoen''s polarized stance rendered him a central figure in the modern circumcision debate. While proponents of infant circumcision viewed him as a pragmatic public health champion, intactivists and bioethicists frequently targeted his work, arguing that his positions minimized the ethics of bodily autonomy and overstated the medical necessity of non-consensual infant genital procedures.', '', '', 'critic', 'Pediatrician and former chair of the AAP Task Force on Circumcision who served as a leading medical advocate for routine infant circumcision.', 1, '[{"name": "Paul Fleiss", "score": 8.253, "shared_docs": 2}, {"name": "Ronald Goldman", "score": 8.116, "shared_docs": 3}, {"name": "American Academy of Pediatrics", "score": 5.362, "shared_docs": 5}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f73385df', 'person', 'Ronald Goldman', 'Ronald Goldman, Ph.D., is an American psychologist, researcher, author, and speaker recognized for his pioneering work on the psychological and emotional impacts of routine infant circumcision. As the founder and executive director of the Circumcision Resource Center based in Boston, Massachusetts, Goldman has spent decades investigating the behavioral, developmental, and relational consequences of neonatal foreskin removal on infants, men, and families.', '', '', 'champion', 'Psychologist, author, and founder of the Circumcision Resource Center known for examining the psychological trauma of infant circumcision and promoting alternatives within Jewish tradition.', 1, '[{"name": "Laurie Evans", "score": 8.946, "shared_docs": 2}, {"name": "Doctors Opposing Circumcision (D.O.C.)", "score": 8.946, "shared_docs": 4}, {"name": "David J. Llewellyn", "score": 8.946, "shared_docs": 2}, {"name": "Roger Saquet", "score": 8.946, "shared_docs": 2}, {"name": "William Sullivan", "score": 8.946, "shared_docs": 2}]');
