INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-4321fd9b', 'organization', 'Mayo Clinic', 'The Mayo Clinic is a renowned non-profit academic medical center headquartered in Rochester, Minnesota, widely recognized for its contributions to clinical care, medical research, and public health education. As one of the largest and most influential integrated healthcare systems in the United States, its clinical guidelines and patient education resources carry significant weight among healthcare providers and the general public.', '', '', 'notable', 'A prominent American academic medical center whose published patient guidance on circumcision serves as a key reference in clinical and public health debates.', 0, '');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-425c4d99', 'organization', 'NOCIRC', 'The National Organization of Circumcision Information Resource Centers (NOCIRC) is a non-profit human rights and healthcare organization founded in 1985 by registered nurse Marilyn Milos and a network of medical professionals. Based in the United States, NOCIRC was the first national organization specifically established to address the ethical, medical, and psychological issues surrounding routine infant circumcision, serving as a pioneer in the modern intactivist movement.', '', '', 'champion', 'Pioneering non-profit organization advocating against non-consensual infant circumcision and promoting universal genital autonomy.', 1, '[{"name": "UNCIRC", "score": 8.265, "shared_docs": 3}, {"name": "Lewis Sayre", "score": 8.265, "shared_docs": 3}, {"name": "Billy Ray Boyd", "score": 8.265, "shared_docs": 3}, {"name": "Anne Briggs", "score": 8.265, "shared_docs": 3}, {"name": "NOHARMM", "score": 8.166, "shared_docs": 10}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-519d4acf', 'organization', 'Royal Dutch Medical Association (KNMG)', 'The Royal Dutch Medical Association (KNMG), founded in 1849, is the primary professional organization for physicians in the Netherlands. Representing tens of thousands of medical professionals, the association sets ethical guidelines, advises on healthcare policy, and addresses fundamental questions regarding medical necessity, human rights, and patient rights within Dutch healthcare.

In May 2010, the KNMG achieved international prominence in bioethics and bodily autonomy debates by publishing a landmark policy statement titled ''Non-therapeutic circumcision of male minors.'' Formulated in collaboration with various Dutch medical specialty societies, the viewpoint concluded that non-therapeutic male circumcision is medically unjustified, violates the physical integrity of children, and breaches the rights of minors to bodily autonomy. The document urged physicians to actively inform parents about the lack of evidence supporting health benefits, the potential for complications, and the ethical obligation to defer non-essential procedures until a child can grant informed consent.

The KNMG''s explicit framing of routine infant male circumcision as a human rights issue influenced medical policy discourse across Northern Europe and international bioethical debates. By advocating for a policy of discouragement rather than total legal bans, the KNMG sought to balance child protection with medical ethics, providing a foundational argument for intactivist advocates and medical reform movement internationally.', '', '', 'champion', 'National medical organization in the Netherlands whose landmark 2010 policy statement framed non-therapeutic male circumcision as a violation of children''s rights and bodily integrity.', 1, '[{"name": "Belgian Advisory Committee on Bioethics", "score": 10.253, "shared_docs": 3}, {"name": "Royal Australasian College of Physicians (RACP)", "score": 9.516, "shared_docs": 3}, {"name": "Marie Fox and Michael Thomson", "score": 9.253, "shared_docs": 2}, {"name": "Tasmania Law Reform Institute", "score": 8.931, "shared_docs": 2}, {"name": "Michael Thomson", "score": 8.931, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-983a1457', 'organization', 'Foregen', 'Foregen is a non-profit biotechnology organization established in 2010 with the primary mission of using tissue engineering and regenerative medicine to regenerate human foreskin tissue. Founded by Vincenzo Aiello, the organization emerged to address the anatomical loss caused by male circumcision through scientific research. Foregen''s technical strategy relies on utilizing decellularized extracellular matrix scaffolds, which are intended to be reseeded with a patient''s own stem cells to fully restore the biological structure, nerve density, and vascularization of the natural foreskin.

Within the broader landscape of intactivism and bodily autonomy, Foregen occupies a distinct position by bridging medical science with bodily integrity advocacy. While traditional intactivist organizations focus primarily on legal action, education, and preventing non-consensual infant circumcision, Foregen directly addresses the physical and psychological impacts experienced by circumcised individuals seeking anatomical restoration. By developing a potential biological alternative to traditional mechanical tissue expansion, the organization emphasizes the right of individuals to reclaim their intact bodily state.

Over the course of its operations, Foregen has funded pre-clinical research, published peer-reviewed studies on extracellular matrix decellularization, and progressed toward human clinical trials. The organization remains a central scientific initiative within the intactivist ecosystem, representing a technological response to non-therapeutic genital cutting.', '', '', 'champion', 'A non-profit biotechnology organization dedicated to regenerating foreskin tissue through regenerative medicine for circumcised men.', 1, '[{"name": "Amsterdam University Medical Center", "score": 10.575, "shared_docs": 2}, {"name": "National Organization of Restoring Men (NORM)", "score": 8.353, "shared_docs": 3}, {"name": "American Academy of Pediatrics (AAP)", "score": 6.903, "shared_docs": 2}, {"name": "National Organization to Halt the Abuse and Routine Mutilation of Males (NOHARMM)", "score": 6.692, "shared_docs": 2}, {"name": "Tim Hammond", "score": 6.366, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-c96bb47e', 'person', 'Thomas E. Wiswell', 'Thomas E. Wiswell was an American pediatrician and neonatologist best known for his influential epidemiological research on neonatal circumcision during his tenure with the U.S. Army Medical Corps. In the mid-1980s, following a period during which circumcision rates in military hospitals declined, Wiswell observed an apparent correlation between uncircumcised male infants and an increased incidence of urinary tract infections (UTIs).

Wiswell authored a series of landmark studies asserting that uncircumcised male infants faced a substantially higher risk of UTIs during their first year of life compared to circumcised infants. His findings proved pivotal in shifting mainstream medical opinion in the United States, serving as a primary catalyst for the American Academy of Pediatrics (AAP) to revise its stance in 1989, moving away from its 1971 statement that there was no absolute medical indication for routine circumcision to acknowledging potential medical benefits.

Within the discourse surrounding bodily autonomy and intactivism, Wiswell''s research represents one of the most frequently cited—and intensely debated—cornerstones of pro-circumcision medical arguments. While intactivist researchers and medical critics challenged his studies regarding potential selection bias, methodology, and the absolute clinical risk of infant UTIs, Wiswell remained a central figure in shaping late 20th-century North American pediatric policy.', '', '', 'critic', 'A prominent pediatrician and researcher whose 1980s studies on urinary tract infections significantly influenced American pediatric policy in favor of routine infant circumcision.', 1, '[{"name": "Abraham L. Wolbarst", "score": 9.488, "shared_docs": 3}, {"name": "Aaron J. Fink", "score": 9.073, "shared_docs": 3}, {"name": "Constance Bohon", "score": 8.903, "shared_docs": 2}, {"name": "Frank Hinman", "score": 8.903, "shared_docs": 2}, {"name": "Glen Anderson", "score": 8.903, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e4eeb0e5', 'person', 'J. Oster', 'J. Oster was a Danish pediatrician and medical researcher best known for conducting one of the most comprehensive observational studies on natural foreskin development in children. His landmark 1968 paper, titled "Further fate of the foreskin," monitored nearly 2,000 Danish schoolboys over several years to document the physiological progression of foreskin retractability, smegma accumulation, and the natural resolution of non-retractability.

Oster''s findings provided critical empirical evidence that non-retractable foreskin in infants and young boys is a normal, developmental state rather than a pathological condition requiring intervention. His research demonstrated that foreskin retractability increases naturally throughout childhood and adolescence, resolving spontaneously in the vast majority of cases without surgical or mechanical intervention.

Within the discourse on genital autonomy and intactivism, Oster''s work remains a foundational reference point. By establishing an evidence-based timeline for natural foreskin development, his study provided medical professionals and advocacy groups with essential scientific data to challenge routine infant circumcision and the premature diagnosis of phimosis.', '', '', 'notable', 'Danish pediatrician whose landmark 1968 study on foreskin development demonstrated that non-retractability naturally resolves with age.', 0, '[{"name": "D. Gairdner", "score": 11.031, "shared_docs": 3}, {"name": "Canadian Paediatric Society", "score": 7.253, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 4.718, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-66355bbb', 'organization', 'American Academy of Pediatrics', 'Founded in 1930, the American Academy of Pediatrics (AAP) is the primary professional association of pediatricians in the United States, responsible for establishing clinical guidelines and public health positions concerning children and adolescents. Over the decades, the AAP''s Task Force on Circumcision has issued several prominent policy statements regarding routine male infant circumcision, evolving from nuanced stances in the 1970s to positions that acknowledged specific preventive health benefits in subsequent decades.', '', '', 'critic', 'A prominent American medical association whose policy statements have framed routine infant male circumcision as a medically beneficial procedure subject to parental discretion.', 1, '[{"name": "Anthony Shaw", "score": 6.04, "shared_docs": 3}, {"name": "Alan R. Fleischman", "score": 6.04, "shared_docs": 3}, {"name": "William G. Bartholome", "score": 6.04, "shared_docs": 3}, {"name": "Ronald L. Poland", "score": 6.04, "shared_docs": 4}, {"name": "Constance Bohon", "score": 6.04, "shared_docs": 3}]');
