INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-5155d44b', 'organization', 'American College of Obstetrics and Gynecology', 'The American College of Obstetricians and Gynecologists (ACOG) is a premier professional organization for physicians specializing in obstetrics and gynecology in the United States. Founded in 1951, ACOG serves as a leading authority on women''s healthcare, maternal-fetal medicine, and neonatal care standards, publishing clinical guidelines, research, and policy recommendations that influence healthcare delivery across the nation.

Within the discourse on neonatal circumcision, ACOG has historically collaborated with other major medical bodies, particularly the American Academy of Pediatrics (AAP), to evaluate clinical evidence regarding the procedure. ACOG''s guidance emphasizes the necessity of informed consent, advocating that healthcare providers present balanced, evidence-based information regarding potential risks and health benefits so that parents can make informed decisions for their newborns.

Because ACOG''s institutional position frames non-therapeutic infant circumcision as an elective procedure within the scope of parental discretion, it occupies a significant place in sociological analyses of bodily autonomy and medical ethics. While bodily autonomy advocates and intactivist organizations often criticize such policy frameworks for permitting non-consensual modifications of infant genitalia, ACOG maintains an institutional focus on procedural safety, pain management, and parental decision-making in the immediate postpartum context.', '', '', 'notable', 'A leading U.S. professional medical organization whose clinical guidelines and joint policies significantly shape physician practice and parental consent surrounding infant circumcision.', 1, '[{"name": "Constance Bohon", "score": 10.668, "shared_docs": 2}, {"name": "Frank Hinman", "score": 10.668, "shared_docs": 2}, {"name": "Glen Anderson", "score": 10.668, "shared_docs": 2}, {"name": "E. Maurice Wakeman", "score": 10.668, "shared_docs": 2}, {"name": "AAP Task Force on Circumcision", "score": 10.668, "shared_docs": 2}]');
