INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-1972e120', 'person', 'Robert Van Howe', 'Dr. Robert S. Van Howe is an American pediatrician, medical researcher, and clinical professor known for his extensive academic work and advocacy regarding male circumcision and bodily autonomy. He earned his medical degree from the University of Wisconsin Medical School and a Master of Science in Public Health from the University of Minnesota. Throughout his clinical and academic career, Van Howe has focused on pediatrics while conducting rigorous epidemiologic and statistical analyses examining the risks, ethics, and claimed medical benefits of routine neonatal circumcision.

Van Howe emerged as a prominent scholarly voice within the intactivist movement through his prolific authorship of peer-reviewed articles critiquing mainstream policy statements on circumcision. His research has frequently challenged positions held by organizations such as the American Academy of Pediatrics (AAP), arguing that studies claiming significant health benefits for circumcision are often methodologically flawed or biased. His published literature addresses a wide array of topics, including HIV transmission dynamics, urinary tract infection incidence, anatomical function, and the ethical dimensions of non-therapeutic pediatric surgery.

In addition to his academic research, Van Howe has served as an expert witness in legal proceedings concerning pediatric genital autonomy and informed consent. He has actively advised and collaborated with advocacy organizations, including the National Organization of Circumcision Information Resource Centers (NOCIRC) and Intact America, to promote public awareness and legal protections for children''s genital integrity. His work remains central to contemporary medical and ethical discourse surrounding infant circumcision in North America.', '', '', 'champion', 'American pediatrician, medical researcher, and prominent advocate for genital autonomy who has published extensively opposing non-therapeutic infant circumcision.', 1, '[{"name": "Laura M. Carpenter", "score": 9.488, "shared_docs": 2}, {"name": "Elizabeth Reis", "score": 9.488, "shared_docs": 2}, {"name": "Morris Sorrells", "score": 9.488, "shared_docs": 2}, {"name": "Tasmania Law Reform Institute", "score": 9.166, "shared_docs": 2}, {"name": "Brian Morris", "score": 9.028, "shared_docs": 4}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-157ed1b5', 'organization', 'American College of Obstetricians and Gynecologists', 'Founded in 1951, the American College of Obstetricians and Gynecologists (ACOG) is a premier professional organization representing tens of thousands of physicians specializing in women''s health, pregnancy, and childbirth in the United States. ACOG plays a central role in establishing clinical guidelines, shaping public health policies, and establishing standard practices surrounding neonatal care and maternal health.', '', '', 'critic', 'A leading American medical association that has endorsed clinical guidelines supporting parental choice and insurance coverage for routine infant male circumcision.', 1, '[{"name": "Charles LeBaron", "score": 8.931, "shared_docs": 3}, {"name": "Ellen Buerk", "score": 8.931, "shared_docs": 3}, {"name": "Lesley Atwood", "score": 8.931, "shared_docs": 3}, {"name": "Steven Wegner", "score": 8.931, "shared_docs": 3}, {"name": "Waldemar Carlo", "score": 8.931, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-cf09eb6b', 'organization', 'Canadian Paediatric Society', 'The Canadian Paediatric Society (CPS) is the national professional association representing pediatricians and child health specialists in Canada. Founded in 1922, the organization establishes clinical guidelines, influences public health policy, and advocates for youth healthcare standardizations. Within the discourse surrounding infant circumcision and bodily autonomy, the CPS serves as a central medical authority whose policy statements have significantly shaped clinical practice, public healthcare coverage, and parental decision-making across Canada.

Historically, the CPS took a restrained stance on routine infant circumcision, issuing position statements in 1975, 1989, and 1996 that consistently concluded the procedure was not medically indicated for all newborn males. These early recommendations played a pivotal role in the systematic de-funding of elective neonatal circumcision by Canadian provincial health insurance plans throughout the late 1980s and 1990s. In 2015, the CPS reaffirmed its stance that routine circumcision for all newborns is not recommended, though it acknowledged potential prophylactic benefits against certain infections, leaving the decision to parental discretion.

In the broader sociological and intactivist discourse, the CPS''s statements are frequently analyzed alongside those of other international medical bodies. Advocates for genital autonomy have often cited the CPS''s non-recommendation stance and the subsequent loss of public funding in Canada as significant policy precedents, while critics of non-therapeutic circumcision occasionally challenge the society''s inclusion of potential medical benefits in its updated guidelines. Overall, the CPS remains a foundational institutional reference point in debates over medical necessity and minor bodily autonomy.', '', '', 'notable', 'Canada''s national association of pediatricians, whose position statements on neonatal circumcision have significantly influenced healthcare policy and medical discourse.', 1, '[{"name": "Arif Bhimji", "score": 8.575, "shared_docs": 2}, {"name": "Dennis Harrison", "score": 8.575, "shared_docs": 3}, {"name": "College of Physicians and Surgeons of British Columbia", "score": 8.253, "shared_docs": 4}, {"name": "College of Physicians and Surgeons of Saskatchewan", "score": 8.253, "shared_docs": 4}, {"name": "Association for Genital Integrity", "score": 8.16, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-6df9adb4', 'organization', 'National Center for Health Statistics', 'The National Center for Health Statistics (NCHS) is the principal federal health statistics agency of the United States, operating as a division of the Centers for Disease Control and Prevention (CDC) within the Department of Health and Human Services. Established to monitor the nation''s health through comprehensive data collection, analysis, and dissemination, the agency tracks a broad array of health indicators, healthcare utilization patterns, and surgical procedures performed across American medical facilities.

Within the historical discourse surrounding routine neonatal circumcision, the NCHS played a pivotal role as a primary provider of quantitative epidemiological data. Through long-running data collection systems, most notably the National Hospital Discharge Survey (NHDS) and the National Health and Nutrition Examination Survey (NHANES), the NCHS systematically recorded trends in routine hospital circumcisions over several decades. Its publications documented significant long-term declines in infant circumcision rates, as well as distinct regional and socioeconomic variations across the country.

While the NCHS maintains a strictly objective statistical function without taking advocacy positions, its data has been central to research and public health debates surrounding male genital autonomy. Both intactivist scholars and medical policymakers have relied extensively on NCHS datasets to evaluate the impact of third-party payer coverage, analyze cultural shifts, and contextualize changes in policy statements issued by organizations such as the American Academy of Pediatrics.', '', '', 'notable', 'The principal U.S. federal health statistics agency whose longitudinal data on neonatal circumcision rates informed public health policy and intactivist research.', 1, '[{"name": "American Medical Association (AMA)", "score": 9.005, "shared_docs": 2}, {"name": "Edgar J. Schoen", "score": 7.24, "shared_docs": 2}, {"name": "Dan Bollinger", "score": 6.935, "shared_docs": 2}, {"name": "Thomas E. Wiswell", "score": 6.825, "shared_docs": 3}, {"name": "American Academy of Pediatrics (AAP)", "score": 6.24, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-32755080', 'organization', 'Australian College of Paediatrics', 'The Australian College of Paediatrics (ACP) was a premier medical body representing pediatricians across Australia prior to its integration into the Paediatrics & Child Health Division of the Royal Australasian College of Physicians (RACP) in the late 1990s. As a leading voice in Australasian child healthcare, the organization played a central role in shaping clinical standards, public health policies, and ethical guidelines surrounding infant care and medical procedures.

The college gained international prominence in the discourse on non-therapeutic infant circumcision through its influential 1996 position statement. Evaluating the available clinical evidence, the ACP concluded that routine infant male circumcision was not medically warranted and that the procedure carried non-negligible surgical risks without providing proportional therapeutic benefits. The statement advised pediatricians and medical practitioners against recommending routine neonatal circumcision.

By framing the issue around evidence-based medicine and the child''s right to physical integrity, the Australian College of Paediatrics significantly contributed to a sharp drop in infant circumcision rates throughout Australia. Its policy served as a key institutional precedent for anti-circumcision advocates and human rights organizations, who frequently reference the college''s findings as authoritative evidence against non-consensual bodily modifications in infants.', '', '', 'champion', 'A former professional medical body whose seminal policy statements discouraged routine infant circumcision and emphasized children''s physical integrity.', 1, '[{"name": "Lord Templeman", "score": 10.405, "shared_docs": 2}, {"name": "American Cancer Society", "score": 10.405, "shared_docs": 2}, {"name": "Australasian Association of Paediatric Surgeons", "score": 9.405, "shared_docs": 3}, {"name": "Queensland Law Reform Commission", "score": 9.405, "shared_docs": 2}, {"name": "General Medical Council", "score": 8.82, "shared_docs": 2}]');
