INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-1d74fe87', 'person', 'Georganne Chapin', 'Georganne Chapin is an American healthcare executive, bioethicist, and attorney who serves as a leading figure in the advocacy for children''s bodily autonomy and genital integrity. Holding a Juris Doctor and a Master of Philosophy in sociomedical sciences, Chapin spent much of her career in healthcare leadership, including serving as the long-time Chief Executive Officer of Hudson Health Plan. Her background in health law and policy provided her with a unique foundation to critically examine public health mandates and routine medical procedures in the United States.

In 2008, Chapin founded Intact America, a national non-profit organization dedicated to ending routine, non-therapeutic infant circumcision in the United States. Under her leadership as Executive Director, Intact America emerged as a prominent voice in the intactivist movement, focusing on public education, media outreach, and challenging established medical guidelines. Chapin has consistently critiqued institutional policies, particularly those of the American Academy of Pediatrics, arguing that non-consensual genital alterations performed on minors lack compelling medical justification.

Through her writing, lectures, and advocacy work, Chapin frames the issue of infant circumcision primarily around ethics, consent, and bodily integrity. She contends that every child possesses a fundamental human right to an intact body, and that decisions regarding non-essential alterations should be deferred until the individual can provide informed consent. Her contributions have significantly shaped modern discourse surrounding pediatric bioethics and patient rights within the bodily autonomy movement.', '', '', 'champion', 'Founder and Executive Director of Intact America and prominent advocate for children''s genital integrity and bioethics.', 0, '[{"name": "Intact America", "score": 10.253, "shared_docs": 5}, {"name": "Dan Bollinger", "score": 8.861, "shared_docs": 2}, {"name": "World Health Organization", "score": 5.668, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 5.303, "shared_docs": 3}]');
