INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-0c589514', 'person', 'Robert S. Van Howe', 'Dr. Robert S. Van Howe is an American pediatrician, clinical researcher, and medical epidemiologist who has served as a prominent scientific voice challenging the medical necessity and ethical justification of routine infant circumcision. Holding an M.D. and a Master of Science in clinical research, Van Howe has dedicated a significant portion of his academic career to evaluating the epidemiological evidence, statistical methodologies, and human rights implications surrounding male genital cutting.

Over several decades, Van Howe authored and co-authored dozens of peer-reviewed articles critically examining claims regarding the purported health benefits of circumcision. His research has addressed topics including urinary tract infection rates, HIV/STI transmission dynamics, sexual function, and the methodological limitations of studies used to justify widespread routine infant procedures. He has been a consistent critic of statements issued by mainstream medical bodies, including the American Academy of Pediatrics (AAP), arguing that their policies often overstate benefits while underestimating risks and ethical concerns.

In addition to his published scientific work, Van Howe has provided expert testimony in legal cases involving genital autonomy, legal consent, and medical necessity. Through his medical research, public lectures, and legal advocacy, Van Howe has served as a key clinical authority within the intactivist movement, advocating for children''s rights to bodily integrity and informed consent.', '', '', 'champion', 'Pediatrician and researcher known for extensive peer-reviewed publications challenging the medical justification of routine infant circumcision.', 1, '[{"name": "Robert S. Van Howe, MD, MS, FAAP", "score": 9.021, "shared_docs": 4}, {"name": "Central Michigan University College of Medicine", "score": 9.021, "shared_docs": 5}, {"name": "Peter W. Adler", "score": 8.699, "shared_docs": 8}, {"name": "Jeffrey D. Klausner", "score": 8.699, "shared_docs": 4}, {"name": "John N. Krieger", "score": 8.436, "shared_docs": 8}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-d4139c01', 'organization', 'Centers for Disease Control and Prevention', 'The Centers for Disease Control and Prevention (CDC) is the national public health institute of the United States, operating under the Department of Health and Human Services. Established in 1946, the agency is responsible for health promotion, disease prevention, and public health policy development. Within the discourse surrounding male circumcision, the CDC acts as a primary institutional authority whose evaluations and clinical recommendations significantly influence U.S. medical standards, insurance coverage, and public perceptions of the procedure.

Following extensive evidence reviews, the CDC released formal guidance in 2014 concluding that elective male circumcision offers significant health benefits, including reduced risk of acquiring HIV, urinary tract infections, and certain sexually transmitted infections. The agency recommended that clinicians inform adult males and parents of male newborns about the potential health benefits and risks of the procedure, emphasizing that circumcision should remain a voluntary choice available to families and individuals.

The CDC''s recommendations positioned the agency as a major point of contention within the bodily autonomy and intactivist movements. Critics and genital autonomy advocates contend that the agency''s guidance overemphasized preventive medical benefits at the expense of infant consent, ethical considerations, and anatomical preservation. Conversely, medical professional organizations and advocates of circumcision regularly cite CDC findings to justify the clinical utility and public health value of routine neonatal circumcision.', '', '', 'critic', 'The United States federal public health agency whose clinical guidance endorsing the medical benefits of male circumcision significantly shaped public policy and intactivist critique.', 1, '[{"name": "Charles LeBaron", "score": 8.366, "shared_docs": 3}, {"name": "Ellen Buerk", "score": 8.366, "shared_docs": 3}, {"name": "Lesley Atwood", "score": 8.366, "shared_docs": 3}, {"name": "Steven Wegner", "score": 8.366, "shared_docs": 3}, {"name": "Waldemar Carlo", "score": 8.366, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-30d5989c', 'organization', 'American Academy of Family Physicians', 'Founded in 1947, the American Academy of Family Physicians (AAFP) is one of the largest national medical organizations in the United States, representing family physicians, residents, and medical students. As primary care providers who frequently deliver routine neonatal care and offer medical counseling to expectant parents, family physicians serve as key practitioners in the clinical landscape surrounding routine infant male circumcision.

Throughout the late 20th and early 21st centuries, the AAFP maintained policy guidance regarding neonatal circumcision that largely aligned with the American Academy of Pediatrics (AAP). Following the AAP''s 2012 policy statement, the AAFP endorsed the view that the preventive health benefits of elective newborn male circumcision outweighed the risks, while maintaining that the procedure was not essential to a child''s immediate health and should remain a decision for parents to make in consultation with medical professionals.

Within the broader discourse on bodily autonomy and intactivism, the AAFP''s policy positions have made it a prominent institutional subject of debate. While the organization presents its guidelines as an evidence-based framework designed to facilitate informed parental choice, genital autonomy advocates and intactivists critique the AAFP for legitimizing non-therapeutic infant circumcision and opposing restrictions on elective pediatric genital surgeries.', '', '', 'critic', 'A primary American medical association whose clinical policies endorse parental choice and insurance coverage for routine male infant circumcision.', 1, '[{"name": "Charles LeBaron", "score": 11.405, "shared_docs": 3}, {"name": "Ellen Buerk", "score": 11.405, "shared_docs": 3}, {"name": "Lesley Atwood", "score": 11.405, "shared_docs": 3}, {"name": "Steven Wegner", "score": 11.405, "shared_docs": 3}, {"name": "Waldemar Carlo", "score": 11.405, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-b62528e7', 'organization', 'Central Michigan University College of Medicine', 'Central Michigan University College of Medicine (CMED), established in 2010, is a public medical school situated in Mount Pleasant and Saginaw, Michigan, focused on medical education, clinical research, and addressing regional healthcare needs. Within the broader sociological and medical literature on circumcision and bodily autonomy, academic institutions like CMED play a critical role in shaping clinical standards, delivering pediatric care training, and instructing future physicians on medical ethics and informed consent.

In archival records documenting debates over neonatal genital procedures, medical colleges serve as key reference points for observational studies, hospital policy implementations, and clinical education. Institutions in this sector influence how emerging medical professionals navigate the intersection of parental preferences, ethical considerations of bodily integrity, and evidence-based clinical guidelines regarding non-therapeutic infant circumcision.

While CMED operates as a standard academic medical training center rather than an advocacy organization, its inclusion in discussions surrounding healthcare practices highlights the ongoing interplay between institutional medicine, clinical education, and contemporary perspectives on patient autonomy.', '', '', 'notable', 'A public medical school in Michigan that contributes to clinical education, pediatric health discussions, and medical ethics training.', 0, '[{"name": "Robert S. Van Howe, MD, MS, FAAP", "score": 11.253, "shared_docs": 2}, {"name": "Robert C. Bailey", "score": 9.346, "shared_docs": 2}, {"name": "Council of Europe", "score": 9.083, "shared_docs": 2}, {"name": "Robert S. Van Howe", "score": 9.021, "shared_docs": 5}, {"name": "Morten Frisch", "score": 8.005, "shared_docs": 2}]');
