INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-1bdd58a1', 'person', 'Andrew Freedman', 'Andrew Freedman, M.D., is an American pediatric urologist who has served as the Director of Pediatric Urology at Cedars-Sinai Medical Center in Los Angeles. He became a central figure in the national discourse on male infant circumcision through his leadership within the American Academy of Pediatrics (AAP). As vice-chair of the AAP Task Force on Circumcision, Freedman played a pivotal role in reviewing medical literature and shaping the organization''s policy guidelines.', '', '', 'critic', 'Pediatric urologist and former vice-chair of the AAP Task Force on Circumcision who co-authored the 2012 AAP policy statement.', 1, '[{"name": "Charles LeBaron", "score": 10.875, "shared_docs": 3}, {"name": "Ellen Buerk", "score": 10.875, "shared_docs": 3}, {"name": "Lesley Atwood", "score": 10.875, "shared_docs": 3}, {"name": "Steven Wegner", "score": 10.875, "shared_docs": 3}, {"name": "Waldemar Carlo", "score": 10.875, "shared_docs": 3}]');
