INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f4028b23', 'person', 'Susan Blank', 'Dr. Susan Blank is an American pediatrician and public health specialist best known for her prominent role in shaping contemporary American medical policy regarding male neonatal circumcision. She earned her medical degree and completed her residency in pediatrics, later serving in public health leadership roles, including positions within the New York City Department of Health and Mental Hygiene.

Blank achieved national and international prominence as the chair of the American Academy of Pediatrics (AAP) Task Force on Circumcision. Under her leadership, the task force authored the AAP''s 2012 updated policy statement and technical report on male circumcision. The policy concluded that the preventive health benefits of newborn male circumcision outweigh the risks, though not by a sufficient margin to recommend routine universal circumcision for all male newborns. The statement advocated for parental choice and recommended that medical insurance cover the procedure.

Following the publication of the 2012 policy, Blank frequently represented the AAP in media discussions and academic forums to defend the task force''s findings. The policy generated significant controversy globally, drawing criticism from intactivist organizations, bioethicists, and several European pediatric associations that argued the AAP overstated the health benefits and understated ethical considerations regarding bodily autonomy and consent.', '', '', 'critic', 'Pediatrician and former chair of the American Academy of Pediatrics Task Force on Circumcision who led the 2012 policy update.', 0, '[{"name": "Charles LeBaron", "score": 11.99, "shared_docs": 3}, {"name": "Ellen Buerk", "score": 11.99, "shared_docs": 3}, {"name": "Lesley Atwood", "score": 11.99, "shared_docs": 3}, {"name": "Steven Wegner", "score": 11.99, "shared_docs": 3}, {"name": "Waldemar Carlo", "score": 11.99, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-1c5ae354', 'person', 'Michael Brady', 'Dr. Michael T. Brady is an American pediatrician specializing in pediatric infectious diseases and public health policy. He has served in prominent academic and clinical roles, including as a professor of pediatrics and leadership figure within the American Academy of Pediatrics (AAP). Brady played a key role in national debates surrounding infant routine procedures through his service on the AAP Task Force on Circumcision.

As a core member and spokesperson for the 2012 AAP Task Force on Circumcision, Brady co-authored the influential policy statement that concluded the health benefits of newborn male circumcision outweighed the procedural risks. The statement highlighted reductions in the risk of urinary tract infections, penile cancer, and the transmission of certain sexually transmitted infections, including HIV, advocating for insurance coverage and parental choice regarding the procedure.

The 2012 AAP policy statement drew substantial criticism from intactivist advocates, ethicists, and several international medical organizations, who challenged its cultural framing, ethical justifications, and interpretation of scientific data. Through his commentary and public representation of the AAP''s position, Brady remained a central figure in discussions regarding pediatric ethics, preventive medicine, and bodily autonomy.', '', '', 'critic', 'Pediatric infectious disease specialist and co-author of the 2012 AAP Task Force policy statement on male circumcision', 0, '[{"name": "Charles LeBaron", "score": 11.768, "shared_docs": 3}, {"name": "Ellen Buerk", "score": 11.768, "shared_docs": 3}, {"name": "Lesley Atwood", "score": 11.768, "shared_docs": 3}, {"name": "Steven Wegner", "score": 11.768, "shared_docs": 3}, {"name": "Waldemar Carlo", "score": 11.768, "shared_docs": 3}]');
