INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-d857a8ff', 'person', 'Morten Frisch', 'Morten Frisch is a Danish physician, epidemiologist, and senior researcher at Statens Serum Institut, as well as an adjunct professor of sexual health epidemiology at Aalborg University. He is widely recognized for his scientific research examining the medical risks, long-term sexual health outcomes, and ethical dimensions associated with non-therapeutic male circumcision.

Throughout his academic career, Frisch authored and co-authored several landmark population-based studies investigating the link between non-therapeutic circumcision and various health outcomes, including sexual dysfunction, meatal stenosis, and psychological distress. His empirical findings challenged prevailing assumptions about the harmlessness and medical utility of routine infant circumcision, providing influential data that helped shape European medical and policy perspectives.

Beyond his research publications, Frisch became a prominent voice advocating for children''s rights and bodily integrity in public policy and medical ethics debates. He consistently argued that non-therapeutic genital procedures on non-consenting minors violate fundamental human rights principles, advocating for equal protection of all children regardless of gender.', '', '', 'champion', 'Danish epidemiologist and professor known for his landmark research on the health risks of male circumcision and his advocacy for children''s bodily integrity.', 1, '[{"name": "Statens Serum Institut", "score": 9.327, "shared_docs": 10}, {"name": "Aalborg University", "score": 9.327, "shared_docs": 8}, {"name": "Jacob Simonsen", "score": 9.327, "shared_docs": 3}, {"name": "Peter W. Adler", "score": 9.005, "shared_docs": 8}, {"name": "Noni MacDonald", "score": 8.742, "shared_docs": 2}]');
