INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-d01228c5', 'organization', 'Danish Medical Association', 'The Danish Medical Association (Lægeforeningen), established in 1857, is the primary professional organization for physicians in Denmark. Representing the vast majority of Danish doctors, the association works to advance public health, maintain professional standards, and establish ethical guidelines for medical practice across the country.', '', '', 'champion', 'The national professional association of Danish physicians, prominent for declaring non-therapeutic male circumcision of minors ethically unacceptable.', 1, '[{"name": "Noni MacDonald", "score": 10.29, "shared_docs": 2}, {"name": "Bernard Friedman", "score": 10.29, "shared_docs": 2}, {"name": "James Munby", "score": 9.875, "shared_docs": 3}, {"name": "Springer Nature Limited", "score": 9.29, "shared_docs": 2}, {"name": "Reinhard Merkel", "score": 9.067, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-2f7a4f95', 'organization', 'Statens Serum Institut', 'Statens Serum Institut (SSI) is a governmental research institute under the Danish Ministry of Health, established in 1902 to oversee disease prevention, health surveillance, and epidemiological research in Denmark. Operating as a central scientific agency, SSI maintains extensive national health registers that provide comprehensive population-level data on medical procedures, diagnoses, and long-term health outcomes.

In the context of genital autonomy and circumcision discourse, SSI became pivotal due to landmark register-based scientific studies conducted by affiliated epidemiologists, most notably Dr. Morten Frisch. These studies utilized Denmark’s robust healthcare registries to investigate the physical, psychological, and developmental risks associated with non-therapeutic male circumcision, examining potential correlations with conditions such as meatal stenosis, cardiac events, and developmental outcomes.

The empirical research originating from SSI significantly influenced international bioethical and medical debates surrounding childhood male circumcision. By providing rigorous, cohort-based observational evidence on post-procedure complications, SSI''s published findings became frequently cited reference points for human rights advocates, European medical associations, and intactivist organizations challenging the medical necessity and ethical justification of non-therapeutic infant circumcision.', '', '', 'notable', 'A Danish sector research institute under the Ministry of Health known for conducting landmark epidemiological studies on the outcomes and risks of non-therapeutic male circumcision.', 1, '[{"name": "Jacob Simonsen", "score": 11.253, "shared_docs": 3}, {"name": "Aalborg University", "score": 11.061, "shared_docs": 7}, {"name": "The Hastings Center Bioethics Research Institute", "score": 9.931, "shared_docs": 2}, {"name": "Morten Frisch", "score": 9.327, "shared_docs": 10}, {"name": "Danish Medical Association", "score": 8.553, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-583d7d47', 'organization', 'Royal Australasian College of Physicians', 'The Royal Australasian College of Physicians (RACP) is the primary professional medical organization responsible for training, educating, and representing physicians and pediatricians across Australia and New Zealand. Established in 1938, the college plays a central role in establishing clinical guidelines, shaping medical education, and advising government bodies on public health policy throughout Australasia.

Within the discourse surrounding circumcision and bodily autonomy, the RACP''s Paediatrics and Child Health Division has been a influential institutional authority. Through a series of policy statements issued in 1996, 2002, 2004, and 2010, the college consistently evaluated the clinical evidence regarding routine infant male circumcision. The RACP concluded that the procedure is not medically indicated as a routine prophylactic measure, emphasizing that the potential health benefits are insufficient to outweigh the risks and ethical implications of performing non-therapeutic surgery on infants.

The RACP''s stance contributed significantly to a dramatic decline in infant circumcision rates across Australia and New Zealand over recent decades. By emphasizing informed consent, risk assessment, and bodily integrity, the college''s policy positions are frequently cited by medical professionals, ethicists, and legal scholars engaged in global discussions on non-therapeutic genital surgery.', '', '', 'notable', 'The leading medical professional body in Australasia, influential for its policy positions discouraging routine infant male circumcision.', 1, '[{"name": "Royal Australasian College of Surgeons", "score": 9.327, "shared_docs": 4}, {"name": "Noni MacDonald", "score": 8.742, "shared_docs": 2}, {"name": "National Health and Medical Research Council", "score": 8.742, "shared_docs": 2}, {"name": "Australian Paediatric Association", "score": 8.742, "shared_docs": 2}, {"name": "Conseil National du SIDA", "score": 8.742, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-802396a3', 'organization', 'British Medical Association', 'The British Medical Association (BMA) is the professional association and registered trade union for doctors in the United Kingdom, founded in 1832. As a leading voice in British healthcare, the BMA formulates medical ethics policy, represents practitioners across various medical specialties, and issues professional guidance on complex clinical and ethical matters, including pediatric care and surgical procedures.', '', '', 'notable', 'The professional association for UK doctors, known for establishing ethical guidelines on non-therapeutic male circumcision and pediatric consent.', 1, '[{"name": "Lord Templeman", "score": 8.229, "shared_docs": 3}, {"name": "John Locke", "score": 8.059, "shared_docs": 2}, {"name": "Intersex Society of North America", "score": 8.059, "shared_docs": 2}, {"name": "Clare Chambers", "score": 8.059, "shared_docs": 2}, {"name": "Cheryl Chase", "score": 8.059, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-8a61b18f', 'organization', 'Harvard Medical School', 'Harvard Medical School (HMS), established in 1782 in Boston, Massachusetts, is one of the premier institutions of medical education and biomedical research in the United States. Through its network of affiliated teaching hospitals and research institutes, the school has long exerted a powerful influence over North American medical standards, clinical training, and public health policy across a broad array of pediatric and surgical disciplines.', '', '', 'notable', 'A leading academic medical institution whose faculty and affiliated researchers have published influential clinical, epidemiological, and ethical research on male circumcision.', 1, '[{"name": "American Medical Association", "score": 6.271, "shared_docs": 2}]');
