INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-3a7af09b', 'person', 'Douglas Gairdner', 'Dr. Douglas Gairdner (1910–1992) was a British pediatrician and clinical researcher best known for his pivotal role in reforming British medical practices regarding infant circumcision. Educated at Cambridge University and the University of Edinburgh, Gairdner served as a consultant pediatrician at Addenbrooke''s Hospital in Cambridge and spent decades as the editor of the Archives of Disease in Childhood.

In December 1949, Gairdner published a landmark study titled "The Fate of the Foreskin: A Study of Circumcision" in the British Medical Journal. The paper thoroughly detailed the normal physiological development of the prepuce, exposed widespread anatomical misconceptions within the medical profession, and presented data on the morbidity and rare mortalities associated with routine infant circumcision. He concluded that the procedure was medically unnecessary in the vast majority of cases and subjected infants to avoidable trauma and risk.

Gairdner''s research fundamentally altered clinical opinion across the United Kingdom and contributed significantly to the decision by the newly formed National Health Service (NHS) to stop coverage for routine non-therapeutic infant circumcision. His paper remains a classic text in pediatric literature and a foundational milestone in the modern movement toward foreskin preservation and children''s bodily autonomy.', '', '', 'champion', 'British pediatrician whose landmark 1949 study effectively ended routine infant circumcision in the United Kingdom.', 1, '[{"name": "Jacob Oster", "score": 9.405, "shared_docs": 3}, {"name": "Sir James Spence", "score": 8.99, "shared_docs": 3}, {"name": "Jakob Oster", "score": 8.891, "shared_docs": 7}, {"name": "Dustin Evans", "score": 8.82, "shared_docs": 2}, {"name": "Boy\u2019s Health Advisory", "score": 8.82, "shared_docs": 2}]');
