INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-7366792b', 'organization', 'UNAIDS', 'The Joint United Nations Programme on HIV/AIDS (UNAIDS) is an international organization established in 1994 by the United Nations Economic and Social Council to lead and coordinate global action against the HIV/AIDS pandemic. Headquartered in Geneva, Switzerland, UNAIDS works alongside national governments, civil society, and international partners to expand access to HIV prevention, treatment, and care services while advocating for evidence-based public health policies.

Within the discourse on circumcision and bodily autonomy, UNAIDS played a pivotal role following the 2007 joint WHO/UNAIDS recommendation endorsing Voluntary Medical Male Circumcision (VMMC) as an effective biomedical intervention to reduce female-to-male HIV transmission. This policy emerged from randomized controlled trials conducted in Sub-Saharan Africa, leading UNAIDS to support large-scale VMMC campaigns targeting adolescent and adult males in fourteen priority countries across Eastern and Southern Africa.

UNAIDS'' institutional endorsement and global scaling of VMMC have made the organization a central subject of critique among intactivist organizations, human rights advocates, and bioethicists. Critics argue that VMMC programs often prioritize epidemiological targets over individual bodily integrity, raise complex ethical questions regarding informed consent in high-prevalence settings, and inadvertently legitimize non-therapeutic male genital cutting.', '', '', 'critic', 'Joint United Nations agency that co-sponsored the global implementation of voluntary medical male circumcision as an HIV prevention strategy.', 1, '[{"name": "Alain Giami", "score": 8.346, "shared_docs": 3}, {"name": "Michel Garenne", "score": 8.346, "shared_docs": 6}, {"name": "University of Western Cape", "score": 8.346, "shared_docs": 3}, {"name": "Fogarty International Center", "score": 8.346, "shared_docs": 3}, {"name": "Jhpiego", "score": 8.083, "shared_docs": 5}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-bb79b6c1', 'person', 'Moses Maimonides', 'Moses Maimonides (1138–1204), also known as Rambam, was a medieval Sephardic Jewish philosopher, Torah scholar, and court physician whose legal and philosophical writings profoundly shaped Jewish tradition and Western philosophy. Born in Córdoba and later residing in Egypt, Maimonides authored seminal works including the comprehensive codification of Jewish law, the Mishneh Torah, and the philosophical treatise, The Guide for the Perplexed.

Within the discourse on bodily autonomy and circumcision, Maimonides is widely cited for his explicit analysis of ritual circumcision (brit milah) in The Guide for the Perplexed (Part III, Chapter 49). He posited that one of the primary purposes of circumcision was to temper excessive sexual desire and reduce physical pleasure, thereby promoting bodily self-control, moral discipline, and spiritual focus. He also highlighted the practice''s role as a unifying physical token that established a shared covenantal identity among the Jewish community.

In modern sociological and intactivist literature, Maimonides occupies a unique historical position. While he defended the practice on religious and moral grounds, contemporary critics of circumcision frequently cite his candid assertions regarding diminished sexual sensation as key historical evidence that foreskin removal intentionally alters natural physiological sensitivity and function.', '', '', 'critic', 'Twelfth-century Jewish philosopher and physician whose classical defense of ritual circumcision as a means to reduce sexual passion is frequently cited in historical and modern debates.', 1, '[{"name": "Sacred Congregation for the Doctrine of the Faith", "score": 9.366, "shared_docs": 3}, {"name": "Ignatius of Loyola", "score": 9.366, "shared_docs": 3}, {"name": "Victor Turner", "score": 8.781, "shared_docs": 2}, {"name": "Baruch Spinoza", "score": 8.781, "shared_docs": 2}, {"name": "Society for Humanistic Judaism", "score": 8.366, "shared_docs": 2}]');
