INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-d584c52a', 'person', 'Miriam Pollack', 'Miriam Pollack is an educator, writer, and activist who emerged as a prominent voice in the movement against routine infant circumcision, particularly within the context of Jewish culture and religious tradition. Drawing upon feminist theology and child advocacy, Pollack challenged long-standing cultural assumptions surrounding Brit Milah (ritual circumcision), advocating for the protection of children''s bodily integrity and the adoption of peaceful, non-cutting welcoming ceremonies such as Brit Shalom.', '', '', 'champion', 'Jewish educator and activist known for pioneering Jewish feminist critiques of routine infant circumcision.', 1, '[{"name": "Anastasios Zavales", "score": 9.575, "shared_docs": 2}, {"name": "Moses Maimonides", "score": 7.951, "shared_docs": 3}, {"name": "Hanny Lightfoot-Klein", "score": 7.575, "shared_docs": 2}, {"name": "National Organization of Circumcision Information Resource Centers (NOCIRC)", "score": 6.01, "shared_docs": 3}]');
