INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-d552901e', 'person', 'J. Steven Svoboda', 'J. Steven Svoboda is an American attorney, legal scholar, and human rights advocate who has played a central role in the legal discourse surrounding circumcision and bodily integrity. He earned his Juris Doctor from Harvard Law School and holds background degrees in physics and English. In 1997, Svoboda founded Attorneys for the Rights of the Child (ARC), a non-profit legal advocacy organization dedicated to securing legal protections for children against non-consensual genital alterations, including male infant circumcision, female genital cutting, and medically unnecessary intersex surgeries.

Through ARC and his legal scholarship, Svoboda has published extensively on the human rights, bioethical, and constitutional implications of infant male circumcision. He has presented at numerous international academic symposia, submitted legal briefs and statements to international bodies such as the United Nations, and routinely provided legal analysis on high-profile cases involving parental rights, medical ethics, and bodily autonomy. His legal framework relies heavily on international human rights standards, notably the UN Convention on the Rights of the Child.

Svoboda has also served as a legal consultant and advisor within the broader intactivist movement, co-authoring scholarly papers and participating in public and academic debates. His work has contributed significantly to establishing genital autonomy as a recognized human rights issue within legal and bioethical literature.', '', '', 'champion', 'Founder of Attorneys for the Rights of the Child and leading legal scholar in the genital autonomy movement', 1, '[{"name": "J. Neville Turner", "score": 8.847, "shared_docs": 3}, {"name": "William Stowell", "score": 8.847, "shared_docs": 3}, {"name": "Peter W. Adler", "score": 8.525, "shared_docs": 8}, {"name": "Christopher P. Price", "score": 8.432, "shared_docs": 3}, {"name": "Attorneys for the Rights of the Child", "score": 8.333, "shared_docs": 21}]');
