INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-8c0c8060', 'person', 'Brian D. Earp', 'Brian D. Earp is a prominent bioethicist, cognitive scientist, and philosopher whose academic work focuses heavily on bodily integrity, children''s rights, and medical ethics. He has held academic and research posts at leading institutions, including the University of Oxford, Yale University, and the Hastings Center. Throughout his career, Earp has applied rigorous analytical philosophy and interdisciplinary research to ethical questions surrounding non-therapeutic bodily modifications.

Earp is particularly recognized for his extensive literature on genital autonomy, male circumcision, intersex interventions, and female genital alteration. He has authored dozens of peer-reviewed articles challenging the medical, legal, and ethical justifications for non-therapeutic infant male circumcision. His work consistently highlights logical inconsistencies in legal and medical attitudes toward male versus female genital cutting, arguing that all children deserve equal protection of their bodily integrity regardless of sex or gender.

In addition to his academic publications, including co-authoring *Children''s Bodily Integrity: A Bioethical and Legal Argument*, Earp has served as a key intellectual voice bridging academic bioethics with public advocacy. His scholarly contributions have provided critical theoretical frameworks for the genital autonomy movement and significantly shaped modern bioethical debates on the rights of minors.', '', '', 'champion', 'Prominent bioethicist and scholar known for his extensive academic research on children''s rights and genital autonomy.', 1, '[{"name": "Dominic Wilkinson", "score": 7.99, "shared_docs": 3}, {"name": "The Brussels Collaboration on Bodily Integrity", "score": 7.99, "shared_docs": 2}, {"name": "Lih-Mei Liao", "score": 7.99, "shared_docs": 3}, {"name": "National University of Singapore", "score": 7.99, "shared_docs": 4}, {"name": "The Hastings Center Bioethics Research Institute", "score": 7.99, "shared_docs": 5}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-0bf5f0fd', 'person', 'Andrew L. Freedman', 'Dr. Andrew L. Freedman was an American pediatric urologist who played a central role in shaping official medical guidelines regarding neonatal male circumcision in the United States. He completed his medical education and residency training at the University of California, Los Angeles, and later served as Vice Chair of Pediatric Urology at Cedars-Sinai Medical Center in Los Angeles. Over the course of his career, he authored numerous medical publications on pediatric kidney and urological conditions, surgical interventions, and clinical decision-making.

Freedman became a prominent figure in the global debate over circumcision when he served as the co-chair of the American Academy of Pediatrics (AAP) Task Force on Circumcision. In 2012, the task force released a widely discussed policy statement concluding that the preventive health benefits of newborn male circumcision outweighed the medical risks. The policy emphasized reductions in the risk of urinary tract infections, penile cancer, and heterosexually acquired HIV transmission, while advising that the final choice should remain a parental decision.

Following the release of the 2012 statement, Freedman frequently represented the AAP in public debates, academic lectures, and media interviews to defend the task force''s methodology and conclusions. His defense of elective infant circumcision made him a prominent target of criticism from intactivist organizations and bioethicists who argue that non-therapeutic genital alterations infringe upon the bodily autonomy of children.', '', '', 'critic', 'Pediatric urologist and co-chair of the 2012 AAP Task Force on Circumcision', 1, '[{"name": "The Hastings Center Bioethics Research Institute", "score": 9.794, "shared_docs": 2}, {"name": "Douglas S. Diekema", "score": 9.531, "shared_docs": 2}, {"name": "Douglas Diekema", "score": 8.656, "shared_docs": 2}, {"name": "Danish Medical Association", "score": 8.415, "shared_docs": 2}, {"name": "Centers for Disease Control and Prevention (CDC)", "score": 8.308, "shared_docs": 3}]');
INSERT OR IGNORE INTO entity_nominations (id, type, name, description, justification, status) VALUES ('nom-7393aecd', 'person', 'William E. Brigman', '', 'Auto-detected: mentioned in 4 archive documents.', 'pending');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-633e883e', 'person', 'Peter W. Adler', 'Peter W. Adler is an American legal scholar, attorney, and bioethicist who has contributed significantly to the legal and ethical discourse surrounding male infant circumcision. Holding a law degree along with advanced degrees in business and international relations, Adler focused much of his research on the intersection of medical ethics, children''s rights, and common law principles regarding non-therapeutic surgical procedures performed on minors.

Adler authored numerous peer-reviewed articles published in prominent legal and medical journals, such as the Journal of Law and Medicine, Bioethics, and the Journal of Medical Ethics. His academic work systematically analyzed routine infant circumcision through the legal frameworks of battery, informed consent, medical negligence, and human rights law. He consistently maintained that non-therapeutic infant circumcision fails to satisfy standards of medical necessity and infringes upon a child''s fundamental right to bodily integrity and self-determination.

Beyond his publication record, Adler''s legal analyses have provided foundational arguments for genital autonomy advocates and intactivist organizations worldwide. By articulating a rigorous legal case against non-consensual infant genital cutting, his work helped frame the debate not merely as a parental choice or medical routine, but as a crucial legal and human rights issue.', '', '', 'champion', 'Legal scholar and bioethicist known for authoring influential papers examining the legal, ethical, and human rights dimensions of infant circumcision.', 1, '[{"name": "William E. Brigman", "score": 10.253, "shared_docs": 2}, {"name": "Michael Brady", "score": 9.446, "shared_docs": 2}, {"name": "Attorneys for the Rights of the Child", "score": 9.346, "shared_docs": 8}, {"name": "Morten Frisch", "score": 9.005, "shared_docs": 8}, {"name": "Royal Dutch Medical Association", "score": 8.851, "shared_docs": 7}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-a1eb83c4', 'organization', 'Medicaid', 'Medicaid is a joint federal and state program in the United States that provides health coverage to low-income individuals, families, and children. Established under Title XIX of the Social Security Act in 1965, the program is administered individually by each state within federal guidelines. Because individual states possess the authority to determine which optional medical procedures are covered under their specific plans, state Medicaid policies regarding elective, non-therapeutic routine infant male circumcision vary significantly across the country.

Within the discourse on circumcision and bodily autonomy, Medicaid coverage policies serve as a critical economic factor influencing newborn circumcision rates. Numerous public health studies have demonstrated that when states discontinue Medicaid funding for non-therapeutic neonatal circumcision, the rate of the procedure among covered populations drops substantially. Consequently, state Medicaid policy decisions and legislative funding debates have become primary focal points for intactivist organizations advocating to end public taxpayer subsidy of non-consensual bodily alterations.

Conversely, several medical trade organizations have historically advocated for Medicaid coverage of routine infant circumcision, asserting that defunding the procedure creates healthcare disparities for lower-income families. As a result, Medicaid remains a central institutional battleground where public health policy, bioethics, fiscal management, and bodily integrity rights intersect.', '', '', 'notable', 'The public healthcare program in the United States whose state-by-state coverage decisions for non-therapeutic infant circumcision serve as a critical economic lever and advocacy battleground.', 1, '[{"name": "St. Anthony Publishing", "score": 11.575, "shared_docs": 2}, {"name": "Agency for Healthcare Research and Quality", "score": 9.768, "shared_docs": 2}, {"name": "American College of Obstetricians and Gynecologists", "score": 6.931, "shared_docs": 2}, {"name": "Centers for Disease Control and Prevention", "score": 6.366, "shared_docs": 2}, {"name": "American Medical Association", "score": 6.271, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-fbc0780c', 'organization', 'Royal Dutch Medical Association', 'The Royal Dutch Medical Association (Koninklijke Nederlandsche Maatschappij tot bevordering der Geneeskunst, or KNMG) is the primary professional organization for physicians in the Netherlands. Established in 1849, the association represents medical doctors and students across the country, serving as a key regulatory and advisory body that formulates ethical guidelines, professional standards, and policy recommendations for Dutch healthcare.

In 2010, the KNMG became a central figure in international bioethical debates by publishing its landmark policy statement, ''Non-therapeutic circumcision of male minors.'' Supported by several other Dutch medical specialty societies, the viewpoint concluded that non-therapeutic male circumcision lacks medical justification, carries risk of physical and psychological harm, and infringes upon a minor''s fundamental right to bodily integrity. The organization advised doctors to actively inform parents of these harms and recommended a policy aimed at discouraging the practice, arguing that decisions regarding genital alteration should be deferred until the individual can make an informed choice for themselves.

The KNMG''s rigorous positioning provided significant institutional backing to the global intactivist and genital autonomy movements. Its 2010 statement set a major precedent for medical organizations across Europe, influencing subsequent policy positions by other Scandinavian and Western European medical bodies and elevating the issue of male non-therapeutic circumcision to a human rights framework.', '', '', 'champion', 'National medical association whose landmark 2010 policy statement formally recognized non-therapeutic male circumcision as a violation of children''s rights and bodily integrity.', 1, '[{"name": "Peter W. Adler", "score": 8.851, "shared_docs": 7}, {"name": "John Locke", "score": 8.781, "shared_docs": 2}, {"name": "American Congress of Obstetricians and Gynecologists", "score": 8.366, "shared_docs": 2}, {"name": "William E. Brigman", "score": 8.366, "shared_docs": 2}, {"name": "Parliamentary Assembly of the Council of Europe", "score": 8.366, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-a52abafe', 'organization', 'Doctors Opposing Circumcision', 'Doctors Opposing Circumcision (DOC) is an international non-profit organization founded in 1995 by physicians and healthcare professionals in Seattle, Washington. The organization was established to educate medical professionals, parents, and policymakers regarding the anatomical, ethical, and legal aspects of routine non-therapeutic infant and pediatric circumcision. Emphasizing evidence-based medicine and patient rights, DOC advocates for the preservation of normal genital anatomy and the principle of bodily integrity for children.

Throughout its existence, DOC has actively participated in medical and public discourse by producing clinical information, reviewing policy guidelines, and providing expert analysis on male foreskin anatomy and function. The group frequently submits formal responses and critiques to professional medical associations, such as the American Academy of Pediatrics (AAP), challenging arguments that support routine neonatal circumcision and advocating for standards of practice aligned with international bioethics and human rights frameworks.', '', '', 'champion', 'An international organization of physicians and healthcare professionals advocating against routine non-therapeutic neonatal circumcision.', 1, '[{"name": "George Hill", "score": 9.488, "shared_docs": 6}, {"name": "John Geisheker", "score": 8.903, "shared_docs": 2}, {"name": "Ronald H Gray", "score": 8.903, "shared_docs": 2}, {"name": "William A. Jellison", "score": 8.903, "shared_docs": 2}, {"name": "Ryan McAllister", "score": 8.903, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-a1f51dd4', 'person', 'Dan Bollinger', 'Dan Bollinger is an American researcher and prominent advocate within the genital autonomy movement. Best known for his quantitative anatomical and histological investigations into the human prepuce, Bollinger has contributed significant research examining the physical structure, surface area, and specialized nerve tissue lost through routine neonatal circumcision.

Bollinger''s published work has focused on the biomechanical and sexual functions of the foreskin, challenging medical perspectives that frame male circumcision as a minor or health-neutral procedure. His studies have been presented at international academic symposia and published in peer-reviewed journals, providing empirical data frequently cited by intactivist organizations and bioethicists to argue against non-consensual infant genital surgery.

Throughout his career, Bollinger has remained active in bodily autonomy networks, participating in educational outreach and advocating for legal and policy reforms to protect children from non-therapeutic genital alterations. His contributions have bridged technical anatomical research with grassroots activism to advance the broader intactivist discourse.', '', '', 'champion', 'An independent researcher and advocate known for his anatomical studies documenting the structural and sensory losses caused by male circumcision.', 1, '[{"name": "Boy\u2019s Health Advisory", "score": 9.598, "shared_docs": 2}, {"name": "Men''s Studies Press, LLC", "score": 9.598, "shared_docs": 2}, {"name": "U.S. Census Bureau", "score": 9.598, "shared_docs": 2}, {"name": "David Reimer", "score": 9.183, "shared_docs": 2}, {"name": "Georganne Chapin", "score": 8.861, "shared_docs": 2}]');
