INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-d88bdf69', 'organization', 'National Institutes of Health', 'The National Institutes of Health (NIH) is the primary agency of the United States government responsible for biomedical and public health research. Comprising 27 separate institutes and centers, the agency serves as one of the world''s foremost medical research centers and the primary federal provider of health-related research grants. Through its scientific leadership and research funding, the NIH plays a foundational role in shaping public health policy, clinical guidelines, and medical practice both in the United States and internationally.

Within the discourse surrounding circumcision and bodily autonomy, the NIH occupies a central position due to its financial and scientific involvement in major epidemiological studies. Most notably, in the 2000s, the National Institute of Allergy and Infectious Diseases (NIAID)—a division of the NIH—co-funded landmark randomized controlled trials in Sub-Saharan Africa investigating adult male voluntary circumcision as an intervention to reduce female-to-male HIV transmission. The findings from these trials significantly influenced policy positions adopted by global health organizations, including the World Health Organization (WHO) and the Centers for Disease Control and Prevention (CDC).

While the NIH maintains a standard medical and public health research mandate, its publications and funded studies are frequently cited by proponents of circumcision to argue for medical benefits. Conversely, genital autonomy advocates and intactivist scholars regularly engage with NIH-funded research, critically evaluating its methodology, ethical implications, and the validity of extrapolating adult HIV prevention data from high-prevalence areas to routine infant circumcision in Western countries. Consequently, the NIH remains a focal institution in ongoing scientific and ethical debates regarding bodily integrity and medical necessity.', '', '', 'notable', 'Primary medical research agency of the United States federal government whose funded studies significantly influence global policies and debates on male circumcision.', 1, '[{"name": "Fred Nalugoda", "score": 9.931, "shared_docs": 3}, {"name": "Fogarty International Center", "score": 9.931, "shared_docs": 3}, {"name": "Thomas C. Quinn", "score": 9.931, "shared_docs": 3}, {"name": "Uganda Virus Research Institute", "score": 9.516, "shared_docs": 3}, {"name": "David Serwadda", "score": 9.516, "shared_docs": 3}]');
