INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-57f0e47b', 'person', 'Fuambai Ahmadu', 'Fuambai Ahmadu is a Sierra Leonean-American anthropologist whose research focuses on gender, ritual, and female cultural practices in West Africa. She earned her Ph.D. in social anthropology from the London School of Economics and conducted extensive ethnographic research on traditional female initiation societies in Sierra Leone, particularly the Bondo society.

Ahmadu gained international attention for her controversial stance on female genital alteration, often referred to as female genital mutilation or cutting (FGM/C). Having chosen to undergo the ritual initiation herself as an adult, she publicly challenged dominant Western and international anti-FGM frameworks. She argued that female circumcision in its traditional West African contexts is a rite of passage that can enhance female solidarity, social power, and bodily self-determination, rather than serving merely as a tool of patriarchal oppression.

Throughout her academic career and public speaking engagements, Ahmadu published work critiquing anti-circumcision campaigns for what she characterized as cultural ethnocentrism and pathologization of African women''s bodies. Her perspectives sparked rigorous debate within feminist, human rights, and intactivist discourse, positioning her as a prominent voice in debates surrounding genital modifications, cultural rights, and bodily autonomy.', '', '', 'critic', 'Sierra Leonean-American anthropologist known for defending traditional female circumcision practices and challenging Western anti-FGM discourse.', 1, '[{"name": "Carla Obermeyer", "score": 10.29, "shared_docs": 2}, {"name": "Carla Makhlouf Obermeyer", "score": 9.875, "shared_docs": 3}, {"name": "Kennedy Institute of Ethics", "score": 9.875, "shared_docs": 2}, {"name": "Johns Hopkins University Press", "score": 9.553, "shared_docs": 2}, {"name": "Nancy Ehrenreich", "score": 9.553, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-fd291ebd', 'person', 'Brian D Earp', 'Brian D. Earp is an American bioethicist, philosopher, and scholar recognized for his extensive academic research on the ethics of bodily autonomy, consent, and childhood genital modifications. Holding research positions at institutions such as the University of Oxford, Yale University, and the Hastings Center, Earp''s work bridges bioethics, moral psychology, and legal philosophy to examine moral and medical standards surrounding non-voluntary bodily interventions.', '', '', 'champion', 'Bioethicist and scholar known for his extensive academic research on bodily autonomy, genital modification, and the ethics of non-therapeutic childhood circumcision.', 1, '[{"name": "Uehiro Centre for Practical Ethics", "score": 10.668, "shared_docs": 2}, {"name": "J Steven Svoboda", "score": 10.253, "shared_docs": 2}, {"name": "Dawoodi Bohra", "score": 9.931, "shared_docs": 2}, {"name": "BMJ", "score": 9.668, "shared_docs": 2}, {"name": "Dena Davis", "score": 9.253, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-b4aeb76b', 'organization', 'Malmö University', 'Founded in 1998 and gaining full university status in 2018, Malmö University is a public Swedish higher education institution situated in Malmö, Sweden. Renowned for its focus on multidisciplinary research, health sciences, and social policy, the university plays an active role in examining contemporary human rights debates, public health policy, and legal ethics within both Scandinavian and international contexts.

Within the discourse on circumcision and bodily autonomy, Malmö University serves as an academic venue where scholars analyze the intersections of children''s rights, bodily integrity, and religious practices. Researchers linked to the institution have contributed to sociological and legal analyses regarding non-therapeutic male circumcision, frequently evaluating these practices against Sweden''s legal framework and international human rights benchmarks such as the UN Convention on the Rights of the Child.

By facilitating scholarly inquiry and debate, Malmö University provides objective research that informs public policy and bioethical discourse. The university''s published work offers crucial context regarding how Nordic societies navigate the complex balance between freedom of religion, parental rights, and the physical rights of minors.', '', '', 'notable', 'A Swedish academic institution contributing scholarly research to the fields of bioethics, children''s rights, and bodily integrity.', 1, '[{"name": "Uppsala University", "score": 11.083, "shared_docs": 4}, {"name": "Anna Wahlberg", "score": 10.82, "shared_docs": 2}, {"name": "Birgitta Ess\u00e9n", "score": 10.235, "shared_docs": 4}, {"name": "Sara Johnsdotter", "score": 10.052, "shared_docs": 9}, {"name": "Carla Makhlouf Obermeyer", "score": 9.82, "shared_docs": 2}]');
