INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-bc1ff852', 'organization', 'World Health Organization (WHO)', 'Established in 1948 as a specialized agency of the United Nations, the World Health Organization (WHO) is responsible for directing and coordinating international public health policy. Headquartered in Geneva, Switzerland, the organization provides health leadership, sets global health standards, and articulates evidence-based policy options across its member states.

The WHO became a central entity in modern circumcision discourse following its 2007 joint consultation with UNAIDS, which formally recommended voluntary medical male circumcision (VMMC) as an additional HIV prevention strategy in countries with high HIV prevalence and low baseline rates of male circumcision, primarily in sub-Saharan Africa. This recommendation relied heavily on data from three randomized controlled trials conducted in South Africa, Kenya, and Uganda, which indicated a reduction in female-to-male HIV transmission risk.

While the WHO framing presents circumcision as an effective biomedical intervention for disease control, its global campaigns have generated significant debate within bioethics, human rights, and intactivist communities. Critics and genital autonomy advocates contend that mass circumcision initiatives risk overriding individual bodily autonomy, raise ethical concerns regarding infant and adolescent consent, and understate surgical complication risks, placing the organization at the center of international debates surrounding medical ethics and bodily integrity.', '', '', 'critic', 'Specialized United Nations agency whose global health policy endorsing medical male circumcision for HIV prevention became a central subject of international bioethical debate.', 1, '[{"name": "Alain Giami", "score": 8.2, "shared_docs": 3}, {"name": "United Nations (UN)", "score": 8.2, "shared_docs": 4}, {"name": "Richard G Wamai", "score": 8.2, "shared_docs": 3}, {"name": "United Nations Population Fund (UNFPA)", "score": 7.978, "shared_docs": 6}, {"name": "Yoweri Museveni", "score": 7.878, "shared_docs": 4}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-40c8d0b1', 'organization', 'UNICEF', 'The United Nations Children''s Fund (UNICEF) is a global agency established in 1946 to advocate for the protection, health, and development of children worldwide. Within the domain of bodily autonomy, UNICEF has long served as a leading international institution in campaigns to eliminate Female Genital Mutilation/Cutting (FGM/C). Working in partnership with governments, non-governmental organizations, and other United Nations entities, UNICEF has consistently framed non-consensual female genital alterations as a severe violation of child rights, health, and physical integrity.

Regarding male circumcision, UNICEF''s role has largely intersected with global public health campaigns. In high-prevalence HIV regions, particularly across Eastern and Southern Africa, UNICEF has collaborated with organizations such as the World Health Organization (WHO) and UNAIDS to support Voluntary Medical Male Circumcision (VMMC) programs targeted at adolescents and men as a disease prevention strategy. These public health initiatives have positioned the agency at the center of ongoing global health discussions.

Within intactivist and bioethical discourse, UNICEF is frequently referenced both as a model for rights-based advocacy against forced genital cutting and as a target of critique. Critics and bodily autonomy advocates often argue that the child rights principles codified in the UN Convention on the Rights of the Child should extend universally to protect all infants and children, regardless of sex or gender, from non-therapeutic genital alterations. As a result, UNICEF remains a key focal point in international debates surrounding bodily integrity, human rights consistency, and health policy.', '', '', 'notable', 'United Nations agency prominent in global efforts to eliminate female genital cutting and a central focal point in international bodily autonomy debates.', 1, '[{"name": "UNFPA", "score": 8.96, "shared_docs": 11}, {"name": "Nawal El-Saadawi", "score": 8.96, "shared_docs": 3}, {"name": "Mustafa Kamal Al-Mahdawi", "score": 8.96, "shared_docs": 3}, {"name": "Mahmud Shaltut", "score": 8.96, "shared_docs": 3}, {"name": "Sami A. Aldeeb Abu-Sahlieh", "score": 8.638, "shared_docs": 4}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-903d53f9', 'organization', 'UNFPA', 'Established in 1969 as the United Nations Fund for Population Activities (now known as the United Nations Population Fund), UNFPA is the primary UN agency tasked with advocating for sexual and reproductive health, gender equality, and human rights globally. Operating in over 150 countries, the agency works with governments and civil society organizations to deliver healthcare services, establish international health policies, and protect bodily autonomy within global development frameworks.

Within the discourse surrounding genital autonomy, UNFPA is widely recognized for its opposition to female genital mutilation/cutting (FGM/C). Since 2008, the agency has co-led the UNFPA-UNICEF Joint Programme on the Elimination of Female Genital Mutilation, framing the practice as a harmful tradition and a direct violation of the human rights and bodily integrity of women and girls. Through this initiative, UNFPA supports legal bans, community-led education campaigns, and healthcare training to eliminate FGM/C worldwide.

At the same time, UNFPA''s scope intersects with male circumcision through its historic involvement with UNAIDS and the World Health Organization in supporting Voluntary Medical Male Circumcision (VMMC) campaigns for HIV prevention in eastern and southern Africa. This dual engagement places UNFPA at the center of ongoing sociological and legal discussions regarding global health ethics, consent, and the application of human rights frameworks to different forms of bodily alteration.', '', '', 'notable', 'The United Nations sexual and reproductive health agency, influential in global efforts to eliminate female genital mutilation and in public health frameworks concerning male circumcision.', 1, '[{"name": "Janice Boddy", "score": 10.379, "shared_docs": 3}, {"name": "Bettina Shell-Duncan", "score": 9.893, "shared_docs": 3}, {"name": "USAID", "score": 9.794, "shared_docs": 2}, {"name": "Nawal El Saadawi", "score": 9.794, "shared_docs": 2}, {"name": "Ellen Gruenbaum", "score": 9.241, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-8870f1fd', 'person', 'Sigmund Freud', 'Sigmund Freud (1856–1939) was an Austrian neurologist and the founder of psychoanalysis, a clinical framework for evaluating and treating psychopathology through dialogue between a patient and a psychoanalyst. Throughout his influential writings, Freud investigated the psychological development of the individual, the structure of the unconscious mind, and the symbolic origins of religious and social rituals. While he did not participate in modern medical or human rights debates concerning genital autonomy, his theoretical framework profoundly shaped subsequent psychological and sociological interpretations of circumcision.', '', '', 'notable', 'Austrian neurologist and founder of psychoanalysis whose theories famously linked circumcision to castration anxiety and unconscious psychological trauma.', 1, '[{"name": "Frederick M. Hodges", "score": 9.903, "shared_docs": 2}, {"name": "Bruno Bettelheim", "score": 9.903, "shared_docs": 4}, {"name": "Anna Freud", "score": 9.903, "shared_docs": 2}, {"name": "George Wald", "score": 9.488, "shared_docs": 2}, {"name": "Desmond Morris", "score": 9.166, "shared_docs": 2}]');
