INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-bb484fbe', 'organization', 'United Nations', 'Founded in 1945, the United Nations (UN) is the premier international organization tasked with promoting international cooperation, peace, and human rights. Within the discourse surrounding bodily autonomy, integrity, and circumcision, the UN and its specialized agencies—including the World Health Organization (WHO), UNICEF, and the Office of the High Commissioner for Human Rights (OHCHR)—serve as pivotal reference points through their global treaties, health guidelines, and human rights declarations.

The UN''s foundational human rights documents, particularly the 1989 Convention on the Rights of the Child (UNCRC), are frequently cited by bodily autonomy advocates and intactivists to argue that children possess a fundamental right to protection from non-consensual bodily modification. Furthermore, UN agencies have led international efforts to eradicate female genital mutilation (FGM), establishing global consensus that non-therapeutic female genital alterations constitute a severe human rights violation.

Conversely, UN bodies such as WHO and UNAIDS have endorsed and funded Voluntary Medical Male Circumcision (VMMC) programs in Sub-Saharan Africa as a public health measure to reduce HIV transmission. This stance has made the UN a central focal point in global bioethical debates, with critics highlighting perceived inconsistencies in how bodily autonomy standards are applied across sexes, while proponents view these health initiatives as targeted epidemiological interventions.', '', '', 'notable', 'International organization whose human rights treaties and public health policies on genital practices make it a focal point in global bodily autonomy debates.', 1, '[{"name": "Ecumenics International, Inc.", "score": 8.116, "shared_docs": 2}, {"name": "International Federation of Gynecology and Obstetrics", "score": 7.701, "shared_docs": 3}, {"name": "Carla Obermeyer", "score": 7.531, "shared_docs": 2}, {"name": "Physicians for Human Rights", "score": 7.531, "shared_docs": 2}, {"name": "National Organization of Circumcision Information Centers", "score": 7.531, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-2e1c1585', 'organization', 'Council of Europe', 'The Council of Europe is an international organization founded in 1949 to uphold human rights, democracy, and the rule of law across its European member states. Headquartered in Strasbourg, France, the institution operates independently of the European Union and oversees the European Court of Human Rights. Throughout its history, the Council has developed legal standards and conventions aimed at protecting vulnerable populations, particularly children, from physical harm and institutional neglect.

In the context of bodily autonomy and genital integrity, the Council of Europe became a central focal point following a landmark vote by its Parliamentary Assembly (PACE) in October 2013. Resolution 1952, titled "Children''s right to physical integrity," classified non-therapeutic male circumcision alongside practices such as female genital mutilation, intersex surgeries, and corporal punishment. The resolution urged member states to initiate public debate, raise awareness regarding health risks, and establish regulatory frameworks to ensure that non-consensual bodily alterations on minors are restricted until a child is old enough to be consulted.

The adoption of Resolution 1952 sparked significant international debate, drawing both strong support from bodily autonomy advocates and criticism from religious groups and political figures concerned about freedom of religion. Intactivist organizations recognized the Council''s statement as a major institutional milestone in framing non-therapeutic infant circumcision as a human rights issue. Subsequent discussions within the Council continued to balance religious rights with the evolving legal recognition of children''s rights to physical integrity.', '', '', 'champion', 'An international human rights organization whose 2013 Parliamentary Assembly resolution formally addressed non-therapeutic male circumcision within the framework of children''s physical integrity.', 1, '[{"name": "Belgian Advisory Committee on Bioethics", "score": 9.82, "shared_docs": 2}, {"name": "European Parliament", "score": 9.82, "shared_docs": 2}, {"name": "Parliamentary Assembly of the Council of Europe (PACE)", "score": 9.405, "shared_docs": 2}, {"name": "Central Michigan University College of Medicine", "score": 9.083, "shared_docs": 2}, {"name": "European Court of Human Rights", "score": 9.083, "shared_docs": 2}]');
