INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-cd0fc853', 'person', 'Angela Merkel', 'Angela Merkel served as the Chancellor of Germany from 2005 to 2021, leading the Christian Democratic Union (CDU) and becoming one of the most influential political leaders in Europe. Before her political career, she trained as a quantum chemist and worked as a research scientist in East Berlin. During her sixteen years in office, her administration navigated numerous domestic and international challenges, including significant legal debates regarding religious freedom and children''s physical integrity.

Merkel became a central figure in the European discourse on circumcision following a landmark May 2012 ruling by a regional court in Cologne (Landgericht Köln). The court determined that non-therapeutic infant male circumcision constituted illegal bodily harm, placing the child''s right to physical integrity above parental rights and religious freedom. The ruling sparked intense debate worldwide and drew strong reactions from Jewish and Muslim communities, who feared the practice would be criminalised across Germany.

In response to the Cologne court''s ruling, Merkel intervened politically, warning that prohibiting the practice would make Germany a laughing stock and compromise religious freedom. Her government quickly drafted and championed federal legislation—Section 1631d of the German Civil Code—which was passed in December 2012. The law explicitly granted parents the right to consent to the non-therapeutic circumcision of their infant sons, provided it is performed according to medical standards, thereby overruling the legal precedent set by the Cologne court.', '', '', 'critic', 'Former Chancellor of Germany who spearheaded federal legislation to legalise non-therapeutic male circumcision following a landmark 2012 court ruling.', 1, '[{"name": "German Bundestag", "score": 11.116, "shared_docs": 3}, {"name": "Charlotte Knobloch", "score": 10.701, "shared_docs": 3}, {"name": "Central Council of Jews in Germany", "score": 10.531, "shared_docs": 2}, {"name": "Deutscher Ethikrat", "score": 10.531, "shared_docs": 2}, {"name": "Landgericht K\u00f6ln", "score": 9.978, "shared_docs": 5}]');
