INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-cef13d03', 'person', 'Immanuel Kant', 'Immanuel Kant (1724–1804) was a seminal German philosopher of the Enlightenment whose work radically transformed Western metaphysics, epistemology, and moral theory. A long-time professor at the University of Königsberg, Kant developed a deontological framework that prioritized rational agency, moral duty, and individual self-determination. His philosophical treatises, particularly the "Groundwork of the Metaphysics of Morals", established foundational concepts of human dignity that continue to shape modern legal, bioethical, and human rights frameworks.

Although Kant lived prior to the modern movement for genital autonomy, his ethical philosophy is frequently cited in contemporary scholarship regarding circumcision and bodily integrity. In particular, his formulation of the Categorical Imperative—which mandates that human beings must be treated as ends in themselves, never merely as a means to an end—serves as a primary theoretical foundation for critics of non-consensual pediatric circumcision. Intactivist scholars and ethicists utilize Kantian ethics to argue that performing irreversible, non-therapeutic bodily alterations on infants violates their inherent moral autonomy and dignity.', '', '', 'notable', 'Eighteenth-century German philosopher whose ethical principles of human dignity and autonomy provide a foundational framework for modern arguments against non-consensual bodily alterations.', 0, '[{"name": "BMJ", "score": 10.405, "shared_docs": 2}, {"name": "United Nations", "score": 6.531, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-14ae5945', 'person', 'Xavier Castellsagué', 'Xavier Castellsagué (1959–2016) was a Spanish epidemiologist and public health researcher best known for his extensive contributions to the study of human papillomavirus (HPV), cervical cancer, and the preventative role of male circumcision against sexually transmitted infections. Holding a medical degree and a doctorate in epidemiology, Castellsagué served as a senior researcher at the Catalan Institute of Oncology (ICO) in Barcelona and collaborated frequently with the International Agency for Research on Cancer (IARC) and the World Health Organization.

Castellsagué became a central figure in global circumcision discourse following the publication of his landmark 2002 study in the New England Journal of Medicine. His research demonstrated a strong inverse association between male circumcision and penile HPV infection, suggesting that circumcision in men reduced the risk of cervical cancer in their female sexual partners. These findings provided key scientific backing that health organizations around the world subsequently cited to support male circumcision as a strategy for disease prevention.

Within the debate over genital autonomy and intactivism, Castellsagué''s epidemiological findings are frequently cited by proponents of circumcision to argue for its public health benefits. Conversely, intactivist scholars and bodily autonomy advocates have critically scrutinized his observational methodologies and contested the application of his findings to justify routine neonatal or non-consensual male circumcision.', '', '', 'critic', 'Spanish epidemiologist whose landmark research on male circumcision and HPV transmission significantly shaped global public health policies.', 0, '[{"name": "Ginesa Albero", "score": 12.253, "shared_docs": 3}, {"name": "Elsevier Ltd.", "score": 11.253, "shared_docs": 2}, {"name": "Michigan State University College of Human Medicine", "score": 10.253, "shared_docs": 2}, {"name": "Robert S. Van Howe", "score": 7.699, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 5.303, "shared_docs": 3}]');
