INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-0b78f3c7', 'person', 'Sami A. Aldeeb Abu-Sahlieh', 'Sami A. Aldeeb Abu-Sahlieh is a Palestinian-Swiss legal scholar, author, and expert in Islamic and comparative law. He earned his doctorate in law from the University of Fribourg and served for decades as a senior researcher responsible for Arab and Islamic law at the Swiss Institute of Comparative Law in Lausanne. Throughout his career, he has published extensively on religious freedoms, human rights, and the legal status of religious minorities and customs in both Western and Islamic legal traditions.

Within the discourse on genital integrity, Aldeeb is widely recognized for his interdisciplinary scholarship critiquing both male and female genital alteration. His seminal works examine circumcision through the lenses of Jewish, Christian, and Islamic theology, alongside international human rights law. Aldeeb consistently argues that non-consensual, non-therapeutic genital cutting performed on minors constitutes a violation of bodily integrity and fundamental rights, advocating for equal legal protection against non-therapeutic body modifications for children of all genders.', '', '', 'champion', 'Palestinian-Swiss legal scholar and author renowned for his comprehensive legal and comparative studies opposing male and female genital cutting.', 0, '[{"name": "Swiss Institute of Comparative Law", "score": 12.253, "shared_docs": 4}, {"name": "Nawal El-Saadawi", "score": 11.668, "shared_docs": 2}, {"name": "Mustafa Kamal Al-Mahdawi", "score": 11.668, "shared_docs": 2}, {"name": "Mahmud Shaltut", "score": 11.668, "shared_docs": 2}, {"name": "G\u00e9rard Zwang", "score": 11.253, "shared_docs": 2}]');
