INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e17343a6', 'organization', 'Al-Azhar University', 'Founded in Cairo during the tenth century, Al-Azhar University serves as Sunni Islam''s premier seat of learning and religious authority. Its scholars and Islamic research assemblies issue legal rulings (fatwas) that shape legal, cultural, and ethical frameworks across the Muslim world. Within socio-legal discourses on bodily autonomy and ritual modification, Al-Azhar occupies an influential position, frequently consulted by international human rights bodies, governments, and medical organizations.

In the ongoing global effort to eradicate female genital mutilation/cutting (FGM/C), Al-Azhar played a prominent role in reshaping religious interpretation. Leadership figures, including former Grand Sheikh Mohamed Sayyed Tantawi, issued decisive declarations establishing that FGM/C had no valid religious foundation in Islam and constituted a harmful violation of physical integrity. These stances provided essential theological grounding for legislative prohibitions in Egypt and anti-FGM/C health campaigns internationally.

Regarding male circumcision (khitan), Al-Azhar continues to uphold traditional Sunni legal consensus, regarding the practice as an established religious obligation or strongly recommended tradition. The university''s scholars navigate complex intersections of religious heritage, public health policies, and human rights law, rendering the institution a critical locus of authority concerning ritual cutting, state regulation, and bodily autonomy.', '', '', 'notable', 'A historic Islamic university in Cairo whose religious decrees heavily influence legal, public health, and human rights discourses on circumcision and female genital cutting.', 1, '[{"name": "Nawal El-Saadawi", "score": 11.405, "shared_docs": 3}, {"name": "Mustafa Kamal Al-Mahdawi", "score": 11.405, "shared_docs": 3}, {"name": "Mahmud Shaltut", "score": 11.405, "shared_docs": 3}, {"name": "G\u00e9rard Zwang", "score": 10.99, "shared_docs": 3}, {"name": "William A. Jellison", "score": 10.82, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-375ad6a4', 'organization', 'Inter-African Committee', 'The Inter-African Committee on Traditional Practices Affecting the Health of Women and Children (IAC) is a prominent African non-governmental organization founded in 1984 in Dakar, Senegal. Established following a landmark seminar on traditional practices affecting the health of women and children, the IAC was formed to lead regional and global efforts against harmful traditional practices, most notably female genital mutilation (FGM) and early forced marriage.

Throughout its history, the IAC has been instrumental in framing female circumcision as a critical issue of bodily autonomy, public health, and human rights. By coordinating a network of national committees across African states, the organization engaged in community outreach, educational campaigns, and policy advocacy. Its efforts contributed significantly to international declarations, the drafting of the Maputo Protocol, and national legislative bans against FGM across the African continent.

Through partnerships with the World Health Organization, UNICEF, and the African Union, the Inter-African Committee helped shape global discourse around female genital alteration and child protection. Its decades of advocacy established foundational frameworks for bodily integrity and rights-based opposition to non-consensual female genital procedures.', '', '', 'champion', 'A pioneering African organization dedicated to eliminating female genital mutilation and advocating for the bodily integrity of women and children.', 0, '[{"name": "Somali Women''s Democratic Organization (SWDO)", "score": 11.183, "shared_docs": 2}, {"name": "Fran P. Hosken", "score": 9.545, "shared_docs": 3}, {"name": "James DeMeo", "score": 7.861, "shared_docs": 2}, {"name": "UNICEF", "score": 7.153, "shared_docs": 2}, {"name": "World Health Organization (WHO)", "score": 6.978, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-2a89a5ff', 'person', 'Abraham', 'Abraham is the central patriarch in the Judeo-Christian and Islamic traditions, recognized in biblical accounts as the foundational figure who established the covenant of ritual circumcision. According to the Book of Genesis, God commanded Abraham to circumcise himself, his household, and all male descendants on the eighth day of life as an everlasting mark of their covenant. Biblical text records that Abraham performed the ritual on himself at ninety-nine years of age, on his son Ishmael, and later on his infant son Isaac, establishing a practice that became central to Jewish identity as Brit Milah and later influenced Islamic traditions of Khitan.

Within historical and theological discourse surrounding circumcision, Abraham represents the primary scriptural origin for mandatory male genital alteration. For millennia, religious adherents and defenders of traditional circumcision have cited Abraham''s obedience to the divine command as a foundational moral and spiritual obligation. Consequently, his narrative remains the cornerstone for theological defenses of infant male circumcision across Abrahamic faiths.

In contemporary discussions regarding bodily autonomy and intactivism, the Abrahamic narrative is frequently critically examined by ethicists and human rights advocates. Scholars analyzing the history of genital cutting view the Abrahamic tradition as the pivotal cultural transmission point that institutionalized non-therapeutic infant circumcision, serving as a key focal point in modern debates concerning the balance between ancestral religious practice and a child''s right to bodily integrity.', '', '', 'critic', 'Biblical patriarch regarded as the foundational figure who introduced male ritual circumcision in Abrahamic religious traditions.', 1, '[{"name": "Ishmael", "score": 11.253, "shared_docs": 3}, {"name": "Isaac", "score": 11.253, "shared_docs": 3}, {"name": "Ronald S. Immerman and Wade C. Mackey", "score": 9.446, "shared_docs": 2}, {"name": "Moses Maimonides", "score": 7.629, "shared_docs": 3}]');
