INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-dac6ec4c', 'organization', 'United Nations Population Fund (UNFPA)', 'The United Nations Population Fund (UNFPA), originally established in 1969 as the United Nations Fund for Population Activities, is the UN''s dedicated sexual and reproductive health agency. Its global mandate centers on expanding access to reproductive healthcare, ending gender-based violence, preventing maternal mortality, and promoting human rights and bodily integrity for vulnerable populations worldwide.

Within the discourse on genital autonomy, UNFPA occupies a prominent position primarily through its opposition to female genital mutilation/cutting (FGM/C). Co-leading the UNFPA-UNICEF Joint Programme on the Elimination of Female Genital Mutilation, the organization advocates for national legislative bans, community education, and human rights frameworks aimed at preserving the bodily integrity of girls and women.

Conversely, in the context of male circumcision, UNFPA has partnered with organizations such as the World Health Organization (WHO) and UNAIDS to support Voluntary Medical Male Circumcision (VMMC) programs as part of comprehensive HIV prevention strategies in Eastern and Southern Africa. This dual engagement places UNFPA at a central intersection of public health policy and human rights debates surrounding bodily autonomy and circumcision.', '', '', 'notable', 'The United Nations agency dedicated to sexual and reproductive health, active in global campaigns against female genital mutilation and HIV prevention initiatives.', 0, '[{"name": "European Parliament", "score": 11.183, "shared_docs": 2}, {"name": "Council of Europe", "score": 8.598, "shared_docs": 2}, {"name": "UNICEF", "score": 8.153, "shared_docs": 4}, {"name": "World Health Organization (WHO)", "score": 7.978, "shared_docs": 6}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-1193d204', 'person', 'Jim Bigelow', 'Jim Bigelow, Ph.D., was an American psychologist, pastoral counselor, and early advocate in the intactivist movement. He emerged as a prominent voice in bodily autonomy discourse during the late 20th century, applying psychological and anatomical insights to challenge the prevalence of routine neonatal male circumcision in the United States.', '', '', 'champion', 'American psychologist, author, and intactivist pioneer best known for writing The Joy of Uncircumcised Sex.', 1, '[{"name": "Shelton Walden", "score": 9.253, "shared_docs": 3}, {"name": "Brothers United for Future Foreskins (BUFF)", "score": 8.838, "shared_docs": 3}, {"name": "Nawal El-Saadawi", "score": 8.668, "shared_docs": 2}, {"name": "Mustafa Kamal Al-Mahdawi", "score": 8.668, "shared_docs": 2}, {"name": "Mahmud Shaltut", "score": 8.668, "shared_docs": 2}]');
