INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-2beee7cb', 'organization', 'NOHARMM', 'NOHARMM (National Organization to Halt the Abuse and Routine Mutilation of Males) is an advocacy organization established in 1992 by Tim Hammond. Operating as a human rights and consumer protection group, NOHARMM was founded to campaign against routine infant male circumcision and to highlight the ethical, physical, and psychological issues associated with non-consensual foreskin removal.

The organization has been instrumental in conducting community-based research and advocacy, notably publishing studies such as the Global Survey of Circumcised Men to document the long-term emotional and physical impacts reported by circumcised individuals. NOHARMM provides educational resources, support networks for men experiencing grief or trauma related to circumcision, and information on foreskin restoration.

Throughout its history, NOHARMM has remained a prominent voice within the intactivist movement, advancing the argument that infant circumcision constitutes a violation of bodily autonomy and fundamental human rights. By participating in academic conferences, media engagements, and grassroots organizing, the organization has consistently challenged prevailing medical and societal norms regarding routine infant circumcision.', '', '', 'champion', 'An advocacy organization dedicated to ending routine infant male circumcision and providing support and resources for circumcised men.', 1, '[{"name": "Tom Morris", "score": 9.516, "shared_docs": 3}, {"name": "Hammond", "score": 9.346, "shared_docs": 2}, {"name": "NOHARMM (National Organization to Halt the Abuse and Routine Mutilation of Males)", "score": 8.709, "shared_docs": 3}, {"name": "Duane Jorde", "score": 8.609, "shared_docs": 2}, {"name": "Soraya Mire", "score": 8.194, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e1b4700a', 'organization', 'American Society of Plastic Surgeons', 'Founded in 1931, the American Society of Plastic Surgeons (ASPS) is the largest specialty organization of board-certified plastic surgeons in the world. Representing thousands of physicians globally, the society establishes clinical practice standards, promotes patient safety, and advances educational resources across reconstructive and cosmetic surgical disciplines.

Within the discourse on circumcision and bodily autonomy, the ASPS intersects with genital surgery primarily through reconstructive procedures, cosmetic penile surgeries, and the surgical management of circumcision complications. Plastic surgeons represented by the organization are frequently involved in repairing severe complications resulting from neonatal circumcisions—such as penile skin loss, meatal stenosis, or scarring—as well as performing adult reconstructive procedures and foreskin restoration consults.

While the ASPS is not a primary policy-making body for routine infant circumcision policy—which is typically overseen by pediatric associations—its clinical framework emphasizes patient safety, rigorous informed consent, and ethical considerations surrounding elective aesthetic and reconstructive procedures. The society''s clinical presence highlights the physical outcomes of neonatal surgical errors and the medical pathways available for individuals seeking bodily repair or restoration in adulthood.', '', '', 'notable', 'The world''s largest plastic surgery organization, involved in the clinical discourse on reconstructive penile surgery, complication repair, and surgical consent.', 0, '[{"name": "World Professional Association for Transgender Health", "score": 11.253, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-b4f0c923', 'organization', 'World Health Organisation', 'The World Health Organization (WHO) is a specialized agency of the United Nations responsible for international public health. Established in 1948 and headquartered in Geneva, Switzerland, the agency plays a directive role in global health policy, disease prevention, and public health guidelines. Its recommendations significantly influence national healthcare policies, international funding priorities, and medical research directives worldwide.

Within the context of bodily autonomy and genital integrity debates, the WHO emerged as a central figure following its 2007 joint recommendation with UNAIDS. The organization formally endorsed Voluntary Medical Male Circumcision (VMMC) as an additional, effective intervention for HIV prevention in high-prevalence, heterosexually driven epidemics, primarily focusing on eastern and southern Africa. This initiative led to massive international campaigns that resulted in tens of millions of surgical circumcisions across target countries.

The WHO''s promotional stance on male circumcision generated substantial pushback from intactivist organizations, bioethicists, and human rights advocates. Opponents argue that the agency''s frameworks overestimate the population-level prophylactic efficacy of circumcision, minimize surgical risks, and undercut principles of bodily integrity and informed consent. Furthermore, critics express concern over how WHO endorsements of male circumcision risk normalizing non-therapeutic infant and pediatric genital alterations globally.', '', '', 'critic', 'Specialized United Nations public health agency whose promotion of medical male circumcision for HIV prevention made it a primary target of global intactivist critique.', 1, '[{"name": "Kate Goldie Townsend", "score": 10.99, "shared_docs": 3}, {"name": "Clare Chambers", "score": 10.405, "shared_docs": 2}, {"name": "University of Exeter", "score": 10.405, "shared_docs": 2}, {"name": "Dena Davis", "score": 8.99, "shared_docs": 2}, {"name": "Royal Australasian College of Physicians", "score": 6.742, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-c5ea7c95', 'organization', 'Jhpiego', 'Jhpiego, an international non-profit healthcare organization affiliated with Johns Hopkins University, was founded in 1973 initially to improve maternal and child health services in low- and middle-income countries. Over the decades, the organization expanded its scope to encompass global infectious disease control, health workforce training, and reproductive health initiatives across Africa, Asia, and Latin America.

Within the global discourse on male circumcision, Jhpiego became a key implementing partner for large-scale public health initiatives supported by the World Health Organization (WHO) and the U.S. President''s Emergency Plan for AIDS Relief (PEPFAR). The organization has played a significant role in scaling up Voluntary Medical Male Circumcision (VMMC) programs across Sub-Saharan Africa, framing surgical male circumcision as an essential intervention for reducing heterosexual HIV transmission in high-prevalence regions.

While public health agencies applaud Jhpiego for its technical training and health infrastructure delivery, its prominent involvement in mass circumcision campaigns has drawn scrutiny from bodily autonomy advocates and intactivist organizations. Critics argue that public health frameworks prioritizing VMMC underemphasize ethical concerns regarding informed consent, bodily integrity, and alternative non-surgical HIV prevention methods.', '', '', 'critic', 'An international public health organization affiliated with Johns Hopkins University that actively implements voluntary medical male circumcision programs across Sub-Saharan Africa.', 0, '[{"name": "London School of Hygiene and Tropical Medicine", "score": 9.82, "shared_docs": 2}, {"name": "UNAIDS", "score": 8.083, "shared_docs": 5}, {"name": "American Academy of Pediatrics (AAP)", "score": 7.318, "shared_docs": 2}, {"name": "World Health Organization (WHO)", "score": 7.2, "shared_docs": 3}, {"name": "World Health Organization", "score": 5.99, "shared_docs": 3}]');
