INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-45402e6e', 'person', 'Jonathan A. Allan', 'Jonathan A. Allan is a Canadian scholar, author, and Canada Research Chair in Men and Masculinities at Brandon University. He earned his Ph.D. in Comparative Literature from the University of Toronto, focusing his research on critical studies of men and masculinities, literary theory, and cultural representations of the male body.

Allan is particularly recognized in the discourse surrounding bodily autonomy and genital integrity for his groundbreaking 2018 monograph, *Reading the Foreskin: Circumcision, Anatomy, and Heritage*. In this work, he critically examines the historical, literary, and cultural significance of the foreskin, interrogating how circumcision and male genital alteredness shape contemporary understandings of gender, vulnerability, and bodily integrity.

Through his academic writing and public scholarship, Allan has contributed significantly to legitimizing the foreskin and circumcision as critical subjects of academic inquiry. His work bridges humanities research with gender studies, offering insightful analyses of the social norms and emotional complexities surrounding male bodily autonomy.', '', '', 'notable', 'Academic scholar and author of Reading the Foreskin, specializing in critical masculinities and the cultural history of male genital integrity.', 0, '[{"name": "Brandon University", "score": 11.99, "shared_docs": 5}, {"name": "Leo Rosenhouse", "score": 11.405, "shared_docs": 2}, {"name": "University of Nairobi", "score": 10.668, "shared_docs": 2}, {"name": "National Organization of Restoring Men (NORM)", "score": 8.183, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 5.04, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-94eba707', 'organization', 'Brandon University', 'Brandon University is a public university located in Brandon, Manitoba, Canada. Tracing its origins back to Brandon College in 1899, the institution has established a long history of liberal arts, science, and professional education in western Canada. The university hosts various academic departments in the social sciences, humanities, and health studies, serving as a hub for regional higher education and interdisciplinary research.', '', '', 'notable', 'A Canadian public university providing an academic venue for scholarly research and bioethical discourse.', 0, '[{"name": "Jonathan A. Allan", "score": 11.99, "shared_docs": 5}, {"name": "Leo Rosenhouse", "score": 11.668, "shared_docs": 2}, {"name": "University of Nairobi", "score": 10.931, "shared_docs": 2}, {"name": "National Organization of Restoring Men (NORM)", "score": 8.446, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 4.718, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-b3d9cec9', 'organization', 'SAGE Publications', 'SAGE Publications is a major independent academic publisher established in 1965 by Sara Miller McCune. Headquartered in Thousand Oaks, California, the company publishes thousands of peer-reviewed journals, books, and reference works spanning the social sciences, humanities, medicine, law, and biomedical ethics. Its extensive global publishing platform plays a foundational role in disseminating scholarly research across diverse academic disciplines.

Within the discourse on circumcision, bodily integrity, and genital autonomy, SAGE Publications serves as a primary host for peer-reviewed sociological, legal, and bioethical literature. Journals under the SAGE umbrella have published critical academic studies analyzing the medicalization of routine neonatal male circumcision, the cultural and socio-historical dimensions of female genital cutting, and the emerging legal frameworks surrounding children''s bodily rights. These publications frequently explore the intersection of medical necessity, parental authority, and human rights.

By facilitating interdisciplinary research, SAGE Publications has significantly contributed to academic and public policy discussions regarding genital autonomy. Its platform provides researchers, ethicists, and activists with empirical data and legal analyses that inform international debates on consent, physical integrity, and medical ethics.', '', '', 'notable', 'A leading global academic publisher disseminating sociological, medical, and bioethical research on circumcision and bodily autonomy.', 0, '');
INSERT OR IGNORE INTO entity_nominations (id, type, name, description, justification, status) VALUES ('nom-1b7f438a', 'person', 'Amanda Kennedy', '', 'Auto-detected: mentioned in 4 archive documents.', 'pending');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-6cab3522', 'person', 'Thomas J. Ritter', 'Thomas J. Ritter, M.D., was an American physician, author, and prominent voice in the movement against routine infant circumcision. Throughout his medical career, Ritter became an outspoken critic of non-therapeutic neonatal genital surgery, arguing that the practice was medically unnecessary, ethically questionable, and harmful to infants. His work contributed substantially to the growing body of medical and popular literature challenging American circumcision practices during the late 20th century.

Ritter gained widespread recognition following the publication of his book, "Say No to Circumcision!" (1992), which was later updated and expanded in collaboration with Dr. George C. Denniston. The book offered a comprehensive overview of the anatomy and function of the foreskin, detailed the physical and psychological risks associated with circumcision, and critically evaluated common medical justifications used to promote the procedure. Designed as an accessible guide for expecting parents, the text served as a foundational resource for the intactivist movement.

In addition to his writing, Ritter engaged in public education and advocacy efforts, frequently collaborating with anti-circumcision organizations such as the National Organization of Circumcision Information Resource Centers (NOCIRC). By leveraging his background as a medical practitioner, he played an important role in lending clinical authority to the defense of bodily autonomy and genital integrity for children.', '', '', 'champion', 'American physician, author, and advocate best known for writing ''Say No to Circumcision!'' in defense of genital integrity.', 1, '[{"name": "National Organization of Circumcision Information and Resource Centers (NOCIRC)", "score": 9.82, "shared_docs": 2}, {"name": "UNCIRC", "score": 9.183, "shared_docs": 3}, {"name": "Anne Briggs", "score": 9.183, "shared_docs": 3}, {"name": "Jim Bigelow", "score": 8.253, "shared_docs": 9}, {"name": "NOCIRC", "score": 7.318, "shared_docs": 4}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-bb85f93a', 'person', 'Lauren M. Sardi', 'Lauren M. Sardi, Ph.D., is an American sociologist and academic whose scholarly work explores the sociology of the body, gender, medicalization, and human sexuality. As a professor of sociology, her research addresses how cultural norms, gender expectations, and institutional medical practices shape bodily autonomy and reproductive health decisions in contemporary society.

Sardi''s contributions to the discourse on circumcision focus on the social, cultural, and ethical dimensions of routine infant male circumcision. Her work critically examines parental decision-making processes, the historical medicalization of the male body, and the ways in which societal perceptions of gender and hygiene perpetuate non-consensual surgical interventions on infants.

Through peer-reviewed publications and academic presentations, Sardi has provided valuable sociological insight into the debates surrounding genital integrity and bodily self-determination. Her research offers scholars, ethicists, and activists a rigorous framework for understanding how bodily autonomy is constructed, contested, and maintained within medical and social institutions.', '', '', 'notable', 'Sociologist and scholar whose research examines the cultural, gendered, and medicalized dimensions of infant circumcision and bodily autonomy.', 0, '[{"name": "William A. Jellison", "score": 11.768, "shared_docs": 3}, {"name": "Quinnipiac University", "score": 11.545, "shared_docs": 6}, {"name": "Ryan McAllister", "score": 11.183, "shared_docs": 2}, {"name": "Amanda Kennedy", "score": 10.768, "shared_docs": 2}, {"name": "Case Western Reserve University School of Law", "score": 10.446, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-aec51975', 'person', 'Judith Butler', 'Judith Butler is an American philosopher, gender theorist, and political theorist whose foundational works have significantly shaped modern understandings of gender, sex, performativity, and bodily integrity. Serving as a distinguished professor in critical theory and comparative literature, Butler gained international theoretical prominence with the publication of her 1990 book, Gender Trouble: Feminism and the Subversion of Identity, which challenged conventional assumptions regarding biological sex and social gender performance.

Within the discourse surrounding bodily autonomy, intersex rights, and circumcision, Butler''s theoretical contributions provide crucial analytical frameworks. Her philosophical work critiques the medical and state regulation of human bodies, particularly the assignment of sex at birth and the imposition of social norms onto physical anatomy. Scholars and bodily autonomy theorists frequently apply Butler''s concepts of bodily vulnerability and precariousness to analyze non-consensual medical interventions, including routine infant circumcision and cosmetic surgeries performed on intersex infants.

Butler''s broader scholarship continues to address themes of ethical responsibility, human rights, and physical self-determination. By examining how institutional power constructs norms of physical completeness and consent, her work provides important theoretical underpinnings for activists and academic archivists engaged in discussions of genital autonomy and bodily integrity.', '', '', 'notable', 'An influential philosopher and gender theorist whose foundational concepts of bodily autonomy, performativity, and physical vulnerability inform scholarly critiques of non-consensual body modification.', 0, '[{"name": "Mary Douglas", "score": 11.183, "shared_docs": 2}, {"name": "Michel Foucault", "score": 10.353, "shared_docs": 3}, {"name": "UNICEF", "score": 7.153, "shared_docs": 2}, {"name": "World Health Organization (WHO)", "score": 6.393, "shared_docs": 2}, {"name": "United Nations", "score": 6.308, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-2d676a47', 'person', 'Brian J. Morris', 'Brian J. Morris is an Australian medical scientist and Professor Emeritus of Molecular Medical Sciences at the University of Sydney. He holds a Ph.D. and a D.Sc. for his research in medical sciences, with an extensive academic career spanning molecular biology, genetics, hypertension, and public health epidemiology.', '', '', 'critic', 'Australian medical researcher and prominent advocate for universal infant male circumcision', 1, '[{"name": "J. A. Bossio", "score": 9.488, "shared_docs": 3}, {"name": "John N. Krieger", "score": 9.488, "shared_docs": 12}, {"name": "Stephen Moreton", "score": 9.488, "shared_docs": 4}, {"name": "CircFacts", "score": 9.488, "shared_docs": 3}, {"name": "Richard G. Wamai", "score": 9.488, "shared_docs": 3}]');
