INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-3f806288', 'organization', 'Bill and Melinda Gates Foundation', 'The Bill & Melinda Gates Foundation is a private global philanthropic organization established by Bill Gates and Melinda French Gates in 2000. Based in Seattle, Washington, the foundation is one of the largest private health and development institutions in the world, directing substantial resources toward disease eradication, poverty reduction, and public health infrastructure across developing nations.', '', '', 'critic', 'A major global health philanthropy whose extensive funding of Voluntary Medical Male Circumcision (VMMC) campaigns in Sub-Saharan Africa made it a prominent focus of criticism among genital autonomy advocates.', 1, '[{"name": "Fred Nalugoda", "score": 10.99, "shared_docs": 2}, {"name": "Uganda Virus Research Institute", "score": 10.575, "shared_docs": 2}, {"name": "David Serwadda", "score": 10.575, "shared_docs": 2}, {"name": "Rakai Health Sciences Program", "score": 10.575, "shared_docs": 2}, {"name": "Makerere University School of Public Health", "score": 10.575, "shared_docs": 2}]');
