INSERT OR IGNORE INTO entity_nominations (id, type, name, description, justification, status) VALUES ('nom-4c2b7c32', 'organization', 'Brothers United for Future Foreskins (BUFF)', '', 'Auto-detected: mentioned in 4 archive documents.', 'pending');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-04694d4e', 'organization', 'National Organization of Restoring Men (NORM)', 'Founded in 1989 by R. Wayne Griffiths, the National Organization of Restoring Men (NORM) emerged as one of the earliest non-profit support networks dedicated to men seeking foreskin restoration. Originally established as a local support group in San Francisco, California, NORM expanded into an international network of autonomous local chapters and online support systems. The organization was created to provide a safe, non-judgmental space for circumcised men to process feelings of grief, loss, or dissatisfaction regarding their infant circumcisions, while offering practical information on non-surgical and surgical restoration methods.

NORM plays a distinct role within the broader genital autonomy and intactivist movements by focusing directly on the post-procedural recovery and rehabilitation of circumcised individuals. The group distributes educational materials detailing manual and device-based tissue expansion techniques, highlights ongoing medical developments in regenerative medicine, and facilitates peer-led discussion groups. Through these efforts, NORM has helped normalize conversations surrounding male bodily integrity, sexual function, and the physiological significance of the prepuce.

Over the decades, NORM''s work has significantly informed the sociological discourse on routine infant circumcision by centering the lived experiences of affected men. By demonstrating that circumcision can cause long-term psychological and physical distress for some individuals, NORM has challenged historical medical consensus and contributed to growing public skepticism regarding non-therapeutic infant genital modifications.', '', '', 'champion', 'A pioneering support and advocacy network providing resources for foreskin restoration and male bodily autonomy.', 1, '[{"name": "Brothers United for Future Foreskins (BUFF)", "score": 9.768, "shared_docs": 4}, {"name": "William A. Jellison", "score": 9.183, "shared_docs": 2}, {"name": "Donald Greer", "score": 9.183, "shared_docs": 2}, {"name": "Ryan McAllister", "score": 9.183, "shared_docs": 2}, {"name": "Stony Brook University", "score": 9.183, "shared_docs": 2}]');
INSERT OR IGNORE INTO entity_nominations (id, type, name, description, justification, status) VALUES ('nom-0f27b8b3', 'organization', 'Arizona State University', '', 'Auto-detected: mentioned in 3 archive documents.', 'pending');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-b22f0d2a', 'person', 'American College of Surgeons', 'The American College of Surgeons (ACS) is a scientific and educational association of surgeons founded in 1913 to raise the standards of surgical practice and improve the quality of care for surgical patients. As one of the largest and most influential professional organizations for surgeons in the United States, the ACS establishes ethical guidelines, educational benchmarks, and standards of clinical practice across various surgical specialties.

Within the discourse surrounding circumcision, bodily autonomy, and surgical consent, the ACS occupies a significant institutional position regarding standard surgical practice and medical ethics. The organization emphasizes the necessity of rigorous surgical training, proper pain management, and adherence to informed consent protocols for elective and non-elective procedures alike. Its guidelines and policy statements contribute to the clinical framework within which pediatric and adult surgical interventions, including neonatal circumcision, are evaluated and performed.

While primary policy recommendations regarding routine infant circumcision in the United States are predominantly issued by pediatric bodies such as the American Academy of Pediatrics, the ACS remains an influential authority on general surgical necessity, patient safety, and surgical ethics. The college''s standards serve as a reference point in debates over bodily integrity, the ethics of non-therapeutic interventions on minors, and the clinical qualifications required to perform surgical procedures.', '', '', 'notable', 'A prominent professional association of surgeons that sets standards for surgical ethics, practice, and informed consent in American medicine.', 0, '[{"name": "James L. Snyder", "score": 9.99, "shared_docs": 3}, {"name": "Virginia Urologic Society", "score": 9.82, "shared_docs": 2}, {"name": "California Medical Association", "score": 8.82, "shared_docs": 2}, {"name": "Benjamin Spock", "score": 8.235, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-a2b2c398', 'person', 'Michel Foucault', 'Michel Foucault (1926–1984) was a seminal French philosopher, historian, and social theorist whose intellectual contributions radically reshaped modern understandings of power, knowledge, and bodily control. As a professor at the Collège de France, Foucault authored influential works such as Discipline and Punish and The History of Sexuality, investigating how modern social and medical institutions regulate, classify, and exert discipline over human bodies through discursive practices and systemic surveillance.', '', '', 'notable', 'French philosopher and social theorist whose foundational concepts of biopower and medicalization provide key frameworks for analyzing bodily autonomy and genital modification.', 1, '[{"name": "Mary Douglas", "score": 10.99, "shared_docs": 2}, {"name": "Judith Butler", "score": 10.353, "shared_docs": 3}, {"name": "UNFPA", "score": 9.116, "shared_docs": 2}, {"name": "Landgericht K\u00f6ln", "score": 9.116, "shared_docs": 2}, {"name": "UNICEF", "score": 7.545, "shared_docs": 3}]');
INSERT OR IGNORE INTO entity_nominations (id, type, name, description, justification, status) VALUES ('nom-ef4a0dad', 'person', 'Mary Douglas', '', 'Auto-detected: mentioned in 3 archive documents.', 'pending');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-a2b3fd1d', 'person', 'Martha Nussbaum', 'Martha Nussbaum is an influential American philosopher, ethicist, and the Ernst Freund Distinguished Service Professor of Law and Ethics at the University of Chicago. Renowned for her seminal contributions to political philosophy, legal theory, and ethics, Nussbaum co-developed the Capabilities Approach alongside economist Amartya Sen. This normative framework evaluates social justice and human well-being based on what individuals are capability-wise enabled to do and be, placing central importance on human dignity and bodily self-determination.

Within the discourse on bodily autonomy, Nussbaum''s work explicitly defines bodily integrity as a core human capability, encompassing security against violent assault and autonomy over one''s own physical body. In her influential writings, including ''Sex and Social Justice'' (1999), she engaged extensively with human rights debates concerning genital alterations, sharply critiquing female genital mutilation/cutting (FGM/C) while analyzing the philosophical, legal, and ethical dimensions of cultural body modifications.

Nussbaum''s philosophical framework has become a critical touchstone for scholars, legal ethicists, and advocates in the intactivist and bodily autonomy movements. Her rigorous defense of bodily integrity as a universal human right offers foundational theoretical support for arguments against non-consensual medical procedures on minors, shaping broader discussions surrounding children''s rights and parental consent.', '', '', 'notable', 'Prominent American philosopher and legal scholar whose Capabilities Approach and framework of bodily integrity deeply inform human rights and genital autonomy discourse.', 1, '[{"name": "Will Kymlicka", "score": 10.82, "shared_docs": 2}, {"name": "Marie Fox and Michael Thomson", "score": 10.405, "shared_docs": 2}, {"name": "Michael Thomson", "score": 10.083, "shared_docs": 2}, {"name": "Marie Fox", "score": 9.598, "shared_docs": 2}, {"name": "Joel Feinberg", "score": 8.705, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-93bc01a2', 'organization', 'Landgericht Köln', 'The Landgericht Köln (District Court of Cologne) is a major regional court in Germany that achieved global prominence in May 2012 due to a groundbreaking legal decision regarding non-therapeutic male child circumcision. The case arose after a doctor performed a routine religious circumcision on a four-year-old boy, who subsequently suffered post-operative bleeding requiring emergency medical care. Although the trial court acquitted the physician, the prosecution appealed to the Landgericht Köln to clarify the legal status of the procedure.', '', '', 'notable', 'German regional court responsible for a landmark 2012 ruling that categorized non-therapeutic male circumcision of minors as illegal bodily harm.', 1, '[{"name": "Deutscher Bundestag", "score": 10.853, "shared_docs": 5}, {"name": "Charlotte Knobloch", "score": 10.701, "shared_docs": 3}, {"name": "Central Council of Jews in Germany", "score": 10.531, "shared_docs": 2}, {"name": "Deutscher Ethikrat", "score": 10.531, "shared_docs": 2}, {"name": "Holm Putzke", "score": 10.268, "shared_docs": 5}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-11e4de9c', 'organization', 'Deutscher Bundestag', 'The Deutscher Bundestag is the federal parliament of Germany and its primary legislative body. It assumed a central role in the global legal and ethical discourse surrounding male circumcision following a landmark ruling by the Cologne District Court (Landgericht Köln) in May 2012. The court had determined that non-therapeutic circumcision of a male minor constituted criminal bodily harm, sparking widespread international debate concerning children''s rights, bodily integrity, and freedom of religion.

In response to the judicial ruling and subsequent public controversy, the Bundestag drafted legislation to clarify the legal status of the procedure. In December 2012, the parliament passed Section 1631d of the German Civil Code (BGB) with a decisive majority. This law explicitly codified the rights of parents to consent to the non-therapeutic male circumcision of their minor sons, provided the procedure is performed according to medical standards and without unnecessary pain.

The passage of Section 1631d drew substantial scrutiny from international human rights organizations, pediatric medical associations, and intactivist groups. While proponents framed the law as a necessary protection for religious freedom and cultural traditions, bodily autonomy advocates criticized the Bundestag''s decision as a setback for children''s rights that compromised the physical integrity of non-consenting minors.', '', '', 'critic', 'The constitutional legislature of Germany, notable for passing landmark legislation in 2012 that legally permitted parental consent for non-therapeutic male circumcision.', 0, '[{"name": "Deutscher Ethikrat", "score": 11.405, "shared_docs": 2}, {"name": "Charlotte Knobloch", "score": 10.99, "shared_docs": 2}, {"name": "Ronald Dworkin", "score": 10.99, "shared_docs": 2}, {"name": "Landgericht K\u00f6ln", "score": 10.853, "shared_docs": 5}, {"name": "Holm Putzke", "score": 10.405, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e7836df5', 'person', 'Amnesty International', 'Amnesty International is a global non-governmental human rights organization founded in 1961, dedicated to preventing abuses of physical integrity and advancing human rights protections worldwide. Operating through frameworks established by international treaties and human rights declarations, the organization historically focused on political prisoners, torture prevention, and the protection of vulnerable populations from state and non-state violence.

Within the discourse on bodily autonomy, Amnesty International has taken an active stance against female genital mutilation (FGM), categorizing the practice as a severe violation of human rights, physical integrity, and the rights of the child. The organization''s campaigns against FGM emphasize the necessity of consent and protection from non-therapeutic bodily harm, contributing significantly to international human rights norms surrounding genital cutting.

In the context of intactivism and male circumcision debates, Amnesty International''s established standards regarding bodily autonomy and child rights are frequently cited by advocates seeking equal protection for all infants. While the organization has maintained a cautious approach regarding routine infant male circumcision, its overarching principles on bodily integrity continue to serve as a key reference in legal, ethical, and sociological evaluations of non-consensual medical procedures.', '', '', 'notable', 'A prominent international human rights organization whose frameworks on physical integrity and bodily autonomy serve as key reference points in global genital autonomy debates.', 1, '[{"name": "Human Rights Watch", "score": 9.931, "shared_docs": 2}, {"name": "James DeMeo", "score": 7.346, "shared_docs": 2}, {"name": "Hanny Lightfoot-Klein", "score": 7.253, "shared_docs": 2}, {"name": "United Nations", "score": 6.794, "shared_docs": 4}, {"name": "National Organization of Circumcision Information Resource Centers (NOCIRC)", "score": 5.103, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-5066723c', 'person', 'John Money', 'John Money (1921–2006) was a New Zealand-born psychologist, sexologist, and researcher at Johns Hopkins University who became a dominant figure in twentieth-century theories of gender identity development. He popularized concepts such as ''gender role'' and ''gender identity,'' arguing that nurture played a far greater role than nature in shaping a child''s gender presentation. His work heavily influenced early medical protocols regarding intersex individuals and infants suffering from severe genital trauma.

Money became deeply intertwined with debates on circumcision and bodily autonomy through his management of the David Reimer case. Following a botched infant circumcision in 1966 that severely damaged Reimer''s penis, Money recommended that Reimer be surgically reassigned and raised as a girl. Money subsequently published papers claiming the intervention was a resounding success, using the case to champion his theories that gender identity could be arbitrarily reassigned through early surgical and social conditioning.

Decades later, Reimer publicly revealed that the experiment had failed and that he had rejected the forced female identity, transitioning back to male as a young adult. The outcome of the Reimer case destroyed Money''s professional standing and transformed his legacy. In bodily autonomy and intactivist literature, Money''s career is frequently examined as a stark warning against non-consensual infant genital surgeries, medical hubris, and the catastrophic risks associated with routine neonatal circumcision.', '', '', 'critic', 'Sexologist whose controversial theories and management of the David Reimer case made him a focal point in critiques of non-consensual infant genital surgery.', 0, '[{"name": "American Psychiatric Association", "score": 10.768, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 4.817, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-34ada1c3', 'organization', 'United Nations Committee on the Rights of the Child', 'The United Nations Committee on the Rights of the Child (CRC) is a body of independent experts established to monitor the implementation of the UN Convention on the Rights of the Child by its State parties. Formed following the entry into force of the treaty in 1990, the Committee conducts periodic reviews of member states'' compliance with child rights standards, assessing national laws and policies regarding health, welfare, protection from violence, and freedom from harm.

Within the discourse on bodily autonomy and physical integrity, the CRC occupies a central reference point for international legal standards. The Committee''s interpretation of Article 24(3) of the Convention—which obligates states to take effective measures to abolish traditional practices prejudicial to the health of children—has been broadly applied to oppose female genital mutilation (FGM) and intersex medically unnecessary surgeries. In various concluding observations and state reviews, the Committee has also addressed non-therapeutic male circumcision, encouraging states to consider children''s emerging autonomy, informed consent, and protection from unnecessary bodily modifications.

Intactivist advocates, legal scholars, and bioethicists frequently cite the CRC''s principles and treaties to argue that non-therapeutic infant circumcision violates fundamental human rights guaranteed under international law. By framing bodily integrity through the lens of child protection and human rights, the CRC''s legal framework remains a cornerstone in global debates concerning children''s rights to physical autonomy.', '', '', 'notable', 'The international treaty body responsible for monitoring child rights, whose human rights framework is centrally invoked in debates over non-therapeutic childhood procedures.', 0, '[{"name": "Attorneys for the Rights of the Child", "score": 8.931, "shared_docs": 3}, {"name": "J. Steven Svoboda", "score": 8.11, "shared_docs": 3}, {"name": "Morten Frisch", "score": 8.005, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 4.718, "shared_docs": 2}]');
INSERT OR IGNORE INTO entity_nominations (id, type, name, description, justification, status) VALUES ('nom-1fbdc4c4', 'organization', 'American Society for Pain Management Nursing', '', 'Auto-detected: mentioned in 3 archive documents.', 'pending');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-2502e8b0', 'organization', 'Human Rights Watch', 'Human Rights Watch (HRW) is an international non-governmental organization headquartered in New York City that investigates, reports on, and advocates against human rights abuses worldwide. Founded in 1978 as Helsinki Watch, the organization expanded its scope globally to monitor compliance with international human rights agreements, including the Universal Declaration of Human Rights and the United Nations Convention on the Rights of the Child. Through detailed country reports and legal analysis, HRW exerts pressure on governments, military entities, and international bodies to enforce human rights standards.

Within the sphere of bodily autonomy and genital integrity, HRW has been a prominent voice against practices that violate rights to physical safety and health. The organization has consistently condemned female genital mutilation/cutting (FGM/C), classifying it as a severe human rights violation and a form of gender-based violence. Additionally, HRW has conducted extensive research into medically unnecessary, non-consensual surgeries performed on intersex children, framing forced intersex medical interventions as violations of bodily integrity and fundamental rights.

While HRW''s explicit campaigns have largely focused on FGM/C and intersex surgeries rather than routine male infant circumcision, its legal frameworks and policy statements are frequently referenced within intactivist discourse. Human rights scholars and bodily autonomy advocates often draw upon HRW''s foundational arguments regarding child rights and bodily integrity to critique all non-therapeutic childhood genital alterations.', '', '', 'notable', 'An international human rights organization that advocates against violations of bodily integrity, including female genital mutilation and non-consensual intersex surgeries.', 0, '[{"name": "Physicians for Human Rights", "score": 11.668, "shared_docs": 2}, {"name": "Amnesty International", "score": 9.931, "shared_docs": 2}, {"name": "United Nations", "score": 7.379, "shared_docs": 3}, {"name": "Brian D. Earp", "score": 6.668, "shared_docs": 2}]');
