INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-cf9c50e4', 'person', 'Robert Darby', 'Dr. Robert Darby is an Australian medical historian, author, and researcher widely recognized for his academic contributions to the history and ethics of male circumcision. He earned his Ph.D. from the University of New England, specializing in the social and medical history of Victorian and early 20th-century medicine. His groundbreaking book, ''A Surgical Temptation: The Rise of Circumcision in the English-Speaking World'' (2005), remains a cornerstone text detailing how non-therapeutic routine infant circumcision became institutionalized within Anglophone healthcare systems.

Throughout his career, Darby has published numerous peer-reviewed articles, book chapters, and essays analyzing the cultural, medical, and ethical dimensions of male genital cutting. His research critically examines the historical shifting justifications for circumcision—from 19th-century anti-masturbation anxieties to contemporary prophylactic arguments—demonstrating how medical rationales were constructed over time. He has consistently argued that non-therapeutic circumcision lacks sufficient medical justification and infringes upon a child''s fundamental right to bodily integrity.

Beyond pure historical analysis, Darby has actively participated in contemporary bioethical and legal debates surrounding genital autonomy, child rights, and medical ethics. By bridging rigorous historiography with human rights discourse, his work has provided essential intellectual foundations for medical ethicists, legal scholars, and intactivist advocates seeking to reform policies around non-consensual pediatric procedures.', '', '', 'champion', 'Independent medical historian and author of ''A Surgical Temptation'', recognized for his comprehensive historical and ethical critiques of routine male circumcision.', 1, '[{"name": "William Acton", "score": 9.021, "shared_docs": 3}, {"name": "E. Harding Freeland", "score": 9.021, "shared_docs": 3}, {"name": "Herbert Snow", "score": 8.605, "shared_docs": 3}, {"name": "Travis Wisdom", "score": 8.436, "shared_docs": 2}, {"name": "Aaron T. Norton", "score": 8.436, "shared_docs": 2}]');
