INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-65e533ef', 'person', 'David L. Gollaher', 'David L. Gollaher, Ph.D., is an American historian, author, and healthcare executive recognized for his extensive scholarship on the history of medicine and public health. He earned his doctorate in the history of science from Harvard University and has served in leadership roles across biotechnology, healthcare policy, and academic institutions.', '', '', 'notable', 'Medical historian and author of ''Circumcision: A History of the World''s Most Controversial Surgery.''', 1, '[{"name": "Case Western Reserve University School of Law", "score": 10.838, "shared_docs": 3}, {"name": "Carla Makhlouf Obermeyer", "score": 9.99, "shared_docs": 2}, {"name": "Bettina Shell-Duncan", "score": 9.768, "shared_docs": 2}, {"name": "Lauren M. Sardi", "score": 9.768, "shared_docs": 2}, {"name": "Lewis A. Sayre", "score": 9.768, "shared_docs": 2}]');
