INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-9ff13614', 'person', 'Leonard B. Glick', 'Leonard B. Glick was an American physician and cultural anthropologist who served as a Professor Emeritus of Anthropology at Hampshire College in Amherst, Massachusetts. Combining his background in clinical medicine and social anthropology, Glick dedicated significant academic research to analyzing the cultural, religious, and medical histories surrounding bodily modification practices, most notably male infant circumcision in Western society.

Glick is best known in bodily autonomy discourse for his seminal 2005 book, "Marked in Your Flesh: Circumcision from Ancient Judea to Modern America." In this work, he detailed the transformation of circumcision from an ancient Jewish religious covenant into a routine Anglo-American medical procedure during the late 19th and early 20th centuries. Glick critically examined how Victorian-era medical theories regarding masturbation and hygiene were used to justify the widespread medicalization of non-therapeutic genital surgery in the United States.

Through his writing, lectures, and academic contributions, Glick provided scholars and intactivist advocates with a detailed historical framework to critique non-consensual infant circumcision. His scholarship emphasized the ethical imperative of preserving physical integrity and autonomy, positioning routine infant circumcision as a cultural artifact rather than an evidence-based medical necessity.', '', '', 'champion', 'Medical anthropologist, physician, and author of ''Marked in Your Flesh'', a foundational historical critique of routine infant circumcision.', 0, '[{"name": "Philo of Alexandria", "score": 10.668, "shared_docs": 2}, {"name": "Moses Maimonides", "score": 7.781, "shared_docs": 2}]');
