INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-a06846c6', 'person', 'Gerry Mackie', 'Gerry Mackie is an associate professor of political science at the University of California, San Diego, best known for his landmark application of social norm theory to harmful bodily conventions. His influential 1996 research paper on footbinding and female genital cutting revolutionized international public health strategies by demonstrating how deeply ingrained social practices can be rapidly abandoned through coordinated collective pledge mechanisms. His work has since informed major human rights organizations and global policy initiatives led by bodies such as UNICEF and the World Health Organization.

In addition to his work on female genital alterations, Mackie has applied social convention theory to routine infant male circumcision. He argued that male circumcision in countries like the United States persists primarily as a self-enforcing social convention maintained by parental anxiety, conformity, and belief traps rather than compelling medical necessity. By framing circumcision as a structural social trap rather than a purely individual choice, he provided a novel sociological mechanism for understanding its persistence in modern medical contexts.

Mackie''s theoretical contributions have provided intactivist scholars and bodily autonomy advocates with vital conceptual tools. By equating the socio-cultural mechanics of male circumcision with other historical and cross-cultural body modification conventions, his scholarship has advanced the critique of non-consensual genital procedures and outlined actionable pathways toward their eventual elimination.', '', '', 'champion', 'Political scientist and social norm theorist whose scholarship models the elimination of non-consensual body modification practices like genital cutting', 0, '[{"name": "Birgitta Ess\u00e9n", "score": 10.083, "shared_docs": 2}, {"name": "Sara Johnsdotter", "score": 8.73, "shared_docs": 2}, {"name": "UNICEF", "score": 7.638, "shared_docs": 2}, {"name": "American Medical Association", "score": 6.949, "shared_docs": 2}, {"name": "World Health Organization (WHO)", "score": 6.878, "shared_docs": 2}]');
