INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-9a361807', 'organization', 'Oxford University Press', 'Oxford University Press (OUP) is the largest university press in the world and a department of the University of Oxford. Tracing its printing origins back to the late sixteenth century, the publisher maintains a global presence, producing academic monographs, peer-reviewed journals, and reference works across fields including medicine, law, bioethics, philosophy, and medical history.

Within the discourse surrounding circumcision and bodily autonomy, Oxford University Press serves as a major platform for scholarly literature and debate. Its academic journals and books frequently feature rigorous legal, ethical, and historical analyses regarding male, female, and intersex genital interventions. Works published under the OUP imprint have critically examined issues such as parental rights, informed consent, medical necessity, religious freedom, and human rights frameworks as they apply to non-therapeutic bodily alterations.

While maintaining an objective publishing stance, the press has facilitated essential discourse among ethicists, legal scholars, and medical practitioners on the boundaries of bodily integrity. By disseminating peer-reviewed research from both advocates and critics of routine circumcision, Oxford University Press remains an influential repository of academic scholarship informing global bioethical standards and legal policy.', '', '', 'notable', 'A leading global academic press publishing influential scholarly literature, bioethics journals, and legal analyses concerning circumcision and bodily integrity.', 1, '[{"name": "Sir James Munby", "score": 9.768, "shared_docs": 2}, {"name": "Statens Serum Institut", "score": 8.446, "shared_docs": 2}, {"name": "Yale University", "score": 6.96, "shared_docs": 2}, {"name": "Moses Maimonides", "score": 6.558, "shared_docs": 2}, {"name": "Morten Frisch", "score": 6.52, "shared_docs": 2}]');
