INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-08b1a37c', 'person', 'Stephen Moses', 'Stephen Moses is a Canadian physician, epidemiologist, and professor at the University of Manitoba who gained international prominence for his extensive research on the epidemiology and control of sexually transmitted infections, particularly HIV/AIDS in sub-Saharan Africa. Throughout his career, he collaborated with international health organizations and research institutions to investigate public health strategies aimed at curbing epidemic disease transmission.', '', '', 'critic', 'An epidemiologist and public health researcher who led pivotal clinical trials establishing male circumcision as an HIV prevention strategy.', 0, '[{"name": "Thomas Wiswell", "score": 9.327, "shared_docs": 3}, {"name": "Robert C. Bailey", "score": 9.083, "shared_docs": 2}, {"name": "Edgar J. Schoen", "score": 8.903, "shared_docs": 2}, {"name": "National Institutes of Health", "score": 8.346, "shared_docs": 2}, {"name": "Royal Australasian College of Physicians", "score": 8.327, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-2954a69c', 'person', 'Robert C. Bailey', 'Robert C. Bailey is an epidemiologist, anthropologist, and professor emeritus at the University of Illinois at Chicago School of Public Health. He gained international prominence for his research on global health and the epidemiology of infectious diseases, particularly focusing on the relationship between male circumcision and the reduction of HIV transmission in Sub-Saharan Africa.

Bailey was the principal investigator for a landmark randomized controlled trial in Kisumu, Kenya, during the early 2000s. His study, published alongside similar trials in South Africa and Uganda, concluded that voluntary medical male circumcision (VMMC) substantially reduced the risk of female-to-male HIV acquisition. This research formed a primary foundation for the 2007 recommendations by the World Health Organization (WHO) and UNAIDS promoting medical male circumcision as a key HIV prevention intervention in high-prevalence settings.

Throughout his career, Bailey actively defended the scientific validity and public health benefits of male circumcision in academic journals and international forums. His prominent advocacy for VMMC initiatives positioned him as a frequent target of criticism from intactivist groups and bioethicists, who raised concerns regarding surgical ethics, informed consent, and the bodily autonomy implications of promoting mass circumcision programs.', '', '', 'critic', 'An epidemiologist and researcher who led major clinical trials promoting voluntary medical male circumcision for HIV prevention.', 1, '[{"name": "University of Illinois at Chicago", "score": 10.154, "shared_docs": 7}, {"name": "Kawango Agot", "score": 10.083, "shared_docs": 2}, {"name": "Alain Giami", "score": 10.083, "shared_docs": 2}, {"name": "University of Nairobi", "score": 9.931, "shared_docs": 3}, {"name": "INSERM", "score": 9.668, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-d7b6f363', 'organization', 'University of Illinois at Chicago', 'The University of Illinois at Chicago (UIC) is a major public research university and academic medical center that plays a significant role in medical, public health, and social science research. Through its College of Medicine, School of Public Health, and affiliated clinical networks, the institution has contributed to clinical scholarship, epidemiological studies, and bioethical commentary regarding neonatal and adult male circumcision practices both in the United States and globally.

Within the discourse on genital autonomy and public health policy, UIC has served as an institutional base for researchers examining the medical, behavioral, and ethical dimensions of circumcision. Affiliated scholars and clinicians have authored studies addressing topics ranging from surgical complication rates and HIV prevention research to pediatric consent and the ethical considerations surrounding non-therapeutic infant surgeries. The university''s research output reflects broader academic discussions on balancing public health measures with principles of bodily integrity.

While not an advocacy organization, UIC functions as a prominent site where medical evidence and ethical perspectives regarding circumcision are generated, analyzed, and debated. Its inclusion in sociological archives highlights the institution''s role in shaping contemporary medical literature and public health frameworks that inform debates between proponents of infant circumcision and advocates for bodily autonomy.', '', '', 'notable', 'A prominent public research institution and medical center contributing to epidemiological, clinical, and bioethical research on circumcision.', 1, '[{"name": "Kawango Agot", "score": 10.668, "shared_docs": 2}, {"name": "University of Nairobi", "score": 10.516, "shared_docs": 3}, {"name": "Robert C. Bailey", "score": 10.154, "shared_docs": 7}, {"name": "London School of Hygiene and Tropical Medicine", "score": 9.668, "shared_docs": 3}, {"name": "Bill & Melinda Gates Foundation", "score": 8.668, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-54152380', 'organization', 'University of Manitoba', 'The University of Manitoba is a public research university located in Winnipeg, Manitoba, Canada. Established in 1877, it is the oldest university in western Canada and home to major faculties of medicine, health sciences, law, and the humanities. Through its affiliated teaching hospitals and academic departments, the institution has long played a central role in Canadian medical education, clinical research, and bioethical inquiry.', '', '', 'notable', 'A prominent Canadian public research institution whose academic and medical faculties have contributed to research, policy discussions, and bioethical literature surrounding circumcision.', 1, '[{"name": "J.R. Taylor", "score": 10.668, "shared_docs": 4}, {"name": "A.P. Lockwood", "score": 10.253, "shared_docs": 2}, {"name": "A.J. Taylor", "score": 10.253, "shared_docs": 2}, {"name": "William Cameron", "score": 10.253, "shared_docs": 4}, {"name": "Marshfield Clinic", "score": 9.668, "shared_docs": 2}]');
