INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-729d8520', 'organization', 'University of Nairobi', 'The University of Nairobi is a premier public research institution located in Nairobi, Kenya. Established as an independent university in 1970, it has long served as a center for higher education, scientific inquiry, and medical research in East Africa. Its College of Health Sciences and affiliated research units have maintained extensive collaborations with international health organizations and academic entities, positioning the institution as a major contributor to global health literature.', '', '', 'critic', 'A leading Kenyan public research university whose clinical trials substantially contributed to international policy endorsing medical male circumcision for HIV prevention.', 0, '[{"name": "Kawango Agot", "score": 11.668, "shared_docs": 2}, {"name": "Brandon University", "score": 10.931, "shared_docs": 2}, {"name": "Jonathan A. Allan", "score": 10.668, "shared_docs": 2}, {"name": "University of Illinois at Chicago", "score": 10.516, "shared_docs": 3}, {"name": "Robert C. Bailey", "score": 9.931, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-5f8e591b', 'person', 'James Loewen', 'James W. Loewen (1942–2021) was an American sociologist, educator, and author best known for his critical examinations of historical memory and cultural myths in the United States, most notably in his award-winning book ''Lies My Teacher Told Me''. He earned his Ph.D. in sociology from Harvard University and spent decades researching race relations, social stratification, and institutional inertia at institutions such as Tougaloo College and the University of Vermont.

Within the study of medical history and bodily autonomy, Loewen addressed routine neonatal circumcision as a compelling case study of a medical practice rooted in 19th-century social panics, specifically anti-masturbation anxieties. His sociological work deconstructed how medical authority and cultural habit combined to normalize non-therapeutic infant circumcision in North America, keeping the practice widespread long after its original justifications were abandoned.

Loewen''s analysis provided significant intellectual support to the bodily autonomy and intactivist movements by contextualizing routine circumcision within broader historical patterns of medical misdirection and institutional conformity. His writings continue to be referenced by historians and advocates seeking to explain how deeply ingrained medical fads persist without sound clinical justification.', '', '', 'champion', 'American sociologist and historian who critically analyzed the cultural and historical roots of routine medical procedures, including neonatal circumcision.', 1, '[{"name": "Barry Ellsworth", "score": 10.668, "shared_docs": 3}, {"name": "Lawrence Dillon", "score": 9.598, "shared_docs": 2}, {"name": "Dillonwood Productions", "score": 9.598, "shared_docs": 2}, {"name": "Tim Hammond", "score": 7.196, "shared_docs": 4}, {"name": "Marilyn Milos", "score": 6.65, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-83ad8220', 'person', 'Jeannine Parvati Baker', 'Jeannine Parvati Baker (1949–2004) was an influential American midwife, herbalist, author, and pioneer in the natural birth movement. Best known for coining the concept of lotus birth and authoring seminal texts such as Prenatal Yoga & Natural Birth and Hygeia: A Woman''s Herbal, Baker advocated for reclaiming birth as a natural, empowering process centered on bodily autonomy for both mothers and infants.

Within the discourse on infant rights and bodily integrity, Baker was a prominent voice opposing routine infant circumcision. She viewed genital alteration as a traumatic violation of a newborn''s natural wholeness and an unnecessary medical intervention that interfered with early bonding and infant well-being. Her holistic philosophy linked gentle birth practices directly with the preservation of intact anatomy.

Through her books, workshops, and international speaking engagements, Baker influenced generations of birth workers, parents, and intactivists. Her legacy remains significant in bridging the natural childbirth movement with genital autonomy advocacy, emphasizing the fundamental right of children to enter the world and remain physically whole.', '', '', 'champion', 'Midwife, author, and natural birth pioneer who advocated for infant bodily integrity and opposed routine infant circumcision.', 0, '[{"name": "Morris Sorrells", "score": 11.353, "shared_docs": 3}, {"name": "Laurie Evans", "score": 11.183, "shared_docs": 2}, {"name": "J. David Bigelow", "score": 11.183, "shared_docs": 2}, {"name": "Peter Ball", "score": 11.183, "shared_docs": 2}, {"name": "Yngve Hofvander", "score": 11.183, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-24263d5f', 'organization', 'NOHARMM (National Organization to Halt the Abuse and Routine Mutilation of Males)', 'Founded in 1992 by Tim Hammond in San Francisco, NOHARMM (National Organization to Halt the Abuse and Routine Mutilation of Males) emerged as one of the prominent early advocacy groups within the American intactivist movement. The organization was established to challenge the medical and cultural normalization of routine neonatal male circumcision, framing the practice as a violation of basic human rights and individual bodily integrity.

Throughout its history, NOHARMM engaged in public education, consumer advocacy, and support services for men addressing the emotional and physical impact of involuntary infant circumcision. The organization actively provided educational resources to expecting parents, medical professionals, and the general public while facilitating support groups and resources focused on grief, healing, and foreskin restoration.

Through its community outreach, media appearances, and participation in human rights conferences, NOHARMM played a foundational role in shaping the modern discourse on male genital autonomy. It remains a key historical entity in the broader movement advocating for children''s rights and the protection of bodily autonomy.', '', '', 'champion', 'Pioneering American advocacy organization dedicated to ending routine infant circumcision and supporting circumcised men.', 1, '[{"name": "NOCIRC (National Organization of Circumcision Information Resource Centers)", "score": 10.768, "shared_docs": 2}, {"name": "NOHARMM", "score": 8.709, "shared_docs": 3}]');
INSERT OR IGNORE INTO entity_nominations (id, type, name, description, justification, status) VALUES ('nom-b06321f1', 'organization', 'NOCIRC (National Organization of Circumcision Information Resource Centers)', '', 'Auto-detected: mentioned in 4 archive documents.', 'pending');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-2d51b4b0', 'organization', 'University of California Press', 'Founded in 1893, the University of California Press (UC Press) is the academic publishing arm of the University of California system and one of the largest public university presses in the United States. It publishes scholarly books and journals across a wide array of disciplines, including sociology, anthropology, history, bioethics, and public health. Through its rigorous peer-review process, the press disseminates influential academic research to global readerships.

Within the context of discourse on circumcision, bodily autonomy, and genital integrity, UC Press serves as a vital platform for academic inquiry. The press has published numerous scholarly titles and journal articles that examine the cultural, historical, medical, and legal dimensions of bodily modification. These publications offer nuanced analysis of how ritual and medicalized circumcisions have been constructed, contested, and regulated across different societies and eras.

By providing a venue for critical scholarship, UC Press plays a significant role in shaping the theoretical and empirical foundations used by researchers, ethicists, and advocates on all sides of the circumcision debate. Its catalog includes key texts in medical anthropology and history that contextualize genital practices within broader framework of human rights, medical authority, and bodily integrity.', '', '', 'notable', 'A prominent academic press that publishes influential scholarly works on the history, anthropology, and ethics of circumcision and bodily modification.', 0, '[{"name": "Jeffery M. Paige", "score": 11.668, "shared_docs": 2}, {"name": "Michael J. Kinane", "score": 11.253, "shared_docs": 2}, {"name": "Karen Ericksen Paige", "score": 10.668, "shared_docs": 2}, {"name": "Charles A. Bonner", "score": 10.083, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 5.303, "shared_docs": 3}]');
