INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-d0491d0b', 'person', 'Isaac Baker Brown', 'Isaac Baker Brown (1812–1873) was a 19th-century English gynaecologist and obstetrical surgeon who served as the president of the Medical Society of London. In the mid-19th century, he became one of the most prominent medical advocates for surgical interventions to treat perceived psychiatric and nervous disorders in women. His work centered heavily on the surgical alteration and removal of female genital tissue, particularly advocating for clitoridectomy as a treatment for conditions he attributed to masturbation and nervous hyper-stimulation.

Brown outlined his theories in his 1866 publication, ''On the Curability of Certain Forms of Insanity, Epilepsy, Catalepsy, and Hysteria in Females,'' promoting surgical removal of the clitoris as a cure for female deviance and mental illness. His practice of performing these irreversible procedures, often without the explicit knowledge or informed consent of his patients, eventually drew severe condemnation from the British medical community. In 1867, following intense debate over his professional ethics and clinical claims, he was formally expelled from the Obstetrical Society of London, effectively ending his medical career.

Within modern discourse on bodily autonomy and intactivism, Isaac Baker Brown is cited as a foundational historical example of medicalized genital cutting and clinical overreach. His legacy serves as a key case study in the history of non-consensual surgical interventions performed under the guise of medical necessity and moral regulation.', '', '', 'critic', '19th-century English surgeon infamous for promoting non-consensual clitoridectomies as a cure for female mental illness.', 0, '[{"name": "Kirsten Bell", "score": 9.82, "shared_docs": 2}, {"name": "Jonathan Hutchinson", "score": 9.668, "shared_docs": 2}, {"name": "Robert Darby", "score": 8.021, "shared_docs": 3}, {"name": "NOCIRC", "score": 7.903, "shared_docs": 2}, {"name": "J. Steven Svoboda", "score": 7.262, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-8ad84f2d', 'person', 'Kevin Barrett', 'Kevin Barrett is an American academic, public commentator, and activist who has engaged with socio-political and human rights issues, including the ethics surrounding infant circumcision and bodily autonomy. With a background in Islamic studies and humanities, Barrett has utilized various media platforms, including radio broadcasts, essays, and public lectures, to analyze cultural and religious practices through the lens of individual rights and physical integrity.

Within the intactivist movement, Barrett''s commentary emphasizes the universal right to bodily self-determination, critiquing routine non-therapeutic neonatal circumcision as a violation of basic human rights. He has addressed the intersection of religious traditions, medical ethics, and legal frameworks, arguing against the normalization of involuntary genital alterations in minors regardless of cultural context.

Through his writing and media presence, Barrett has contributed to broadening the public dialogue surrounding genital integrity. His work underscores the necessity of informed consent and advocates for the protection of children from non-consensual surgical procedures, positioning genital autonomy as a fundamental component of bodily freedom.', '', '', 'champion', 'An academic and public commentator who advocates for universal bodily autonomy and critiques non-consensual infant circumcision.', 0, '[{"name": "Committee on Publication Ethics (COPE)", "score": 12.253, "shared_docs": 3}, {"name": "JAMA Pediatrics", "score": 11.931, "shared_docs": 4}, {"name": "American Medical Association (AMA)", "score": 10.931, "shared_docs": 2}, {"name": "American Academy of Pediatrics (AAP)", "score": 8.166, "shared_docs": 3}, {"name": "American Academy of Pediatrics", "score": 4.718, "shared_docs": 2}]');
INSERT OR IGNORE INTO entity_nominations (id, type, name, description, justification, status) VALUES ('nom-d6fb86cd', 'organization', 'Committee on Publication Ethics (COPE)', '', 'Auto-detected: mentioned in 3 archive documents.', 'pending');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-ac557517', 'organization', 'American Medical Association (AMA)', 'Founded in 1847, the American Medical Association (AMA) is the largest professional association of physicians and medical students in the United States. Throughout its history, the organization has played a major role in shaping public health policy, medical ethics, and clinical practice standards across the nation. As a primary authority on American medicine, the AMA''s official positions often inform insurance coverage, state legislation, and institutional practices in hospitals nationwide.

Within the discourse on routine infant male circumcision, the AMA has historically maintained a stance aligned with other major American pediatric and medical bodies. In 1999, the AMA''s Council on Scientific Affairs conducted a comprehensive review of the practice, determining that routine neonatal circumcision is not medically necessary. The association affirmed that while the procedure may convey certain potential health benefits, it also carries inherent surgical risks, ultimately framing the practice as an elective procedure that requires informed parental consent rather than a routine medical mandate.

While intactivist organizations and bodily autonomy advocates often critique the AMA for not adopting an explicit stance against non-therapeutic infant circumcision, the association''s policy updates reflected a significant shift away from the unchecked medical enthusiasm for the procedure seen in the early-to-mid 20th century. By classifying circumcision as an elective surgical intervention, the AMA''s guidance reinforced the legal and ethical framework requiring physicians to provide balanced disclosures of risks and benefits to prospective parents.', '', '', 'notable', 'The largest professional association of physicians in the United States, maintaining a policy position that frames infant circumcision as an elective procedure.', 0, '[{"name": "Committee on Publication Ethics (COPE)", "score": 11.668, "shared_docs": 2}, {"name": "Kevin Barrett", "score": 10.931, "shared_docs": 2}, {"name": "JAMA Pediatrics", "score": 10.931, "shared_docs": 2}, {"name": "National Center for Health Statistics", "score": 9.005, "shared_docs": 2}, {"name": "American Academy of Pediatrics (AAP)", "score": 8.903, "shared_docs": 5}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e210932e', 'organization', 'JAMA Pediatrics', 'JAMA Pediatrics is a monthly peer-reviewed medical journal published by the American Medical Association (AMA). Originally established in 1911 as the American Journal of Diseases of Children, it is the oldest continuously published pediatric journal in the United States and remains one of the most influential academic publications in the field of child and adolescent health.

Within the discourse surrounding circumcision and bodily autonomy, JAMA Pediatrics serves as a primary venue for biomedical research, clinical trials, and epidemiological studies. The journal has published numerous influential papers examining the outcomes, complication rates, pain management strategies, and potential medical benefits and risks associated with neonatal male circumcision. Articles featured in the journal often inform clinical practice guidelines issued by professional organizations like the American Academy of Pediatrics (AAP).

While JAMA Pediatrics functions as an objective scholarly forum rather than an advocacy platform, the research and commentaries published within its pages are routinely cited by medical professionals, ethicists, and intactivist scholars. The journal''s coverage of topic-adjacent issues—such as pediatric consent, procedural ethics, and the necessity of non-therapeutic interventions on minors—has made it a critical reference point in debates over genital autonomy.', '', '', 'notable', 'A prominent peer-reviewed medical journal that serves as a major platform for research and debate on pediatric circumcision.', 0, '[{"name": "Kevin Barrett", "score": 11.931, "shared_docs": 4}, {"name": "Committee on Publication Ethics (COPE)", "score": 11.668, "shared_docs": 2}, {"name": "American Medical Association (AMA)", "score": 10.931, "shared_docs": 2}, {"name": "American Academy of Pediatrics (AAP)", "score": 7.581, "shared_docs": 2}, {"name": "American Medical Association", "score": 6.949, "shared_docs": 2}]');
