INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f594bf6e', 'person', 'Philo of Alexandria', 'Philo of Alexandria (c. 20 BCE – c. 50 CE) was a Hellenistic Jewish philosopher who lived in Alexandria, Egypt. Operating at the intersection of Jewish scriptural tradition and Greek philosophy, Philo sought to harmonize the Torah with Platonism and Stoicism. His prolific writings aimed to explain Jewish religious customs and law to both the Hellenized Jewish diaspora and educated Gentile audiences within the Roman Empire.

Philo is notably significant in the history of bodily modification discourse for providing one of antiquity''s earliest and most detailed philosophical defenses of circumcision. In his treatise De Specialibus Legibus (On the Special Laws), Philo directly responded to Greco-Roman critiques of the practice. He presented a multifaceted justification, arguing that circumcision promoted physical cleanliness, guarded against disease, enhanced fertility, and served as a moral allegorical symbol for the excision of arrogance, unbridled pleasure, and passion from the human soul.

Within the sociological study of circumcision, Philo''s work represents a pivotal moment where a ritual practice was reinterpreted through philosophical and pseudo-medical rationales. His arguments established enduring tropes in defense of the procedure—spanning hygiene, health, and spiritual purity—that influenced subsequent Jewish apologetics and historical debates regarding body autonomy and covenantal marks.', '', '', 'critic', 'Hellenistic Jewish philosopher who authored one of antiquity''s foundational philosophical defenses of circumcision.', 0, '[{"name": "Leonard B. Glick", "score": 10.668, "shared_docs": 2}, {"name": "Moses Maimonides", "score": 8.044, "shared_docs": 2}]');
