INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-10c30d98', 'person', 'Eike-Henner Kluge', 'Eike-Henner Kluge is a Canadian philosopher, bioethicist, and academic who served as a professor of philosophy at the University of Victoria. He gained national and international recognition as a leading authority on medical ethics, notably serving as the founding Director of Ethics and Legal Affairs for the Canadian Medical Association (CMA) during the late 1980s and early 1990s.

Throughout his career, Kluge applied core principles of medical ethics—specifically non-maleficence, bodily autonomy, and rights-based patient care—to the practice of non-therapeutic neonatal male circumcision. He consistently argued that infants possess fundamental rights to bodily integrity and self-determination, contending that parents and legal guardians lack the ethical authority to provide proxy consent for non-therapeutic surgical alterations of a child''s healthy body.

Kluge''s published scholarship and policy analyses contributed significantly to shifting medical perspectives surrounding infant genital cutting. By framing non-therapeutic circumcision as a violation of basic human rights and medical ethics, his work provided foundational academic arguments for bodily autonomy advocates and intactivist organizations globally.', '', '', 'champion', 'Canadian bioethicist and scholar whose work establishes ethical and rights-based arguments against non-therapeutic infant circumcision.', 0, '[{"name": "Australasian Association of Paediatric Surgeons", "score": 9.668, "shared_docs": 2}, {"name": "Andrew Freedman", "score": 9.553, "shared_docs": 2}, {"name": "Yale University", "score": 8.446, "shared_docs": 2}, {"name": "University of Oxford", "score": 7.931, "shared_docs": 2}, {"name": "Robert Darby", "score": 7.699, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-52f38e15', 'organization', 'Australasian Association of Paediatric Surgeons', 'The Australasian Association of Paediatric Surgeons (AAPS) is the primary professional organization representing pediatric surgeons across Australia and New Zealand. Established to advance surgical care, clinical standards, and research for infants and children, the association serves as an authoritative voice on surgical ethics, clinical guidelines, and pediatric healthcare policy within the region.

In the ongoing discourse regarding infant male circumcision and bodily autonomy, AAPS has played a pivotal institutional role. During the late 20th century, the association reviewed the medical evidence surrounding non-therapeutic neonatal circumcision and concluded that routine infant circumcision was not medically indicated. AAPS highlighted the inherent risks of the procedure, the lack of therapeutic justification for universal infant intervention, and the importance of preserving healthy tissue.

Alongside positions adopted by the Royal Australasian College of Physicians (RACP), AAPS''s policy statements contributed to a substantial shift in clinical practice and public opinion across Australasia, leading to a dramatic decline in routine infant circumcision rates. By advocating against unnecessary surgical interventions on minors, the association established a precedent that emphasizes the child''s right to bodily integrity and deferral of non-essential procedures until an age of consent.', '', '', 'champion', 'Peak professional body for pediatric surgeons in Australia and New Zealand that formally opposes routine infant male circumcision.', 1, '[{"name": "Eike-Henner Kluge", "score": 9.668, "shared_docs": 2}, {"name": "Queensland Law Reform Commission", "score": 9.575, "shared_docs": 3}, {"name": "Australian College of Paediatrics", "score": 9.405, "shared_docs": 3}, {"name": "Margaret Somerville", "score": 8.82, "shared_docs": 4}, {"name": "Gregory J. Boyle", "score": 8.29, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e4ca6b52', 'person', 'Kavita Shah Arora', 'Kavita Shah Arora, MD, MBE, is an American obstetrician-gynecologist, academic bioethicist, and researcher specializing in reproductive health ethics, health equity, and medical decision-making. She has served in academic and clinical roles at major medical institutions, including the University of North Carolina at Chapel Hill and Case Western Reserve University, publishing extensively on the ethical boundaries of pediatric medical procedures and parental authority.', '', '', 'notable', 'An American obstetrician-gynecologist and bioethicist known for her academic scholarship on the ethics of male infant circumcision and female genital alteration.', 1, '[{"name": "Allan J. Jacobs", "score": 10.768, "shared_docs": 11}, {"name": "Routledge", "score": 10.268, "shared_docs": 5}, {"name": "Taylor & Francis", "score": 9.946, "shared_docs": 4}, {"name": "Reinhard Merkel", "score": 9.308, "shared_docs": 2}, {"name": "Holm Putzke", "score": 8.946, "shared_docs": 2}]');
