INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-5b6ab355', 'person', 'Allan J. Jacobs', 'Dr. Allan J. Jacobs is an American physician and bioethicist specializing in obstetrics, gynecology, and medical ethics. Throughout his academic career, he has contributed extensively to peer-reviewed bioethical literature on pediatric procedures, reproductive health, and parental rights in medical decision-making.

Within the discourse on circumcision and bodily autonomy, Jacobs is known for his scholarly defense of the ethical permissibility of routine neonatal male circumcision. His publications analyze the procedure through the lenses of harm assessment, parental autonomy, and cultural or religious freedoms, arguing that infant male circumcision does not violate ethical norms when requested by parents. He has also addressed comparative ethical frameworks regarding minor forms of genital alteration in academic contexts.

Jacobs'' writings are frequently cited within bioethics literature and are often engaged by scholars and advocates examining the intersection of medicine, ethics, and bodily integrity. While intactivists and bodily autonomy advocates critique his conclusions regarding consent and physical integrity, his work represents a major academic voice arguing for the continued permissibility of parental authorization for male circumcision.', '', '', 'critic', 'American physician and bioethicist known for his academic defenses of the ethics and permissibility of infant male circumcision.', 1, '[{"name": "Kavita Shah Arora", "score": 10.768, "shared_docs": 11}, {"name": "Isaiah Berlin", "score": 10.183, "shared_docs": 2}, {"name": "Routledge", "score": 9.92, "shared_docs": 5}, {"name": "Taylor & Francis", "score": 9.598, "shared_docs": 4}, {"name": "Reinhard Merkel", "score": 8.96, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f6dad8b6', 'organization', 'Taylor & Francis', 'Taylor & Francis is a major international academic publisher founded in London in 1798, specializing in the dissemination of scholarly books, journals, and reference works across medicine, ethics, humanities, and social sciences. As one of the world''s leading academic publishing houses, the company hosts a vast library of peer-reviewed research that documents public health interventions, bioethical debates, and legal frameworks across diverse global contexts.

Within the discourse surrounding circumcision, bodily autonomy, and genital integrity, Taylor & Francis serves as a primary platform for peer-reviewed academic literature. Its publications include critical studies and bioethical analyses on male, female, and intersex genital modifications. Scholars from various disciplines utilize Taylor & Francis journals to debate the medical utility, human rights implications, legal status, and psychological impacts of non-therapeutic childhood circumcision.

While the organization maintains an editorially neutral stance as a publisher, its archives form a critical repository of evidence and argumentation for sociologists, bioethicists, and intactivist scholars. By providing a forum for both traditional medical perspectives and critical bodily autonomy scholarship, Taylor & Francis plays an influential role in shaping the contemporary academic debate on genital autonomy.', '', '', 'notable', 'A prominent international academic publisher that disseminates peer-reviewed literature on bioethics, public health, and genital autonomy.', 1, '[{"name": "Routledge", "score": 11.043, "shared_docs": 7}, {"name": "Kavita Shah Arora", "score": 9.946, "shared_docs": 4}, {"name": "Allan J. Jacobs", "score": 9.598, "shared_docs": 4}, {"name": "Royal Dutch Medical Association (KNMG)", "score": 8.083, "shared_docs": 2}, {"name": "Morten Frisch", "score": 7.742, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-c2781044', 'organization', 'Routledge', 'Routledge is a prominent international academic publisher and imprint of the Taylor & Francis Group, traceably originating to the early nineteenth century. As one of the world''s leading publishers in the humanities, social sciences, and medical ethics, the organization produces thousands of scholarly monographs, reference works, and peer-reviewed academic journals each year.', '', '', 'notable', 'A global academic publisher providing scholarly platforms for research on bioethics, law, human rights, and genital autonomy.', 1, '[{"name": "Taylor & Francis", "score": 11.043, "shared_docs": 7}, {"name": "Kavita Shah Arora", "score": 10.268, "shared_docs": 5}, {"name": "Allan J. Jacobs", "score": 9.92, "shared_docs": 5}, {"name": "Royal Dutch Medical Association (KNMG)", "score": 8.083, "shared_docs": 2}, {"name": "Robert Darby", "score": 7.436, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e7fa875d', 'person', 'John V. Geisheker', 'John V. Geisheker is an American attorney, legal ethicist, and prominent advocate within the genital autonomy movement. He served for many years as the Executive Director and Legal Counsel for Doctors Opposing Circumcision (DOC), an international educational organization of physicians and healthcare professionals established in 1995 to end routine non-therapeutic infant circumcision.

Throughout his career, Geisheker focused on the legal, ethical, and human rights dimensions of non-consensual bodily alterations performed on minors. He authored and co-authored numerous legal analyses and scholarly papers arguing that non-therapeutic infant circumcision violates established medical ethics, fails to meet standards for valid parental consent, and conflicts with constitutional and international protections regarding child health and physical integrity.

Geisheker engaged extensively in educational outreach, presenting at academic institutions, legal seminars, and medical conferences. His work helped shape the legal arguments used by intactivist organizations to challenge non-therapeutic medical interventions on infants and promote gender-inclusive bodily autonomy.', '', '', 'champion', 'Executive Director and Legal Counsel for Doctors Opposing Circumcision (DOC) and legal scholar for child bodily integrity.', 0, '[{"name": "Mark D. Reiss", "score": 10.668, "shared_docs": 2}, {"name": "George C. Denniston", "score": 8.794, "shared_docs": 2}, {"name": "Doctors Opposing Circumcision", "score": 8.751, "shared_docs": 3}, {"name": "Robert S. Van Howe", "score": 7.699, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 5.303, "shared_docs": 3}]');
