INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-7206e711', 'person', 'Marie Fox', 'Marie Fox is a British legal academic and professor of law specializing in health law, bioethics, and feminist legal theory. Having held prominent academic appointments at institutions including the University of Liverpool and the University of Manchester, her scholarly research extensively explores the legal regulation of the body, healthcare decision-making, and bodily integrity rights.', '', '', 'champion', 'British legal scholar and bioethicist known for her critical legal analysis of non-consensual male infant circumcision and children''s rights to bodily integrity.', 0, '[{"name": "Marie Fox and Michael Thomson", "score": 11.768, "shared_docs": 4}, {"name": "Michael Thomson", "score": 11.768, "shared_docs": 5}, {"name": "Keele University", "score": 11.183, "shared_docs": 2}, {"name": "Martha Nussbaum", "score": 9.598, "shared_docs": 2}, {"name": "National Health Service", "score": 8.598, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-980bf3f1', 'organization', 'National Organization of Circumcision Information Resource Centers', 'The National Organization of Circumcision Information Resource Centers (NOCIRC) was established in 1985 by nurse Marilyn Milos as one of the first major non-profit organizations in the United States dedicated to securing genital autonomy and ending routine infant circumcision. Founded to address a widespread lack of unbiased information regarding foreskin anatomy, functions, and surgical risks, NOCIRC served as a pioneer in framing non-therapeutic child circumcision as a fundamental violation of human rights and bodily integrity.', '', '', 'champion', 'Pioneering non-profit educational organization founded in 1985 to advocate for bodily autonomy and oppose routine infant circumcision.', 1, '[{"name": "Tatiana Bertschinger", "score": 9.116, "shared_docs": 3}, {"name": "Sara Pitta", "score": 8.946, "shared_docs": 4}, {"name": "American Pediatric Urologic Society", "score": 8.946, "shared_docs": 2}, {"name": "University of Lausanne", "score": 8.946, "shared_docs": 2}, {"name": "Kris Teplin", "score": 8.946, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-5dfc8932', 'organization', 'University of Washington School of Medicine', 'The University of Washington School of Medicine is a public academic medical center and research institution based in Seattle, Washington. Established in 1946, the school is widely recognized for its clinical training, primary care programs, and extensive biomedical research output. Within the broader landscape of American healthcare and public health, the institution plays a significant role in establishing regional clinical practices, educating medical practitioners, and publishing peer-reviewed research across various surgical and pediatric disciplines.

In the context of the discourse surrounding circumcision and bodily autonomy, the University of Washington School of Medicine serves as a key institutional reference point. Faculty, researchers, and clinical staff associated with the institution have contributed to medical literature addressing pediatric care, surgical outcomes, patient consent, and infectious disease prevention strategies. The school''s affiliated hospitals and clinical guidelines reflect broader trends within American organized medicine regarding routine infant circumcision, informing regional practice standards and parental decision-making frameworks.

While the institution itself functions as an academic and healthcare entity rather than an advocacy organization, its research outputs and clinical policies frequently surface in debates between bodily autonomy advocates and public health proponents. Studies originating from or cited by researchers at the university contribute empirical data and ethical perspectives that inform discussions on non-therapeutic neonatal procedures, informed consent, and bodily integrity.', '', '', 'notable', 'A leading academic medical center whose research and clinical practices contribute to the broader medical literature on routine and therapeutic circumcision.', 1, '[{"name": "CircFacts", "score": 10.668, "shared_docs": 2}, {"name": "Stephen Moreton", "score": 10.253, "shared_docs": 2}, {"name": "VA Puget Sound Health Care System", "score": 10.253, "shared_docs": 2}, {"name": "John N. Krieger", "score": 9.99, "shared_docs": 5}, {"name": "Circumcision Academy of Australia", "score": 9.838, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-be709441', 'person', 'David Gollaher', 'David L. Gollaher is an American historian, executive, and scholar known for his contributions to the history of medicine and public health. He earned his Ph.D. in the history of science from Harvard University and held prominent leadership roles in healthcare and life sciences organizations, including serving as the president and CEO of the California Healthcare Institute.

Gollaher gained widespread recognition in the discourse on bodily integrity with his seminal 2000 book, "Circumcision: A History of the World''s Most Controversial Operation." In this work, he comprehensively traced the evolution of male infant circumcision from ancient religious and ritual origins to its routine medicalization in nineteenth- and twentieth-century English-speaking nations. His research illuminated how Victorian-era medical theories regarding masturbation, hygiene, and disease prevention transformed a religious rite into a standard hospital procedure in the United States.

His historical scholarship provided essential context for medical ethicists, sociologists, and intactivist advocates seeking to understand the institutional and cultural factors behind routine neonatal circumcision. By documenting the rise and gradual decline of the practice in the West, Gollaher''s work remains a primary scholarly reference point in debates surrounding consent, medical necessity, and bodily autonomy.', '', '', 'notable', 'Medical historian and author of ''Circumcision: A History of the World''s Most Controversial Operation.''', 1, '[{"name": "Lewis Sayre", "score": 9.768, "shared_docs": 2}, {"name": "Dena Davis", "score": 9.575, "shared_docs": 2}, {"name": "Thomas Szasz", "score": 9.253, "shared_docs": 2}, {"name": "Dan Bollinger", "score": 8.183, "shared_docs": 2}, {"name": "Robert Darby", "score": 8.021, "shared_docs": 4}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-c4a74f4a', 'person', 'Maimonides', 'Moses ben Maimon (1138–1204), widely known as Maimonides or the Rambam, was a Sephardic Jewish philosopher, physician, and prominent Rabbinic authority of the Middle Ages. Born in Córdoba and later serving as the personal physician to Saladin''s court in Cairo, his codification of Jewish law in the Mishneh Torah and his philosophical masterwork, The Guide for the Perplexed, established him as one of the most influential figures in Jewish history and medieval philosophy.

Within the discourse surrounding circumcision, Maimonides is a foundational historical figure due to his detailed legal and philosophical treatments of brit milah (Jewish ritual circumcision). In Book III, Chapter 49 of The Guide for the Perplexed, he posited that one of the primary purposes of circumcision was to quiet bodily desires and weaken the sexual organ''s sensitivity, thereby fostering moral discipline and bodily restraint, alongside serving as a physical unifying mark for the Jewish covenant.

In contemporary debates on bodily autonomy and intactivism, Maimonides'' writings are frequently referenced by both sides of the movement. Intactivist researchers and bodily integrity advocates cite his historical observations as early acknowledgment that circumcision alters and diminishes sexual sensation. Meanwhile, defenders of religious circumcision cite his legal codifications and theological rationale to support the continued preservation of traditional ritual practices.', '', '', 'critic', '12th-century Jewish philosopher and physician whose medieval philosophical writings on circumcision are widely cited in modern genital autonomy discourse.', 0, '[{"name": "Dan Bollinger", "score": 8.598, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 4.455, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f0acc67f', 'organization', 'International Coalition for Genital Integrity', 'The International Coalition for Genital Integrity (ICGI) is an international network and advocacy organization dedicated to protecting children from non-consensual, non-therapeutic genital alterations. Formed to unite global efforts against infant male circumcision, female genital cutting, and involuntary intersex surgeries, the organization operates on the foundational principle that every individual possesses an absolute right to bodily autonomy and physical integrity.

Throughout its active years, ICGI facilitated collaboration among legal scholars, medical professionals, human rights advocates, and grassroots intactivist organizations worldwide. By organizing international symposia, disseminating educational materials, and engaging with international rights bodies, the coalition worked to shift public and medical consensus, framing childhood genital cutting as a fundamental human rights issue rather than a benign cultural tradition.

ICGI''s work played a critical role in expanding the reach of the intactivist movement across national borders. By fostering cross-disciplinary dialogue and advocating for legislative reform and ethical medical practices, the coalition helped lay the groundwork for contemporary human rights approaches to genital autonomy.', '', '', 'champion', 'An international advocacy network dedicated to protecting children from non-consensual genital alterations.', 0, '[{"name": "Laurie Evans", "score": 11.668, "shared_docs": 2}, {"name": "Amber Craig", "score": 10.083, "shared_docs": 2}, {"name": "Nurses for the Rights of the Child", "score": 9.931, "shared_docs": 2}, {"name": "Doctors Opposing Circumcision (DOC)", "score": 9.794, "shared_docs": 2}, {"name": "Attorneys for the Rights of the Child (ARC)", "score": 9.794, "shared_docs": 2}]');
