INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-b795d21f', 'person', 'C. Everett Koop', 'Charles Everett Koop (1916–2013) was an American pediatric surgeon and public health administrator who served as the 13th Surgeon General of the United States from 1982 to 1989 under President Ronald Reagan. Prior to his government service, Koop was the surgeon-in-chief at the Children''s Hospital of Philadelphia, where he gained international recognition as a pioneer in pediatric surgery, congenital defect repair, and neonatal care.

During his tenure as Surgeon General and throughout his surgical career, Koop addressed a wide array of public health issues, including tobacco control, HIV/AIDS education, and pediatric medical practices. In the context of infant circumcision, Koop applied his extensive experience in pediatric surgery to evaluate the medical necessity of routine neonatal procedures, contributing authoritative commentary to ongoing clinical and public health discussions.

Koop maintained a cautious perspective regarding routine non-therapeutic infant circumcision, reflecting broader shifts in pediatric medicine during the late 20th century. He emphasized that the procedure lacked sufficient preventative health justifications to warrant universal application, encouraging parents and medical professionals to weigh the surgical risks and considerations carefully.', '', '', 'notable', '13th Surgeon General of the United States and prominent pediatric surgeon whose public health perspective influenced debates on routine infant circumcision.', 0, '[{"name": "Stanford University Medical School", "score": 11.405, "shared_docs": 2}, {"name": "Eugene Robin", "score": 10.183, "shared_docs": 2}, {"name": "Frederick Leboyer", "score": 9.405, "shared_docs": 2}, {"name": "Dean Edell", "score": 9.405, "shared_docs": 2}, {"name": "Benjamin Spock", "score": 8.82, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-b0206dee', 'person', 'Benjamin Spock', 'Dr. Benjamin Spock (1903–1998) was an American pediatrician and author whose seminal work, The Common Sense Book of Baby and Child Care (1946), became one of the most influential parenting guides of the twentieth century. His advice shaped the child-rearing practices of millions of families worldwide, bestowing upon him unprecedented cultural and medical influence over infant healthcare and routine surgical procedures in North America.

Early in his career, Spock reflected the prevailing American medical consensus that favored routine neonatal circumcision, endorsing or accepting the practice in initial editions of his book. However, as medical research evolved and ethical questions regarding bodily integrity and pain management gained traction, Spock publicly reexamined his stance. By the late 1980s and 1990s, he reversed his position, revising later editions of his book to explicitly advise parents against routine circumcision and emphasizing that intact anatomy was natural and healthy.

Spock''s high-profile change of mind provided critical mainstream legitimacy to the growing foreskin advocacy and intactivist movements. By using his platform to oppose routine neonatal circumcision, he challenged long-held clinical assumptions and contributed significantly to the declining rates of infant circumcision in the United States during the late twentieth century.', '', '', 'champion', 'Influential American pediatrician and author whose stance on routine infant circumcision shifted from standard approval to strong opposition later in his career.', 1, '[{"name": "J. David Bigelow", "score": 9.235, "shared_docs": 2}, {"name": "C. Everett Koop", "score": 8.82, "shared_docs": 3}, {"name": "Gerald A. Larue", "score": 8.82, "shared_docs": 2}, {"name": "Moshe Rothenberg", "score": 8.82, "shared_docs": 2}, {"name": "Frederick Leboyer", "score": 8.557, "shared_docs": 5}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-bacf3f53', 'person', 'Desmond Morris', 'Desmond Morris is a renowned British zoologist, ethologist, surrealist painter, and popular science author best known for his groundbreaking 1967 book *The Naked Ape*. Throughout his career, Morris applied zoological and evolutionary principles to the study of human behavior, culture, and body modification rituals. His work examined human anatomical and social developments from a strictly biological perspective, challenging long-held cultural traditions and social norms.

In his writings on human anatomy and cultural practices, including *The Naked Ape*, *Manwatching*, and *The Human Sexes*, Morris offered explicit critiques of routine infant male circumcision and female genital cutting. He analyzed these practices as socio-cultural rituals of body marking and trauma rather than medically necessary procedures, highlighting the evolutionary function of human foreskin and the physical and psychological harm caused by involuntary non-therapeutic genital surgery. His accessible scientific commentary helped demystify human biology and provided early popular academic backing to the bodily autonomy movement.', '', '', 'champion', 'British zoologist, ethologist, and author whose evolutionary writings provided early popular scientific critiques of routine genital cutting.', 0, '[{"name": "Sigmund Freud", "score": 9.166, "shared_docs": 2}, {"name": "Ronald Goldman", "score": 8.209, "shared_docs": 2}, {"name": "Marilyn Fayre Milos", "score": 7.609, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 4.718, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-9beb1369', 'person', 'Van Lewis', 'Van Lewis is an American bodily autonomy advocate and intactivist who has engaged in public education and advocacy regarding routine infant circumcision. His work within the intactivist movement focuses on raising awareness about foreskin restoration, the ethical implications of non-consensual pediatric procedures, and the preservation of bodily integrity for children.', '', '', 'champion', 'American intactivist and advocate for bodily autonomy and foreskin restoration awareness.', 0, '[{"name": "David Llewellyn", "score": 11.668, "shared_docs": 2}, {"name": "Kristen O''Hara", "score": 11.668, "shared_docs": 2}, {"name": "George Wald", "score": 11.253, "shared_docs": 2}, {"name": "Bruno Bettelheim", "score": 10.668, "shared_docs": 2}, {"name": "Steve Scott", "score": 10.668, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-bf2732ed', 'person', 'Edward Wallerstein', 'Edward Wallerstein was an American author, researcher, and early pioneer in the contemporary movement opposing routine infant circumcision. He gained national prominence in 1980 with the publication of his landmark book, "Circumcision: An American Health Fallacy," which provided one of the first comprehensive, multidisciplinary critiques of non-therapeutic neonatal circumcision in the United States.

In his work, Wallerstein systematically analyzed medical literature, historical trends, and sociological factors, arguing that routine circumcision lacked sound medical justification and carried significant underreported risks. His writing exposed inconsistencies in medical policy and challenged the prevailing clinical consensus of the era, offering parents and healthcare providers a detailed counter-narrative to the widespread practice.

Wallerstein''s research served as a foundational text for the modern intactivist movement, directly influencing subsequent scholars, advocacy organizations, and human rights campaigners. Through his literature and public outreach, he played a critical role in framing non-consensual infant circumcision as an issue of bodily integrity, child welfare, and medical ethics.', '', '', 'champion', 'Author of Circumcision: An American Health Fallacy and pioneer of modern anti-circumcision literature', 1, '[{"name": "Society for Humanistic Judaism", "score": 8.432, "shared_docs": 3}, {"name": "T. Berry Brazelton", "score": 8.432, "shared_docs": 3}, {"name": "Anne Briggs", "score": 8.04, "shared_docs": 4}, {"name": "P. C. Remondino", "score": 7.847, "shared_docs": 3}, {"name": "Leonard J. Marino", "score": 7.847, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-89ce8a8c', 'person', 'Jed Diamond', 'Dr. Jed Diamond is an American psychotherapist, author, and prominent figure in the field of men''s health and psychology. Holding a Ph.D. in International Health and a Master''s degree in Social Work, Diamond has authored numerous books and articles focusing on male health, psychological well-being, relationships, and trauma. Throughout his multi-decade career, he has worked to address the unique biological, emotional, and social challenges faced by men throughout various life stages.

Within the discourse on bodily autonomy and intactivism, Diamond has examined the psychological and emotional ramifications of routine infant circumcision. His work explores the potential long-term impacts of neonatal pain and bodily alteration on male bonding, sexual intimacy, and emotional resilience. By writing about the connection between early genital cutting and trauma, Diamond has advocated for the protection of children''s bodily integrity and emphasized the importance of male emotional healing.', '', '', 'champion', 'Psychotherapist, author, and men''s health advocate who explores the psychological and emotional impacts of infant circumcision.', 1, '[{"name": "Dick Mansfield", "score": 10.575, "shared_docs": 3}, {"name": "Sam Keen", "score": 9.99, "shared_docs": 2}, {"name": "Paul Shippee", "score": 9.99, "shared_docs": 2}, {"name": "Robert Bly", "score": 9.99, "shared_docs": 2}, {"name": "John Mark", "score": 9.99, "shared_docs": 2}]');
