INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-b944461d', 'person', 'Frederick Leboyer', 'Frédérick Leboyer (1918–2017) was a French obstetrician and author who gained international recognition for his pioneering approach to humanized childbirth. After completing his medical education at the University of Paris and practicing conventional obstetrics for decades, Leboyer began critically evaluating standard medical procedures surrounding delivery. In 1975, he published his influential book, Birth Without Violence, which challenged medical paradigms by asserting that newborns are sensitive beings who experience profound physical and emotional trauma during violent hospital births.

Leboyer advocated for delivery practices that prioritized the comfort and dignity of the infant, including dimming bright delivery room lights, maintaining quiet environments, encouraging immediate skin-to-skin contact, delaying umbilical cord clamping, and placing newborns in warm baths to ease their transition into the world. His work played a major role in shifting global birth practices toward gentler, family-centered care.

Within the broader context of bodily autonomy and intactivism, Leboyer''s philosophy provided a key conceptual framework for critiques of routine infant male circumcision. By establishing that infants experience lasting distress from painful neonatal interventions, his work was frequently cited by anti-circumcision advocates to argue against non-therapeutic genital surgeries and to advocate for the fundamental right of newborns to gentle treatment and physical integrity.', '', '', 'notable', 'French obstetrician and pioneer of gentle childbirth whose work highlighted newborn sensitivity and inspired critiques of routine infant trauma.', 1, '[{"name": "Eugene Robin", "score": 10.183, "shared_docs": 4}, {"name": "Rima Laibow", "score": 10.183, "shared_docs": 4}, {"name": "P. R. Hickey", "score": 9.768, "shared_docs": 3}, {"name": "C. Everett Koop", "score": 9.405, "shared_docs": 2}, {"name": "K. J. S. Anand", "score": 9.405, "shared_docs": 3}]');
