INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-5ab18774', 'person', 'John M. Foley', 'John M. Foley was a medical professional and advocate who contributed to the critical discourse surrounding routine infant circumcision and bodily autonomy. Through his participation in educational and advocacy initiatives, Foley addressed the ethical, medical, and legal implications of performing non-therapeutic genital surgical procedures on minors without their consent. His work emphasized the importance of medical ethics, patient rights, and the preservation of bodily integrity.

Throughout his involvement in the intactivist movement, Foley engaged with medical literature and public forums to challenge prevailing clinical assumptions regarding the health benefits of neonatal circumcision. By advocating for evidence-based medicine and human rights standards, he sought to inform both health care providers and parents about the physical and ethical consequences of non-consensual bodily modifications.', '', '', 'champion', 'A medical advocate and commentator dedicated to challenging routine infant circumcision and promoting bodily integrity.', 0, '[{"name": "INTACT Educational Foundation", "score": 11.253, "shared_docs": 2}, {"name": "Bruno Bettelheim", "score": 10.668, "shared_docs": 2}, {"name": "Sigmund Freud", "score": 9.166, "shared_docs": 2}, {"name": "James DeMeo", "score": 8.346, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 4.718, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-05f3fea0', 'organization', 'INTACT Educational Foundation', 'The INTACT Educational Foundation is an advocacy and non-profit organization dedicated to promoting bodily autonomy, children''s rights, and the protection of infants from non-consensual routine circumcision. Established to address the social, medical, and ethical dimensions of non-therapeutic genital alterations, the foundation focuses on raising awareness about the importance of bodily integrity from birth. Through educational campaigns and outreach programs, the organization seeks to inform expectant parents, healthcare professionals, and the wider public about the physiological functions of the foreskin and the ethical considerations surrounding pediatric medical consent.

Throughout its history, the foundation has developed and distributed educational literature, hosted public awareness initiatives, and engaged in media outreach to challenge cultural norms surrounding routine infant circumcision. By framing intact anatomy as a default human right, the organization provides resources on intact care and counteracts medical misconceptions regarding male genital cutting. It also serves as a supportive platform for individuals affected by involuntary neonatal circumcision, advocating for legal and medical reforms that align with international human rights standards.

Within the broader context of the intactivist movement, the INTACT Educational Foundation has played a key role in framing circumcision as a bodily autonomy issue rather than merely a personal or cultural preference. Its work emphasizes the principle that every individual should retain the right to make informed decisions regarding their own body when they reach an age of consent. By contributing research, educational materials, and advocacy frameworks, the foundation continues to influence contemporary debates surrounding medical ethics and pediatric rights.', '', '', 'champion', 'An advocacy and educational organization dedicated to ending non-consensual infant circumcision and advancing bodily autonomy.', 0, '[{"name": "John M. Foley", "score": 11.253, "shared_docs": 2}, {"name": "Rosemary Romberg", "score": 8.82, "shared_docs": 2}, {"name": "American Medical Association", "score": 7.271, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-bb37268a', 'organization', 'American College of Obstetricians and Gynecologists (ACOG)', 'The American College of Obstetricians and Gynecologists (ACOG) is a leading professional association of physicians specializing in obstetrics and gynecology in the United States. Founded in 1951, ACOG sets clinical standards, produces educational resources, and issues policy guidance affecting maternal and neonatal health. Because obstetricians and clinical delivery staff frequently perform or advise parents on infant male circumcision in hospital settings, the organization occupies a central position in the institutional practice of the procedure.

In the ongoing discourse regarding circumcision and bodily autonomy, ACOG''s position has largely aligned with the American Academy of Pediatrics (AAP). ACOG officially endorsed the AAP''s 2012 Task Force on Circumcision policy statement, which concluded that the preventive health benefits of newborn male circumcision outweigh the risks, while maintaining that the decision should ultimately rest with parents in consultation with medical providers. This position supported the medical necessity of access to the procedure and recommended third-party insurance coverage.

Because of its endorsement of guidelines affirming the health benefits of non-therapeutic neonatal circumcision, ACOG has been a target of critique from intactivist organizations and bodily autonomy advocates. Critics argue that ACOG''s policy framework legitimizes non-consensual bodily alterations on minors and fails to uphold the child''s right to bodily integrity, whereas ACOG maintains its guidance reflects an evidence-based assessment of clinical risks and preventive benefits.', '', '', 'critic', 'A premier medical association that endorsed joint policy statements affirming the health benefits of non-therapeutic newborn male circumcision.', 1, '[{"name": "Jacob Oster", "score": 10.99, "shared_docs": 2}, {"name": "Donna Macris", "score": 8.99, "shared_docs": 2}, {"name": "American Academy of Pediatrics (AAP)", "score": 8.225, "shared_docs": 5}, {"name": "George C. Denniston", "score": 8.116, "shared_docs": 2}, {"name": "Marilyn Fayre Milos", "score": 7.516, "shared_docs": 3}]');
