INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-72bd0d5f', 'person', 'K. J. S. Anand', 'Kanwaljeet S. "Sunny" Anand is a distinguished pediatrician, anesthesiologist, and clinical researcher whose pioneering work transformed the scientific understanding of neonatal pain perception. After earning his medical degree in India and completing advanced research training at the University of Oxford and Harvard Medical School, Anand dedicated his career to studying the neurobiology and clinical management of pain in critically ill infants and newborns.', '', '', 'notable', 'Pediatric anesthesiologist and researcher whose landmark studies on neonatal pain perception revolutionized medical understanding of infant surgical distress and routine circumcision.', 1, '[{"name": "P. R. Hickey", "score": 11.405, "shared_docs": 7}, {"name": "Frederick Leboyer", "score": 9.405, "shared_docs": 3}, {"name": "Benjamin Spock", "score": 8.235, "shared_docs": 3}, {"name": "Rosemary Romberg", "score": 8.235, "shared_docs": 3}, {"name": "Edward Wallerstein", "score": 7.262, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-a374a08d', 'person', 'Anna Taddio', 'Anna Taddio is a Canadian clinical pharmacist, professor, and researcher at the Leslie Dan Faculty of Pharmacy at the University of Toronto, as well as a Senior Associate Scientist at The Hospital for Sick Children in Toronto. She has dedicated much of her academic career to pediatric pain management, pain mitigation strategies, and understanding the long-term physiological and psychological impacts of early childhood procedural pain.', '', '', 'notable', 'Canadian academic researcher whose landmark studies demonstrated the long-term neurobiological impacts and pain hypersensitivity caused by neonatal circumcision.', 0, '[{"name": "Canadian Paediatric Society", "score": 7.353, "shared_docs": 3}, {"name": "American Academy of Pediatrics", "score": 4.817, "shared_docs": 3}]');
