INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f2091025', 'organization', 'National Organization to Halt the Abuse and Routine Mutilation of Males', 'The National Organization to Halt the Abuse and Routine Mutilation of Males (NOHARMM) was founded in 1992 by Tim Hammond as an advocacy group dedicated to ending routine neonatal male circumcision in the United States. Operating from a human rights and bodily autonomy perspective, NOHARMM emerged as a key organizational voice within the growing intactivist movement during the 1990s, aiming to challenge long-standing medical and cultural justifications for non-therapeutic infant foreskin removal.

NOHARMM''s work focused on public education, medical ethics advocacy, and providing support resources for circumcised men who experienced physical or psychological distress from their infant circumcisions. Under Hammond''s leadership, the organization conducted foundational survey research on circumcised men''s attitudes toward their alterings, offering early qualitative and quantitative insights that helped legitimize the psychological study of circumcision loss within anti-circumcision literature.

Alongside contemporary advocacy organizations such as NOCIRC, NOHARMM played a critical role in framing routine male circumcision as an unnecessary bodily harm and a violation of children''s rights. Through educational campaigns, media outreach, and support for foreskin restoration initiatives, NOHARMM contributed significantly to broadening national discourse surrounding infant genital integrity and individual consent.', '', '', 'champion', 'An American non-profit advocacy organization established in 1992 to oppose routine infant male circumcision and promote genital autonomy.', 1, '[{"name": "Men Organized Against Infant Circumcision", "score": 10.575, "shared_docs": 3}, {"name": "National Organization of Restoring Men", "score": 9.353, "shared_docs": 3}, {"name": "Jennifer A. Bossio", "score": 7.99, "shared_docs": 2}, {"name": "Paul Fleiss", "score": 7.838, "shared_docs": 3}, {"name": "National Organization of Circumcision Information Resource Centers", "score": 7.531, "shared_docs": 4}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-8f8697c9', 'person', 'Charles A. Bonner', 'Charles A. Bonner is an American civil rights attorney based in Northern California with a long career focused on constitutional law, human rights, and bodily integrity advocacy. Admitted to the California Bar in 1978, Bonner established a legal practice centered on representing individuals whose fundamental rights have been infringed by systemic practices, government institutions, or medical protocols.', '', '', 'champion', 'Civil rights attorney known for representing intactivist legal challenges and defending bodily autonomy initiatives in California.', 1, '[{"name": "Michael J. Kinane", "score": 11.405, "shared_docs": 4}, {"name": "Jeffery M. Paige", "score": 10.82, "shared_docs": 2}, {"name": "Shelton Walden", "score": 10.82, "shared_docs": 2}, {"name": "William Stowell", "score": 10.82, "shared_docs": 2}, {"name": "University of California Press", "score": 10.083, "shared_docs": 2}]');
