INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-ae3e5d53', 'person', 'Karen Ericksen Paige', 'Karen Ericksen Paige was an American sociologist and psychologist whose academic research critically examined reproductive rituals, gender roles, and bodily practices. Holding a Ph.D. in psychology from the University of Michigan, she served for many years as a professor at the University of California, Davis, where her work focused on the intersection of social structures, medicine, and human behavior.

In the late 1970s, Paige emerged as one of the first academic figures to challenge the medical rationales surrounding routine infant male circumcision in the United States. Her landmark 1978 article, "The Ritual of Circumcision," published in Psychology Today, analyzed the practice through a sociological lens. She argued that the procedure persisted not because of demonstrable health benefits, but due to entrenched cultural traditions, medical conservatism, and social conformity.

Her broader contributions, including the 1981 book "The Politics of Reproductive Ritual" (co-authored with Richard C. Paige), provided foundational intellectual support for the emerging genital autonomy movement. By framing routine infant circumcision as a societal ritual rather than an essential medical intervention, Paige helped pave the way for subsequent ethical and medical reevaluations of non-consensual bodily alterations.', '', '', 'champion', 'A sociologist and researcher whose pioneering 1970s critiques exposed routine infant circumcision as a cultural ritual rather than a medical necessity.', 0, '[{"name": "Jeffery M. Paige", "score": 11.99, "shared_docs": 3}, {"name": "Michael J. Kinane", "score": 10.99, "shared_docs": 2}, {"name": "University of California Press", "score": 10.668, "shared_docs": 2}, {"name": "Charles A. Bonner", "score": 9.82, "shared_docs": 2}, {"name": "Moses Maimonides", "score": 7.781, "shared_docs": 2}]');
