INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-16241897', 'organization', 'Elsevier', 'Elsevier is a major global academic publishing company specializing in scientific, technical, and medical content. Established in its modern form in 1880 and headquartered in Amsterdam, the publisher maintains a vast portfolio of peer-reviewed scientific journals, books, and reference works across clinical medicine, bioethics, public health, and the social sciences.

Within the discourse surrounding circumcision, bodily autonomy, and genital integrity, Elsevier serves as a primary conduit for peer-reviewed research and scholarly debate. Its clinical and surgical journals—such as the *Journal of Pediatric Urology*, *Urology*, and *The Lancet*—frequently publish studies examining the physiological outcomes, complication rates, surgical techniques, and psychological effects of male, female, and intersex genital procedures.

While Elsevier as a corporate entity maintains an editorial stance of neutrality, its publications play a critical role in shaping public policy and academic understanding of genital cutting. Research published under its imprint is regularly cited by medical associations, bioethicists, human rights advocates, and intactivist organizations in debates concerning consent, medical necessity, and bodily integrity.', '', '', 'notable', 'A major academic publisher whose peer-reviewed medical and ethical journals host key scholarly debates on circumcision and bodily autonomy.', 0, '[{"name": "Reproductive Health Matters", "score": 11.183, "shared_docs": 2}, {"name": "World Health Organization", "score": 5.768, "shared_docs": 3}, {"name": "American Academy of Pediatrics", "score": 4.232, "shared_docs": 2}]');
INSERT OR IGNORE INTO entity_nominations (id, type, name, description, justification, status) VALUES ('nom-4ab9bb7a', 'organization', 'Reproductive Health Matters', '', 'Auto-detected: mentioned in 3 archive documents.', 'pending');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-d3dc0882', 'person', 'Jennifer A. Bossio', 'Jennifer A. Bossio, Ph.D., is a Canadian clinical psychologist and sexology researcher recognized for her empirical work investigating the sensory and psychological correlates of male circumcision. During her academic career at Queen''s University in Kingston, Ontario, Bossio conducted controlled studies evaluating physiological and functional outcomes between circumcised and uncircumcised men.

Her research, frequently co-authored with prominent sex researchers such as Caroline Pukall, utilized standardized methodologies to measure penile tactile sensitivity thresholds, thermal pain perception, and sexual satisfaction. By applying rigorous experimental designs to the study of foreskin anatomy and sensory perception, Bossio''s publications provided nuanced scientific data to a research landscape historically characterized by conflicting conclusions and anecdotal assertions.

Within the broader discourse surrounding bodily autonomy and genital modification, Bossio''s scientific output is regularly cited by medical ethicists, clinicians, and advocacy groups seeking objective evidence regarding the sensory consequences of neonatal and adult circumcision. Her scholarly contributions remain significant references in contemporary discussions on human sexuality, surgical anatomy, and informed consent.', '', '', 'notable', 'Canadian clinical psychologist and researcher known for empirical studies on penile sensitivity and sexual function in relation to circumcision status.', 1, '[{"name": "Caroline F. Pukall", "score": 10.99, "shared_docs": 8}, {"name": "Stephen Steele", "score": 10.99, "shared_docs": 4}, {"name": "Queen''s University", "score": 10.505, "shared_docs": 5}, {"name": "Adrienne Carmack", "score": 9.99, "shared_docs": 2}, {"name": "National Organization of Restoring Men", "score": 9.183, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-8791db2a', 'person', 'Caroline F. Pukall', 'Caroline F. Pukall, Ph.D., is a Professor in the Department of Psychology at Queen''s University in Kingston, Ontario, and a prominent Canadian clinical psychologist and sexologist. She serves as the director of the Sexual Health Research Laboratory at Queen''s University, where her scholarship broadly encompasses human sexuality, sexual pain conditions, and the physiological aspects of sexual response. Beyond her widely recognized work on vulvodynia and female sexual health, Pukall has established a significant body of academic literature investigating male genital anatomy and sexual function.

In the context of male circumcision, Pukall''s research group conducted landmark studies assessing tactile sensitivity, sexual function, and satisfaction differences between circumcised and uncircumcised men. Utilizing quantitative sensory testing to measure fine-touch and somatosensory thresholds across various regions of the penis, her work provided objective clinical data to a field often characterized by subjective reporting. These findings added empirical rigor to long-standing scientific debates regarding the neurosensory impact of foreskin removal.

Pukall''s contributions occupy an influential position within the literature surrounding bodily autonomy, medical ethics, and genital integrity. By generating peer-reviewed data on penile neurophysiology, her publications are frequently referenced by medical associations, policy analysts, and advocacy groups on all sides of the discourse. Her work remains a key reference point for understanding the physiological and psychosexual dimensions of male circumcision.', '', '', 'notable', 'Professor of psychology and clinical sexologist known for her empirical research on penile sensitivity, sexual function, and the effects of male circumcision.', 1, '[{"name": "Stephen Steele", "score": 11.575, "shared_docs": 4}, {"name": "Queen''s University", "score": 11.09, "shared_docs": 5}, {"name": "Jennifer A. Bossio", "score": 10.99, "shared_docs": 8}, {"name": "American Academy of Pediatrics", "score": 4.625, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-41706d1f', 'organization', 'Queen''s University', 'Queen''s University is a public research university located in Kingston, Ontario, Canada. Established in 1841, the institution houses well-regarded faculties of medicine, law, and philosophy, making it a key academic hub for research into health policy, medical ethics, and human rights. Within the Canadian higher education landscape, the university has frequently served as a site for scholarly inquiry into routine medical procedures and patient rights.', '', '', 'notable', 'A prominent Canadian research university whose faculties have contributed scholarly research and ethical analyses to the discourse on infant circumcision and bodily autonomy.', 0, '[{"name": "Stephen Steele", "score": 11.353, "shared_docs": 3}, {"name": "Caroline F. Pukall", "score": 11.09, "shared_docs": 5}, {"name": "Jennifer A. Bossio", "score": 10.505, "shared_docs": 5}, {"name": "Brian D. Earp", "score": 6.183, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 4.232, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-407afc52', 'organization', 'Springer Science+Business Media', 'Springer Science+Business Media is a prominent global academic publisher that produces peer-reviewed books, e-books, and scientific journals across science, technology, medicine, humanities, and social sciences. Formed through the merger of several historic publishing houses, the company serves as one of the primary academic dissemination platforms worldwide, hosting vast repositories of medical, legal, and ethical research.', '', '', 'notable', 'A global academic publishing company that disseminates peer-reviewed research, legal scholarship, and medical literature addressing circumcision, bioethics, and bodily integrity.', 1, '[{"name": "National Organization of Restoring Men (NORM)", "score": 7.768, "shared_docs": 2}, {"name": "National Organization of Circumcision Information Resource Centers (NOCIRC)", "score": 5.425, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 4.04, "shared_docs": 2}]');
