INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-da9f4179', 'person', 'John N. Krieger', 'John N. Krieger, M.D., is an American urologist, researcher, and professor emeritus of urology at the University of Washington School of Medicine. Throughout his medical career, he specialized in urological infections, male reproductive health, and sexually transmitted infections (STIs). His scientific output spans several decades and includes extensive clinical research into the etiology and management of complex urological conditions.

Krieger gained notable prominence within international public health discourse through his involvement in landmark clinical trials and epidemiological studies evaluating adult male circumcision as an intervention against HIV transmission and other STIs in sub-Saharan Africa. His published research provided empirical findings that international health organizations, including the World Health Organization and UNAIDS, subsequently cited to support voluntary medical male circumcision programs in regions with high HIV prevalence.

Within the discourse surrounding bodily autonomy and foreskin preservation, Krieger''s work represents a major reference point for medicalized defenses of routine or prophylactic circumcision. Consequently, his research methodologies and conclusions have frequently been analyzed and contested by intactivist scholars and bioethicists who advocate for genital autonomy and question the ethics and efficacy of population-level circumcision initiatives.', '', '', 'critic', 'Urologist and public health researcher whose studies on male circumcision and STI prevention significantly influenced global public health policy.', 1, '[{"name": "Richard G. Wamai", "score": 10.99, "shared_docs": 3}, {"name": "VA Puget Sound Health Care System", "score": 10.99, "shared_docs": 4}, {"name": "CircFacts", "score": 10.405, "shared_docs": 2}, {"name": "Circumcision Academy of Australia", "score": 10.312, "shared_docs": 5}, {"name": "University of Washington School of Medicine", "score": 9.99, "shared_docs": 5}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-73a8b886', 'organization', 'International Society for Sexual Medicine', 'Founded in 1978, the International Society for Sexual Medicine (ISSM) is an international multidisciplinary organization dedicated to research, education, and clinical practice in human sexual health. The society hosts scientific congresses and oversees prominent peer-reviewed publications, including The Journal of Sexual Medicine, which publish clinical studies and systematic reviews on sexual physiology, function, and related medical interventions.

In the context of circumcision and bodily autonomy, the ISSM serves as a primary scientific platform for research evaluating the anatomical, physiological, and psychological impacts of foreskin removal. Studies published under its auspices frequently examine questions regarding penile sensitivity, erectile function, sexual satisfaction, and surgical complications in both adult and pediatric populations.

While the ISSM maintains a broad medical focus rather than a dedicated political or advocacy position on routine circumcision, its scientific output is heavily cited in debates surrounding genital integrity. Intactivists, bioethicists, and medical practitioners frequently rely on ISSM-published literature to analyze claims regarding the sensory function of the prepuce and the impact of non-therapeutic circumcision on sexual health.', '', '', 'notable', 'An international medical association whose peer-reviewed publications provide critical scientific research on penile physiology, sexual function, and circumcision outcomes.', 1, '[{"name": "VA Puget Sound Health Care System", "score": 10.253, "shared_docs": 2}, {"name": "John N. Krieger", "score": 9.253, "shared_docs": 3}, {"name": "University of Washington School of Medicine", "score": 8.931, "shared_docs": 2}, {"name": "Jennifer A. Bossio", "score": 8.668, "shared_docs": 2}, {"name": "University of Sydney", "score": 8.138, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-09856b15', 'organization', 'Doctors Opposing Circumcision (DOC)', 'Founded in 1995 in Seattle, Washington, by medical professionals including Dr. George Denniston, Doctors Opposing Circumcision (DOC) emerged as a physician-led advocacy organization dedicated to ending non-therapeutic infant and pediatric circumcision. The group operates on the principles of evidence-based medicine, bioethics, and bodily integrity, seeking to inform healthcare providers, expectant parents, and the public about the anatomical functions of the human foreskin and the ethical implications of non-consensual genital procedures.', '', '', 'champion', 'An international organization of medical professionals dedicated to ending non-therapeutic infant circumcision through bioethical education and advocacy.', 1, '[{"name": "Laurie Evans", "score": 10.531, "shared_docs": 2}, {"name": "Nurses for the Rights of the Child (NRC)", "score": 10.531, "shared_docs": 2}, {"name": "Amanda Kennedy", "score": 10.116, "shared_docs": 2}, {"name": "International Coalition for Genital Integrity", "score": 9.794, "shared_docs": 2}, {"name": "Peter Charles Remondino", "score": 9.531, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-706122ab', 'organization', 'University of Ottawa', 'Established in 1848, the University of Ottawa is a major bilingual public research university located in Ottawa, Ontario, Canada. Within the academic and legal discourse surrounding bodily autonomy, medical ethics, and children''s rights, the institution has served as an academic hub for research into the ethical, legal, and social dimensions of non-therapeutic pediatric interventions, including routine infant circumcision.

Faculty and researchers associated with the university''s faculties of law, medicine, and bioethics have contributed to scholarly literature on consent, physical integrity, and the duties of healthcare providers regarding bodily alterations on minors. Work originating from or presented at the institution has helped inform broader interdisciplinary discussions on Canadian health policy, human rights frameworks, and the ethical responsibilities surrounding infant male circumcision.', '', '', 'notable', 'A prominent Canadian research institution whose scholars contribute to the legal, ethical, and medical discourse on pediatric bodily autonomy.', 0, '[{"name": "William Cameron", "score": 10.253, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 4.718, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-95fb9a1c', 'person', 'Gregory J. Boyle', 'Gregory J. Boyle is an Australian psychologist, psychometrician, and academic researcher known for his scholarly contributions to the critique of non-therapeutic infant circumcision. Over his career, he held various academic and research appointments, publishing extensively across psychology, neuroscience, and medical ethics.', '', '', 'champion', 'Australian psychologist and academic researcher known for his extensive scholarly publications critiquing routine infant circumcision from psychological and ethical perspectives.', 1, '[{"name": "Bond University", "score": 10.682, "shared_docs": 7}, {"name": "George Hill", "score": 9.875, "shared_docs": 3}, {"name": "University of Melbourne", "score": 9.875, "shared_docs": 2}, {"name": "Queensland Law Reform Commission", "score": 8.875, "shared_docs": 2}, {"name": "Circumcision Academy of Australia", "score": 8.875, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-93a59d39', 'organization', 'Bond University', 'Bond University is a private, non-profit educational institution located in Gold Coast, Queensland, Australia. Established in 1987, the university is recognized for its faculties of law, health sciences, and medicine. Within the broader discourse on bodily autonomy and genitally alterative procedures, Bond University has served as an institutional base for academic researchers contributing to bioethics, health law, and human rights frameworks regarding pediatric medical interventions.', '', '', 'notable', 'A private Australian university whose bioethics and legal scholars have contributed influential research to international debates on bodily autonomy and non-therapeutic pediatric circumcision.', 1, '[{"name": "Gregory J. Boyle", "score": 10.682, "shared_docs": 7}, {"name": "George Hill", "score": 10.575, "shared_docs": 3}, {"name": "Doctors Opposing Circumcision", "score": 8.073, "shared_docs": 3}, {"name": "Attorneys for the Rights of the Child", "score": 7.668, "shared_docs": 2}, {"name": "J. Steven Svoboda", "score": 6.847, "shared_docs": 2}]');
