INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-d20e20bc', 'organization', 'Queensland Law Reform Commission', 'The Queensland Law Reform Commission (QLRC) is an independent statutory body established in Queensland, Australia, tasked with reviewing and recommending reforms to the state''s legal framework. Operating under the Law Reform Commission Act 1968, the Commission functions to modernize, simplify, and systematically review laws to ensure they reflect contemporary social values, legal standards, and human rights principles.

Within the legal discourse surrounding circumcision and bodily autonomy, law reform bodies like the QLRC serve as crucial institutional mechanisms for examining statutory regulations, criminal codes, and medical consent requirements. In Australian legal contexts, the Commission''s inquiries and reporting process frequently touch upon the rights of children, the scope of parental consent, and the legal parameters governing non-therapeutic surgical interventions on minors.

Through public consultations, research papers, and formal reports submitted to the state government, the QLRC provides evidence-based analysis on matters of bodily integrity and child protection. While maintaining an impartial and consultative mandate, the Commission''s reviews help shape legislative approaches to non-therapeutic bodily alterations and inform legal scholarship on autonomy and consent.', '', '', 'notable', 'An independent statutory body in Queensland, Australia, providing legal review and recommendations regarding statutory frameworks, medical consent, and bodily integrity.', 1, '[{"name": "Tasmania Law Reform Institute", "score": 10.253, "shared_docs": 2}, {"name": "High Court of Australia", "score": 10.253, "shared_docs": 2}, {"name": "Australasian Association of Paediatric Surgeons", "score": 9.575, "shared_docs": 3}, {"name": "Australian College of Paediatrics", "score": 9.405, "shared_docs": 2}, {"name": "Gregory J. Boyle", "score": 8.875, "shared_docs": 2}]');
