INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-10939ec0', 'organization', 'Circumcision Resource Center', 'The Circumcision Resource Center (CRC) is a non-profit educational organization founded in 1988 by psychologist and author Dr. Ronald Goldman, based in Boston, Massachusetts. The center was established to address the psychological, emotional, and physical impacts of routine infant male circumcision and to provide comprehensive information to parents, medical practitioners, and mental health professionals. Operating as a pivotal hub within the intactivist and bodily autonomy movements, the CRC has consistently sought to reframe routine circumcision as a cultural practice with documented harms rather than a necessary medical procedure.', '', '', 'champion', 'An educational non-profit organization advocating against infant circumcision and raising awareness of its physical and psychological consequences.', 1, '[{"name": "Roger Saquet", "score": 10.327, "shared_docs": 3}, {"name": "William Sullivan", "score": 10.327, "shared_docs": 3}, {"name": "Vicki MacLean", "score": 10.327, "shared_docs": 3}, {"name": "Charles Konia", "score": 10.327, "shared_docs": 3}, {"name": "Myron Sharaf", "score": 10.327, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-adaa5c3f', 'organization', 'Circumcision Academy of Australia', 'The Circumcision Academy of Australia (CAA) is an association composed of medical practitioners and advocates who support the practice and public health benefits of male circumcision in Australia. Established to counter shifting medical policy guidelines and rising opposition to non-therapeutic infant circumcision, the organization provides medical training, clinical resources, and public information aimed at promoting and maintaining access to circumcision services across the nation.

Within public health and ethical discourses surrounding bodily autonomy, the CAA maintains that neonatal circumcision provides substantial lifelong prophylactic health advantages, such as reduced risk for urinary tract infections, sexually transmitted infections, and penile cancer. The group actively engages with media outlets, policy discussions, and regulatory bodies to defend the procedure against critiques from intactivist organizations, human rights advocates, and bioethicists who emphasize rights to bodily integrity.

The CAA''s advocacy has made it a focal point in Australian debates over children''s rights, consent, and preventative medicine. While the academy frames its mission as advancing evidence-based health measures, critics and bodily autonomy advocates view its positions as promoting unnecessary surgical interventions on unconsenting minors. Despite ongoing societal and professional shifts toward declining circumcision rates in Australia, the CAA remains a prominent organizational voice defending the practice.', '', '', 'critic', 'An Australian association of medical practitioners advocating for the health benefits and practice of infant circumcision.', 1, '[{"name": "CircFacts", "score": 10.99, "shared_docs": 2}, {"name": "Richard G. Wamai", "score": 10.99, "shared_docs": 2}, {"name": "Stephen Moreton", "score": 10.575, "shared_docs": 2}, {"name": "John N. Krieger", "score": 10.312, "shared_docs": 5}, {"name": "University of Washington School of Medicine", "score": 9.838, "shared_docs": 3}]');
