INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-480660ba', 'organization', 'UNESCO', 'The United Nations Educational, Scientific and Cultural Organization (UNESCO) is a specialized agency of the United Nations established in 1945, dedicated to promoting world peace and security through international cooperation in education, the sciences, culture, and communication. Headquartered in Paris, France, UNESCO establishes international standards, charters, and declarations aimed at protecting human rights, cultural heritage, and fundamental freedoms across member states.

Within the discourse on circumcision, bodily autonomy, and intactivism, UNESCO''s work is primarily cited through its foundational bioethics documents and human rights frameworks. Its 2005 Universal Declaration on Bioethics and Human Rights, along with agreements regarding the rights of children and the protection of vulnerable populations, serves as a frequent point of reference for legal scholars, ethicists, and bodily integrity advocates. Intactivist researchers and legal theorists invoke UNESCO''s emphasis on informed consent, individual dignity, and protection from harm when evaluating non-therapeutic genital modifications performed on minors.

Although UNESCO does not maintain an explicit operational focus specifically targeting male circumcision, its mandate intersects regularly with discussions concerning harmful traditional practices, gender equality, and cultural rights versus universal human rights standards. The organization''s declarations provide an institutional standard against which researchers and activists benchmark national policies and legal protections regarding bodily integrity and childhood autonomy.', '', '', 'notable', 'A specialized United Nations agency whose international declarations on bioethics and human rights serve as foundational standards in debates over bodily integrity and cultural practices.', 0, '[{"name": "Robert Darby", "score": 7.699, "shared_docs": 2}, {"name": "UNICEF", "score": 7.638, "shared_docs": 2}, {"name": "UNAIDS", "score": 7.609, "shared_docs": 3}, {"name": "World Health Organization (WHO)", "score": 6.878, "shared_docs": 2}]');
