INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-923054bc', 'person', 'Lisa Braver Moss', 'Lisa Braver Moss is an American author, essayist, and advocate known for her early and influential contributions to the genital autonomy movement, particularly within the context of Jewish cultural and religious tradition. Emerging as a prominent voice against routine infant circumcision in the 1980s and 1990s, Moss has written extensively on the psychological, physical, and ethical dimensions of the procedure, questioning both medical consensus and deep-seated cultural traditions.

Throughout her career, Moss has published commentary in prominent outlets and parenting publications, including landmark essays in Mothering magazine. Her work frequently explores the intersection of bodily integrity, parental responsibility, and religious identity, offering pathways for Jewish families to celebrate covenantal traditions through non-surgical welcoming ceremonies such as Brit Shalom. By advocating for alternative rites, she has worked to reconcile traditional religious heritage with the principles of bodily autonomy.

In addition to her commentary on circumcision and child advocacy, Moss is an accomplished novelist and speaker whose literary works explore themes of family dynamics, personal ethics, and identity. Her long-standing engagement with intactivism has established her as a key figure in reforming religious discourse surrounding non-consensual infant circumcision.', '', '', 'champion', 'American author and advocate who championed genital autonomy and alternative Jewish covenant ceremonies.', 0, '[{"name": "Paul Fleiss", "score": 8.931, "shared_docs": 2}, {"name": "George Denniston", "score": 8.73, "shared_docs": 2}, {"name": "Ronald Goldman", "score": 8.209, "shared_docs": 2}, {"name": "American Academy of Pediatrics (AAP)", "score": 7.581, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 4.718, "shared_docs": 2}]');
