INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-b636f1fe', 'person', 'Jumana Nagarwala', 'Dr. Jumana Nagarwala is an emergency medicine physician based in Detroit, Michigan, who became a central figure in American legal and public discourse surrounding female genital cutting and bodily autonomy. A member of the Dawoodi Bohra Muslim community, Nagarwala was arrested by federal authorities in April 2017 and charged under a 1996 federal statute prohibiting female genital mutilation (FGM), marking the first federal prosecution of its kind in the United States.

The case against Nagarwala centered on allegations that she performed ritual genital cutting procedures on young girls at a clinic in Livonia, Michigan. Defense arguments maintained that the procedures, referred to within the community as khatna or khafz, constituted a minor, religiously motivated ritual rather than severe physical alteration. Conversely, medical organizations, anti-FGM advocates, and bodily autonomy campaigners argued that any non-therapeutic genital cutting performed on minors constitutes a violation of bodily integrity and child protection standards.

In late 2018, a federal district court judge dismissed the core FGM charges against Nagarwala, ruling that Congress exceeded its constitutional authority under the Commerce Clause in passing the federal prohibition, thereby leaving the regulation of such procedures to state law. The case prompted widespread national debate over legislative mechanisms to protect children from non-consensual genital cutting and highlighted the legal complexities of addressing traditional bodily alterations across different cultural contexts.', '', '', 'critic', 'An emergency medicine physician whose landmark 2017 prosecution brought national focus to the legal, medical, and human rights debates surrounding female genital cutting.', 1, '[{"name": "Bernard A. Friedman", "score": 11.575, "shared_docs": 3}, {"name": "United States Department of Justice", "score": 11.575, "shared_docs": 3}, {"name": "Bernard Friedman", "score": 11.575, "shared_docs": 3}, {"name": "Richard Shweder", "score": 10.253, "shared_docs": 2}, {"name": "Danish Medical Association", "score": 8.875, "shared_docs": 2}]');
