INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-8cff1584', 'organization', 'Yale University', 'Yale University, founded in 1701 in New Haven, Connecticut, is a premier private Ivy League research institution. Through the Yale School of Medicine, Yale Law School, and the Interdisciplinary Center for Bioethics, the university has long functioned as a major hub for academic inquiry into public health, pediatric ethics, legal rights, and the history of medicine. Within the context of circumcision and bodily autonomy, Yale faculty, researchers, and alumni have produced influential scholarship addressing the medical, legal, and ethical dimensions of non-therapeutic surgical interventions on minors.

Scholarship associated with Yale has frequently engaged with fundamental questions of bodily integrity, informed consent, and parental authority. Scholars affiliated with the institution have examined the historical evolution of routine neonatal circumcision in the United States, analyzed the legal boundaries of parental proxy consent, and evaluated public health guidelines surrounding elective procedures. While individual academics affiliated with Yale hold varying perspectives ranging from defending circumcision''s medical utility to advocating for bodily autonomy rights, the institution itself acts as a neutral platform for rigorous academic debate.

Through its academic publications, medical library archives, and scholarly symposia, Yale University continues to play a significant role in shaping the intellectual framework of bioethics and health law. Its research output provides foundational citations and analytical models used by medical historians, legal scholars, and advocates on all sides of the circumcision debate.', '', '', 'notable', 'A prestigious American research university whose faculty and affiliated scholars have contributed significant bioethical, legal, and historical scholarship concerning circumcision and bodily autonomy.', 1, '[{"name": "The Hastings Center", "score": 9.298, "shared_docs": 13}, {"name": "Alexandre T. Rotta", "score": 9.183, "shared_docs": 2}, {"name": "Nancy Ehrenreich", "score": 9.031, "shared_docs": 3}, {"name": "Eike-Henner Kluge", "score": 8.446, "shared_docs": 2}, {"name": "Dawoodi Bohra", "score": 8.446, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-464b6173', 'organization', 'The Hastings Center', 'Founded in 1969 by philosopher Daniel Callahan and psychoanalyst Willard Gaylin, The Hastings Center is an independent, nonpartisan bioethics research institute based in Garrison, New York. As one of the world''s premier bioethics institutions, it publishes influential academic journals, including *The Hastings Center Report*, which serve as prominent venues for interdisciplinary scholarship at the intersection of medicine, philosophy, law, and public policy.

Within the discourse on circumcision and bodily autonomy, The Hastings Center has functioned as a vital academic forum for evaluating the moral and legal dimensions of elective pediatric interventions. Scholars publishing through the center have frequently examined the ethical boundaries of parental decision-making, comparing routine infant male circumcision with other non-therapeutic procedures and weighing parental religious or cultural preferences against a child''s future autonomy and right to bodily integrity.

While maintaining an institutional posture of scholarly neutrality rather than policy advocacy, the analyses published by The Hastings Center have significantly informed broader bioethical frameworks. Its literature is regularly cited by medical ethicists, legal experts, and intactivist advocates seeking to define the standards of informed consent and rights-based approaches to pediatric surgical procedures.', '', '', 'notable', 'A leading independent bioethics research institute whose scholarly publications have deeply shaped ethical discourse on pediatric bodily autonomy and routine circumcision.', 1, '[{"name": "Yale-Hastings Program in Ethics and Health Policy", "score": 9.82, "shared_docs": 2}, {"name": "Alexandre T. Rotta", "score": 9.82, "shared_docs": 2}, {"name": "Elizabeth Reis", "score": 9.405, "shared_docs": 2}, {"name": "Yale University", "score": 9.298, "shared_docs": 13}, {"name": "Brian D Earp", "score": 8.668, "shared_docs": 3}]');
