INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-c1b81e21', 'person', 'Richard Shweder', 'Richard A. Shweder is an American cultural anthropologist and the Harold H. Swift Distinguished Service Professor of Human Development at the University of Chicago. A prominent figure in cultural psychology, Shweder has spent decades researching the intersection of culture, morality, and custom. His scholarly work frequently challenges universalist human rights frameworks and Western ethical standards, advocating instead for a perspective grounded in cultural pluralism and tolerance.', '', '', 'critic', 'A cultural anthropologist and University of Chicago professor known for defending traditional genital modifications against Western universalist critiques.', 0, '[{"name": "Bernard Friedman", "score": 11.668, "shared_docs": 2}, {"name": "Dawoodi Bohra", "score": 10.931, "shared_docs": 2}, {"name": "Jumana Nagarwala", "score": 10.253, "shared_docs": 2}, {"name": "Andrew Freedman", "score": 9.553, "shared_docs": 2}, {"name": "Brussels Collaboration on Bodily Integrity", "score": 9.253, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-3837aecf', 'organization', 'Dawoodi Bohra', 'The Dawoodi Bohra are a religious sect within the Ismaili branch of Shia Islam, primarily concentrated in India, Pakistan, and diaspora communities across North America, Europe, and East Africa. Governed by a centralized clergy led by the Dai al-Mutlaq, the community maintains distinct cultural and religious traditions. Within sociological and bodily autonomy archives, the Dawoodi Bohra are frequently cited due to their adherence to childhood genital alterations for both males and females as standard religious practices.

The community practices male circumcision as well as a form of female genital alteration locally referred to as *khaffd* or *khatna*, typically performed on young girls. This practice has made the Dawoodi Bohra a focal point in international legal, medical, and human rights debates regarding bodily integrity, minor consent, and religious freedom. While official leadership has historically characterized the procedure as a minor, obligatory religious rite, international health organizations and legal bodies classify it as a form of female genital mutilation/cutting (FGM/C).

The discourse surrounding the Dawoodi Bohra has catalyzed significant internal reform movements alongside external advocacy. Grassroots organizations founded by Bohra women, such as Sahiyo and WeSpeakOut, have actively campaigned against *khaffd*, advocating for bodily autonomy and child protection. Consequently, the sect serves as a key case study in the intersection of religious tradition, internal community reform, and the broader global movement for genital autonomy.', '', '', 'critic', 'A Shia Islamic religious denomination central to debates on religious tradition, bodily autonomy, and childhood genital alterations.', 0, '[{"name": "Richard Shweder", "score": 10.931, "shared_docs": 2}, {"name": "Canadian Pediatric Society", "score": 10.931, "shared_docs": 2}, {"name": "Dena Davis", "score": 10.253, "shared_docs": 2}, {"name": "Andrew Freedman", "score": 10.138, "shared_docs": 3}, {"name": "Brian D Earp", "score": 9.931, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-43369dd6', 'organization', 'Brussels Collaboration on Bodily Integrity', 'The Brussels Collaboration on Bodily Integrity (BCBI) is an international, interdisciplinary network of bioethicists, legal scholars, medical professionals, and human rights researchers dedicated to analyzing the ethics and legality of non-consensual bodily modifications. Formed to address complex global debates surrounding children''s rights and medical autonomy, the organization focuses on providing rigorous scholarly evaluation of practices that alter the human body without explicit personal consent.', '', '', 'champion', 'An international bioethics research consortium advocating for children''s rights and bodily integrity regarding non-therapeutic genital alterations.', 1, '[{"name": "University of Exeter", "score": 9.99, "shared_docs": 2}, {"name": "Richard Shweder", "score": 9.253, "shared_docs": 2}, {"name": "Kai M\u00f6ller", "score": 9.16, "shared_docs": 3}, {"name": "Richard A. Shweder", "score": 8.405, "shared_docs": 4}, {"name": "Jasmine Abdulcadir", "score": 7.99, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-1b9f3eb9', 'person', 'Dena Davis', 'Dena S. Davis is an American legal scholar and bioethicist who has held prominent academic appointments, including serving as the Presidential Endowed Chair in Law and Religion at Lehigh University and as a professor at the Cleveland-Marshall College of Law. Holding a Ph.D. in Religion and Ethics from the University of Iowa and a J.D. from the University of Virginia, her interdisciplinary scholarship focuses on the intersections of bioethics, constitutional law, religious freedom, and the rights of children.

Davis became a foundational voice in the bioethical analysis of male infant circumcision through her application of Joel Feinberg''s framework regarding a child''s "right to an open future." In her scholarly work, she argued that non-therapeutic genital alterations performed on minors infringe upon their bodily autonomy and future self-determination. Davis posited that parental rights and religious freedom do not extend to making irreversible, non-medically necessary bodily alterations that can be safely deferred until the child is old enough to give informed consent.

Her writings have been widely cited across legal, medical, and bioethical literature, as well as within intactivist discourse. By placing routine infant circumcision within the framework of pediatric bioethics and international human rights law, Davis provided a rigorous academic foundation for arguments favoring the protection of children''s physical integrity.', '', '', 'champion', 'Bioethicist and legal scholar known for pioneering academic critiques of infant circumcision centered on children''s rights and bodily autonomy.', 1, '[{"name": "Uehiro Centre for Practical Ethics", "score": 10.99, "shared_docs": 2}, {"name": "Centers for Disease Control", "score": 10.575, "shared_docs": 2}, {"name": "Dawoodi Bohra", "score": 10.253, "shared_docs": 2}, {"name": "Julian Savulescu", "score": 10.253, "shared_docs": 2}, {"name": "Canadian Pediatric Society", "score": 10.253, "shared_docs": 2}]');
