INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-1590544b', 'organization', 'University of Oxford', 'The University of Oxford, located in Oxford, England, is one of the world''s oldest and most prestigious research institutions. Within the fields of bioethics, philosophy, law, and medicine, Oxford has served as a critical global hub for academic scholarship addressing bodily autonomy, children''s rights, and the ethical dimensions of non-therapeutic genital modifications.', '', '', 'notable', 'A leading global research institution whose bioethicists and scholars have significantly shaped modern academic debates on genital autonomy, consent, and bodily integrity.', 1, '[{"name": "Uehiro Centre for Practical Ethics", "score": 9.253, "shared_docs": 3}, {"name": "National University of Singapore", "score": 9.253, "shared_docs": 4}, {"name": "Brighton and Sussex Medical School", "score": 8.838, "shared_docs": 3}, {"name": "Oxford Uehiro Centre for Practical Ethics", "score": 8.838, "shared_docs": 3}, {"name": "Tanya Gold", "score": 8.668, "shared_docs": 2}]');
