INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-4315e4d7', 'person', 'Edward O. Laumann', 'Edward O. Laumann is an American sociologist and George Herbert Mead Distinguished Service Professor Emeritus at the University of Chicago. He is widely recognized for his pioneering quantitative research on social networks and human sexuality, most notably as the principal investigator for the National Health and Social Life Survey (NHSLS) in the early 1990s. The NHSLS provided one of the most comprehensive demographic and behavioral analyses of sexual practices in the United States, serving as a landmark dataset for social scientists and public health researchers.

Within the sociological discourse surrounding circumcision and bodily autonomy, Laumann contributed pivotal empirical data regarding the prevalence, social distribution, and health correlates of male circumcision in America. His prominent 1997 analysis published in the Journal of the American Medical Association (JAMA), co-authored with Christopher M. Masi and Raoul C. Zuckerman, investigated national patterns of circumcision status and its relationship to sexual dysfunction, sexually transmitted infections, and medical history across diverse demographic groups.

Laumann''s empirical findings have been frequently cited across academic literature, bioethics debates, and intactivist critiques to contextualize the socio-cultural factors driving routine infant circumcision in the United States. Rather than taking a polemical stance, his work provided a methodological framework for examining how medicalized bodily procedures are shaped by social class, ethnicity, and institutional healthcare practices.', '', '', 'notable', 'Prominent American sociologist known for landmark quantitative studies on sexual behavior and male circumcision practices in the United States.', 0, '[{"name": "Thomas E. Wiswell", "score": 7.68, "shared_docs": 2}, {"name": "American Medical Association", "score": 7.049, "shared_docs": 3}, {"name": "National Organization to Halt the Abuse and Routine Mutilation of Males (NOHARMM)", "score": 6.885, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 5.554, "shared_docs": 5}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-1919fb52', 'person', 'Robert Bailey', 'Robert C. Bailey is an American epidemiologist and professor emeritus of public health at the University of Illinois at Chicago. With a background in biological anthropology and public health, Bailey became a prominent figure in global health research through his extensive work on HIV/AIDS prevention in sub-Saharan Africa during the late 20th and early 21st centuries.

Bailey served as the principal investigator for a landmark 2007 randomized controlled trial in Kisumu, Kenya, which evaluated the efficacy of male circumcision in reducing female-to-male transmission of HIV. The findings of this study, alongside parallel trials in Uganda and South Africa, indicated a significant reduction in HIV acquisition risk among circumcised men. These results contributed significantly to the Joint United Nations Programme on HIV/AIDS (UNAIDS) and the World Health Organization (WHO) recommending voluntary medical male circumcision (VMMC) as a core HIV prevention strategy in high-prevalence regions.

Within the broader discourse on circumcision and bodily autonomy, Bailey''s research has been a primary focal point. While public health institutions embraced his findings to justify large-scale VMMC campaigns, intactivists and critics of circumcision argued that such trials overemphasized statistical benefits while minimizing ethical considerations surrounding bodily integrity, surgical complications, and informed consent in resource-limited settings. Consequently, Bailey remains a central academic figure in ongoing international debates over the ethics and utility of medicalized male circumcision.', '', '', 'critic', 'Epidemiologist and public health researcher known for leading landmark clinical trials on male circumcision for HIV prevention.', 0, '[{"name": "Catherine Hankins", "score": 11.668, "shared_docs": 2}, {"name": "Yoweri Museveni", "score": 10.931, "shared_docs": 2}, {"name": "Daniel Halperin", "score": 10.931, "shared_docs": 2}, {"name": "Joint United Nations Programme on HIV/AIDS (UNAIDS)", "score": 9.794, "shared_docs": 2}, {"name": "World Health Organization (WHO)", "score": 7.463, "shared_docs": 3}]');
