INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-a2af95ba', 'person', 'R. Wayne Griffiths', 'R. Wayne Griffiths is an American researcher, author, and activist prominent within the intactivist movement. He has focused extensively on the historical, epidemiological, and ethical aspects of routine infant male circumcision, particularly within the context of American medical practice. Working alongside other scholars and bodily autonomy advocates, Griffiths has contributed significantly to documenting demographic trends and statistical shifts in circumcision rates across the United States.

Throughout his involvement in the movement, Griffiths co-authored numerous articles and reports that challenged prevailing medical rationales for non-therapeutic neonatal circumcision. His research frequently highlighted the historical origins of the practice in the late nineteenth and early twentieth centuries, providing critical context to contemporary debates over medical necessity, parental consent, and children''s human rights. His writings have served as reference points for activists and scholars examining the decline of routine circumcision in various clinical settings.

Through his dedicated research and contributions to anti-circumcision organizations and publications, Griffiths helped reframe the discourse around genital alteration from a routine medical decision to a fundamental issue of bodily autonomy and physical integrity. His work remains a key historical and analytical resource within the broader sociological documentation of the intactivist movement.', '', '', 'champion', 'Intactivist researcher and author known for documenting historical trends and epidemiology of American circumcision', 1, '[{"name": "Brothers United for Future Foreskins (BUFF)", "score": 10.253, "shared_docs": 3}, {"name": "William A. Jellison", "score": 10.083, "shared_docs": 2}, {"name": "J. David Bigelow", "score": 10.083, "shared_docs": 2}, {"name": "Ryan McAllister", "score": 10.083, "shared_docs": 2}, {"name": "Warren Smith", "score": 9.346, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-c7999aeb', 'person', 'Sheila Curran', 'Sheila Curran is an advocate for child rights and bodily integrity who became active in the intactivist movement, primarily working to raise public awareness regarding the ethical and medical arguments against non-consensual infant male circumcision. Operating within human rights and advocacy networks, Curran focused her efforts on educating parents, healthcare professionals, and policy makers about the functional importance of the foreskin and the imperative of bodily autonomy for children.

Throughout her activism, Curran contributed to regional and international efforts to challenge routine pediatric circumcision practices. She frequently collaborated with organizations such as the National Organization of Circumcision Information Resource Centers (NOCIRC) to disseminate educational materials, organize symposiums, and critique the medicalization of routine non-therapeutic procedures performed on minors.

Curran''s work emphasized a human rights perspective, aligning genital autonomy with established international legal frameworks concerning children''s rights. Her efforts contributed to the broader discourse surrounding medical ethics, informed consent, and bodily integrity in modern pediatric healthcare.', '', '', 'champion', 'Prominent intactivist advocate and campaigner for child rights and genital autonomy.', 1, '[{"name": "Sara Pitta", "score": 10.768, "shared_docs": 6}, {"name": "Tatiana Bertschinger", "score": 10.768, "shared_docs": 4}, {"name": "Kris Teplin", "score": 10.768, "shared_docs": 3}, {"name": "Trudie London", "score": 10.282, "shared_docs": 5}, {"name": "United Nations Economic and Social Council", "score": 10.183, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-2348ef1b', 'person', 'Sara Pitta', 'Sara Pitta is an activist and advocate within the intactivist movement, focusing on bodily integrity, children''s rights, and the ethical implications of non-therapeutic routine infant circumcision. Through her public advocacy and engagement with human rights discussions, she has sought to raise awareness regarding the physical and psychological impacts of early childhood genital alterations.', '', '', 'champion', 'An advocate for bodily integrity and genital autonomy in the intactivist movement.', 0, '[{"name": "Tatiana Bertschinger", "score": 11.99, "shared_docs": 4}, {"name": "Julia Attwood", "score": 11.253, "shared_docs": 3}, {"name": "Trudie London", "score": 11.183, "shared_docs": 4}, {"name": "Sheila Curran", "score": 10.768, "shared_docs": 6}, {"name": "National Organization of Circumcision Information Resource Centers", "score": 8.946, "shared_docs": 4}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-59daa737', 'person', 'Brian Morris', 'Brian J. Morris is an Australian molecular biologist and Professor Emeritus of Medical Sciences at the University of Sydney. Over his academic career, he published extensively on cardiovascular genetics, molecular biology, and public health, eventually becoming one of the most prominent academic figures advocating for male circumcision.

Within the discourse surrounding circumcision and bodily autonomy, Morris is widely recognized as a leading advocate for routine neonatal male circumcision. He authored numerous peer-reviewed papers, literature reviews, and books asserting that circumcision provides significant lifelong health benefits, including reduced risks of urinary tract infections, penile cancer, and sexually transmitted infections such as HIV and HPV. His research frequently advocates for universal infant circumcision as a cost-effective preventive health strategy.

Morris''s strong advocacy and scientific conclusions have positioned him in direct opposition to intactivist organizations and medical bodies that emphasize bodily autonomy and child consent. He has frequently engaged in public and academic debates, criticizing health policy statements from Australasian, European, and American medical associations that adopt neutral or restrictive positions regarding non-therapeutic infant circumcision.', '', '', 'critic', 'Australian medical researcher and prominent academic proponent of routine infant male circumcision.', 1, '[{"name": "Roger Collier", "score": 10.116, "shared_docs": 3}, {"name": "Northwestern University", "score": 9.794, "shared_docs": 2}, {"name": "Royal Australasian College of Physicians (RACP)", "score": 9.794, "shared_docs": 2}, {"name": "Michel Garenne", "score": 9.531, "shared_docs": 2}, {"name": "Canadian Medical Association", "score": 9.116, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-a162fe9f', 'person', 'George Denniston', 'Dr. George C. Denniston (1933–2021) was an American physician, public health advocate, and leading figure in the medical opposition to routine non-therapeutic infant circumcision. He earned his medical degree from the University of Pennsylvania and a Master of Public Health from Harvard University. Throughout his career in family planning and preventive medicine, Denniston became deeply concerned with the ethical, anatomical, and psychological ramifications of neonatal circumcision, ultimately transitioning into a dedicated advocate for children''s bodily integrity.', '', '', 'champion', 'Physician, author, and co-founder of Doctors Opposing Circumcision (DOC) who spearheaded medical and ethical opposition to routine infant circumcision.', 1, '[{"name": "Kris Teplin", "score": 10.052, "shared_docs": 3}, {"name": "John Mark", "score": 10.052, "shared_docs": 3}, {"name": "J. David Bigelow", "score": 9.467, "shared_docs": 2}, {"name": "Dick Mansfield", "score": 9.467, "shared_docs": 2}, {"name": "Shelton Walden", "score": 9.467, "shared_docs": 2}]');
