INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-1f933772', 'person', 'Jasmine Abdulcadir', 'Dr. Jasmine Abdulcadir is a Swiss obstetrician-gynecologist, researcher, and faculty member at Geneva University Hospitals (HUG) and the University of Geneva. She is internationally recognized for her clinical leadership and scientific contributions to the healthcare, treatment, and ethics surrounding female genital mutilation/cutting (FGM/C). Her medical practice and academic focus encompass specialized clinical management for affected women, including defibulation, psychosexual support, and clitoral reconstruction procedures.

Throughout her career, Abdulcadir has authored numerous peer-reviewed studies and contributed to international public health guidelines on female genital procedures. Her research critically examines surgical outcomes, pain management, anatomical definitions, and ethical frameworks, advocating for patient-centered care, informed consent, and evidence-based practice. She has frequently collaborated with and advised international bodies, including the World Health Organization (WHO), on clinical guidelines and health policies related to FGM/C.

Within the broader discourse on bodily autonomy and genital integrity, Abdulcadir''s work provides essential empirical and ethical context regarding non-therapeutic female genital alterations. Her comparative analyses and clinical research on female genital anatomy and surgical interventions have made her a key academic authority in discussions spanning medical ethics, human rights, and the physical impacts of genital cutting practices.', '', '', 'notable', 'Swiss obstetrician-gynecologist and leading researcher on the clinical care, medical ethics, and surgical management of female genital cutting.', 1, '[{"name": "National University of Singapore", "score": 10.99, "shared_docs": 4}, {"name": "University of Geneva", "score": 10.768, "shared_docs": 6}, {"name": "Geneva University Hospitals", "score": 10.727, "shared_docs": 5}, {"name": "Lih-Mei Liao", "score": 10.405, "shared_docs": 2}, {"name": "Brighton and Sussex Medical School", "score": 9.99, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-9c8bd74c', 'organization', 'Joint United Nations Programme on HIV/AIDS (UNAIDS)', 'The Joint United Nations Programme on HIV/AIDS (UNAIDS) is an international advocacy and coordinating body established by the United Nations in 1994 to lead the global response to the HIV/AIDS epidemic. Headquartered in Geneva, Switzerland, UNAIDS coordinates the efforts of multiple UN co-sponsoring agencies to expand access to HIV prevention, treatment, care, and support services worldwide.

Within the discourse on circumcision and public health, UNAIDS became a pivotal entity in 2007 when it jointly recommended Voluntary Medical Male Circumcision (VMMC) with the World Health Organization (WHO) as an additional HIV prevention intervention. This recommendation followed randomized controlled trials in South Africa, Kenya, and Uganda suggesting that male circumcision reduced the risk of female-to-male HIV transmission through heterosexual intercourse. Subsequently, UNAIDS helped establish public health targets to scale up VMMC programs across high-prevalence countries in Eastern and Southern Africa.

UNAIDS''s endorsement of circumcision as a biomedical HIV intervention has drawn significant critical analysis from intactivist organizations, bioethicists, and human rights scholars. Critics contend that mass circumcision campaigns prioritize population-level risk reduction at the expense of individual bodily integrity, raising concerns over informed consent, target-driven implementation, and the ethics of expanding procedures to minors and adolescents. UNAIDS has consistently defended its policy directives on the basis of epidemiological research and global health priorities, maintaining that VMMC forms a critical component of comprehensive HIV risk reduction.', '', '', 'critic', 'Joint United Nations program that co-sponsored global voluntary medical male circumcision initiatives for HIV prevention.', 1, '[{"name": "President''s Emergency Plan for AIDS Relief (PEPFAR)", "score": 10.531, "shared_docs": 4}, {"name": "Catherine Hankins", "score": 10.531, "shared_docs": 2}, {"name": "Daniel Halperin", "score": 10.379, "shared_docs": 3}, {"name": "Peter Piot", "score": 9.794, "shared_docs": 2}, {"name": "Robert Bailey", "score": 9.794, "shared_docs": 2}]');
