INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-043092df', 'organization', 'Springer Nature Limited', 'Springer Nature Limited is a major global academic and educational publishing company created in 2015 through the merger of Springer Science+Business Media and the Nature Publishing Group. Headquartered in London, the organization publishes thousands of peer-reviewed journals, books, and scientific resources across medicine, ethics, the social sciences, and the humanities.', '', '', 'notable', 'A major global academic publisher whose journals host key bioethical, medical, and sociological scholarship regarding circumcision and genital autonomy.', 0, '[{"name": "Danish Medical Association", "score": 9.29, "shared_docs": 2}, {"name": "Centers for Disease Control and Prevention", "score": 6.781, "shared_docs": 2}, {"name": "Brian D. Earp", "score": 6.405, "shared_docs": 2}, {"name": "World Health Organization", "score": 5.405, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 5.04, "shared_docs": 3}]');
