INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-5a930f81', 'organization', 'World Association for Sexual Health', 'Founded in 1978 as the World Association for Sexology, the World Association for Sexual Health (WAS) is a global non-governmental organization dedicated to promoting sexual health, rights, and scientific sexology. Comprising international multidisciplinary experts, sexologists, and health professional organizations, WAS works to advance public health policies, comprehensive sex education, and human rights standards worldwide.

Within the discourse on bodily autonomy and genital integrity, WAS plays a critical role through its formal declarations on sexual rights. The organization’s seminal Declaration of Sexual Rights—first adopted in 1999 and comprehensively revised in 2014—explicitly affirms the fundamental rights to bodily integrity, autonomy, and freedom from non-consensual harm and harmful traditional practices. These codified principles are frequently cited by intactivist organizations and human rights scholars as an ethical framework against involuntary, non-therapeutic child circumcision.

Through its international congresses, policy statements, and collaboration with global bodies such as the World Health Organization, WAS continues to shape global standards regarding bodily self-determination. Its human rights framework provides a foundational basis for opposing non-consensual genital modifications and affirming bodily autonomy as an essential component of universal sexual health.', '', '', 'champion', 'An international sexual health organization that established key human rights declarations affirming bodily integrity and autonomy.', 0, '');
