INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e624bd13', 'person', 'David B. Chamberlain', 'David B. Chamberlain (1928–2014) was an American psychologist, author, and pioneer in the field of prenatal and perinatal psychology. He was a co-founder and long-time president of the Association for Pre- and Perinatal Psychology and Health (APPPAH). Throughout his career, Chamberlain focused on validating the consciousness, sensory capabilities, and memory of human fetuses and newborns, challenging long-standing medical assumptions regarding infant pain insensitivity.

Within the discourse on routine infant circumcision, Chamberlain''s work served as an influential critique of early surgical interventions. His landmark studies and popular writings, including his 1988 book *Babies Remember Birth* (later republished as *The Mind of Your Newborn Baby*), argued that newborns experience acute pain and retain implicit psychological trauma from invasive procedures performed without anesthesia. He specifically addressed infant circumcision as a significant source of early trauma that violates the natural bonding process and neurological well-being of the child.

Chamberlain frequently collaborated with intactivist organizations and bodily autonomy advocates, providing psychological research to support arguments against routine non-therapeutic genital cutting. His work helped shift medical and public understanding toward recognizing infants as conscious subjects deserving of physical integrity and trauma-free birth practices.', '', '', 'champion', 'American psychologist and prenatal memory researcher whose work on infant pain and consciousness provided psychological arguments against neonatal circumcision.', 0, '');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-b9c5830d', 'person', 'P. C. Remondino', 'Peter Charles Remondino (1846–1926) was an Italian-born American physician, surgeon, and public health official based in San Diego, California. A prominent figure in regional medicine, Remondino co-founded San Diego''s first private hospital and served as the first president of the local Board of Health. In addition to his general medical and public health work, he became one of the most vocal late 19th-century proponents of routine male circumcision in the United States.

Remondino''s primary contribution to the discourse on circumcision was his 1891 volume, "History of Circumcision: From the Earliest Times to the Present." In this widely cited work, he framed the prepuce as a redundant and hazardous anatomical feature responsible for a vast array of physical, mental, and moral ailments, including epilepsy, alcoholism, and masturbation. He advocated for routine neonatal circumcision as an essential hygienic and prophylactic measure, blending medical theory with moral panic characteristic of Victorian-era medicine.

Within contemporary studies of bodily autonomy and intactivism, Remondino''s legacy is viewed as pivotal to the historical medicalization and normalization of routine infant circumcision in North America. Scholars and bodily autonomy advocates often cite his writings as a prime example of late 19th-century medical pathologization of intact natural anatomy.', '', '', 'critic', '19th-century American physician and author whose 1891 text strongly promoted routine medical circumcision.', 0, '[{"name": "Edward Wallerstein", "score": 7.847, "shared_docs": 3}, {"name": "American Academy of Pediatrics", "score": 4.455, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-263847f2', 'organization', 'Northwestern University', 'Northwestern University, established in 1851 and located in Evanston and Chicago, Illinois, is a leading private research institution known for its contributions to medicine, bioethics, law, and the social sciences. Through its Feinberg School of Medicine, School of Law, and associated healthcare networks, the university has long served as a hub for academic inquiry, clinical research, and ethical analysis regarding medical practices in the United States.

Within the discourse surrounding circumcision and bodily autonomy, Northwestern University has functioned primarily as a venue for scholarship and debate. Researchers, bioethicists, and legal scholars affiliated with the institution have produced published studies and commentary exploring the medical, legal, and ethical dimensions of routine neonatal circumcision. These academic contributions have addressed topics such as parental consent, bodily integrity, pain management during surgical procedures, and the shifting social norms surrounding male infant circumcision in North America.', '', '', 'notable', 'A prominent American research university whose faculty and bioethicists have contributed scholarly research and ethical analysis to the discourse on circumcision and bodily autonomy.', 0, '[{"name": "Roger Collier", "score": 10.668, "shared_docs": 2}, {"name": "Brian Morris", "score": 9.794, "shared_docs": 2}, {"name": "Canadian Medical Association", "score": 9.668, "shared_docs": 2}, {"name": "George Denniston", "score": 8.73, "shared_docs": 2}, {"name": "Doctors Opposing Circumcision", "score": 8.166, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-d234604c', 'organization', 'Johns Hopkins University', 'Johns Hopkins University, a prestigious private research university based in Baltimore, Maryland, has played a prominent role in global health and epidemiological research through its Bloomberg School of Public Health and School of Medicine. The institution became a central fixture in modern circumcision discourse during the early 2000s due to landmark clinical trials conducted by its faculty members regarding male circumcision and infectious disease transmission.', '', '', 'critic', 'A leading research university whose medical faculty conducted pivotal studies promoting male circumcision for HIV and STI prevention.', 1, '[{"name": "Joya Banerjee", "score": 10.668, "shared_docs": 2}, {"name": "Brian J Morris", "score": 10.253, "shared_docs": 3}, {"name": "Jeffrey D Klausner", "score": 10.253, "shared_docs": 2}, {"name": "Catherine A Hankins", "score": 10.253, "shared_docs": 2}, {"name": "University of Sydney", "score": 8.138, "shared_docs": 3}]');
