INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-3770e0e3', 'organization', 'USAID', 'Established in 1961, the United States Agency for International Development (USAID) is an independent agency of the U.S. federal government primarily responsible for administering civilian foreign aid and global development assistance. Operating under the broader framework of U.S. foreign policy, USAID manages extensive public health initiatives worldwide, focusing on disease prevention, maternal and child health, and global health security.

Following randomized controlled trials in the mid-2000s indicating that male circumcision reduced female-to-male HIV transmission rates, USAID emerged as a major funding and operational partner in global health campaigns. Working in coordination with the President''s Emergency Plan for AIDS Relief (PEPFAR) and the World Health Organization (WHO), USAID helped design, fund, and execute large-scale Voluntary Medical Male Circumcision (VMMC) programs across targeted countries in Eastern and Southern Africa.

USAID''s involvement in mass circumcision initiatives has made the agency a focal point in human rights and genital autonomy discussions. Intactivist organizations and bodily autonomy advocates have criticized these foreign aid programs, raising ethical concerns regarding informed consent, resource allocation, and the promotion of irreversible surgical interventions in international development policy.', '', '', 'critic', 'A U.S. federal agency that has funded and implemented large-scale voluntary medical male circumcision programs for global HIV prevention.', 0, '[{"name": "Antony Chikutsa", "score": 11.668, "shared_docs": 2}, {"name": "UNFPA", "score": 9.794, "shared_docs": 2}, {"name": "UNICEF", "score": 8.223, "shared_docs": 3}, {"name": "UNAIDS", "score": 7.609, "shared_docs": 3}, {"name": "World Health Organization (WHO)", "score": 6.878, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-61b084df', 'organization', 'University of California, San Francisco', 'The University of California, San Francisco (UCSF) is a prominent public research university focused exclusively on health sciences. Established as a leading center for biomedical research, medical education, and patient care, UCSF includes renowned pediatric, urological, and public health departments that frequently contribute to North American medical literature and clinical policy debates.', '', '', 'notable', 'A premier academic medical center and health sciences university involved in clinical research and public health discussions regarding infant circumcision.', 1, '[{"name": "Jeffrey D. Klausner", "score": 10.083, "shared_docs": 2}, {"name": "University of Sydney", "score": 7.705, "shared_docs": 2}, {"name": "Brian J. Morris", "score": 7.318, "shared_docs": 2}, {"name": "Robert S. Van Howe", "score": 6.851, "shared_docs": 2}, {"name": "UNAIDS", "score": 6.761, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-7cf56210', 'organization', 'Lippincott Williams & Wilkins', 'Lippincott Williams & Wilkins (LWW) is a leading international publisher of medical, nursing, and health sciences content. Operating as an imprint of Wolters Kluwer, the organization has a long-standing history dating back to the late eighteenth century, producing seminal textbooks, clinical journals, and digital resources for healthcare professionals, educators, and researchers worldwide.

Within the discourse on circumcision, bodily autonomy, and pediatric medicine, Lippincott Williams & Wilkins serves as a primary conduit for clinical and surgical literature. The publisher produces numerous influential reference works and journals in urology, pediatrics, obstetrics, and surgical anatomy. These materials document anatomical research, surgical methodologies, potential complication rates, and clinical guidelines concerning neonatal male circumcision and related procedures.

By disseminating peer-reviewed research and standard medical reference texts, the organization plays a significant role in shaping clinical practice and informing institutional policies regarding genital surgeries. While the publisher itself does not advocate an ideological position, its catalog provides foundational evidence and clinical perspectives referenced by medical professionals, sociologists, and bioethicists engaged in debates over bodily integrity and surgical necessity.', '', '', 'notable', 'A prominent medical publisher whose clinical textbooks and journals document surgical practices, anatomical research, and pediatric guidelines surrounding circumcision.', 0, '');
