INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-6f62dff2', 'person', 'Roger Collier', 'Roger Collier is a Canadian medical journalist and former news editor for the Canadian Medical Association Journal (CMAJ). Throughout his career in health journalism, Collier reported extensively on medical policy, public health controversies, and clinical guidelines. His work frequently examined complex bioethical issues at the intersection of medical consensus, evidence-based care, and healthcare management.

Within the discourse on circumcision and bodily autonomy, Collier documented the evolving medical and cultural debates surrounding routine neonatal male circumcision in North America. Writing for the CMAJ, he covered key policy developments, such as the contrasting positions between the American Academy of Pediatrics and the Canadian Paediatric Society, detailing arguments regarding preventive health claims alongside ethical considerations of non-therapeutic surgery performed on infants.

Collier''s reporting contributed to public and professional understanding of shifting trends and declining circumcision rates in Canada. By examining both clinical evidence and the broader societal implications of early childhood interventions, his journalistic work provided an objective record of how medical authorities and the public navigated issues of consent and bodily integrity.', '', '', 'notable', 'A Canadian medical journalist and editor known for his reporting on public health policy and the medical debate surrounding infant circumcision.', 0, '[{"name": "Canadian Medical Association", "score": 10.99, "shared_docs": 6}, {"name": "Northwestern University", "score": 10.668, "shared_docs": 2}, {"name": "Wayne Griffiths", "score": 10.405, "shared_docs": 2}, {"name": "Brian Morris", "score": 10.116, "shared_docs": 3}, {"name": "George Denniston", "score": 9.052, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-fc1a7a67', 'organization', 'University of Sydney', 'Founded in 1850, the University of Sydney is Australia''s oldest public research institution and a major contributor to global academic literature. Within the sociological and medical discourses surrounding circumcision, bodily autonomy, and pediatric ethics, the university has served as a significant site of research, debate, and scholarship. Its academic divisions, particularly in medicine, public health, and bioethics, have produced numerous influential studies evaluating the clinical risks, potential health outcomes, and ethical implications of non-therapeutic neonatal male circumcision.

Most notably, the institution was long associated with Professor Emeritus Brian Morris, a leading proponent of routine infant male circumcision whose prolific publication output strongly advocated for the procedure''s medical benefits. Work from Morris and other researchers affiliated with the university generated widespread international discussion, drawing scrutiny and counterarguments from genital autonomy advocates, bioethicists, and medical professional bodies who questioned the methodology and normative claims presented in several published papers.

Through its published literature and academic staff, the University of Sydney has played a pivotal role in shaping public health debates regarding pediatric procedures in Australia and internationally. The research originating from its faculties continues to serve as a primary reference point for both proponents of circumcision and intactivist critics examining the intersection of evidence-based medicine, bodily integrity, and informed consent.', '', '', 'notable', 'A premier Australian research university whose faculty have produced influential and widely debated scholarship on male circumcision and public health.', 1, '[{"name": "CircFacts", "score": 9.875, "shared_docs": 3}, {"name": "VA Puget Sound Health Care System", "score": 9.875, "shared_docs": 4}, {"name": "Northeastern University", "score": 9.875, "shared_docs": 5}, {"name": "Jeffrey D. Klausner", "score": 9.553, "shared_docs": 4}, {"name": "Circumcision Foundation of Australia", "score": 9.46, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-3c691ad7', 'person', 'Bill Clinton', 'William Jefferson Clinton served as the 42nd President of the United States from 1993 to 2001. Prior to his presidency, he served as the Governor and Attorney General of Arkansas. While his presidency involved significant national health policy discussions, his primary connection to the discourse on circumcision and bodily autonomy emerged primarily during his post-presidential career through global public health philanthropy.

Following his tenure in office, Clinton established the Clinton Foundation and the Clinton Health Access Initiative (CHAI). Through these organizations, he played a prominent role in international efforts to combat the HIV/AIDS epidemic, particularly in Sub-Saharan Africa. In alignment with guidelines from the World Health Organization and UNAIDS, CHAI supported the funding, distribution, and implementation of Voluntary Medical Male Circumcision (VMMC) programs as a public health strategy to reduce heterosexually acquired HIV transmission.

Clinton''s endorsement and institutional backing of VMMC initiatives positioned his global health work within broader sociological debates surrounding genital autonomy. While proponents view these initiatives as vital, evidence-based public health interventions, intactivists and bodily autonomy advocates critique such international campaigns for promoting surgical alteration and influencing public health policy toward mass circumcision.', '', '', 'critic', '42nd President of the United States whose post-presidential foundation promoted voluntary medical male circumcision initiatives in Sub-Saharan Africa.', 0, '[{"name": "Bill Gates", "score": 11.668, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-35855625', 'person', 'Wayne Griffiths', 'Wayne Griffiths is a prominent human rights advocate and long-standing figure within the international movement for genital autonomy and bodily integrity. Operating primarily in the United Kingdom and internationally, Griffiths has worked for decades to raise awareness about the ethical, legal, and human rights implications of non-therapeutic routine infant circumcision. His work asserts that all individuals, regardless of sex or gender, inherently possess the right to protection from non-consensual bodily modifications.', '', '', 'champion', 'British human rights advocate and prominent campaigner for genital integrity and bodily autonomy.', 0, '[{"name": "Roger Collier", "score": 10.405, "shared_docs": 2}, {"name": "Canadian Medical Association", "score": 9.405, "shared_docs": 2}, {"name": "National Organization of Restoring Men (NORM)", "score": 8.768, "shared_docs": 3}, {"name": "George Denniston", "score": 8.467, "shared_docs": 2}, {"name": "Jim Bigelow", "score": 7.668, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e5c9e958', 'person', 'Aulus Cornelius Celsus', 'Aulus Cornelius Celsus (c. 25 BC – c. 50 AD) was a Roman encyclopedist best known for his surviving medical treatise, De Medicina. Writing during the reign of Tiberius, Celsus compiled comprehensive records of ancient Greco-Roman medical and surgical practices. His writings serve as one of the most critical primary historical sources on early European medicine, surgery, and anatomical understandings.

Within the historical discourse on circumcision and foreskin restoration, Celsus holds a foundational role due to his detailed documentation of prepuce reconstruction (epispasm). In Book VII of De Medicina, he outlined specific surgical procedures designed to restore a foreskin for men who were circumcised or whose prepuce was naturally deficient. These techniques were primarily sought by Jewish men in the Hellenistic and Roman periods seeking to assimilate into Greco-Roman society, where public nudity in gymnasia was customary and circumcision carried significant social stigma.

Celsus also described surgical instructions for therapeutic circumcisions, providing a neutral, clinical record of ancient genital surgeries. His writings are frequently referenced by historians of medicine and genital autonomy advocates as evidence of the long-standing cultural and surgical efforts to preserve, restore, and alter human genital anatomy.', '', '', 'notable', 'Ancient Roman medical writer who documented the earliest known surgical techniques for foreskin restoration in De Medicina.', 0, '[{"name": "National Organization of Restoring Men (NORM)", "score": 8.768, "shared_docs": 3}]');
