INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-c7656d3d', 'person', 'J.R. Taylor', 'J.R. Taylor is an author, researcher, and activist who has contributed to the discourse surrounding male circumcision, genital autonomy, and foreskin restoration. His work emerged within the broader intactivist movement as an effort to document the anatomical and psychological consequences of routine neonatal circumcision, while providing educational resources for individuals seeking information on foreskin recovery and bodily integrity.

Through various articles and archival publications, Taylor examined the medicalized history of circumcision in the United States, challenging conventional clinical justifications and advocating for the protection of children''s rights to non-mutilated bodies. His writings frequently addressed both the physical mechanics of non-therapeutic foreskin removal and the practical methods of non-surgical foreskin restoration, helping to bridge personal advocacy with broader social critique.

Taylor''s contributions remain preserved in early intactivist literature and educational archives, where his work served as a reference point for men navigating the personal impact of infant circumcision. His efforts helped establish foundational literature within the contemporary movement for genital autonomy.', '', '', 'champion', 'An author and intactivist advocate known for his contributions to literature on foreskin restoration and male bodily autonomy.', 0, '[{"name": "A.P. Lockwood", "score": 11.99, "shared_docs": 4}, {"name": "A.J. Taylor", "score": 11.99, "shared_docs": 4}, {"name": "University of Manitoba", "score": 10.668, "shared_docs": 4}, {"name": "Marshfield Clinic", "score": 10.405, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-82537114', 'organization', 'Marshfield Clinic', 'Marshfield Clinic is a major regional healthcare system headquartered in Marshfield, Wisconsin. Established in 1916 by six physicians, the organization expanded into one of the largest multispecialty group medical practices in the United States, operating dozens of clinics and hospitals across central, northern, and western Wisconsin. The health system provides comprehensive medical care, including obstetrics, pediatrics, and surgical services.

Within the discourse on infant circumcision and bodily autonomy, Marshfield Clinic represents the institutional medical perspective typical of Midwestern healthcare systems. The network delivers routine neonatal circumcision services, patient education materials, and clinical counseling to prospective parents, generally reflecting standard professional recommendations and mainstream clinical practices in American medicine.

In archival contexts examining circumcision policy and bodily autonomy, Marshfield Clinic is referenced as an example of health system practice regarding elective pediatric procedures. Documents referencing the clinic often discuss institutional consent protocols, billing practices, and the framing of circumcision risks and benefits within regional healthcare settings.', '', '', 'notable', 'A prominent Wisconsin-based healthcare network providing regional medical services, clinical guidance, and patient education on infant circumcision.', 0, '[{"name": "J.R. Taylor", "score": 10.405, "shared_docs": 2}, {"name": "University of Manitoba", "score": 9.668, "shared_docs": 2}, {"name": "Robert S. Van Howe", "score": 8.021, "shared_docs": 3}, {"name": "Canadian Paediatric Society", "score": 6.99, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 5.04, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-9798a49f', 'person', 'Parliamentary Assembly of the Council of Europe', 'The Parliamentary Assembly of the Council of Europe (PACE) is the parliamentary branch of the Council of Europe, an international organization dedicated to upholding human rights, democracy, and the rule of law across its member states. Composed of parliamentarians appointed by national parliaments, the Assembly serves as a deliberative body that passes resolutions and recommendations addressing key social, legal, and human rights issues across Europe.

PACE gained significant prominence within the discourse on bodily autonomy and intactivism through its passage of Resolution 1952 in October 2013, titled "Children''s right to physical integrity." The resolution categorized non-therapeutic male circumcision alongside female genital mutilation and early intersex medical interventions as violations of children''s physical integrity. It urged member states to promote public awareness, ensure proper sanitary conditions, and initiate discussions on establishing legal frameworks to protect young boys from non-consensual bodily modifications.

The Assembly''s resolution generated substantial international debate, drawing both praise from human rights and intactivist advocates and criticism from religious organizations and foreign governments concerned about religious freedom. In response to these debates, PACE adopted Resolution 2076 in 2015, which reaffirmed the importance of children''s rights while placing greater emphasis on interfaith dialogue and parental rights. Despite subsequent discussions, PACE''s early actions established a critical legal and ethical precedent in framing non-therapeutic childhood circumcision as a human rights issue within European governance.', '', '', 'champion', 'International parliamentary assembly whose landmark 2013 resolution framed non-therapeutic infant circumcision as a violation of children''s physical integrity.', 0, '[{"name": "Royal Dutch Medical Association", "score": 8.366, "shared_docs": 2}, {"name": "United Nations", "score": 7.116, "shared_docs": 2}, {"name": "Brian D. Earp", "score": 6.99, "shared_docs": 2}, {"name": "World Health Organization", "score": 5.99, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-78cec8f3', 'person', 'Guy Cox', 'Guy Cox was an Australian academic, biophysicist, and researcher who became a prominent figure in the Australian movement against non-therapeutic infant male circumcision. Utilizing his background in biomedical science and microscopy at the University of Sydney, Cox brought a scientific and anatomical perspective to discussions surrounding genital integrity, challenging medical justifications for neonatal foreskin removal.', '', '', 'champion', 'Australian academic and advocate for genital integrity who served as a leading voice against infant circumcision in Australia.', 0, '[{"name": "John N. Krieger", "score": 9.668, "shared_docs": 2}, {"name": "Brian J. Morris", "score": 9.166, "shared_docs": 4}, {"name": "University of Sydney", "score": 9.138, "shared_docs": 3}, {"name": "Centers for Disease Control and Prevention", "score": 7.044, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 4.718, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-4d4b15f5', 'person', 'Amber Craig', 'Amber Craig is an American advocate and commentator within the intactivist movement, recognized for her contributions to public education and discourse surrounding children''s right to bodily integrity. Her work focuses primarily on raising awareness about the ethical, psychological, and physical implications of routine infant male circumcision. Through articles, public speaking, and community outreach, Craig has worked to inform parents, medical professionals, and the general public about the importance of intact care and informed consent.', '', '', 'champion', 'American intactivist advocate and commentator dedicated to promoting bodily autonomy and infant genital integrity.', 1, '[{"name": "Kristen O''Hara", "score": 11.405, "shared_docs": 3}, {"name": "Peter Ball", "score": 11.405, "shared_docs": 3}, {"name": "Yngve Hofvander", "score": 11.405, "shared_docs": 3}, {"name": "Morris Sorrells", "score": 10.99, "shared_docs": 3}, {"name": "Lawrence W. Green", "score": 10.82, "shared_docs": 2}]');
