INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-345df1d3', 'person', 'Frederick Hodges', 'Frederick M. Hodges is a medical historian and scholar who has contributed significantly to the academic literature surrounding the history, anatomy, and ethics of male circumcision. Educated at the University of Oxford, Hodges focused much of his scholarly research on the historical emergence of routine infant circumcision in Anglo-American medical culture, detailing how 19th-century medical theories transformed a rare surgical intervention into a widespread prophylactic practice.

In addition to his historical scholarship, Hodges co-authored foundational medical and anatomical studies examining the fine structure, specialized innervation, and sexual function of the human foreskin. His interdisciplinary work helped bridge the gap between clinical research and bodily autonomy advocacy, providing rigorous academic grounding for critiques of non-consensual infant genital modifications.

Hodges has collaborated with prominent genital autonomy organizations, including Doctors Opposing Circumcision (DOC) and the National Organization of Circumcision Information Resource Centers (NOCIRC). Through his peer-reviewed publications, educational lectures, and historical analyses, he has served as a key intellectual figure in the modern intactivist movement.', '', '', 'champion', 'Medical historian and researcher known for his foundational work on foreskin anatomy and the history of routine circumcision.', 1, '[{"name": "Abraham L. Wolbarst", "score": 10.768, "shared_docs": 3}, {"name": "Plenum Press", "score": 9.768, "shared_docs": 2}, {"name": "Aaron J. Fink", "score": 9.768, "shared_docs": 2}, {"name": "Lewis A. Sayre", "score": 8.96, "shared_docs": 2}, {"name": "Thomas Szasz", "score": 8.446, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-8d4b054c', 'organization', 'Tasmania Law Reform Institute', 'Established in 2001, the Tasmania Law Reform Institute (TLRI) is the principal law reform body in the state of Tasmania, Australia. Based at the University of Tasmania, the Institute conducts independent legal research and public consultations to advise the Tasmanian government on modernizing, simplifying, and reforming state legislation across various civil, criminal, and ethical domains.

Within the discourse on bodily autonomy and circumcision, the TLRI has engaged with the legal and ethical dimensions of non-therapeutic surgical procedures performed on minors. Through research papers and legal reviews, the Institute has examined the parameters of lawful parental consent, the applicability of criminal law provisions regarding assault and grievous bodily harm, and the legal obligations of healthcare practitioners performing non-therapeutic male circumcision.

By evaluating how existing Tasmanian criminal and civil law aligns with international human rights frameworks, including the United Nations Convention on the Rights of the Child, the TLRI''s reports have provided a significant legal foundation for discussions on children''s bodily integrity in Australia. The Institute''s scholarly analysis remains a frequently cited reference point in legal and bioethical debates concerning the regulation of non-consensual bodily alterations.', '', '', 'notable', 'An independent legal research institution that has analyzed the legal frameworks surrounding non-therapeutic circumcision and bodily autonomy in Tasmania.', 0, '[{"name": "Queensland Law Reform Commission", "score": 10.253, "shared_docs": 2}, {"name": "Angela Merkel", "score": 9.794, "shared_docs": 2}, {"name": "Robert Van Howe", "score": 9.166, "shared_docs": 2}, {"name": "Royal Dutch Medical Association (KNMG)", "score": 8.931, "shared_docs": 2}, {"name": "Royal Australasian College of Physicians", "score": 8.59, "shared_docs": 3}]');
