INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-4ec51fb4', 'person', 'Paul Fleiss', 'Paul M. Fleiss (1933–2014) was a prominent American pediatrician based in Los Angeles who became a prominent medical voice within the intactivist and bodily autonomy movements. Known for his holistic, child-centered approach to healthcare, Fleiss advocated for natural childbirth, extended breastfeeding, and intact care for infants. Throughout his career, he challenged the routine practice of neonatal circumcision in the United States, arguing that it was an unnecessary, painful surgical alteration that violated a child''s fundamental right to bodily integrity.

In 2002, Fleiss co-authored the book ''What Your Doctor May Not Tell You About Circumcision'' with historian Frederick Hodges. The work critically examined the medical, historical, and ethical dimensions of routine circumcision, offering parents an evidence-based perspective against the procedure. Fleiss frequently educated medical colleagues and parents on the natural anatomy and function of the foreskin, pushing back against prevailing cultural and medical norms of the era.

Beyond his literary contributions, Fleiss participated in public debates, media appearances, and advocacy campaigns to promote intact care and child autonomy. Despite intense public scrutiny regarding aspects of his personal life, he maintained a respected position within the intactivist community until his death, remembered as one of the few high-profile pediatricians of his generation to explicitly campaign against routine infant circumcision.', '', '', 'champion', 'Prominent American pediatrician, author, and advocate for infant bodily autonomy who co-authored ''What Your Doctor May Not Tell You About Circumcision''.', 1, '[{"name": "Laurie Evans", "score": 10.253, "shared_docs": 3}, {"name": "Peter Ball", "score": 10.253, "shared_docs": 3}, {"name": "Yngve Hofvander", "score": 10.253, "shared_docs": 3}, {"name": "Morris Sorrells", "score": 9.838, "shared_docs": 3}, {"name": "Jeannine Parvati Baker", "score": 9.768, "shared_docs": 5}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e3040325', 'person', 'Nahid Toubia', 'Dr. Nahid Toubia is a Sudanese surgeon, scholar, and women''s health advocate recognized globally for her pioneering work to eradicate female genital mutilation/cutting (FGM/C) and advance bodily integrity rights. Becoming the first female surgeon in Sudan after training at the Royal College of Surgeons in England, her clinical practice in Khartoum brought her face-to-face with the severe medical complications caused by FGM/C. This experience led her to shift her career focus toward public health, human rights advocacy, and empirical research into traditional practices affecting women''s bodily autonomy.

In 1994, Toubia founded the Research, Action and Information Network for Bodily Integrity of Women (RAINBO), an international non-governmental organization aimed at eradicating FGM/C through health education, self-empowerment, and policy reform. Through RAINBO, she published influential works—such as ''Female Genital Mutilation: A Call for Global Action''—that helped reframe FGM/C from an isolated cultural tradition into an urgent international public health and human rights issue. Her scholarly and activist contributions provided vital frameworks for international bodies including the World Health Organization, UNICEF, and Human Rights Watch.

Toubia also served as an associate professor at the Columbia University School of Public Health and worked extensively with community-based organizations across Africa and the Middle East. Her approach consistently emphasized culturally nuanced, community-led strategies alongside an uncompromising stance on the universal right to bodily autonomy and physical integrity.', '', '', 'champion', 'Sudanese surgeon and human rights advocate who founded RAINBO and pioneered global public health campaigns against female genital mutilation.', 1, '[{"name": "Carla Obermeyer", "score": 10.531, "shared_docs": 2}, {"name": "Johns Hopkins University Press", "score": 9.794, "shared_docs": 2}, {"name": "Janice Boddy", "score": 9.794, "shared_docs": 2}, {"name": "Alice Miller", "score": 9.308, "shared_docs": 2}, {"name": "UNFPA", "score": 8.656, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-63735e6d', 'organization', 'Johns Hopkins University Press', 'Established in 1878, Johns Hopkins University Press is the oldest continuously operating university press in the United States. As a major academic publisher, it produces a wide array of peer-reviewed journals and scholarly books across the humanities, social sciences, history of medicine, public health, and bioethics.

Within the discourse on circumcision and bodily autonomy, Johns Hopkins University Press serves as a key venue for scholarly literature analyzing the historical, ethical, and medical aspects of routine infant circumcision. Publications released under its imprint have documented the evolving socio-medical opinions on male and female genital cutting, examined the legal and bioethical frameworks surrounding parental consent and bodily integrity, and explored the rise of anti-circumcision advocacy in Western medicine.

While the press does not endorse a specific advocacy position, its catalog provides vital academic context and critical analysis that inform both scholars and activists within the intactivist movement and the broader bioethics community.', '', '', 'notable', 'A prominent academic publisher producing influential historical, bioethical, and medical literature related to circumcision and bodily autonomy.', 0, '[{"name": "Kennedy Institute of Ethics", "score": 11.253, "shared_docs": 2}, {"name": "Nahid Toubia", "score": 9.794, "shared_docs": 2}, {"name": "Fuambai Ahmadu", "score": 9.553, "shared_docs": 2}, {"name": "Robert Darby", "score": 7.699, "shared_docs": 2}, {"name": "J. Steven Svoboda", "score": 7.525, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-9b996ed8', 'organization', 'Michigan State University', 'Michigan State University (MSU) is a major public research institution located in East Lansing, Michigan. Founded in 1855 as the Agricultural College of the State of Michigan, it has grown into a leading academic center known for its research across medicine, law, social sciences, and bioethics. Through its various academic departments and affiliated research programs, the university has frequently provided an institutional base for scholarly analysis concerning health policy, human rights, and pediatric ethics.

Within the discourse surrounding circumcision and bodily autonomy, Michigan State University functions primarily as a site of academic research and ethical deliberation. Scholars, bioethicists, and legal experts affiliated with the university have published literature examining the socio-legal dimensions of non-therapeutic neonatal routine procedures, parental consent frameworks, and individual bodily rights. Their contributions offer empirical and theoretical perspectives that inform broader legal, medical, and intactivist commentary.

While the university itself maintains a neutral institutional stance, its scholarly outputs and hosting of academic symposiums have provided a forum for analyzing genital autonomy and medical ethics. The institution remains a recognized academic reference point in research addressing bodily integrity, legal protections for minors, and the evolving medical consensus regarding neonatal procedures.', '', '', 'notable', 'A prominent public research university whose faculty and scholars contribute to bioethical, legal, and medical literature on bodily autonomy and circumcision.', 1, '[{"name": "Robert S. Van Howe", "score": 7.021, "shared_docs": 2}, {"name": "World Health Organization", "score": 4.99, "shared_docs": 2}]');
