INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-13f93c2c', 'person', 'Peter Charles Remondino', 'Peter Charles Remondino (1846–1926) was an Italian-born American physician, surgeon, and medical historian based in San Diego, California. After serving as a military surgeon during the Franco-Prussian War, he settled in Southern California, where he served as the first president of the San Diego Board of Health and played a prominent role in establishing local medical institutions and public health initiatives during the late nineteenth and early twentieth centuries.

Remondino achieved lasting influence through his 1891 volume, "History of Circumcision from the Earliest Times to the Present." In this widely circulated treatise, he argued vigorously for universal male circumcision, presenting the procedure as a vital medical prophylactic rather than merely a religious ritual. Remondino claimed that routine circumcision could prevent or cure a broad spectrum of physical, neurological, and behavioral conditions, including syphilis, epilepsy, alcoholism, and masturbation.

His writings served as a key foundational text for the medicalization of infant circumcision in the United States. By providing pseudo-historical and medical rationales for the procedure during the Victorian era, Remondino helped embed routine non-therapeutic neonatal circumcision into mainstream American medical practice, making his work a primary reference point in historical analyses of bodily autonomy and anti-circumcision advocacy.', '', '', 'critic', 'Nineteenth-century physician and author whose 1891 book served as a foundational medical text promoting routine male circumcision.', 0, '[{"name": "Amanda Kennedy", "score": 10.99, "shared_docs": 2}, {"name": "Lewis A. Sayre", "score": 10.768, "shared_docs": 3}, {"name": "Doctors Opposing Circumcision (DOC)", "score": 9.531, "shared_docs": 2}, {"name": "Intact America", "score": 8.668, "shared_docs": 2}]');
