INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-5666bcfa', 'organization', 'Catholic Church', 'The Catholic Church is the largest Christian denomination worldwide, exercising substantial historical and contemporary influence over global bioethics, healthcare standards, and moral philosophy. Historically, the Church established a definitive theological position regarding circumcision at the Council of Florence in 1442, declaring that the practice was no longer a required religious covenant or necessary for salvation, thereby distancing Christian practice from traditional ritual circumcision.', '', '', 'notable', 'A global religious institution whose theological doctrines on bodily integrity and historical decrees inform modern bioethical debates on non-consensual circumcision.', 0, '[{"name": "Paul the Apostle", "score": 9.82, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-9a87639d', 'organization', 'Taylor & Francis Group', 'Taylor & Francis Group is an international academic publisher founded in 1852 by William Francis and Richard Taylor. As a division of Informa PLC, the company publishes thousands of peer-reviewed academic journals, books, and reference works across disciplines including medicine, bioethics, sociology, law, and human rights.

In the context of bodily autonomy and circumcision discourse, Taylor & Francis serves as a critical repository of scholarly literature. Its portfolio includes prominent publications such as The American Journal of Bioethics, Ethics & Behavior, and the Journal of Sex Research, which frequently feature academic papers analyzing non-therapeutic neonatal circumcision, foreskin anatomy, patient consent, and children''s rights.

While the publisher itself maintains a neutral organizational stance, the work disseminated through its platforms has significantly shaped both medical ethics guidelines and intactivist scholarly arguments. By publishing rigorous analyses from diverse academic perspectives, Taylor & Francis remains a foundational venue for formal inquiry into genital autonomy and bodily integrity.', '', '', 'notable', 'A major international academic publisher whose journals host key bioethical, medical, and legal debates on circumcision and bodily autonomy.', 0, '[{"name": "UNICEF", "score": 7.153, "shared_docs": 2}, {"name": "World Health Organization", "score": 5.183, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-8e9b1f24', 'person', 'Leonard Glick', 'Leonard B. Glick is an American physician, anthropologist, and historian whose scholarly work offers a critical examination of the cultural, religious, and medical histories of male circumcision. He earned an M.D. and a Ph.D. in anthropology, later serving as a professor of anthropology at Hampshire College in Amherst, Massachusetts. His dual expertise in clinical medicine and cultural anthropology positioned him to rigorously analyze how genital cutting practices transitioned from ancient religious rituals into routine medical procedures in Western societies.

Glick is widely recognized for his seminal 2005 book, "Marked in Your Flesh: Circumcision from Ancient Judea to Modern America." In this work, he detailed the historical progression of Jewish ritual circumcision (brit milah) and analyzed the 19th-century medicalization of the procedure in North America. Glick argued that the widespread adoption of routine infant circumcision in the United States was largely driven by Victorian-era social anxieties and moral rationalizations rather than sound scientific evidence, persisting into the modern era primarily as an unquestioned cultural habit.

Beyond his written scholarship, Glick actively contributed to the discourse on bodily autonomy by presenting at academic conferences and international symposia on sexual integrity and genital autonomy. His historical research provided a crucial academic framework for intactivist scholars and activists seeking to challenge the routine non-therapeutic circumcision of infants. Through his writing and advocacy, Glick emphasized the ethical imperative of preserving an individual''s bodily integrity until they are capable of making informed personal choices.', '', '', 'champion', 'Anthropologist, physician, and author of Marked in Your Flesh, known for his historical critiques of medicalized and religious circumcision.', 0, '[{"name": "Laurie Evans", "score": 11.668, "shared_docs": 2}, {"name": "Peter Ball", "score": 11.668, "shared_docs": 2}, {"name": "Yngve Hofvander", "score": 11.668, "shared_docs": 2}, {"name": "Milton Diamond", "score": 11.253, "shared_docs": 2}, {"name": "Morris Sorrells", "score": 11.253, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-4e8fc9f9', 'person', 'Aaron Fink', 'Dr. Aaron Fink was an American urologist and physician who became an influential early voice within the medical establishment challenging the practice of routine neonatal circumcision in the United States. Writing during the late 20th century, Fink utilized his surgical expertise to critique the medical rationale for routine foreskin removal, arguing that the procedure lacked empirical necessity and infringed upon the natural physical integrity of newborns.', '', '', 'champion', 'Urologist and early medical critic of routine neonatal circumcision who highlighted its physiological and psychological impacts.', 0, '[{"name": "National Organization of Circumcision Information Centers", "score": 11.405, "shared_docs": 2}, {"name": "Eugene Robin", "score": 10.768, "shared_docs": 3}, {"name": "Mahatma Gandhi", "score": 10.668, "shared_docs": 2}, {"name": "John Erickson", "score": 10.253, "shared_docs": 3}, {"name": "Rima Laibow", "score": 10.183, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e83a5ed2', 'person', 'Pat Schroeder', 'Patricia Scott Schroeder (1940–2023) was an American politician and attorney who served as a Democratic member of the United States House of Representatives representing Colorado''s 1st congressional district from 1973 to 1997. Renowned for her advocacy on civil rights, women''s rights, and reproductive freedom, Schroeder was one of the most influential female lawmakers of her era and a pioneer for gender equity in federal legislation.

In the realm of bodily autonomy, Schroeder played a key role by sponsoring and driving the passage of the Federal Prohibition of Female Genital Mutilation Act of 1996. The legislation criminalized the practice of female genital cutting on minors in the United States, establishing a significant legal standard for children''s physical integrity and human rights under federal law.

Within the broader discourse surrounding circumcision and intactivism, Schroeder''s legislative legacy is frequently referenced in legal and human rights analyses. Scholars and advocates for bodily autonomy often cite her anti-FGM legislation when discussing equal protection arguments, ethical consistency in pediatric medicine, and the legal frameworks governing non-consensual genital modifications of minors.', '', '', 'champion', 'U.S. Representative who authored the landmark 1996 federal legislation prohibiting female genital mutilation in the United States.', 0, '[{"name": "Cleveland-Marshall College of Law", "score": 11.405, "shared_docs": 2}, {"name": "Dena S. Davis", "score": 10.575, "shared_docs": 3}, {"name": "British Medical Association", "score": 7.059, "shared_docs": 2}, {"name": "Tim Hammond", "score": 6.781, "shared_docs": 2}, {"name": "United Nations", "score": 6.531, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-ef130fa7', 'person', 'Joel Feinberg', 'Joel Feinberg (1926–2004) was a prominent American legal and political philosopher whose work significantly shaped modern bioethics and rights theory. A longtime professor of philosophy and law at the University of Arizona, Feinberg authored influential treatises on legal moralism, harm, and liberty, most notably his four-volume study The Moral Limits of the Criminal Law.

Feinberg''s most enduring contribution to discussions of bodily autonomy is his formulation of ''the child''s right to an open future.'' He posited that children possess rights in trust—anticipatory rights that adults must safeguard until the child reaches maturity to exercise them independently. Under this framework, irreversible physical modifications or non-therapeutic medical interventions performed on infants, such as non-consensual circumcision, violate a child''s right to make autonomous decisions regarding their own body once capable of informed consent.

Although Feinberg was a broad legal theorist rather than an advocate targeting circumcision specifically, his conceptualization of autonomy, parental authority, and paternalism became a cornerstone of bioethical arguments against non-therapeutic infant genital procedures. His work continues to be extensively cited by legal scholars, ethicists, and intactivists advocating for the legal and ethical protection of children''s bodily integrity.', '', '', 'notable', 'American legal philosopher best known for formulating ''the child''s right to an open future,'' a foundational concept in arguments for bodily autonomy and genital integrity.', 1, '[{"name": "Robert J. L. Darby", "score": 10.29, "shared_docs": 2}, {"name": "Julian Savulescu", "score": 9.553, "shared_docs": 2}, {"name": "Dena S. Davis", "score": 9.46, "shared_docs": 3}, {"name": "Deutscher Bundestag", "score": 9.29, "shared_docs": 2}, {"name": "James Munby", "score": 9.29, "shared_docs": 2}]');
