INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-fc05352c', 'organization', 'Case Western Reserve University School of Law', 'Case Western Reserve University School of Law, located in Cleveland, Ohio, is a prominent American legal institution recognized for its contributions to health law, bioethics, and human rights scholarship. Within the broader legal discourse surrounding non-consensual male circumcision and bodily autonomy, the law school has served as an academic venue for examining the ethical, constitutional, and legal frameworks governing non-therapeutic medical procedures on minors.', '', '', 'notable', 'A leading legal institution whose faculty and academic publications contribute to legal and bioethical scholarship surrounding children''s rights and bodily integrity.', 0, '[{"name": "David L. Gollaher", "score": 10.838, "shared_docs": 3}, {"name": "Lauren M. Sardi", "score": 10.446, "shared_docs": 2}, {"name": "Quinnipiac University", "score": 10.446, "shared_docs": 2}, {"name": "Intact America", "score": 8.931, "shared_docs": 2}, {"name": "Ronald Goldman", "score": 8.209, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-42b7826f', 'person', 'David Benatar', 'David Benatar is a South African philosopher, bioethicist, and author who served as a Professor of Philosophy and Director of the Bioethics Centre at the University of Cape Town. Widely recognized for his contributions to moral philosophy, applied ethics, and antinatalism, Benatar has published extensive scholarly work examining the moral boundaries of medical interventions, bodily autonomy, and parental authority.', '', '', 'champion', 'South African philosopher and bioethicist known for his academic critiques of routine infant circumcision and defense of children''s bodily integrity.', 1, '[{"name": "Michael Benatar", "score": 11.405, "shared_docs": 8}, {"name": "Ronald Dworkin", "score": 10.99, "shared_docs": 3}, {"name": "Joseph Mazor", "score": 10.083, "shared_docs": 4}, {"name": "Deutscher Bundestag", "score": 9.82, "shared_docs": 2}, {"name": "Dena S. Davis", "score": 9.405, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-7065fdd7', 'person', 'Michael Benatar', 'Michael Benatar is an advocate and public commentator known for his contributions to the discourse surrounding bodily autonomy, children''s rights, and the ethical implications of non-consensual infant circumcision. Through public outreach, media engagement, and participation in intactivist networks, he has consistently highlighted the importance of genital integrity and equal protection for all children regardless of gender.', '', '', 'champion', 'An activist and commentator advocating for children''s bodily autonomy and the end of non-consensual infant circumcision.', 1, '[{"name": "David Benatar", "score": 11.405, "shared_docs": 8}, {"name": "Ronald Dworkin", "score": 11.16, "shared_docs": 3}, {"name": "Deutscher Bundestag", "score": 9.99, "shared_docs": 2}, {"name": "Joseph Mazor", "score": 9.838, "shared_docs": 3}, {"name": "Dena S. Davis", "score": 9.575, "shared_docs": 2}]');
