INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-4270cffc', 'person', 'Holm Putzke', 'Holm Putzke is a German legal scholar and professor of criminal law at the University of Passau who played a central role in shaping modern European legal debate surrounding non-therapeutic male circumcision. He gained widespread prominence through his scholarly work examining the tension between parental rights, religious freedom, and a child''s fundamental right to physical integrity and self-determination.

In 2008, Putzke published a landmark legal paper arguing that non-therapeutic circumcision of boys unable to consent constitutes criminal bodily injury under German law. His legal reasoning served as a primary foundation for the landmark 2012 Cologne District Court ruling, which determined that a child''s right to physical integrity outweighs parental religious freedoms in cases of non-therapeutic circumcision. The verdict sparked an intense global legal, ethical, and political discussion regarding bodily autonomy and children''s rights.

Following the 2012 judgment and the subsequent passage of legislation by the German Bundestag allowing religious circumcision under specific conditions, Putzke remained a vocal legal analyst on the topic. He has authored numerous publications on criminal law, medical ethics, and child welfare, continuously advocating for legal frameworks that prioritize the bodily autonomy and physical integrity of minors.', '', '', 'champion', 'German legal scholar whose academic work on bodily integrity laid the legal foundation for the landmark 2012 Cologne ruling on infant circumcision.', 1, '[{"name": "Reinhard Merkel", "score": 11.405, "shared_docs": 7}, {"name": "Charlotte Knobloch", "score": 10.99, "shared_docs": 3}, {"name": "Central Council of Jews in Germany", "score": 10.82, "shared_docs": 2}, {"name": "Eldar Sarajlic", "score": 10.82, "shared_docs": 2}, {"name": "Deutscher Ethikrat", "score": 10.82, "shared_docs": 2}]');
