INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-1b42feb8', 'organization', 'University of Geneva', 'The University of Geneva (Université de Genève), founded in 1559 by John Calvin, is a leading public research university located in Geneva, Switzerland. Renowned for its strong emphasis on international law, medicine, public health, and bioethics, the institution maintains close academic ties with numerous international organizations and non-governmental bodies headquartered in Geneva, including the World Health Organization and the United Nations High Commissioner for Human Rights.', '', '', 'notable', 'A prestigious Swiss research university whose faculty and scholarly publications contribute critical bioethical, medical, and legal analysis to human rights and bodily autonomy discourses.', 0, '[{"name": "National University of Singapore", "score": 11.353, "shared_docs": 3}, {"name": "Geneva University Hospitals", "score": 11.183, "shared_docs": 4}, {"name": "Jasmine Abdulcadir", "score": 10.768, "shared_docs": 6}, {"name": "Birgitta Ess\u00e9n", "score": 9.598, "shared_docs": 2}, {"name": "University of Oxford", "score": 8.446, "shared_docs": 4}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-3394eadc', 'person', 'Arianne Shahvisi', 'Arianne Shahvisi is a British philosopher and bioethicist who serves as a Senior Lecturer in Ethics at the Brighton and Sussex Medical School. With an academic background in both physics and philosophy, her research primarily focuses on feminist bioethics, healthcare inequality, and the moral dimensions of bodily integrity and consent.

Within the discourse on circumcision and bodily autonomy, Shahvisi is prominent for her critical bioethical analyses of childhood genital alteration. Her academic publications systematically address the ethical inconsistencies in how Western legal and medical frameworks treat female genital cutting in comparison to routine male circumcision. She argues that the principles of bodily autonomy, non-maleficence, and rights to physical integrity must be applied uniformly to all children, challenging traditional cultural justifications and medical rationales for non-consensual male circumcision.

Through her scholarly work and public engagement, Shahvisi has contributed to reframing debates on genital cutting away from gendered double standards toward a universal human rights framework. Her analysis emphasizes that children of all genders possess a right to bodily autonomy that should preclude non-therapeutic surgical interventions prior to the age of consent.', '', '', 'champion', 'British philosopher and bioethicist known for her academic critiques of double standards in genital cutting and defense of children''s bodily autonomy.', 0, '[{"name": "Brighton and Sussex Medical School", "score": 11.768, "shared_docs": 4}, {"name": "Godfrey B. Tangwa", "score": 11.183, "shared_docs": 2}, {"name": "National University of Singapore", "score": 10.768, "shared_docs": 2}, {"name": "Max Fish", "score": 10.446, "shared_docs": 2}, {"name": "Geneva University Hospitals", "score": 10.183, "shared_docs": 2}]');
