INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-24b37905', 'organization', 'Geneva University Hospitals', 'Geneva University Hospitals (Hôpitaux Universitaires de Genève) is a major healthcare complex and academic medical center based in Geneva, Switzerland. Affiliated with the University of Geneva Faculty of Medicine, the institution is one of the largest university hospital networks in Switzerland, renowned for its contributions to clinical care, bioethics, and international medical research. In the context of global health, the hospital system frequently intersects with international human rights standards and health policy discussions hosted in Geneva.

Within the discourse on bodily autonomy and genital integrity, Geneva University Hospitals serves as a key institutional reference point regarding clinical guidelines, pediatric surgical practices, and bioethical considerations. The medical center''s protocols and clinical studies contribute to broader European discussions on non-therapeutic surgeries, informed consent, and the treatment of minors. In particular, European medical institutions like Geneva University Hospitals often navigate complex intersections between patient rights, cultural practices, and bioethical mandates regarding procedures such as non-therapeutic male circumcision, female genital cutting prevention, and medical interventions on intersex infants.

As a research and teaching facility, the hospital represents the institutional framework through which medical ethics and bodily integrity are evaluated and applied in clinical settings. Its documentation and clinical guidelines provide valuable context for sociological studies on how established healthcare systems address the evolving legal, ethical, and human rights aspects of non-consensual bodily modifications.', '', '', 'notable', 'A prominent Swiss academic medical center providing clinical standards and bioethical research regarding pediatric care and medical ethics.', 0, '[{"name": "National University of Singapore", "score": 11.575, "shared_docs": 3}, {"name": "University of Geneva", "score": 11.183, "shared_docs": 4}, {"name": "Brighton and Sussex Medical School", "score": 10.99, "shared_docs": 2}, {"name": "Jasmine Abdulcadir", "score": 10.727, "shared_docs": 5}, {"name": "Arianne Shahvisi", "score": 10.183, "shared_docs": 2}]');
