INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e65a55c2', 'organization', 'United States Agency for International Development (USAID)', 'The United States Agency for International Development (USAID) is an independent federal agency responsible for administering civilian foreign aid and international development assistance. Established in 1961, USAID manages public health, economic, and humanitarian initiatives globally, frequently collaborating with international non-governmental organizations, local governments, and multilateral entities like the World Health Organization (WHO).

Within the global health landscape, USAID plays a significant role in funding and executing Voluntary Medical Male Circumcision (VMMC) initiatives across Eastern and Southern Africa. Following WHO and UNAIDS recommendations in 2007 that recognized circumcision as an additional intervention for HIV prevention, USAID, primarily through the U.S. President''s Emergency Plan for AIDS Relief (PEPFAR), expanded funding for mass circumcision programs to reduce heterosexual HIV transmission risks in high-prevalence countries.

USAID''s involvement in mass circumcision campaigns has positioned it as a major focal point in debates over genital autonomy and bioethics. Intactivist organizations and human rights critics contend that USAID-funded programs compromise bodily integrity, prioritize epidemiological targets over holistic consent, and put pressure on vulnerable populations in developing nations. Conversely, USAID maintains that its VMMC programs are voluntary, evidence-based, and vital components of global HIV eradication strategies.', '', '', 'critic', 'A U.S. federal agency that extensively funds Voluntary Medical Male Circumcision (VMMC) campaigns for HIV prevention in Sub-Saharan Africa.', 0, '[{"name": "Yoweri Museveni", "score": 10.668, "shared_docs": 2}, {"name": "President''s Emergency Plan for AIDS Relief (PEPFAR)", "score": 10.405, "shared_docs": 2}, {"name": "Arianne Shahvisi", "score": 10.183, "shared_docs": 2}, {"name": "Ellen Gruenbaum", "score": 9.531, "shared_docs": 2}, {"name": "World Health Organization (WHO)", "score": 7.615, "shared_docs": 4}]');
