INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-eddd988b', 'person', 'Brian J Morris', 'Brian J. Morris is an Australian molecular biologist and Professor Emeritus at the University of Sydney. Over his academic career, his scientific work spanned cardiovascular genetics and molecular medicine, but he became internationally recognized for his extensive literature and public commentary advocating for the health benefits of male circumcision.

Morris authored and co-authored numerous research papers, meta-analyses, and books arguing that male circumcision offers substantial protection against urinary tract infections, sexually transmitted diseases including HIV and HPV, and various cancers. He frequently advocated for policy changes to increase access to and medical endorsement of routine infant circumcision, citing pediatric guidelines and epidemiological data to support his positions.

His prominent position as a vocal academic proponent of circumcision made him a central and polarizing figure in the global debate surrounding bodily autonomy and genital cutting. While his publications were utilized by supporters of circumcision to argue for its public health utility, his methodology, interpretations, and overt advocacy were frequently challenged by intactivist organizations, bioethicists, and opposing medical professionals.', '', '', 'critic', 'Australian medical scientist and prominent academic advocate for routine male circumcision.', 0, '[{"name": "Joya Banerjee", "score": 11.99, "shared_docs": 3}, {"name": "Jeffrey D Klausner", "score": 11.575, "shared_docs": 3}, {"name": "Catherine A Hankins", "score": 11.575, "shared_docs": 3}, {"name": "Richard G Wamai", "score": 11.405, "shared_docs": 2}, {"name": "Johns Hopkins University", "score": 10.253, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-d38d2648', 'person', 'Joseph Mazor', 'Joseph Mazor is an academic, political philosopher, and bioethicist whose research addresses normative health policy, distributive justice, and personal autonomy. Holding academic positions at institutions such as Victoria University of Wellington and having completed post-doctoral fellowships at Harvard, Princeton, and Stanford, Mazor has published extensively on the intersection of individual rights, state regulation, and parental authority.', '', '', 'champion', 'Political philosopher and bioethicist known for his academic defenses of children''s bodily integrity and ethical critiques of non-therapeutic infant circumcision.', 1, '[{"name": "Ronald Dworkin", "score": 10.838, "shared_docs": 3}, {"name": "London School of Economics", "score": 10.668, "shared_docs": 2}, {"name": "Eldar Sarajlic", "score": 10.668, "shared_docs": 2}, {"name": "David Benatar", "score": 10.083, "shared_docs": 4}, {"name": "Michael Benatar", "score": 9.838, "shared_docs": 3}]');
