INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-72cec890', 'organization', 'BMJ', 'BMJ, originally known as the British Medical Journal, is a leading global medical publisher and peer-reviewed journal established in 1840 by the British Medical Association. Renowned for its contributions to evidence-based medicine, clinical research, and bioethics, the publication serves as a primary forum for debate on global healthcare policies, medical ethics, and surgical practices.

Within the discourse surrounding circumcision and bodily autonomy, BMJ has played a significant role by publishing numerous peer-reviewed studies, ethical analyses, and clinical commentaries on male and female genital cutting. The journal has hosted critical discussions regarding the medical necessity, consent issues, and long-term consequences of routine non-therapeutic infant circumcision, providing a platform for medical professionals, legal scholars, and bioethicists to evaluate bodily integrity principles.

While maintaining a standard of scholarly neutrality, the papers published in BMJ have frequently informed intactivist arguments and international medical policy discussions. By featuring rigorous debates on pain management, human rights, and the comparative risks and benefits of penile modification, BMJ remains a crucial source of scientific literature for researchers investigating genital autonomy.', '', '', 'notable', 'A prominent global medical journal and publisher that has featured critical academic, ethical, and clinical debates on non-therapeutic infant circumcision and bodily autonomy.', 0, '[{"name": "Journal of Medical Ethics", "score": 11.405, "shared_docs": 2}, {"name": "Immanuel Kant", "score": 10.405, "shared_docs": 2}, {"name": "Brian D Earp", "score": 9.668, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 5.455, "shared_docs": 4}]');
