INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-7fba8a08', 'organization', 'University of New South Wales', 'The University of New South Wales (UNSW) is a public research university based in Sydney, Australia. Established in 1949, UNSW is recognized globally for its contributions to medicine, public health, and scientific research. Within the broader sociological and medical discourse surrounding male circumcision and bodily autonomy, the university served as an institutional home for prominent scholars and published studies addressing the health impacts, epidemiological outcomes, and prophylactic claims associated with the procedure.

The institution''s prominent presence in circumcision literature is notably tied to academic figures affiliated with the university, most prominently Professor Emeritus Brian Morris. As a vocal proponent of routine infant male circumcision, Morris produced numerous papers at UNSW arguing for the medical necessity and health benefits of circumcision, sparking significant debate within both global public health circles and bodily autonomy advocacy movements.

While UNSW as an organization maintains standard institutional neutrality, its academic platform enabled significant contributions to the global debate on neonatal and adult male circumcision. The research generated by its faculty continues to be cited by medical organizations, ethicists, and intactivist scholars evaluating the validity of prophylactic circumcision claims and the ethics of non-therapeutic bodily interventions.', '', '', 'notable', 'A leading Australian research university whose faculty and affiliated scholars have significantly influenced global public health literature on male circumcision.', 1, '[{"name": "Circumcision Foundation of Australia", "score": 11.16, "shared_docs": 3}, {"name": "University of Queensland", "score": 10.99, "shared_docs": 2}, {"name": "Terry Russell", "score": 10.575, "shared_docs": 2}, {"name": "University of Sydney", "score": 8.46, "shared_docs": 3}, {"name": "Royal Australasian College of Physicians", "score": 7.912, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-29bbc942', 'person', 'Soraya Mire', 'Soraya Mire is a Somali-born filmmaker, activist, and author best known for her pioneering efforts to raise global awareness about female genital mutilation (FGM). Having undergone FGM at the age of thirteen, her personal experience with the procedure''s severe physical and psychological consequences profoundly shaped her life''s work, driving her commitment to championing bodily autonomy and human rights for women and children.', '', '', 'champion', 'Somali filmmaker, author, and human rights activist widely recognized for her groundbreaking documentary Fire Eyes and advocacy against Female Genital Mutilation', 1, '[{"name": "David Llewellyn", "score": 10.668, "shared_docs": 2}, {"name": "Kristen O''Hara", "score": 10.668, "shared_docs": 2}, {"name": "William Stowell", "score": 10.668, "shared_docs": 2}, {"name": "Peter Ball", "score": 10.668, "shared_docs": 2}, {"name": "Yngve Hofvander", "score": 10.668, "shared_docs": 2}]');
