INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-cd2527b7', 'organization', 'Agency for Healthcare Research and Quality', 'The Agency for Healthcare Research and Quality (AHRQ) is a federal agency within the United States Department of Health and Human Services (HHS) charged with producing evidence to make healthcare safer, higher quality, more accessible, equitable, and affordable. Established originally as the Agency for Health Care Policy and Research in 1989, the agency serves as a primary federal source for health services research, technology assessments, and clinical evidence syntheses across a wide array of medical procedures.', '', '', 'notable', 'A United States federal agency whose health technology assessments and evidence reviews inform clinical guidelines and policy debates surrounding neonatal circumcision.', 0, '[{"name": "Emilie K. Johnson", "score": 11.183, "shared_docs": 2}, {"name": "Ilina Rosoklija", "score": 10.768, "shared_docs": 2}, {"name": "Medicaid", "score": 9.768, "shared_docs": 2}, {"name": "Centers for Disease Control and Prevention", "score": 7.143, "shared_docs": 3}, {"name": "American Academy of Pediatrics", "score": 5.554, "shared_docs": 5}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e35d4427', 'organization', 'Case Western Reserve University', 'Case Western Reserve University (CWRU) is a private research university located in Cleveland, Ohio. Established through the 1967 federation of Western Reserve University and the Case Institute of Technology, the university is widely recognized for its high-impact research programs, particularly within the School of Medicine, the School of Law, and the Department of Bioethics.

In the context of the discourse on circumcision and bodily autonomy, Case Western Reserve University serves as a key site of academic scholarship and medical research. Faculty members, ethicists, and legal scholars affiliated with the university have contributed to peer-reviewed literature examining the ethical, legal, and medical dimensions of routine infant circumcision, informed consent, and pediatric rights.

While the university as an administrative entity does not take an advocacy position, its academic platform enables ongoing investigation into medical necessity, bodily integrity, and patient rights. Scholars from CWRU continue to influence contemporary discussions surrounding bioethics, health policy, and the rights of children in medical decision-making.', '', '', 'notable', 'A prominent American research university whose medical, legal, and bioethics faculty contribute to scholarly literature on routine circumcision and bodily autonomy.', 0, '[{"name": "Ronald S. Immerman", "score": 10.99, "shared_docs": 3}, {"name": "Wade C. Mackey", "score": 10.768, "shared_docs": 3}, {"name": "Ronald S. Immerman and Wade C. Mackey", "score": 10.768, "shared_docs": 3}, {"name": "Brian D. Earp", "score": 6.405, "shared_docs": 2}, {"name": "World Health Organization", "score": 5.405, "shared_docs": 2}]');
