INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-cd21e6de', 'person', 'Nancy Ehrenreich', 'Nancy Ehrenreich is a legal scholar and Professor Emerita at the University of Denver Sturm College of Law, specializing in constitutional law, feminist legal theory, critical race theory, and reproductive rights. Throughout her academic career, her work has focused on the ways in which legal systems regulate bodily autonomy, gender, and cultural practices, particularly concerning medical and surgical interventions on human bodies.

In the discourse surrounding circumcision and bodily integrity, Ehrenreich is recognized for her comparative legal analyses examining female genital cutting, routine infant male circumcision, and medically unnecessary intersex surgeries. Her scholarship critically addresses the Western cultural biases and legal double standards that stringently condemn non-Western practices while normalizing or legally protecting non-consensual genital modifications performed within domestic healthcare systems.

By evaluating genital alterations through an intersectional legal and human rights framework, Ehrenreich has significantly contributed to academic understandings of bodily autonomy and consent. Her writings serve as foundational references in legal ethics, highlighting the political and social constructs that dictate which forms of bodily alteration are rendered acceptable or unlawful.', '', '', 'notable', 'Legal scholar known for her critical analysis of legal double standards and bodily autonomy regarding male, female, and intersex genital alterations.', 0, '[{"name": "Kirsten Bell", "score": 10.668, "shared_docs": 3}, {"name": "Kai M\u00f6ller", "score": 10.253, "shared_docs": 2}, {"name": "Fuambai Ahmadu", "score": 9.553, "shared_docs": 2}, {"name": "Margaret Somerville", "score": 9.083, "shared_docs": 2}, {"name": "Yale University", "score": 9.031, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-7e9a042b', 'person', 'Rebecca Steinfeld', 'Dr. Rebecca Steinfeld is a British academic, political scientist, and journalist whose work focuses on gender, bioethics, reproductive rights, and bodily autonomy. She earned her doctorate in politics from the University of Oxford and has held academic and research positions at several institutions, including Goldsmiths, University of London. Steinfeld gained widespread public recognition in the United Kingdom for her successful legal campaign to extend civil partnerships to opposite-sex couples, establishing her as a prominent advocate for equality and bodily rights.

Within the discourse on genital autonomy, Steinfeld has been a key voice challenging non-therapeutic infant circumcision. Through her public commentary and academic writing, she has argued that non-consensual male circumcision violates children''s human rights and bodily integrity, drawing explicit parallels to female genital mutilation (FGM). She has consistently advocated for legal frameworks that provide equal protection to all children against non-therapeutic genital alterations, regardless of gender.

Her contributions to the debate emphasize medical ethics, consent, and the principle that physical alterations should be deferred until an individual is old enough to make an informed decision. By framing infant circumcision through the lens of universal human rights and child welfare, Steinfeld has helped bring discussions of male genital autonomy into mainstream scholarly and media attention.', '', '', 'champion', 'British academic and political scientist advocating for universal bodily integrity and equal legal protection against non-therapeutic infant circumcision.', 0, '[{"name": "Goldsmiths, University of London", "score": 11.768, "shared_docs": 3}, {"name": "Tanya Gold", "score": 11.183, "shared_docs": 2}, {"name": "Elizabeth Reis", "score": 10.768, "shared_docs": 2}, {"name": "Council of Europe", "score": 8.598, "shared_docs": 2}, {"name": "The Hastings Center", "score": 8.598, "shared_docs": 2}]');
