INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-6192da40', 'organization', 'Canadian Pediatric Society', 'The Canadian Pediatric Society (CPS) is Canada''s national professional association for pediatricians and child health specialists, established in 1922. The organization represents thousands of healthcare professionals and is responsible for setting clinical guidelines, advocating for child health policy, and conducting medical education across the country. Through its policy statements and practice points, the CPS serves as the primary authority on pediatric standards of care in Canada.

The CPS has played a pivotal role in shaping medical practice and public health policy regarding non-therapeutic neonatal male circumcision. In 1975, 1996, and 2015, the society published comprehensive position statements reviewing the scientific literature on the procedure. The 1996 statement concluded that routine infant circumcision was not medically indicated, a position that significantly influenced provincial health authorities across Canada to remove the procedure from public health insurance coverage. The 2015 position statement reaffirmed that routine circumcision is not recommended for newborn infants, stating that while the procedure may carry certain localized medical benefits, the overall evidence does not justify universal surgical intervention.

Within the discourse on bodily autonomy and intactivism, the CPS''s clinical recommendations are frequently cited as key evidence against routine infant circumcision. While the society adopts a neutral, evidence-based stance designed to guide healthcare providers and parents, its explicit determination that routine circumcision lacks medical necessity has provided substantial support for advocates seeking to protect children''s right to genital integrity.', '', '', 'notable', 'Canada''s national pediatric association whose policy statements against routine infant circumcision significantly influenced public health policy and genital autonomy discourse.', 0, '[{"name": "Dawoodi Bohra", "score": 10.931, "shared_docs": 2}, {"name": "Dena Davis", "score": 10.253, "shared_docs": 2}, {"name": "Royal Australasian College of Physicians", "score": 8.59, "shared_docs": 3}, {"name": "Royal Dutch Medical Association", "score": 8.044, "shared_docs": 2}, {"name": "University of Oxford", "score": 7.931, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-391c1475', 'organization', 'Aalborg University', 'Aalborg University is a public Danish university founded in 1974, recognized internationally for its problem-based learning model and strong research programs in medicine, public health, and social sciences. Within the context of genital autonomy and circumcision discourse, the university serves as an important hub for Nordic health research and epidemiological studies examining the outcomes and ethics of male circumcision.

Researchers affiliated with Aalborg University, often in collaboration with other Danish health institutes, have authored influential peer-reviewed studies investigating the physiological, psychosexual, and long-term health impacts of non-therapeutic infant male circumcision. This research has frequently analyzed national registry data to evaluate potential complications, sexual function effects, and ethical considerations surrounding bodily integrity in minors.

Findings produced by researchers at Aalborg University are frequently cited by medical ethicists, human rights advocates, and bodily autonomy organizations globally. The institution''s academic contributions have played a notable role in informing European policy discussions and public debates regarding the necessity, risks, and age-of-consent requirements for non-therapeutic surgical interventions on children.', '', '', 'notable', 'A Danish public university whose researchers have contributed significant epidemiological and health studies to the global discourse on non-therapeutic circumcision.', 1, '[{"name": "Jacob Simonsen", "score": 11.575, "shared_docs": 3}, {"name": "Statens Serum Institut", "score": 11.061, "shared_docs": 7}, {"name": "The Hastings Center Bioethics Research Institute", "score": 10.253, "shared_docs": 2}, {"name": "Morten Frisch", "score": 9.327, "shared_docs": 8}, {"name": "Robert S. Van Howe", "score": 7.021, "shared_docs": 2}]');
