INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-0c1fa0f7', 'person', 'Kai Möller', 'Kai Möller is a legal scholar and Associate Professor of Law at the London School of Economics and Political Science (LSE). Specializing in constitutional theory, human rights, and legal philosophy, Möller has written extensively on rights inflation, proportionality, and the moral foundations of fundamental rights. His scholarly work frequently examines the legal limits of parental authority and the constitutional protections afforded to children''s bodily integrity.

In the context of the circumcision debate—particularly following the landmark 2012 Cologne court ruling in Germany—Möller authored key legal analyses examining the conflict between parental freedom of religion and a child''s fundamental rights. He argued from a constitutional standpoint that non-therapeutic infant male circumcision violates a child''s right to physical integrity and right to an open future, asserting that parental rights do not extend to irreversible physical modifications without medical necessity.

Through his rigorous legal commentaries, Möller provided an influential academic framework for analyzing non-consensual genital modifications through a human rights lens. His scholarship remains a primary reference point in jurisprudence and bioethics concerning the priority of children''s self-determination over traditional parental prerogatives.', '', '', 'champion', 'Legal scholar and professor whose work provides constitutional and human rights arguments for protecting children''s right to bodily integrity.', 1, '[{"name": "Nancy Ehrenreich", "score": 10.253, "shared_docs": 2}, {"name": "James Munby", "score": 9.99, "shared_docs": 2}, {"name": "Brian D Earp", "score": 9.253, "shared_docs": 2}, {"name": "Brussels Collaboration on Bodily Integrity", "score": 9.16, "shared_docs": 3}, {"name": "Joel Feinberg", "score": 8.875, "shared_docs": 2}]');
