INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-09b75f2a', 'person', 'Norm Cohen', 'Norm Cohen is an American human rights activist and prominent figure within the intactivist movement, recognized for his sustained advocacy for genital integrity and bodily autonomy. His involvement in the movement stemmed from an ethical and human rights perspective regarding non-consensual neonatal circumcision, leading him to become an active voice in challenging prevailing medical and cultural norms surrounding the practice in the United States.

Throughout his activism, Cohen played a key role in community organizing, public education, and support networks for individuals seeking information on intact care and foreskin restoration. As an active organizer associated with regional chapters of the National Organization of Circumcision Information Resource Centers (NOCIRC), he facilitated educational workshops, distributed literature, and participated in national symposiums aimed at informing parents, medical professionals, and the public about the functions of the human foreskin and the ethics of infant surgery.

In addition to grassroots outreach, Cohen contributed to the broader discourse on bodily autonomy by addressing the psychological and physical impacts of circumcision on men. His work helped establish support structures for circumcised men and laid important groundwork for contemporary bodily integrity advocacy groups.', '', '', 'champion', 'Prominent American intactivist and regional NOCIRC leader dedicated to bodily autonomy and genital integrity education.', 1, '[{"name": "Laurie Evans", "score": 10.531, "shared_docs": 2}, {"name": "NOCIRC of Michigan", "score": 10.379, "shared_docs": 3}, {"name": "Leonard Glick", "score": 9.794, "shared_docs": 2}, {"name": "Jeannine Parvati Baker", "score": 9.308, "shared_docs": 2}, {"name": "Mary Conant", "score": 9.116, "shared_docs": 2}]');
