INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-b38fbb9b', 'organization', 'Quinnipiac University', 'Quinnipiac University is a private university located in Hamden, Connecticut. Founded in 1929, the institution has grown into a major academic center offering widely recognized programs in law, medicine, health sciences, and journalism. Through its Frank H. Netter MD School of Medicine and School of Law, the university serves as a venue for scholarship surrounding health policy, medical ethics, and bodily autonomy.

Within the discourse on circumcision and intactivism, Quinnipiac University is recognized as a research and educational platform rather than an advocacy body. Scholars, legal researchers, and bioethicists affiliated with the university have produced work analyzing parental rights, informed consent, and the legal and ethical dimensions of non-therapeutic medical interventions on minors.

While maintaining an institutional position of academic neutrality, Quinnipiac University contributes to the broader sociological landscape through its scholarly publications and educational forums. Its academic contributions assist researchers and advocates in examining the intersection of pediatric medicine, law, and bodily integrity.', '', '', 'notable', 'A private American university known for its legal, medical, and polling research relevant to bioethics and healthcare policy.', 0, '[{"name": "William A. Jellison", "score": 11.768, "shared_docs": 3}, {"name": "Lauren M. Sardi", "score": 11.545, "shared_docs": 6}, {"name": "Ryan McAllister", "score": 11.183, "shared_docs": 2}, {"name": "Case Western Reserve University School of Law", "score": 10.446, "shared_docs": 2}, {"name": "David L. Gollaher", "score": 9.768, "shared_docs": 2}]');
