INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e86238ac', 'organization', 'Georgetown University', 'Georgetown University, established in 1789 in Washington, D.C., is a private research university renowned for its contributions to law, international affairs, bioethics, and medicine. Home to prominent research centers such as the Kennedy Institute of Ethics and the Georgetown University Law Center, the institution has long served as a key venue for rigorous academic inquiry into medical decision-making, pediatric ethics, and human rights.

Within the discourse surrounding circumcision and bodily autonomy, Georgetown University frequently appears as a institutional background for foundational legal and ethical scholarship. Researchers, ethicists, and legal commentators associated with the university have examined the complex intersections of parental authority, child welfare, religious freedom, and physical integrity. Publications and symposia associated with Georgetown have hosted debates on the ethical justification of non-therapeutic neonatal procedures and the application of international human rights standards to pediatric care.

While Georgetown University as an entity maintains an institutional posture of academic neutrality, its faculty, academic journals, and affiliated ethics panels have significantly influenced contemporary debates on genital autonomy. The university remains a noted reference point in sociological and legal archives documenting the evolution of bioethical perspectives on circumcision.', '', '', 'notable', 'A prominent private research university in Washington, D.C., recognized in bioethics and legal archives for hosting scholarly discourse on bodily autonomy, pediatric rights, and medical ethics.', 0, '[{"name": "John W. Travis", "score": 11.768, "shared_docs": 3}, {"name": "Ryan G. McAllister", "score": 11.768, "shared_docs": 3}, {"name": "Lawrence W. Green", "score": 11.183, "shared_docs": 2}, {"name": "University of California at San Francisco", "score": 11.183, "shared_docs": 2}, {"name": "Amber Craig", "score": 9.598, "shared_docs": 2}]');
