INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-24664e43', 'organization', 'European Court of Human Rights', 'Established in 1959 in Strasbourg, France, the European Court of Human Rights (ECtHR) is an international judicial body created under the European Convention on Human Rights to enforce civil and political rights across Council of Europe member states. The Court adjudicates applications brought by individuals or states regarding alleged treaty violations, serving as a primary authority on human rights law across the continent.

Within the discourse on circumcision, bodily autonomy, and children''s rights, the ECtHR''s jurisprudence serves as a critical legal framework. Debates regarding non-therapeutic pediatric circumcision frequently intersect with the Court''s interpretations of Article 8 (the right to respect for private and family life, encompassing physical integrity) and Article 9 (freedom of thought, conscience, and religion). Legal scholars and activists on both sides of the issue reference the Court''s principles when assessing the legal balance between parental rights to religious expression and a child''s right to physical integrity.

While the Court often grants state parties a ''margin of appreciation''—allowing national authorities leeway in balancing sensitive cultural and religious practices against state interest—its evolving standards on minor autonomy and medical consent remain central to legislative and judicial discussions across Europe regarding non-consensual bodily alterations.', '', '', 'notable', 'International judicial tribunal whose jurisprudence on privacy, bodily integrity, and religious freedom shapes European legal discourse on circumcision.', 0, '[{"name": "Council of Europe", "score": 9.083, "shared_docs": 2}, {"name": "World Health Organization", "score": 6.253, "shared_docs": 3}, {"name": "American Academy of Pediatrics", "score": 4.718, "shared_docs": 2}]');
