INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-c8a84d2b', 'organization', 'High Court of Australia', 'The High Court of Australia is the highest judicial authority in the Australian court hierarchy, established in 1901 under Section 71 of the Australian Constitution. Serving as the ultimate court of appeal and the primary interpreter of constitutional law, the Court shapes legal standards across the nation regarding individual rights, state powers, and the limits of legal authority.', '', '', 'notable', 'The supreme court of Australia whose rulings on parental consent and bodily integrity inform legal debates on non-therapeutic medical procedures.', 0, '[{"name": "Queensland Law Reform Commission", "score": 10.253, "shared_docs": 2}]');
