INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-59410e16', 'organization', 'Northwestern University Feinberg School of Medicine', 'Northwestern University Feinberg School of Medicine, located in Chicago, Illinois, is a prominent American research institution and medical school. Established in 1859, the school is recognized for its contributions to clinical medicine, public health research, pediatrics, and urology. As an academic medical center, Feinberg hosts numerous physician-researchers and scholars who contribute to peer-reviewed medical literature and ethical guidelines across various medical disciplines.

Within the discourse surrounding circumcision and bodily autonomy, Feinberg''s significance stems from the empirical research, clinical studies, and bioethical analyses produced by its affiliated faculty. Researchers associated with the institution have published work examining neonatal care practices, surgical outcomes, pediatric urology, and the ethical considerations surrounding informed consent and parental decision-making in non-therapeutic infant procedures.

As an institutional body, Feinberg serves as a forum for academic inquiry rather than an advocacy organization. Its research outputs reflect the broader professional and scientific dialogues in the United States regarding the medical risks, benefits, and ethical frameworks surrounding routine infant circumcision.', '', '', 'notable', 'A prominent American medical school whose affiliated researchers contribute to clinical literature and bioethical discourse surrounding pediatric health and circumcision.', 0, '[{"name": "Ilina Rosoklija", "score": 11.838, "shared_docs": 3}, {"name": "Emilie K. Johnson", "score": 11.668, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 5.718, "shared_docs": 4}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-df85d53f', 'organization', 'National Institutes of Health (NIH)', 'The National Institutes of Health (NIH) is the primary agency of the United States government responsible for biomedical and public health research. Operating under the U.S. Department of Health and Human Services, the NIH plays a central role in shaping global clinical knowledge through its extensive funding of scientific studies, clinical trials, and epidemiological research. Within the discourse surrounding male circumcision and bodily autonomy, the NIH has served as a foundational institutional authority whose funded research heavily informs public health policy and clinical practice.

Most notably, the NIH funded key randomized controlled trials in sub-Saharan Africa during the 2000s that investigated the relationship between adult male circumcision and heterosexually acquired HIV infection. The findings from these trials reported a protective effect against HIV transmission, significantly influencing policy recommendations issued by international bodies like the World Health Organization (WHO) as well as domestic organizations like the Centers for Disease Control and Prevention (CDC) and the American Academy of Pediatrics (AAP).

Within the intactivist movement and broader bioethical scholarship, the NIH is viewed as a major pillar of the medical establishment''s perspective on male circumcision. Researchers, human rights advocates, and bodily autonomy campaigners frequently analyze and critique NIH-funded studies, raising questions about research methodologies, the cross-cultural application of adult HIV data to non-therapeutic infant circumcision, and the ethical priority of bodily integrity over potential prophylactic benefits. Consequently, the NIH remains a central entity in the ongoing debate over the medicalization of human genitals.', '', '', 'notable', 'The primary U.S. federal biomedical research agency whose funded studies heavily inform global medical and public health debates on circumcision.', 0, '[{"name": "Richard G Wamai", "score": 11.183, "shared_docs": 2}, {"name": "Jeffrey D Klausner", "score": 10.768, "shared_docs": 2}, {"name": "Joint United Nations Programme on HIV/AIDS (UNAIDS)", "score": 9.308, "shared_docs": 2}, {"name": "World Health Organization (WHO)", "score": 7.715, "shared_docs": 5}, {"name": "UNAIDS", "score": 7.124, "shared_docs": 3}]');
