INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-945c43ae', 'person', 'John A. Erickson', 'John A. Erickson was an activist and advocate within the intactivist movement who contributed to public education and legal discourse surrounding non-consensual infant circumcision. Operating during a pivotal era of growing bodily autonomy advocacy in North America, Erickson focused on the ethical, legal, and human rights dimensions of routine neonatal genital alteration. His work sought to reframe circumcision not merely as a medical choice, but as a violation of an individual''s fundamental right to bodily integrity.

Throughout his involvement in the movement, Erickson authored articles, engaged in grassroots organizing, and collaborated with anti-circumcision organizations to raise awareness among parents and medical professionals. He critically examined the historical and cultural justifications for the practice, arguing for the legal protection of minors from non-therapeutic genital surgery. His contributions helped shape early legal arguments and educational outreach strategies utilized by advocates challenging established medical norms.

Erickson''s archival presence reflects a sustained commitment to legal reform and rights-based advocacy for children. By emphasizing constitutional rights, informed consent, and child protection standards, his work remains a key reference point in the history of the modern intactivist movement and ongoing debates over pediatric bioethics.', '', '', 'champion', 'American intactivist advocate and writer who contributed to the legal and ethical arguments against routine infant circumcision.', 1, '[{"name": "David S. Bate", "score": 10.768, "shared_docs": 3}, {"name": "Paul M. Fleiss", "score": 9.446, "shared_docs": 4}, {"name": "Martin Altschul", "score": 9.446, "shared_docs": 2}, {"name": "James L. Snyder", "score": 8.183, "shared_docs": 2}, {"name": "Sheila Curran", "score": 7.96, "shared_docs": 2}]');
