INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-de2000d2', 'organization', 'Nurses for the Rights of the Child', 'Nurses for the Rights of the Child (NRC) is an organization of nursing professionals dedicated to protecting infants and children from non-consensual genital alteration, including routine infant male circumcision and female genital cutting. Grounded in nursing ethics, pediatric healthcare standards, and international human rights principles, the organization emphasizes the fundamental duty of healthcare providers to advocate for vulnerable pediatric patients who cannot provide informed consent to irreversible surgical procedures.

Through public education, professional outreach, and policy engagement, NRC works to align clinical nursing practice with bioethical standards regarding bodily autonomy and physical integrity. The organization provides educational materials to nurses, parents, and medical institutions, highlighting the pain, surgical risks, and lack of medical necessity associated with non-therapeutic infant circumcision. By invoking the nursing code of ethics and the primary imperative to do no harm, NRC challenges traditional hospital protocols and cultural practices surrounding routine infant surgery.

As a distinct professional voice within the broader movement for genital autonomy, Nurses for the Rights of the Child collaborates with allied medical and human rights advocacy groups to influence policy and public perception. Their contributions have helped foster critical discussion within the healthcare community regarding child advocacy, informed consent, and the ethical obligation to preserve a child''s natural body.', '', '', 'champion', 'An organization of nursing professionals advocating for child bodily integrity and opposing non-therapeutic infant circumcision.', 1, '[{"name": "Laurie Evans", "score": 11.253, "shared_docs": 3}, {"name": "David Llewellyn", "score": 10.668, "shared_docs": 2}, {"name": "Zenas Baer", "score": 10.668, "shared_docs": 2}, {"name": "Peter Ball", "score": 10.668, "shared_docs": 2}, {"name": "Yngve Hofvander", "score": 10.668, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-9c731014', 'organization', 'Attorneys for the Rights of the Child (ARC)', 'Founded in 1997 by attorney Steven Svoboda, Attorneys for the Rights of the Child (ARC) is a non-profit legal advocacy organization based in the United States. The organization promotes the principle that all children, regardless of sex or gender, possess a fundamental human right to bodily integrity and protection from unnecessary, non-therapeutic medical interventions. ARC focuses extensively on educating legal, medical, and ethical professionals regarding the legal issues surrounding forced genital alterations.

ARC’s work centers on the legal analysis of parental consent, medical ethics, and constitutional rights as they apply to routine infant male circumcision, female genital mutilation/cutting, and intersex surgeries. The organization regularly submits amicus curiae briefs in legal cases, contributes scholarly articles to law journals, participates in international human rights conferences, and provides legal consultation to individuals and advocates seeking to challenge non-consensual genital cutting procedures.

Through its academic and legal outreach, ARC has played a pivotal role in shifting the discourse on circumcision from a routine cultural practice to a human rights issue. By advocating for the equal legal protection of all children''s bodies, the organization remains a foundational legal institution within the global intactivist movement.', '', '', 'champion', 'A legal advocacy organization dedicated to securing children''s fundamental rights to bodily integrity and self-determination.', 1, '[{"name": "Shelton Walden", "score": 11.116, "shared_docs": 3}, {"name": "Morris Sorrells", "score": 10.701, "shared_docs": 3}, {"name": "J. Neville Turner", "score": 10.531, "shared_docs": 2}, {"name": "Laurie Evans", "score": 10.531, "shared_docs": 2}, {"name": "Nurses for the Rights of the Child (NRC)", "score": 10.531, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-4a4585f0', 'person', 'Billy Ray Boyd', 'Billy Ray Boyd is an American author, editor, and advocate known for his early contributions to the intactivist movement and the broader discourse surrounding bodily autonomy and nonviolence. Through his research and published works, Boyd examined the historical, cultural, and psychological factors behind routine infant circumcision, positioning the practice as a violation of basic human rights and physical integrity.

He is best known for authoring accessible educational literature that critically analyzed the medical justifications for infant circumcision while highlighting the physiological functions of the human foreskin and the potential trauma of non-consensual surgery. His writings provided parents, ethics researchers, and bodily autonomy advocates with clear arguments and resources to challenge medicalized infant genital cutting in North America.

Boyd''s work helped lay the groundwork for modern genital autonomy advocacy during the late 20th century. His contributions remain referenced within sociological and historical archives detailing the evolution of anti-circumcision activism and rights-based healthcare critiques.', '', '', 'champion', 'Author and activist known for early foundational literature on the ethical, physical, and psychological aspects of infant circumcision.', 0, '[{"name": "Ron Goldman", "score": 9.446, "shared_docs": 2}, {"name": "California Medical Association", "score": 8.598, "shared_docs": 2}, {"name": "NOCIRC", "score": 8.265, "shared_docs": 3}, {"name": "Jim Bigelow", "score": 8.031, "shared_docs": 3}, {"name": "Marilyn Fayre Milos", "score": 7.124, "shared_docs": 2}]');
