INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-b3355321', 'person', 'Mohamed A. Baky Fahmy', 'Mohamed A. Baky Fahmy is a Professor of Pediatric Surgery at Al-Azhar University in Cairo, Egypt, and a prominent medical scholar specializing in pediatric urology and congenital genital anomalies. Throughout his medical career, Fahmy has authored numerous surgical textbooks and peer-reviewed articles detailing genital anatomy, reconstructive procedures, and the clinical outcomes of pediatric surgeries across the Middle East and internationally.

Fahmy gained significant recognition within bodily autonomy and medical ethics discourse through his extensive research on the harms and complications of non-therapeutic genital surgery. His landmark text, *Complications of Circumcision in Males and Females* (2019), provided a rigorous clinical categorization of the physical, functional, and psychological injuries resulting from both male circumcision and female genital mutilation/cutting (FGM/C). His work highlights common surgical errors, severe post-procedure deformities, and the risks associated with performative or traditional cutting practices.

Within the broader discourse on circumcision and intactivism, Fahmy''s scholarship serves as a key medical reference documenting the latent risks of routine non-consensual genital procedures. While his primary orientation is clinical and educational rather than activist, his detailed documentation of tissue damage and surgical failure has been widely cited by bioethicists, medical boards, and genital autonomy advocates working to curtail non-therapeutic pediatric surgeries.', '', '', 'notable', 'Egyptian professor of pediatric surgery and author renowned for his clinical research on the surgical complications of male and female genital cutting.', 0, '[{"name": "National Organization of Restoring Men (NORM)", "score": 8.446, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-92428069', 'organization', 'Elsevier Inc.', 'Elsevier Inc. is a major global academic publishing company specializing in scientific, technical, and medical content. Operating under the RELX Group, the organization publishes thousands of peer-reviewed journals and reference books, providing critical infrastructure for academic research and clinical education worldwide across medicine, bioethics, law, and sociology.

Within the discourse surrounding circumcision, bodily autonomy, and intactivism, Elsevier serves as a primary publisher for foundational peer-reviewed literature. Its clinical and ethical journals—such as Urology, the Journal of Pediatric Urology, and The Lancet—have hosted significant debates regarding the necessity, ethics, and outcomes of routine neonatal male circumcision, female genital alteration, and intersex medical interventions. Research published under the Elsevier imprint spans clinical studies on preputial anatomy and surgical complications to bioethical arguments advocating for bodily integrity and informed consent.

While Elsevier itself maintains a neutral corporate stance that delegates editorial decisions to individual journal boards, its publications remain pivotal reference points for both intactivist researchers and medical advocates. As a primary channel for medical literature, the company plays a structural role in shaping the evidence base used by policymakers, legal scholars, and advocacy groups worldwide.', '', '', 'notable', 'A leading global academic publisher responsible for distributing peer-reviewed medical, ethical, and sociological literature regarding circumcision and bodily autonomy.', 0, '');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-3d31cf07', 'person', 'Max Fish', 'Max Fish is an American human rights activist and prominent figure within the intactivist movement, dedicated to advancing bodily autonomy and opposing non-consensual infant male circumcision. Emerging as an advocate in the early 21st century, Fish focused his efforts on public education, ethics reform, and challenging the socio-cultural normalization of routine neonatal circumcision in North America.

Throughout his activism, Fish engaged in grassroots advocacy, participating in public demonstrations, street outreach, and media campaigns aimed at informing the public about foreskin anatomy, the psychological and physical impacts of circumcision, and the ethical principles of bodily integrity. His work often brought attention to the fundamental human rights aspect of children''s genital autonomy, framing non-therapeutic infant procedures as violations of personal consent.

Fish''s contributions reflect the broader sociological movement toward expanding bioethical standards of consent to include pediatric genital integrity. Through direct action and community engagement, he has remained an influential voice advocating for legislative and medical reform regarding genital autonomy.', '', '', 'champion', 'An American human rights activist and prominent intactivist advocating for pediatric genital autonomy and bodily integrity.', 0, '[{"name": "Godfrey B. Tangwa", "score": 11.668, "shared_docs": 2}, {"name": "Berufsverband der Kinder- und Jugend\u00e4rzte (BVKJ)", "score": 11.668, "shared_docs": 2}, {"name": "Arianne Shahvisi", "score": 10.446, "shared_docs": 2}, {"name": "UNICEF", "score": 8.223, "shared_docs": 3}, {"name": "University of Oxford", "score": 7.931, "shared_docs": 2}]');
