INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-be280f03', 'person', 'Janice Boddy', 'Janice Boddy is a Canadian socio-cultural anthropologist and Professor of Anthropology at the University of Toronto. She earned her Ph.D. from the University of British Columbia and has conducted extensive ethnographic fieldwork in Sudan, focusing on gender, health, body politics, and colonial history. Her academic work is widely recognized for its deep engagement with the social, symbolic, and historical contexts of bodily modifications in Northeastern Africa.

Boddy''s landmark 1989 ethnography, ''Wombs and Alien Spirits: Women, Men, and the Zar Cult in Northern Sudan'', examined female genital cutting—specifically infibulation—within local frameworks of social identity, fertility, and bodily purity. Rather than viewing the practice solely through a human rights lens, she analyzed how women themselves understood and reproduced these traditions. In her 2007 book, ''Civilizing Women: British Crusades in Colonial Sudan'', Boddy investigated 20th-century British colonial anti-circumcision campaigns, demonstrating how external, top-down interventions often exacerbated local resistance and complicated reform efforts.

Within the broader discourse on bodily autonomy, circumcision, and genital integrity, Boddy''s scholarship serves as a foundational reference for understanding the socio-cultural complexities of female genital practices. Her work challenges universalizing Western narratives while providing essential empirical grounding for sociologists, bioethicists, and human rights scholars analyzing bodily autonomy and cultural reform movements.', '', '', 'notable', 'Canadian anthropologist known for her seminal ethnographic research on female genital practices and colonial intervention in Sudan.', 0, '[{"name": "UNFPA", "score": 10.379, "shared_docs": 3}, {"name": "Ellen Gruenbaum", "score": 9.794, "shared_docs": 2}, {"name": "Nahid Toubia", "score": 9.794, "shared_docs": 2}, {"name": "Fuambai Ahmadu", "score": 9.553, "shared_docs": 2}, {"name": "Sara Johnsdotter", "score": 8.73, "shared_docs": 2}]');
