INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-ab018a98', 'person', 'Michael Thomson', 'Michael Thomson is a distinguished legal scholar and professor specializing in health law, law and humanities, and children''s human rights. Throughout his academic career, which includes appointments at prominent institutions in the United Kingdom and Australia, he has published extensively on the legal regulation of the body, gender, and healthcare ethics. His work frequently examines the intersections of medical decision-making, parental rights, and individual bodily autonomy.', '', '', 'champion', 'Legal scholar and professor specializing in health law, human rights, and legal frameworks surrounding children''s bodily integrity.', 0, '[{"name": "Marie Fox and Michael Thomson", "score": 12.253, "shared_docs": 4}, {"name": "Marie Fox", "score": 11.768, "shared_docs": 5}, {"name": "Keele University", "score": 11.668, "shared_docs": 2}, {"name": "Martha Nussbaum", "score": 10.083, "shared_docs": 2}, {"name": "National Health Service", "score": 9.083, "shared_docs": 2}]');
