INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-ad99470e', 'person', 'James Munby', 'Sir James Munby is a prominent British jurist and former judge who served as the President of the Family Division of the High Court of England and Wales from 2013 to 2018. Throughout his distinguished legal career, he presided over numerous complex family law matters involving children''s welfare, medical treatment consent, and religious practices.

Munby played a central role in establishing English legal precedent regarding non-therapeutic male circumcision. In significant family law decisions, including Re J (Child''s Religious Upbringing: Circumcision) [1999], he ruled that non-therapeutic male circumcision constitutes an irreversible act of broad significance and carries inherent medical risks. As a result, he established that one parent cannot unilaterally arrange for a child''s circumcision over the objections of another parent without explicit court authorization.

His judicial opinions underscored the necessity of balancing parental rights, religious freedom, and the child''s bodily integrity and best interests. By subjecting non-therapeutic pediatric circumcision to judicial oversight in contested cases, Munby''s rulings became foundational references in legal and bioethical discussions concerning bodily autonomy and children''s rights in the United Kingdom.', '', '', 'notable', 'Former President of the Family Division of the High Court of England and Wales whose legal rulings established key precedents regarding parental consent and non-therapeutic male circumcision.', 0, '[{"name": "National Secular Society", "score": 11.405, "shared_docs": 2}, {"name": "Kai M\u00f6ller", "score": 9.99, "shared_docs": 2}, {"name": "Danish Medical Association", "score": 9.875, "shared_docs": 3}, {"name": "General Medical Council", "score": 9.405, "shared_docs": 2}, {"name": "Joel Feinberg", "score": 9.29, "shared_docs": 2}]');
