INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-c128a26e', 'person', 'John Taylor', 'John Taylor emerged as a prominent voice within the global movement for genital bodily autonomy during the late 20th and early 21st centuries. Engaging deeply with human rights frameworks surrounding infant male circumcision, Taylor contributed significantly to raising public awareness regarding physical integrity, medical ethics, and the principle of informed consent for minors.

His work within the intactivist community focused on educating the public regarding the anatomical and physiological functions of the prepuce, while critically examining mainstream clinical justifications for routine neonatal surgical procedures. Through written literature, community outreach, and collaboration with advocacy organizations, Taylor played an active role in connecting international networks of activists across the United Kingdom, North America, and Europe.

Throughout his involvement in the discourse, Taylor emphasized the universal application of bodily autonomy across all genders. His historical contributions remain a subject of study within archival literature documenting the evolution of child advocacy, anti-circumcision campaigning, and the broader social shift toward non-therapeutic genital autonomy.', '', '', 'champion', 'Human rights advocate and key figure in the international movement against non-consensual infant circumcision.', 1, '[{"name": "J. David Bigelow", "score": 10.668, "shared_docs": 2}, {"name": "National Organization of Circumcision Information Centers", "score": 10.668, "shared_docs": 2}, {"name": "William Stowell", "score": 10.668, "shared_docs": 2}, {"name": "Peter Ball", "score": 10.668, "shared_docs": 2}, {"name": "Yngve Hofvander", "score": 10.668, "shared_docs": 2}]');
