INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-843a9761', 'person', 'D. Gairdner', 'Douglas Gairdner (1910–1992) was a distinguished British pediatrician and editor whose clinical research fundamentally altered medical policy regarding routine infant circumcision in the United Kingdom. Based at Addenbrooke''s Hospital in Cambridge and serving for many years as the editor of the Archives of Disease in Childhood, Gairdner dedicated much of his career to evaluating standard pediatric interventions and defending normal infantile anatomy.

In 1949, Gairdner published his seminal paper, "The Fate of the Foreskin," in the British Medical Journal. The study systematically dismantled prevailing medical arguments for routine neonatal circumcision by demonstrating that physiological adhesions between the foreskin and glans are a normal feature of infant development rather than a pathology requiring surgery. He detailed the morbidity and mortality risks associated with the procedure, concluding that routine infant circumcision was medically unjustified and caused unnecessary harm.

Gairdner''s rigorous clinical analysis served as a major catalyst for the British medical establishment''s rejection of routine neonatal circumcision, contributing directly to its exclusion from coverage under the newly established National Health Service (NHS). His pioneering work remains a cornerstone of the medical argument for genital autonomy and intact care, providing foundational scientific backing for modern anti-circumcision advocacy.', '', '', 'champion', 'British pediatrician whose landmark 1949 study "The Fate of the Foreskin" led to the end of routine infant circumcision in the United Kingdom', 0, '[{"name": "J. Oster", "score": 11.031, "shared_docs": 3}, {"name": "American Academy of Pediatrics", "score": 5.232, "shared_docs": 4}]');
