INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-0e96a580', 'person', 'Mark D. Reiss', 'Mark D. Reiss, M.D., is an American physician and prominent figure within the intactivist movement. Trained in medicine, Reiss emerged as a key medical voice challenging routine non-therapeutic infant circumcision in the United States, arguing that the practice violates fundamental principles of medical ethics, informed consent, and bodily integrity.', '', '', 'champion', 'Physician and founder of Doctors Opposing Circumcision who spearheaded medical professional advocacy for genital autonomy.', 0, '[{"name": "Norma Wilcox", "score": 11.575, "shared_docs": 3}, {"name": "John V. Geisheker", "score": 10.668, "shared_docs": 2}, {"name": "Marilyn F. Milos", "score": 10.405, "shared_docs": 2}, {"name": "James L. Snyder", "score": 9.405, "shared_docs": 2}, {"name": "George C. Denniston", "score": 9.116, "shared_docs": 3}]');
