INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-4e0dde3c', 'organization', 'Johns Hopkins Bloomberg School of Public Health', 'The Johns Hopkins Bloomberg School of Public Health (JHSPH), founded in 1916 in Baltimore, Maryland, is a leading academic institution for public health research, education, and policy formulation. Throughout its history, the school has conducted extensive epidemiological and clinical research that has heavily influenced global health directives, infectious disease control strategies, and preventive medicine standards across numerous international settings.

Within the discourse on circumcision and bodily autonomy, JHSPH became highly prominent due to the work of several key researchers involved in international clinical trials, notably through the Rakai Health Sciences Program in Uganda. Studies led by JHSPH faculty provided pivotal randomized controlled trial data indicating that male circumcision reduced female-to-male heterosexual HIV transmission, as well as risks for other sexually transmitted infections. These findings directly informed the 2007 World Health Organization and UNAIDS recommendations promoting voluntary medical male circumcision as an HIV prevention strategy in high-prevalence regions of sub-Saharan Africa.

Additionally, JHSPH researchers frequently published cost-benefit analyses and epidemiological models defending routine infant male circumcision in the United States, arguing that declining rates would lead to increased healthcare costs and STI incidence. Consequently, the institution emerged as a primary scientific authority cited by medical proponents of circumcision, while drawing significant criticism from intactivist organizations and bodily autonomy advocates who questioned the trial methodologies, ethical frameworks, and application of population-level findings to non-consensual infant procedures.', '', '', 'critic', 'A premier public health institution whose faculty and research trials strongly influenced global and national policies advocating for male circumcision.', 0, '[{"name": "Thomas C. Quinn", "score": 11.668, "shared_docs": 2}, {"name": "Johns Hopkins University School of Medicine", "score": 11.253, "shared_docs": 2}, {"name": "Aaron A. R. Tobian", "score": 10.931, "shared_docs": 2}, {"name": "Bill and Melinda Gates Foundation", "score": 10.253, "shared_docs": 2}, {"name": "Ronald H. Gray", "score": 9.931, "shared_docs": 2}]');
