INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-c1301f88', 'person', 'Wilhelm Reich', 'Wilhelm Reich (1897–1957) was an Austrian psychoanalyst, psychiatrist, and social theorist recognized for his pioneering contributions to somatic psychology, character analysis, and the study of body-mind integration. A prominent second-generation student of Sigmund Freud, Reich eventually broke from traditional psychoanalysis to develop a body-centered therapeutic framework. He conceptualized ''character armor'' as the somatic and psychological defenses formed in response to societal repression, arguing that physical rigidity and emotional distress stem from the systematic suppression of natural human vitality and sexuality.

Central to Reich''s theoretical framework was a firm opposition to routine infant circumcision and other forms of early genital intervention. Reich viewed infant circumcision as a form of early bodily trauma that fundamentally compromises an individual''s sensory integrity and natural self-regulation. He argued that genital cutting was a culturally enforced trauma designed to suppress biological drive, induce emotional compliance, and solidify emotional rigidity within patriarchal and authoritarian social systems.

Reich''s early explicit critiques of routine infant circumcision established a foundational connection between psychoanalytic theory, somatic integrity, and anti-authoritarian bodily self-determination. His legacy continues to be referenced within intactivist discourse and sociological literature examining the historic medical and psychological critiques of routine neonatal surgery.', '', '', 'champion', 'Austrian psychoanalyst and pioneer of somatic psychology who identified routine infant circumcision as a traumatic violation of bodily autonomy and sexual integrity.', 1, '[{"name": "Bruno Bettelheim", "score": 9.405, "shared_docs": 2}, {"name": "Sigmund Freud", "score": 8.903, "shared_docs": 4}, {"name": "Ashley Montagu", "score": 8.598, "shared_docs": 4}, {"name": "James DeMeo", "score": 8.405, "shared_docs": 5}, {"name": "James W. Prescott", "score": 7.668, "shared_docs": 2}]');
