INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-a03c0d6b', 'organization', 'University College London', 'University College London (UCL) is a public research university in London, England, established in 1826. Recognized as one of the United Kingdom''s leading academic institutions, UCL encompasses a broad range of disciplines, including medicine, law, social sciences, and bioethics. Within the archive''s focus on bodily autonomy and genital integrity, UCL serves as a significant site for scholarly inquiry, legal analysis, and public debate regarding the ethics and legality of bodily modifications.', '', '', 'notable', 'A leading British research university whose legal and ethical scholarship contributes to broader academic debates on bodily integrity and consent.', 0, '');
