INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-351e04f4', 'person', 'Jomo Kenyatta', 'Jomo Kenyatta (c. 1897 – 1978) was an anti-colonial activist, anthropologist, and the first President of independent Kenya. Educated in social anthropology at the London School of Economics under Bronislaw Malinowski, Kenyatta authored the seminal ethnographic study ''Facing Mount Kenya'' (1938), which documented the traditional customs, social organisation, and religious practices of the Kikuyu people.

During the 1920s and 1930s, Kenyatta emerged as a central defender of Kikuyu cultural practices during the female circumcision controversy in colonial Kenya. When British missionaries and colonial authorities attempted to suppress traditional male and female initiation rites—specifically the practice of female genital modification (irua)—Kenyatta and the Kikuyu Central Association vigorously opposed the bans. He argued that circumcision was not merely a physical procedure, but an indispensable rite of passage that maintained Kikuyu age-grade systems, moral cohesion, and cultural identity.

Kenyatta''s defense of traditional genital operations positioned bodily practices as key battlegrounds for anti-colonial resistance and indigenous sovereignty. In contemporary sociological and human rights discourse on bodily autonomy and genital integrity, his writings remain a foundational case study in how bodily modifications have historically intersected with cultural relativism, anti-imperialism, and national identity.', '', '', 'critic', 'Kenyan anti-colonial leader and anthropologist who defended traditional Kikuyu male and female circumcision practices as vital cultural rites of passage.', 0, '[{"name": "Richard A. Shweder", "score": 9.083, "shared_docs": 2}, {"name": "American Academy of Pediatrics (AAP)", "score": 7.581, "shared_docs": 2}, {"name": "World Health Organization (WHO)", "score": 7.463, "shared_docs": 3}, {"name": "United Nations", "score": 6.794, "shared_docs": 2}]');
