INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-6c1c8902', 'person', 'Ron Goldman', 'Dr. Ron Goldman is an American psychologist, researcher, author, and speaker who emerged as a prominent figure in the intactivist and genital autonomy movements in the late 20th century. Based in Boston, Massachusetts, Goldman founded the Circumcision Resource Center, a non-profit educational organization established to inform the public and healthcare professionals about the psychological, emotional, and physical impacts of male circumcision.

Goldman is best known for his landmark books, including "Circumcision: The Hidden Trauma" (1997) and "Questioning Circumcision: A Jewish Perspective" (1998). His research integrated psychological theory with empirical evidence to argue that neonatal circumcision causes significant pain and potential long-term trauma affecting early parent-child bonding, emotional development, and adult psychological well-being. His work on Jewish cultural and religious perspectives sought to foster internal dialogue within Jewish communities regarding traditional practices and bodily integrity.

Throughout his career, Goldman has conducted extensive public lectures, media appearances, and consultations with expecting parents and medical professionals. By focusing on the psychological and human rights dimensions of non-consensual infant circumcision, his work contributed substantially to the broader ethical debate surrounding children''s bodily autonomy.', '', '', 'champion', 'Psychologist, author, and founder of the Circumcision Resource Center known for examining the psychological impacts of non-consensual infant circumcision.', 1, '[{"name": "David Chamberlain", "score": 10.253, "shared_docs": 2}, {"name": "Warren Smith", "score": 9.931, "shared_docs": 2}, {"name": "Ron Fisher", "score": 9.668, "shared_docs": 2}, {"name": "RECAP", "score": 9.516, "shared_docs": 3}, {"name": "Billy Ray Boyd", "score": 9.446, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-151f4859', 'person', 'Alice Miller', 'Alice Miller (1923–2010) was a Swiss psychologist, psychoanalyst, and author renowned for her seminal work on childhood trauma, parental abuse, and the long-term emotional consequences of physical and psychological harm inflicted on children. Born in Poland, Miller studied philosophy and psychology in Switzerland, practicing psychoanalysis for over two decades before resigning from the professional psychoanalytic establishment to focus independently on advocacy and writing against routine societal violence toward infants and children.

While her publications examined a wide array of normalized child-rearing practices, Miller''s core theories on bodily integrity and early trauma became deeply influential within the intactivist and genital autonomy movements. Works such as *The Drama of the Gifted Child* and *For Your Own Good* provided a psychological framework used by intactivist scholars to analyze routine infant circumcision as a form of non-consensual childhood trauma and systemic denial of physical autonomy.

Throughout her career, Miller asserted that early physical pain and bodily violations leave lasting psychological scars, often minimized or rationalized by adult society through cultural tradition. Her uncompromising stance on protecting infants from physical alteration and pain established a critical theoretical foundation for contemporary ethics surrounding children''s bodily rights.', '', '', 'notable', 'Swiss psychologist and author whose pioneering research on childhood trauma provided a theoretical foundation for the intactivist movement.', 0, '[{"name": "Nahid Toubia", "score": 9.308, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 4.232, "shared_docs": 2}]');
