INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-a01d19ce', 'organization', 'National Organization of Restoring Men', 'The National Organization of Restoring Men (NORM) is a non-profit support and advocacy organization founded in 1989 to assist individuals seeking foreskin restoration and to promote male bodily integrity. Originally established as the National Organization of Restoring Males, the group emerged as one of the earliest organized responses to the psychological and physical dissatisfaction experienced by circumcised men in North America.

Throughout its history, NORM has operated through local support chapters, educational outreach, and digital platforms to provide comprehensive information regarding non-surgical and surgical foreskin restoration techniques. The organization also serves as a crucial space for emotional processing, offering peer-led support to address the trauma, grief, and body image concerns associated with involuntary infant circumcision.

As a foundational pillar of the broader intactivist movement, NORM has contributed significantly to public discourse on consent, medical ethics, and bodily autonomy. By providing resources and normalizing discussions around male genital anatomy and restoration, the organization has championed the rights of individuals to make informed decisions regarding their own bodies.', '', '', 'champion', 'A pioneering support and advocacy organization providing resources for foreskin restoration and promoting male bodily autonomy.', 0, '[{"name": "Adrienne Carmack", "score": 10.768, "shared_docs": 2}, {"name": "Ron Goldman", "score": 9.446, "shared_docs": 2}, {"name": "National Organization to Halt the Abuse and Routine Mutilation of Males", "score": 9.353, "shared_docs": 3}, {"name": "Jennifer A. Bossio", "score": 9.183, "shared_docs": 2}, {"name": "Attorneys for the Rights of the Child", "score": 7.861, "shared_docs": 2}]');
