INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-fee4190c', 'person', 'Lawrence Dillon', 'Lawrence Dillon emerged as an advocate within the movement for bodily autonomy, focusing his efforts on the ethical, human rights, and legal dimensions of routine non-therapeutic infant circumcision. Through his writings and involvement in public discourse, Dillon has consistently argued against the medicalization of healthy genital tissue and emphasized the fundamental right of individuals to make informed decisions regarding their own bodies upon reaching maturity.', '', '', 'champion', 'An advocate and writer dedicated to promoting bodily autonomy and challenging routine infant circumcision.', 0, '[{"name": "American Men''s Studies Association", "score": 11.183, "shared_docs": 2}, {"name": "Dillonwood Productions", "score": 10.96, "shared_docs": 4}, {"name": "American Psychological Association", "score": 10.768, "shared_docs": 2}, {"name": "Barry Ellsworth", "score": 10.446, "shared_docs": 2}, {"name": "PBS", "score": 10.183, "shared_docs": 2}]');
