INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e073960a', 'organization', 'Dillonwood Productions', 'Dillonwood Productions is an independent media production organization recognized for its pivotal role in creating educational and documentary films focused on medical ethics, bodily integrity, and genital autonomy. Operating during a key formative period for the modern intactivist movement, the production house sought to challenge prevailing cultural and medical norms surrounding routine neonatal circumcision in North America through documentary media.

The organization gained widespread recognition within human rights and advocacy circles through its landmark production, *Whose Body, Whose Rights?* (1995). The documentary systematically examined routine infant circumcision by combining interviews with medical professionals, bioethicists, legal scholars, and affected men. By detailing the anatomy, history, ethical implications, and psychological aspects of circumcision, Dillonwood Productions provided one of the earliest comprehensive visual critiques of non-consensual infant genital surgery.

Audiovisual resources produced by Dillonwood Productions served as critical tools for grassroots activism, public education, and academic discussion throughout the 1990s and 2000s. Distributed across activist networks, health conferences, and educational seminars, the company''s work significantly aided advocacy groups in reaching expecting parents, medical practitioners, and the broader public regarding the importance of bodily integrity.', '', '', 'champion', 'An independent media production company best known for producing foundational educational documentaries on genital autonomy, including *Whose Body, Whose Rights?*', 1, '[{"name": "Lawrence Dillon", "score": 10.96, "shared_docs": 4}, {"name": "PBS", "score": 10.768, "shared_docs": 3}, {"name": "Barry Ellsworth", "score": 10.446, "shared_docs": 2}, {"name": "James Loewen", "score": 9.598, "shared_docs": 2}, {"name": "George C. Denniston", "score": 8.308, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-12c6492b', 'organization', 'Doctors Opposing Circumcision (D.O.C.)', 'Doctors Opposing Circumcision (D.O.C.) was founded in 1995 in Seattle, Washington, by a group of medical practitioners led by physician George C. Denniston. The organization was established to challenge the practice of routine non-therapeutic neonatal male circumcision in the United States and abroad. Composed of physicians, medical researchers, and allied healthcare professionals, D.O.C. operates on the principle that non-consenting infant circumcision violates medical ethics, bodily integrity, and basic human rights.

Throughout its history, the organization has served as an educational resource for medical professionals, legal scholars, and parents. D.O.C. produces medical literature, ethical analyses, and policy critiques detailing the physiological functions of the foreskin and the potential physical and psychological risks of its removal. The group has actively engaged with major professional associations, such as the American Academy of Pediatrics, advocating for policy frameworks that prioritize bodily autonomy and informed consent.', '', '', 'champion', 'An international organization of physicians and healthcare professionals dedicated to ending routine infant circumcision and upholding bodily autonomy.', 0, '[{"name": "Nurses for the Rights of the Child", "score": 10.253, "shared_docs": 3}, {"name": "Charles A. Bonner", "score": 9.82, "shared_docs": 2}, {"name": "Attorneys for the Rights of the Child (ARC)", "score": 9.531, "shared_docs": 2}, {"name": "Sheila Curran", "score": 9.183, "shared_docs": 2}, {"name": "Ronald Goldman", "score": 8.946, "shared_docs": 4}]');
