INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e7fb4c20', 'person', 'Rosemary Romberg', 'Rosemary Romberg was an early American advocate for bodily autonomy and genital integrity, recognized as one of the pioneering figures in the modern intactivist movement. Prompted by her personal experiences as a mother and her investigation into routine neonatal male circumcision in North America, she dedicated her work to educating the public and healthcare providers about the ethical, anatomical, and psychological dimensions of the procedure.

In 1985, Romberg published her landmark book, Circumcision: The Painful Dilemma, which served as one of the earliest comprehensive texts to critically re-evaluate non-therapeutic infant circumcision. The work synthesized medical literature, historical analysis, and personal testimonies, offering parents and professionals a detailed counter-narrative to the prevailing medical consensus of the late 20th century.

In addition to her authorial contributions, Romberg established grassroots support networks and educational organizations aimed at promoting informed consent and protecting infants from unnecessary surgical alterations. Her pioneering organizing efforts in the 1980s significantly shaped subsequent activist strategies and laid critical intellectual foundations for modern genital autonomy advocacy.', '', '', 'champion', 'Pioneering author and advocate who wrote Circumcision: The Painful Dilemma and helped establish early grassroots intactivist networks.', 1, '[{"name": "Bergin & Garvey", "score": 9.82, "shared_docs": 4}, {"name": "Peaceful Beginnings", "score": 9.29, "shared_docs": 9}, {"name": "Anne Briggs", "score": 9.013, "shared_docs": 4}, {"name": "Society for Humanistic Judaism", "score": 8.82, "shared_docs": 2}, {"name": "INTACT Educational Foundation", "score": 8.82, "shared_docs": 2}]');
