INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-94cdd236', 'organization', 'Kaiser Foundation Hospital', 'Kaiser Foundation Hospitals constitute the hospital network of Kaiser Permanente, one of the largest non-profit integrated managed care and healthcare providers in the United States. Established in the mid-20th century, the organization operates medical centers and facilities across several states, providing comprehensive clinical care, obstetrics, and pediatric services to millions of members.

Within the history and archival record of circumcision policy and bodily autonomy debates, Kaiser Foundation Hospitals represent an important institutional locus. As major regional providers of newborn care, the medical network''s policies regarding routine neonatal circumcision, parental consent frameworks, medical necessity criteria, and insurance coverage have frequently served as points of reference for broader medical and legal discussions surrounding the procedure.

The institution''s appearance in archival materials highlights the role of managed care organizations in operationalizing pediatric medical guidelines and managing parental choices. While primarily functioning as a standard healthcare service provider, its clinical practices and policy decisions reflect the evolving medical consensus and legal landscape surrounding genital autonomy and non-therapeutic surgical interventions.', '', '', 'notable', 'A major American healthcare provider network whose clinical practices and institutional policies intersect with the implementation of routine neonatal circumcision.', 0, '[{"name": "Kelen Nelson", "score": 11.575, "shared_docs": 3}, {"name": "Alameda Superior Court", "score": 11.575, "shared_docs": 3}, {"name": "Permanente Medical Group", "score": 11.405, "shared_docs": 4}, {"name": "Marin County Superior Court", "score": 11.405, "shared_docs": 4}, {"name": "Adam London", "score": 10.531, "shared_docs": 4}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f03ff0d8', 'person', 'Frederick Mansfield Hodges', 'Frederick Mansfield Hodges is a medical historian, researcher, and author recognized for his extensive scholarly work on the history, anatomy, and ethics of male circumcision. His research primarily examines the socio-historical origins of routine neonatal circumcision in English-speaking countries, tracing its rise to Victorian-era medical theories, anti-masturbation anxieties, and outdated hygienic beliefs of the late nineteenth and early twentieth centuries.', '', '', 'champion', 'A medical historian and researcher whose work documented the history of medicalized circumcision and advocated for foreskin preservation.', 0, '[{"name": "William Stowell", "score": 11.768, "shared_docs": 3}, {"name": "Peter Ball", "score": 11.183, "shared_docs": 2}, {"name": "Yngve Hofvander", "score": 11.183, "shared_docs": 2}, {"name": "Leonard Glick", "score": 10.446, "shared_docs": 2}, {"name": "Kluwer Academic / Plenum Publishers", "score": 10.446, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-97168d28', 'person', 'Leo Sorger', 'Dr. Leo Sorger was an American obstetrician-gynecologist who became a prominent advocate against routine infant circumcision in the United States. Drawing from decades of clinical experience in women''s health and childbirth, Sorger publicly challenged the medical necessity of neonatal circumcision, emphasizing the anatomical importance of the prepuce and the ethical imperatives of bodily autonomy and informed consent.

Throughout his involvement in the intactivist movement, Sorger contributed expert commentary and educational resources to organizations dedicated to ending non-therapeutic child genital cutting. He argued that routine circumcision violated basic medical ethics and Hippocratic principles, positioning himself as a leading medical voice calling for reform within pediatric and surgical practices.', '', '', 'champion', 'American obstetrician-gynecologist and medical advocate against routine infant circumcision.', 0, '[{"name": "Roger Saquet", "score": 11.99, "shared_docs": 3}, {"name": "William Sullivan", "score": 11.99, "shared_docs": 3}, {"name": "Vicki MacLean", "score": 11.99, "shared_docs": 3}, {"name": "Charles Konia", "score": 11.99, "shared_docs": 3}, {"name": "Myron Sharaf", "score": 11.99, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e61a5080', 'person', 'Paul M. Fleiss', 'Paul Murray Fleiss (1933–2014) was a prominent American pediatrician based in Los Angeles, California, recognized for his holistic approach to pediatrics, promotion of extended breastfeeding, and vocal opposition to routine infant circumcision. After earning his medical degree from Wayne State University School of Medicine, Fleiss established a renowned practice in Los Feliz, where he treated generations of children and advocated for patient-centered, low-intervention infant care.', '', '', 'champion', 'American pediatrician and prominent medical advocate for routine infant genital integrity and natural child rearing.', 1, '[{"name": "David S. Bate", "score": 11.253, "shared_docs": 3}, {"name": "John A. Erickson", "score": 9.446, "shared_docs": 4}, {"name": "Frederick Hodges", "score": 8.446, "shared_docs": 2}, {"name": "Thomas E. Wiswell", "score": 7.166, "shared_docs": 2}, {"name": "Marilyn Fayre Milos", "score": 6.609, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-092a5d33', 'organization', 'Michigan State University College of Human Medicine', 'The Michigan State University College of Human Medicine (MSU CHM) is a public medical school headquartered in East Lansing and Grand Rapids, Michigan. Founded in 1964, the institution is widely recognized for its community-based medical education model, clinical research output, and emphasis on primary care and bioethics. As a major center for medical training in the American Midwest, the college educates future physicians in pediatrics, obstetrics, and public health policy.

Within the broader discourse on circumcision, bodily autonomy, and medical ethics, MSU CHM serves as an institutional site for medical research, professional education, and scholarly dialogue. Faculty members, researchers, and bioethicists affiliated with the university have contributed to academic literature regarding pediatric patient rights, informed consent, and the clinical justifications surrounding routine neonatal procedure practices.

As medical consensus and public awareness surrounding non-therapeutic infant procedures continue to evolve, academic institutions like MSU CHM remain central to shaping physician perspectives and clinical standards. The college''s clinical faculties and bioethics programs provide an arena where evidence-based medicine, ethical considerations, and patient autonomy principles intersect within contemporary healthcare education.', '', '', 'notable', 'A leading American medical institution involved in medical education, pediatric research, and bioethical discourse surrounding clinical care.', 1, '[{"name": "Elsevier Ltd.", "score": 10.575, "shared_docs": 2}, {"name": "Xavier Castellsagu\u00e9", "score": 10.253, "shared_docs": 2}, {"name": "Robert S Van Howe", "score": 10.253, "shared_docs": 2}, {"name": "Robert S. Van Howe", "score": 8.021, "shared_docs": 4}, {"name": "Attorneys for the Rights of the Child", "score": 7.668, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-d72927f5', 'person', 'Ronald S. Immerman', 'Ronald S. Immerman is an academic researcher known for his sociobiological and evolutionary analyses of human cultural behaviors, particularly male genital modification practices. Working frequently in collaboration with researcher Wade C. Mackey, Immerman explored the historical origins, persistence, and social dynamics of male circumcision from an evolutionary psychology and anthropological perspective during the late 1990s and early 2000s.

Immerman''s scholarship examined how routine and ritualistic circumcision functioned within human social structures. His publications theorized that male circumcision historically served as a cultural signaling mechanism designed to enhance paternal certainty, reinforce group cohesion, and mark social identity. By framing genital alterations through an evolutionary lens, his work analyzed why such traditions maintained strong continuity across generations despite the physical pain and risks involved.

Within the broader discourse on circumcision and bodily autonomy, Immerman’s contributions offer a descriptive theoretical framework rather than a normative moral position. His research is frequently referenced by social scientists, bioethicists, and scholars seeking to understand the socio-cultural mechanics and evolutionary theories behind the persistence of male genital cutting.', '', '', 'notable', 'An academic researcher known for his sociobiological and evolutionary analyses of ritual and routine male circumcision.', 0, '[{"name": "Wade C. Mackey", "score": 11.768, "shared_docs": 6}, {"name": "Ronald S. Immerman and Wade C. Mackey", "score": 11.505, "shared_docs": 5}, {"name": "Case Western Reserve University", "score": 10.99, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-8ccc57d9', 'person', 'Wade C. Mackey', 'Wade C. Mackey was an American anthropologist and researcher who contributed to the study of human behavior, sociobiology, and cultural practices. He earned his doctorate in anthropology from the University of Virginia and held various academic and teaching posts throughout his career. His broader research portfolio encompassed topics such as human mating systems, fatherhood roles, and cross-cultural demographic trends.

Within the study of bodily autonomy and genital alteration, Mackey collaborated frequently with researcher Ronald S. Immerman to examine male circumcision through an evolutionary and cross-cultural lens. Their scholarly work analyzed the cultural persistence, social functions, and historical prevalence of male circumcision, investigating how institutionalized physical markers function within social structures and reproductive strategies.

Mackey''s publications provided theoretical frameworks for understanding the anthropological mechanisms behind societal acceptance and continuity of infant and adolescent circumcision. His academic contributions remain a subject of reference in sociological archives examining the intersection of culture, biology, and bodily autonomy.', '', '', 'notable', 'American anthropologist and researcher recognized for his cross-cultural and sociobiological analyses of male circumcision practices.', 0, '[{"name": "Ronald S. Immerman", "score": 11.768, "shared_docs": 6}, {"name": "Ronald S. Immerman and Wade C. Mackey", "score": 11.282, "shared_docs": 5}, {"name": "Case Western Reserve University", "score": 10.768, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-a9a9ed16', 'person', 'Ronald S. Immerman and Wade C. Mackey', 'Ronald S. Immerman and Wade C. Mackey were academic researchers who co-authored a series of papers in the late 1990s and 2000s examining male circumcision through the lenses of evolutionary psychology, bio-cultural anthropology, and epidemiology. Their collaborative research sought to provide sociobiological explanations for the historical emergence, persistence, and spread of non-therapeutic male genital modification across diverse human societies.

In their published work, Immerman and Mackey proposed theoretical models suggesting that circumcision historically served specific evolutionary and socio-structural functions. They hypothesized that the practice acted as a cultural mechanism to mitigate the transmission of sexually transmitted infections, influence male sexual behavior, increase paternity confidence, and reinforce intra-group cohesion. Their papers explored how cultural practices could co-evolve with biological pressures to shape social norms surrounding sexuality and bodily alteration.

While Immerman and Mackey approached the topic primarily from a descriptive and theoretical perspective rather than an activist one, their research became a significant reference point within broader debates on circumcision and bodily autonomy. Their bio-cultural hypotheses continue to be cited, discussed, and analyzed by scholars, intactivist theorists, and medical historians seeking to understand the historical and social motivations behind routine infant and ritual circumcision.', '', '', 'notable', 'Academic researchers known for their evolutionary and biocultural analyses regarding the historical origins and social functions of male circumcision.', 0, '[{"name": "Ronald S. Immerman", "score": 11.505, "shared_docs": 5}, {"name": "Wade C. Mackey", "score": 11.282, "shared_docs": 5}, {"name": "Case Western Reserve University", "score": 10.768, "shared_docs": 3}, {"name": "Abraham", "score": 9.446, "shared_docs": 2}]');
