INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-09352e40', 'person', 'Daniel Halperin', 'Daniel Halperin is an epidemiologist and medical anthropologist recognized for his extensive work in global HIV prevention and public health policy. He has held academic and advisory positions at institutions such as the Harvard T.H. Chan School of Public Health, the University of North Carolina at Chapel Hill, and the United States Agency for International Development (USAID). His research has focused primarily on infectious disease epidemiology, sexual behavior patterns, and structural interventions to curb HIV transmission in Sub-Saharan Africa.

Within the discourse surrounding circumcision, Halperin emerged as a leading academic proponent of voluntary medical male circumcision (VMMC) as an HIV prevention strategy. Beginning in the late 1990s and 2000s, he co-authored several influential observational studies, reviews, and opinion pieces in major scientific journals advocating for the expansion of male circumcision programs in high-prevalence regions, arguing that the procedure significantly reduces heterosexually acquired HIV infection in men.

Halperin''s scientific publications and public advocacy played a pivotal role in shaping international public health policies, including recommendations by the World Health Organization and UNAIDS. Because his work provided key empirical justifications for large-scale circumcision initiatives, it has been a frequent subject of analysis and critique by bodily autonomy advocates and intactivist scholars, who challenge the methodological frameworks, ethical considerations, and policy implications of public health circumcision campaigns.', '', '', 'critic', 'An epidemiologist and public health researcher known for advocating male circumcision as a primary HIV prevention strategy.', 0, '[{"name": "Harvard School of Public Health", "score": 11.516, "shared_docs": 3}, {"name": "Robert Bailey", "score": 10.931, "shared_docs": 2}, {"name": "Joint United Nations Programme on HIV/AIDS (UNAIDS)", "score": 10.379, "shared_docs": 3}, {"name": "Bill & Melinda Gates Foundation", "score": 10.253, "shared_docs": 3}, {"name": "London School of Hygiene and Tropical Medicine", "score": 10.083, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e3584454', 'person', 'Fran P. Hosken', 'Franziska Porges Hosken (1919–2006) was an Austrian-born American author, publisher, and feminist activist whose pioneering work brought global attention to female genital cutting and bodily autonomy. Educated at Smith College and the Harvard Graduate School of Design, Hosken initially worked in urban design and journalism before redirecting her focus to international women''s rights and health during the 1970s.

In 1975, Hosken founded the Women''s International Network News (WIN News), an independent quarterly journal that served as a critical platform for reporting on women''s health and human rights worldwide. Through WIN News and extensive field research, Hosken became one of the first researchers to systematically document female genital mutilation (FGM). Her landmark 1979 publication, "The Hosken Report: Genital and Sexual Mutilation of Females," systematically detailed the health consequences and socio-cultural dimensions of these practices, firmly framing non-consensual genital alterations as violations of human rights.

Hosken''s relentless campaigning challenged international health organizations, including the World Health Organization, to acknowledge and take action against FGM. Her conceptualization of genital integrity as a fundamental human right provided foundational discourse that continues to influence modern bodily autonomy movements and intactivist scholarship.', '', '', 'champion', 'Feminist author, activist, and publisher who pioneered the international campaign against female genital mutilation and advocated for global genital autonomy.', 1, '[{"name": "Women''s International Network", "score": 10.768, "shared_docs": 3}, {"name": "Gerald A. Larue", "score": 10.353, "shared_docs": 3}, {"name": "Somali Women''s Democratic Organization (SWDO)", "score": 10.183, "shared_docs": 2}, {"name": "WIN NEWS", "score": 10.183, "shared_docs": 2}, {"name": "American College of Nurse-Midwives (ACNM)", "score": 9.768, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-16170045', 'organization', 'Uppsala University', 'Founded in 1477, Uppsala University is the oldest university in Sweden and one of Scandinavia''s premier research institutions. Across its faculties of medicine, law, and social sciences, the university has fostered an environment for interdisciplinary scholarship concerning public health, medical ethics, and international human rights frameworks.

In the context of bodily autonomy and genital integrity, researchers affiliated with Uppsala University have contributed to bioethical, legal, and sociological discussions surrounding both male circumcision and female genital cutting. Scholars at the institution have examined non-therapeutic pediatric procedures through the frameworks of children''s rights, consent, and bodily integrity, often reflecting broader Nordic legal perspectives that emphasize individual autonomy and child welfare.

While Uppsala University itself remains an academic institution without institutional advocacy positions, its academic output has provided empirical and theoretical context used by ethicists, policymakers, and activists engaged in global debates over genital autonomy and bodily integrity.', '', '', 'notable', 'A historic Swedish research university whose scholars have contributed significant bioethical and legal research to discussions on bodily autonomy and children''s rights.', 0, '[{"name": "Anna Wahlberg", "score": 11.668, "shared_docs": 2}, {"name": "Birgitta Ess\u00e9n", "score": 11.083, "shared_docs": 4}, {"name": "Malm\u00f6 University", "score": 11.083, "shared_docs": 4}, {"name": "Sara Johnsdotter", "score": 9.73, "shared_docs": 4}, {"name": "UNICEF", "score": 7.638, "shared_docs": 2}]');
