INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-675bda99', 'person', 'Steven Svoboda', 'Steven Svoboda is an American human rights attorney and legal scholar best known for his foundational role in advancing the legal dimensions of the intactivist movement. Educated at the University of California, Berkeley and Harvard Law School, Svoboda established Attorneys for the Rights of the Child (ARC) in 1997. ARC emerged as a leading non-profit organization dedicated to securing legal protections against non-consensual genital alterations for minors, encompassing male infant circumcision as well as medically unnecessary intersex surgeries.

Throughout his career, Svoboda framed non-consensual circumcision as a fundamental violation of human rights and bodily integrity. His legal analysis frequently emphasized constitutional arguments regarding equal protection, privacy, and physical autonomy, challenging the legal inconsistency of protecting females from genital cutting while leaving males and intersex infants unprotected. Through ARC, he provided legal counsel, authored amicus curiae briefs, and engaged with medical associations and governmental bodies to advocate for legal reform.

In addition to his organizational leadership, Svoboda contributed extensively to academic and legal literature, publishing numerous articles and book chapters on the legal, ethical, and human rights aspects of circumcision. He has been a prominent speaker at international symposia on bodily autonomy and sexual integrity, bridging professional legal analysis with grassroots advocacy to challenge the social and institutional acceptance of infant male circumcision.', '', '', 'champion', 'Human rights attorney and founder of Attorneys for the Rights of the Child (ARC), pioneering legal advocacy for genital autonomy.', 0, '[{"name": "National Coalition of Free Men (NCFM)", "score": 9.668, "shared_docs": 2}, {"name": "Ronald Goldman", "score": 8.209, "shared_docs": 2}]');
