INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-585b09d1', 'organization', 'Royal College of Obstetricians and Gynaecologists', 'Founded in 1929, the Royal College of Obstetricians and Gynaecologists (RCOG) is a major professional medical association based in the United Kingdom dedicated to setting clinical standards, supporting specialist training, and advancing healthcare in obstetrics and gynaecology globally. As an authoritative institutional body, RCOG produces clinical guidelines and policy statements that inform ethical medical practice, patient consent standards, and safeguarding protocols across reproductive and maternal healthcare.

Within the discourse on bodily autonomy and non-therapeutic surgical procedures, the RCOG has been particularly prominent in the global movement to eradicate Female Genital Mutilation (FGM). The college actively provides educational resources and clinical guidelines to help healthcare professionals identify, treat, and safeguard girls and women affected by or at risk of FGM, framing the practice strictly as a human rights violation and a breach of bodily integrity.

While its primary clinical remit centers on female reproductive health, the RCOG''s broader policy statements and joint publications with other UK medical institutions reinforce the principle that non-therapeutic surgical interventions require robust ethical justification and informed consent. Through its advocacy against forced interventions and its emphasis on evidence-based medicine, the organization remains a key reference point in debates surrounding bodily autonomy, safeguarding, and medical ethics.', '', '', 'notable', 'A leading UK professional medical association that establishes clinical standards, opposes female genital mutilation, and informs healthcare policy on reproductive ethics.', 0, '[{"name": "UNICEF", "score": 7.96, "shared_docs": 3}, {"name": "World Health Organization", "score": 6.99, "shared_docs": 6}]');
