INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-707d6979', 'person', 'Marilyn F. Milos', 'Marilyn Fay Milos is an American registered nurse and activist recognized as one of the foundational leaders of the modern intactivist movement. Her path toward advocacy began during her clinical training as a nursing student in the late 1970s, where observing routine neonatal circumcisions prompted her to question the medical necessity, ethics, and pain management associated with the procedure. Recognizing a significant gap in public and professional awareness regarding intact genital anatomy and informed consent, she began collecting research and organizing educational materials to inform parents and medical staff.

In 1985, Milos co-founded the National Organization of Circumcision Information Resource Centers (NOCIRC), the first national non-profit organization in the United States dedicated to securing genital autonomy for infants and children. Under her leadership as executive director, NOCIRC published educational literature, coordinated network centers worldwide, and hosted international symposia on sexual integrity and bioethics. Through these initiatives, Milos played a key role in reframing non-therapeutic infant circumcision as a human rights issue and a violation of bodily integrity.

Over several decades of advocacy, Milos authored numerous articles, testified before policy-making bodies, and collaborated with medical, legal, and human rights scholars globally. Her work challenged prevailing medical practices, raised public awareness regarding the function of the prepuce, and provided structural inspiration for subsequent generations of bodily autonomy advocates and organizations.', '', '', 'champion', 'Founder of NOCIRC and pioneer of the international movement for infant genital autonomy.', 0, '[{"name": "Norma Wilcox", "score": 10.99, "shared_docs": 2}, {"name": "Mark D. Reiss", "score": 10.405, "shared_docs": 2}, {"name": "James L. Snyder", "score": 9.405, "shared_docs": 2}, {"name": "Robert S. Van Howe", "score": 7.436, "shared_docs": 2}, {"name": "National Organization of Circumcision Information Resource Centers (NOCIRC)", "score": 6.425, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-83a2f3ee', 'person', 'John Erickson', 'John Erickson is an American legal advocate and activist recognized for his contributions to the movement for bodily autonomy and genital integrity. With a background in legal analysis and human rights advocacy, Erickson focused much of his work on challenging the legal and ethical standards surrounding routine neonatal circumcision in the United States. His writings and public advocacy emphasized the constitutional and human rights frameworks protecting minors from non-therapeutic bodily modifications.', '', '', 'champion', 'Legal advocate and activist dedicated to advancing legal protections for children''s bodily integrity and opposing involuntary infant circumcision.', 1, '[{"name": "National Organization of Circumcision Information Centers", "score": 10.668, "shared_docs": 2}, {"name": "Aaron Fink", "score": 10.253, "shared_docs": 3}, {"name": "Mahatma Gandhi", "score": 9.931, "shared_docs": 2}, {"name": "Eugene Robin", "score": 9.446, "shared_docs": 2}, {"name": "John Taylor", "score": 8.931, "shared_docs": 2}]');
