INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f86ab593', 'organization', 'Harvard School of Public Health', 'The Harvard School of Public Health (officially renamed the Harvard T.H. Chan School of Public Health in 2014) is a prominent graduate professional school of Harvard University located in Boston, Massachusetts. Established in 1913 as the School for Health Officers, it has long been a leading institution for epidemiological research, global health policy, and medical education. Its faculty and affiliated researchers have conducted extensive work across diverse areas of epidemiology, global health interventions, and biostatistics.

Within the discourse surrounding male circumcision, research published by faculty and affiliates of the Harvard School of Public Health has frequently intersected with public health policy debates. The institution''s researchers have contributed significantly to epidemiological literature analyzing public health interventions, particularly concerning HIV transmission reduction and disease prevention strategies in Sub-Saharan Africa. These studies have frequently served as foundational evidence in international global health guidelines promulgated by organizations such as the World Health Organization and UNAIDS.

Because of its authoritative status in global health research, studies originating from or affiliated with the school are widely cited across public health, ethics, and activist spheres. Medical institutions frequently draw on its published data to evaluate the clinical efficacy of public health measures, while advocates for genital autonomy and intactivists often examine and critique these findings regarding methodology, ethical frameworks, and the balance between population-level public health strategies and individual bodily rights.', '', '', 'notable', 'A leading public health research institution whose epidemiological studies have significantly influenced global public health policy and debates surrounding medical circumcision.', 0, '[{"name": "Daniel Halperin", "score": 11.516, "shared_docs": 3}, {"name": "Joint United Nations Programme on HIV/AIDS (UNAIDS)", "score": 9.794, "shared_docs": 2}, {"name": "Bill & Melinda Gates Foundation", "score": 9.668, "shared_docs": 2}, {"name": "National Institutes of Health", "score": 8.609, "shared_docs": 2}, {"name": "World Health Organization", "score": 6.668, "shared_docs": 4}]');
