INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-b8825571', 'organization', 'University of Victoria', 'The University of Victoria is a public research university located in Greater Victoria, British Columbia, Canada. Established as Victoria College in 1903 and gaining full university status in 1963, the institution has developed a reputation for rigorous academic scholarship across law, social sciences, humanities, and health studies. Its academic faculties regularly produce research examining human rights, medical ethics, and bodily integrity.

Within the broader discourse on circumcision and bodily autonomy, the University of Victoria serves as an academic venue where legal, bioethical, and sociological inquiries take place. Scholars associated with Canadian academic institutions like the University of Victoria contribute to debates surrounding children''s rights, informed consent, and the legal frameworks governing non-therapeutic interventions on minors, reflecting broader shifts in Canadian policy and legal scholarship.', '', '', 'notable', 'A prominent Canadian research university serving as a forum for academic inquiry into legal ethics, human rights, and bodily autonomy.', 0, '[{"name": "Canadian Paediatric Society", "score": 6.99, "shared_docs": 2}, {"name": "American Medical Association", "score": 6.686, "shared_docs": 2}]');
