INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e4dcb154', 'person', 'James DeMeo', 'James DeMeo (1949–2022) was an American geographer, researcher, and author known for his work in orgone biophysics and cross-cultural geography. He earned his Ph.D. in geography from the University of Kansas, where he initiated large-scale spatial analyses of human social behaviors, violence, and child-rearing practices across global cultures. DeMeo founded the Orgone Biophysical Research Lab in Oregon, dedicated to exploring and preserving the scientific theories of psychoanalyst Wilhelm Reich.

Within the discourse on genital autonomy, DeMeo gained prominence through his 1998 study *Saharasia: The 4000 BCE Earth-Change Since When Tier-1 Body-Armoring Has Caused Patriarchy, Violence, and War*. In his research, he mapped the global distribution of extreme patriarchal practices, including male and female infant genital cutting. DeMeo argued that circumcision originated in the hyper-arid regions of North Africa and the Middle East following severe climate change, serving as a primary mechanism for inflicting emotional armoring and perpetuating authoritarian, anti-sexual social structures.

Throughout his career, DeMeo remained a fierce opponent of all forms of non-consensual genital cutting. He argued that routine infant circumcision causes neurological trauma, disrupts early mother-infant bonding, and permanently impairs emotional and sexual responsiveness. His cross-cultural and historical framework provided intactivist scholars with a unique interdisciplinary argument linking early bodily trauma to broader societal violence.', '', '', 'champion', 'Geographer and author whose Saharasia hypothesis framed infant circumcision as a primary cause of psychological armoring and societal violence.', 1, '[{"name": "Gerald A. Larue", "score": 9.668, "shared_docs": 4}, {"name": "University of Kansas", "score": 9.668, "shared_docs": 3}, {"name": "J. David Bigelow", "score": 9.083, "shared_docs": 2}, {"name": "National Organization of Circumcision Information Centers", "score": 9.083, "shared_docs": 2}, {"name": "Roger Saquet", "score": 9.083, "shared_docs": 2}]');
