INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-045e714a', 'person', 'Donna Macris', 'Donna Macris is a prominent advocate within the international genital autonomy movement, best known for her leadership and educational outreach in campaigning against non-therapeutic infant circumcision. Operating primarily within advocacy networks such as the National Organization of Circumcision Information Resource Centers (NOCIRC), Macris has spent years raising awareness about the ethical, legal, and physiological implications of male neonatal circumcision.

Throughout her activism, Macris has focused on providing evidence-based resources to expectant parents, healthcare professionals, and policymakers. Her work emphasizes the principles of bodily integrity, informed consent, and human rights, arguing that bodily autonomy should extend equally to all children regardless of gender. Through participation in regional campaigns, public education, and support networks, she has contributed significantly to shifting public perception and medical discourse around routine infant circumcision.', '', '', 'champion', 'A dedicated advocate for children''s rights and prominent coordinator within the genital autonomy movement.', 1, '[{"name": "J. David Bigelow", "score": 10.405, "shared_docs": 2}, {"name": "Jacob Oster", "score": 10.405, "shared_docs": 2}, {"name": "University of Southern California", "score": 10.405, "shared_docs": 2}, {"name": "International Symposia on Circumcision", "score": 10.405, "shared_docs": 4}, {"name": "American College of Nurse-Midwives (ACNM)", "score": 9.99, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-494e8c80', 'person', 'Eugene Robin', 'Eugene D. Robin, M.D. (1919–2000), was a distinguished professor of medicine and physiology at Stanford University School of Medicine. Renowned for his critical approach to medical practice and public health policy, Robin spent much of his career evaluating medical procedures through the lens of rigorous scientific evidence and patient safety. He frequently challenged established medical norms that lacked empirical justification, advocating against over-treatment and unproven interventions.

Within the discourse on circumcision and bodily autonomy, Dr. Robin was a prominent early medical critic of routine neonatal circumcision. Through scholarly publications and medical commentary, he analyzed the clinical arguments surrounding the procedure, arguing that routine infant circumcision lacked strong evidence of medical necessity and exposed non-consenting infants to unnecessary surgical risks. His critiques emphasized the importance of ethical medical practice and informed decision-making.

Robin''s work provided valuable clinical authority to the growing opposition against routine infant circumcision in the late 20th century. By applying strict epidemiological and ethical standards to pediatric surgical practices, he contributed significantly to the academic groundwork supporting infant bodily integrity and the movement toward reducing non-therapeutic surgical interventions.', '', '', 'champion', 'Stanford professor of medicine and medical critic who challenged the clinical necessity and ethical basis of routine infant circumcision.', 0, '[{"name": "Stanford University Medical School", "score": 11.768, "shared_docs": 3}, {"name": "Leonard J. Marino", "score": 11.353, "shared_docs": 3}, {"name": "Aaron Fink", "score": 10.768, "shared_docs": 3}, {"name": "Sydney Gellis", "score": 10.446, "shared_docs": 2}, {"name": "C. Everett Koop", "score": 10.183, "shared_docs": 2}]');
