INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-fa696ffb', 'person', 'Sydney Gellis', 'Dr. Sydney S. Gellis (1914–2002) was a prominent American pediatrician, professor, and long-time editor of the Year Book of Pediatrics. Serving as chairman of pediatrics at Tufts University School of Medicine and Beth Israel Hospital in Boston, Gellis was widely recognized as one of the most influential authorities in pediatric medicine during the mid-to-late twentieth century.

Throughout his career, Gellis used his editorial platform to critically evaluate standard pediatric interventions, most notably routine neonatal circumcision. He consistently challenged the medical necessity of the procedure, highlighting the lack of robust scientific evidence supporting routine infant surgery and raising concerns about unnecessary pain and surgical risks. His outspoken commentaries in medical journals encouraged physicians to re-examine long-held assumptions regarding non-therapeutic circumcisions.

Gellis''s academic critiques provided early medical foundation for the growing intactivist movement and contributed to a broader shift in policy among major pediatric organizations. By advocating against routine infant circumcision from a position of high medical authority, he played a key role in raising awareness around pediatric ethics, bodily integrity, and informed consent.', '', '', 'champion', 'Prominent American pediatrician and medical journal editor who challenged routine neonatal circumcision in medical literature.', 0, '[{"name": "Leonard Marino", "score": 11.668, "shared_docs": 2}, {"name": "Eugene Robin", "score": 10.446, "shared_docs": 2}, {"name": "James Snyder", "score": 9.668, "shared_docs": 2}, {"name": "James DeMeo", "score": 8.346, "shared_docs": 2}, {"name": "Marilyn Fayre Milos", "score": 7.609, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f9783472', 'person', 'Rima Laibow', 'Rima E. Laibow, MD, is an American physician and psychiatrist recognized for her advocacy in medical sovereignty, alternative medicine, and individual bodily autonomy. After graduating from the Albert Einstein College of Medicine in 1970, she spent decades practicing drugless psychiatry and integrative medicine, focusing on holistic health paradigms and medical ethics.', '', '', 'champion', 'Physician and health freedom advocate who frames opposition to routine infant circumcision within broader principles of bodily integrity and medical consent.', 0, '[{"name": "J. David Bigelow", "score": 11.183, "shared_docs": 2}, {"name": "Gerald A. Larue", "score": 10.768, "shared_docs": 2}, {"name": "Moshe Rothenberg", "score": 10.768, "shared_docs": 2}, {"name": "William Cameron", "score": 10.353, "shared_docs": 3}, {"name": "Frederick Leboyer", "score": 10.183, "shared_docs": 4}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-191e7a77', 'person', 'William Cameron', 'Dr. D. William Cameron is a Canadian physician and infectious disease specialist whose clinical research significantly influenced global medical perspectives on male circumcision. In the late 1980s, while conducting epidemiological field research in Nairobi, Kenya, Cameron served as a lead author on landmark observational studies investigating risk factors for heterosexual female-to-male HIV-1 transmission.

Cameron''s 1989 study, published in The Lancet, reported a significant statistical association between the uncircumcised status of men and an increased risk of acquiring HIV. This findings established one of the earliest primary medical frameworks connecting foreskin tissue with heightened susceptibility to viral pathogens, laying the groundwork for subsequent randomized controlled trials and global health initiatives promoting voluntary medical male circumcision (VMMC) in Sub-Saharan Africa.

Within the broader discourse on bodily autonomy and intactivism, Cameron''s work represents a major milestone in the medicalization of circumcision as a preventive health intervention. While cited extensively by public health agencies to justify surgical HIV-prevention programs, his research has drawn scrutiny from genital autonomy advocates and critical bioethicists who question the methodological interpretations, long-term efficacy claims, and human rights implications of promoting surgical modification for disease prevention.', '', '', 'critic', 'Canadian infectious disease researcher whose early epidemiological studies linked male circumcision with reduced HIV transmission risk.', 1, '[{"name": "Rima Laibow", "score": 10.353, "shared_docs": 3}, {"name": "University of Manitoba", "score": 10.253, "shared_docs": 4}, {"name": "University of Ottawa", "score": 10.253, "shared_docs": 2}, {"name": "Aaron Fink", "score": 9.99, "shared_docs": 2}, {"name": "Eugene Robin", "score": 9.768, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-3114f6e1', 'person', 'Mahatma Gandhi', 'Mohandas Karamchand Gandhi (1869–1948) was an Indian lawyer, anti-colonial nationalist, and political ethicist who led the successful campaign for India''s independence from British rule through nonviolent resistance. Trained in law in London, Gandhi initially practiced in South Africa, where he developed his philosophy of Satyagraha (truth-force). Upon returning to India, he led nationwide campaigns for poverty alleviation, women''s rights, religious harmony, and self-rule, becoming an internationally recognized symbol of peace and moral authority.', '', '', 'notable', 'Indian anti-colonial leader and philosopher whose ethical framework of ahimsa (non-violence) and bodily integrity influences modern autonomy discourse.', 0, '[{"name": "National Organization of Circumcision Information Centers", "score": 11.668, "shared_docs": 2}, {"name": "Aaron Fink", "score": 10.668, "shared_docs": 2}, {"name": "John Taylor", "score": 9.931, "shared_docs": 2}, {"name": "John Erickson", "score": 9.931, "shared_docs": 2}, {"name": "James DeMeo", "score": 8.346, "shared_docs": 2}]');
