INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-6aed9b06', 'person', 'Adam London', 'Adam London is an activist and voice within the intactivist movement, dedicated to promoting bodily autonomy and ending non-therapeutic routine infant circumcision. Through public education, street activism, and community outreach, London has worked to raise awareness regarding the ethical, human rights, and bodily integrity considerations surrounding male infant circumcision.

Throughout his involvement in genital autonomy advocacy, London has engaged in public demonstrations and educational initiatives aimed at challenging prevailing cultural norms. His work emphasizes the principle that every individual possesses an inherent right to bodily integrity, arguing that decisions regarding non-essential surgical interventions on functional tissue should be reserved for the individual themselves upon reaching the age of consent.', '', '', 'champion', 'Intactivist advocate dedicated to promoting bodily autonomy and protecting children from non-therapeutic circumcision.', 1, '[{"name": "Permanente Medical Group", "score": 11.116, "shared_docs": 6}, {"name": "Marin County Superior Court", "score": 10.853, "shared_docs": 5}, {"name": "Richard W. Morris", "score": 10.701, "shared_docs": 3}, {"name": "Kelen Nelson", "score": 10.701, "shared_docs": 3}, {"name": "Alameda Superior Court", "score": 10.701, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-792128ec', 'organization', 'California Court of Appeal', 'The California Court of Appeal serves as the state''s intermediate appellate judicial body, responsible for reviewing decisions rendered by trial-level Superior Courts across California''s six appellate districts. Operating within one of the largest state court systems in the United States, the appellate court handles a wide array of civil, criminal, and family law matters, establishing legal precedents that govern medical jurisprudence, parental rights, and municipal regulations within the state.', '', '', 'notable', 'An intermediate state appellate court in California that adjudicates legal disputes concerning parental consent, custodial rights, and medical decisions involving minor circumcision.', 0, '[{"name": "Richard W. Morris", "score": 10.99, "shared_docs": 2}, {"name": "California Supreme Court", "score": 10.82, "shared_docs": 4}, {"name": "Adam London", "score": 9.531, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-abc41c3d', 'organization', 'California Supreme Court', 'The California Supreme Court is the highest judicial body in the U.S. state of California. Composed of a Chief Justice and six Associate Justices, the court holds final state authority over the interpretation of California''s constitution and statutes. Throughout its history, the court has ruled on foundational legal issues concerning individual privacy, healthcare provider liability, municipal authority, and parental consent, establishing legal precedents that frequently intersect with matters of medical ethics and bodily integrity.', '', '', 'notable', 'The highest state court in California, issuing pivotal rulings on municipal jurisdiction, medical consent, and constitutional rights.', 1, '[{"name": "United States Supreme Court", "score": 10.82, "shared_docs": 2}, {"name": "California Court of Appeal", "score": 10.82, "shared_docs": 4}, {"name": "John W. Hardebeck", "score": 10.82, "shared_docs": 2}, {"name": "Richard W. Morris", "score": 10.405, "shared_docs": 2}, {"name": "Adam London", "score": 10.268, "shared_docs": 5}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-adcecd78', 'organization', 'Permanente Medical Group', 'The Permanente Medical Group represents the physician partnership component of Kaiser Permanente, one of the largest integrated managed care consortiums in the United States. Operating primarily in California and other key regions, the medical group provides multi-specialty healthcare services, including obstetrics, pediatrics, and surgical care, to millions of enrolled members. Within the framework of American healthcare delivery, physician groups like Permanente play a central role in translating general medical guidelines into direct clinical practices and patient care protocols.

In the context of the circumcision discourse and bodily autonomy, the Permanente Medical Group is significant as an institutional practitioner and policy implementer. The organization''s regional clinical practices, informed consent protocols, and coverage policies regarding non-therapeutic infant circumcision directly affect parental decision-making and procedure rates among its vast member base. Over the years, institutional decisions by managed care providers regarding whether to cover routine neonatal circumcision or classify it as an elective, out-of-pocket procedure have served as important indicators of shifting medical and economic consensus on the procedure.

Because of its size and influence in modern managed care, the Permanente Medical Group has occasionally been a focal point for advocacy groups and medical ethicists examining consent standards, ethical delivery of elective pediatric procedures, and patient rights. Discussions surrounding the group''s policies highlight the broader intersection between institutional managed care structures, clinical practice guidelines, and advocacy efforts focused on bodily integrity and pediatric medical ethics.', '', '', 'notable', 'A major American physician group within Kaiser Permanente that influences regional clinical practices and coverage policies regarding routine infant circumcision.', 0, '[{"name": "Kelen Nelson", "score": 11.575, "shared_docs": 3}, {"name": "Alameda Superior Court", "score": 11.575, "shared_docs": 3}, {"name": "Kaiser Foundation Hospital", "score": 11.405, "shared_docs": 4}, {"name": "Marin County Superior Court", "score": 11.405, "shared_docs": 4}, {"name": "Adam London", "score": 11.116, "shared_docs": 6}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f480f80a', 'organization', 'First International Symposium on Circumcision', 'The First International Symposium on Circumcision was held in March 1989 in Anaheim, California. Organized by the National Organization of Circumcision Information Resource Centers (NOCIRC) under the leadership of Marilyn Milos, the conference represented the first major international and interdisciplinary gathering dedicated to critically examining the practice of routine infant circumcision. The event brought together medical practitioners, legal scholars, bioethicists, psychologists, and human rights activists to share research and construct a cohesive critique of involuntary genital alteration.

The symposium featured formal presentations on the anatomical functions of the foreskin, the psychological and physical trauma of neonatal surgery, the legal considerations of non-therapeutic surgery on minors, and the ethics of informed consent. By documenting and compiling scholarly research against routine circumcision, the proceedings provided a foundational body of literature that challenged long-standing medical traditions in North America and beyond.

The 1989 symposium served as a catalyst for the global intactivist movement, establishing an enduring framework for international scholarship and organized advocacy. It inaugurated a long-running series of international symposia on sexual medicine, human rights, and bodily integrity, which continued to influence medical policy discussions and legal debates surrounding genital autonomy for decades.', '', '', 'champion', 'A landmark 1989 conference that brought together medical professionals, scholars, and activists to challenge routine infant circumcision and establish the international intactivist movement.', 1, '[{"name": "Mohamed Badawi", "score": 10.668, "shared_docs": 2}, {"name": "Richard W. Morris", "score": 10.253, "shared_docs": 2}, {"name": "James W. Prescott", "score": 8.516, "shared_docs": 3}, {"name": "Marilyn Fayre Milos", "score": 7.194, "shared_docs": 3}, {"name": "United Nations", "score": 6.379, "shared_docs": 3}]');
