INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-11fc6ffb', 'person', 'James W. Prescott', 'James W. Prescott, Ph.D., is an American developmental psychologist and neuroscientist who formerly served as a Health Scientist Administrator at the National Institute of Child Health and Human Development (NICHD), a division of the National Institutes of Health (NIH). His early scientific career centered on developmental neurobiology, with a particular focus on somatosensory affectional deprivation (SAD) and its role in the development of emotional health, violent behavior, and social bonding.

Applying his neurodevelopmental theories to cultural practices, Prescott became a prominent scientific opponent of routine infant male circumcision. He argued that the intense pain and stress caused by neonatal genital cutting act as a profound traumatic disruption to early neural development, sensory integration, and maternal-infant bonding. According to his research, early painful bodily trauma can impair the brain''s capacity for empathy, affection, and peaceful social relationships later in life.

Throughout his involvement in the intactivist movement, Prescott has written extensively and lectured at conferences advocating for the bodily integrity of infants. By framing genital autonomy through the lens of developmental neuroscience and trauma, his work has provided critical theoretical and scientific support to human rights organizations seeking to end non-consensual infant circumcision.', '', '', 'champion', 'American developmental psychologist and neuroscientist who critiques infant circumcision through the lens of somatosensory trauma and affectional deprivation.', 1, '[{"name": "Sacred Congregation for the Doctrine of the Faith", "score": 9.668, "shared_docs": 2}, {"name": "National League for Separation of Church and State", "score": 9.668, "shared_docs": 2}, {"name": "Walt Whitman", "score": 9.668, "shared_docs": 2}, {"name": "The Truth Seeker", "score": 9.516, "shared_docs": 3}, {"name": "David M. Levy", "score": 9.253, "shared_docs": 2}]');
