INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e2ae3df8', 'person', 'Elizabeth Noble', 'Elizabeth Noble was an Australian-born physical therapist, author, and educator who played a pioneering role in obstetrical physical therapy and humanized childbirth education. In 1977, she founded the Section on Women''s Health of the American Physical Therapy Association (APTA). She authored numerous seminal books on maternal health, exercise, and childbirth, advocating for natural birth practices and the protection of maternal-infant bonding.

Beyond her foundational work in physical therapy, Noble extended her advocacy for infant welfare into the discourse surrounding neonatal circumcision. She criticized routine male infant circumcision as a painful, traumatic, and medically unnecessary surgical procedure that violates bodily integrity and disrupts early parent-child attachment. Her perspective integrated physical health, emotional development, and ethical considerations regarding non-consensual bodily alterations.

Throughout her career, Noble lectured internationally and framed genital autonomy within a broader framework of gentle birth and respectful infant care. Her writings and public statements contributed to early intactivist literature, positioning her as an influential voice against routine infant circumcision within the humanized birth and childbearing advocacy movements.', '', '', 'champion', 'Physical therapist, author, and childbirth educator who advocated for maternal-infant bonding and infant bodily integrity.', 1, '[{"name": "Roger Saquet", "score": 11.575, "shared_docs": 3}, {"name": "William Sullivan", "score": 11.575, "shared_docs": 3}, {"name": "Vicki MacLean", "score": 11.575, "shared_docs": 3}, {"name": "Charles Konia", "score": 11.575, "shared_docs": 3}, {"name": "Myron Sharaf", "score": 11.575, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-47c1ccae', 'person', 'Steve Scott', 'Steve Scott is a prominent activist within the international intactivist movement, best known for his advocacy work in the United Kingdom and globally regarding bodily integrity and human rights. Recognizing the lack of public discussion surrounding non-therapeutic infant circumcision, Scott engaged in public education and grassroots campaigning to raise awareness about the physical and psychological impacts of early non-consensual genital procedures.', '', '', 'champion', 'British intactivist advocate and co-founder of NOCIRC UK, dedicated to promoting bodily autonomy and child rights.', 0, '[{"name": "David Llewellyn", "score": 11.405, "shared_docs": 2}, {"name": "Kristen O''Hara", "score": 11.405, "shared_docs": 2}, {"name": "Morris Sorrells", "score": 10.99, "shared_docs": 2}, {"name": "Van Lewis", "score": 10.668, "shared_docs": 2}, {"name": "Mary Conant", "score": 10.575, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-ae49b99d', 'person', 'James L. Snyder', 'James L. Snyder is a commentator and contributor to the discourse surrounding bodily autonomy, children''s rights, and non-therapeutic neonatal circumcision. Within the archive, his work addresses the ethical, legal, and social dimensions of routine infant circumcision, critically examining the medicalization of the procedure and the historical factors that contributed to its widespread adoption in Western societies.

Snyder''s writings emphasize the importance of bodily integrity and informed consent, framing non-consensual genital alterations of minors as a violation of fundamental human rights. Through educational outreach, essays, and archival contributions, he has sought to challenge established medical norms and promote greater awareness regarding the psychological and physical implications of infant circumcision.

His contributions remain part of the broader sociological and ethical documentation of the intactivist movement, serving as a resource for researchers, bioethicists, and advocates examining the evolution of genital autonomy movements.', '', '', 'champion', 'An advocate and writer focused on bodily autonomy, children''s rights, and the ethics of infant circumcision.', 1, '[{"name": "Kris Teplin", "score": 10.99, "shared_docs": 3}, {"name": "American College of Surgeons", "score": 9.99, "shared_docs": 3}, {"name": "Norma Wilcox", "score": 9.99, "shared_docs": 2}, {"name": "Mark D. Reiss", "score": 9.405, "shared_docs": 2}, {"name": "Marilyn F. Milos", "score": 9.405, "shared_docs": 2}]');
