INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f3d6c993', 'person', 'Robert S Van Howe', 'Dr. Robert S. Van Howe is an American pediatrician, epidemiologist, and medical researcher who became a prominent scientific voice in the debate surrounding routine male infant circumcision. Holding an M.D. and a Master of Science in Epidemiology, Van Howe dedicated much of his professional research to examining the clinical data, methodologies, and ethical considerations surrounding neonatal genital cutting.', '', '', 'champion', 'Pediatrician and researcher known for extensive epidemiological studies opposing routine infant circumcision.', 0, '[{"name": "J Steven Svoboda", "score": 11.838, "shared_docs": 3}, {"name": "Michigan State University College of Human Medicine", "score": 10.253, "shared_docs": 2}, {"name": "Attorneys for the Rights of the Child", "score": 8.931, "shared_docs": 3}, {"name": "American Medical Association", "score": 6.949, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 5.303, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-650f6d28', 'person', 'Tina Kimmel', 'Tina Kimmel, PhD, MSW, MPH, is an American public health researcher, social worker, and advocate known for her contributions to child welfare and genital autonomy movement. Holding advanced degrees in public health and social welfare, Kimmel has spent decades working in health research, policy evaluation, and epidemiology, using her professional background to critically evaluate the practice of non-therapeutic infant circumcision.', '', '', 'champion', 'Public health scholar and advocate for infant bodily autonomy and child welfare.', 0, '[{"name": "United Nations Economic and Social Council", "score": 11.668, "shared_docs": 2}, {"name": "Morris Sorrells", "score": 11.253, "shared_docs": 2}, {"name": "Amber Craig", "score": 10.083, "shared_docs": 2}, {"name": "Paul Fleiss", "score": 8.931, "shared_docs": 2}, {"name": "Jim Bigelow", "score": 7.931, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-2e6376bd', 'person', 'Charles Bonner', 'Charles Bonner is an American civil rights attorney known for his legal representation in high-profile cases involving constitutional rights, equal protection, and bodily autonomy. Based in California, Bonner established a distinguished career specializing in civil rights litigation, human rights, and environmental justice prior to his prominent legal work within the intactivist movement.', '', '', 'champion', 'Civil rights attorney who provided vital legal representation in defense of genital autonomy initiatives.', 1, '[{"name": "J. David Bigelow", "score": 10.531, "shared_docs": 2}, {"name": "David Llewellyn", "score": 10.531, "shared_docs": 2}, {"name": "Zenas Baer", "score": 10.531, "shared_docs": 2}, {"name": "Gerald A. Larue", "score": 10.116, "shared_docs": 2}, {"name": "Moshe Rothenberg", "score": 10.116, "shared_docs": 2}]');
