INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-0ed342cf', 'person', 'FileMaker, Inc.', 'FileMaker, Inc., originally known as Claris Corporation and later rebranded as Claris International Inc., is a software company known for developing the relational database application FileMaker Pro. Released in the 1980s, FileMaker Pro became a widely used tool among non-profit organizations, research archives, and independent advocacy groups due to its accessible graphical interface and flexible data management capabilities.

Within the history of the intactivist and bodily autonomy movements, software developed by FileMaker, Inc. served as an operational foundation for several pioneer organizations and registries. During the 1990s and 2000s, grassroots groups and medical research clearinghouses utilized FileMaker databases to catalog clinical literature, manage donor and advocate rosters, track media outreach, and maintain records related to genital integrity initiatives.

Appearing in archival documentation primarily through software metadata, licensing records, and database export files, FileMaker, Inc. represents the technological infrastructure that enabled early intactivist organizations to digitize their administrative operations. While the company maintained a neutral corporate posture, its database solutions were instrumental in organizing data and preserving historical records for the movement.', '', '', 'notable', 'Software company whose database management applications provided essential administrative infrastructure for early intactivist organizations and archives.', 1, '');
