INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-c28a7626', 'organization', 'Northeastern University', 'Northeastern University is a private research university located in Boston, Massachusetts. Founded in 1898, the institution is widely recognized for its cooperative education program, which integrates classroom study with professional practice, as well as its robust research activity across health sciences, law, ethics, and social sciences.

Within the sociological archive of bodily autonomy and circumcision debates, Northeastern University serves as a notable institutional hub for academic inquiry, legal scholarship, and bioethical research. Faculty members and affiliated researchers at the university have engaged with issues surrounding consent, bodily integrity, children''s rights, and medical ethics, contributing published work and legal commentary that informs broader discussions on routine non-therapeutic procedures.

While the university as an organization maintains a neutral academic stance, its legal and sociological departments have provided a platform for rigorous analysis regarding the ethical boundaries of parental consent and state regulation over physical integrity. Through academic forums, publications, and interdisciplinary studies, Northeastern University has contributed to the intellectual framework surrounding bodily autonomy discourse.', '', '', 'notable', 'A major research university in Boston whose academic and legal scholars have contributed to research on bioethics, consent, and bodily autonomy.', 0, '[{"name": "Richard G. Wamai", "score": 11.668, "shared_docs": 2}, {"name": "VA Puget Sound Health Care System", "score": 11.253, "shared_docs": 2}, {"name": "University of Sydney", "score": 9.875, "shared_docs": 5}, {"name": "John N. Krieger", "score": 9.668, "shared_docs": 2}, {"name": "Brian J. Morris", "score": 8.751, "shared_docs": 3}]');
