INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-60df9254', 'organization', 'Michigan State University Libraries', 'The Michigan State University Libraries system serves as the primary academic library and archival repository for Michigan State University in East Lansing, Michigan. As a major research institution, the library system maintains extensive collections spanning diverse academic disciplines, including medical history, sociology, bioethics, and social movement literature. Its special collections and archives play a vital role in preserving primary source materials for scholarly research and public inquiry.

In the context of bodily autonomy and intactivism, Michigan State University Libraries provides access to key historical and contemporary records detailing the debate surrounding infant circumcision, human rights, and medical ethics. By cataloging and housing organizational publications, activist newsletters, and personal papers related to genital autonomy movements, the libraries serve as an important institutional home for materials documenting the history of intactivism and medical reform.

Through its commitment to preservation and academic access, the library system ensures that historical documents addressing circumcision practices, legal arguments, and ethical considerations remain available to researchers, legal scholars, and medical historians. Its holdings contribute significantly to the preservation of the institutional memory surrounding bodily integrity advocacy within American social history.', '', '', 'notable', 'An academic library and archival repository preserving historical collections and research materials related to medical history, social movements, and bodily autonomy advocacy.', 0, '[{"name": "Ed Barton", "score": 10.99, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f08b789f', 'person', 'P. R. Hickey', 'P. R. Hickey is a medical researcher and anesthesiologist best known for co-authoring groundbreaking clinical studies regarding pain perception in fetuses and newborn infants. In 1987, alongside K. J. S. Anand, Hickey published a seminal review in The New England Journal of Medicine titled "Pain and Its Effects in the Human Fetus and Neonate." This research directly challenged long-standing medical assumptions that neonates lacked the neuroanatomical development required to experience acute pain, demonstrating instead that unanesthetized infants experience severe physiological and hormonal stress during surgical procedures.

His research had a profound impact on the medical and ethical discourse surrounding routine neonatal male circumcision. By providing empirical evidence of the physiological trauma associated with unmedicated infant surgery, Hickey''s work prompted widespread reevaluations of clinical guidelines, eventually leading professional medical associations to mandate or strongly recommend the use of local anesthesia during circumcision procedures.

Within the broader framework of bodily autonomy and intactivism, Hickey''s findings became central reference points for advocates seeking to highlight the physical harms and sensory trauma of non-therapeutic infant surgeries. Although his contributions were rooted in clinical research and pediatric anesthesia rather than socio-political activism, his scientific legacy remains foundational to arguments against non-consensual genital alterations on infants.', '', '', 'notable', 'Medical researcher and co-author of landmark studies on neonatal pain that transformed clinical practices surrounding infant circumcision.', 0, '[{"name": "K. J. S. Anand", "score": 11.405, "shared_docs": 7}, {"name": "Frederick Leboyer", "score": 9.768, "shared_docs": 3}, {"name": "Benjamin Spock", "score": 8.013, "shared_docs": 2}, {"name": "Rosemary Romberg", "score": 8.013, "shared_docs": 2}, {"name": "Edward Wallerstein", "score": 7.04, "shared_docs": 2}]');
