INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-344b1232', 'person', 'James Prescott', 'James W. Prescott is an American developmental psychologist and neuroscientist known for his research on somatosensory affectional deprivation and the neurobiology of violence and affection. During his tenure as a health scientist administrator at the National Institute of Child Health and Human Development (NICHD), Prescott conducted foundational work investigating how early physical contact, bonding, and sensory experiences shape human brain development and social behavior.

Applying his developmental theories to the issue of infant circumcision, Prescott became a prominent scientific critic of the practice. He argued that the intense pain and trauma inflicted by neonatal circumcision constitute a severe form of sensory deprivation and trauma, which can disrupt critical early mother-infant bonding processes and potentially alter neurodevelopmental pathways related to affection, trust, and emotional regulation.

Prescott frequently contributed to intactivist literature, educational conferences, and advocacy organizations, framing routine neonatal circumcision as an infringement on children''s human rights and bodily integrity. His scientific arguments provided the intactivist movement with a neurobiological rationale for opposing infant genital cutting.', '', '', 'champion', 'American neuroscientist and developmental psychologist who authored neurodevelopmental critiques of infant circumcision based on somatosensory deprivation theory.', 1, '[{"name": "J. David Bigelow", "score": 10.531, "shared_docs": 2}, {"name": "Roger Saquet", "score": 10.531, "shared_docs": 2}, {"name": "William Sullivan", "score": 10.531, "shared_docs": 2}, {"name": "Vicki MacLean", "score": 10.531, "shared_docs": 2}, {"name": "Charles Konia", "score": 10.531, "shared_docs": 2}]');
