INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-530f1faf', 'person', 'Karl Menninger', 'Karl Menninger (1893–1990) was an influential American psychiatrist and co-founder of the Menninger Foundation in Topeka, Kansas. A major figure in mid-20th-century psychoanalysis and mental health reform, Menninger authored several foundational texts, including The Human Mind (1930) and Man Against Himself (1938), which explored human aggression, self-destructive behavior, and the psychological mechanisms underlying social rituals and medical practices.', '', '', 'notable', 'Influential American psychiatrist whose psychoanalytic writings critiqued the psychological and symbolic motivations behind routine circumcision.', 0, '[{"name": "Ralph Nader", "score": 11.405, "shared_docs": 2}, {"name": "Ronald F. Goldman", "score": 10.668, "shared_docs": 2}, {"name": "Circumcision Resource Center", "score": 8.742, "shared_docs": 2}, {"name": "James DeMeo", "score": 8.083, "shared_docs": 2}, {"name": "Marilyn Milos", "score": 7.235, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f75caa25', 'organization', 'California Medical Association', 'The California Medical Association (CMA) is a major professional organization founded in 1856, representing tens of thousands of physicians across the state of California. As one of the largest state medical societies in the United States, the CMA plays a central role in setting regional healthcare standards, advising legislative bodies, and shaping public health policies. Throughout its history, the organization has frequently addressed issues surrounding pediatric care, surgical necessity, and parental decision-making in clinical settings.

Within the discourse on infant male circumcision and bodily autonomy, the CMA has traditionally mirrored the positions of broader institutional medicine, such as the American Academy of Pediatrics and the American Medical Association. The organization has historically viewed non-therapeutic neonatal circumcision as an elective surgical option, emphasizing that the procedure requires informed consent from parents in consultation with qualified healthcare providers rather than routine application.

The CMA''s most visible intersection with intactivist advocacy occurred during the 2011 municipal ballot initiative campaigns in California, notably in San Francisco and Santa Monica, where activists sought to legally ban the circumcision of male minors. The CMA joined other healthcare entities in opposing municipal legislation restricting the procedure, contending that state laws and medical consensus, rather than local bans, should govern clinical decisions and parental rights.', '', '', 'notable', 'A prominent professional society representing California physicians that has influenced regional policy and opposed municipal bans on non-therapeutic infant circumcision.', 1, '[{"name": "John W. Hardebeck", "score": 9.82, "shared_docs": 2}, {"name": "Virginia Urologic Society", "score": 8.82, "shared_docs": 3}, {"name": "American College of Surgeons", "score": 8.82, "shared_docs": 2}, {"name": "California Supreme Court", "score": 8.82, "shared_docs": 3}, {"name": "Supreme Court of the United States", "score": 8.598, "shared_docs": 2}]');
