INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-24a0f3fe', 'person', 'Thomas Ritter', 'Dr. Thomas J. Ritter was an American physician, author, and prominent advocate for genital autonomy who actively challenged routine neonatal male circumcision in North America. Recognizing the need for accessible, medically grounded information for parents and the public, Ritter devoted significant efforts to educating communities on the medical, anatomical, and ethical aspects of bodily integrity.', '', '', 'champion', 'American physician and author of ''Say No to Circumcision!'', a foundational text in modern intactivist literature.', 1, '[{"name": "RECAP", "score": 9.083, "shared_docs": 2}, {"name": "American Urological Association", "score": 8.705, "shared_docs": 2}, {"name": "Jim Bigelow", "score": 8.668, "shared_docs": 6}, {"name": "California Medical Association", "score": 8.235, "shared_docs": 2}, {"name": "Ashley Montagu", "score": 8.013, "shared_docs": 2}]');
