INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-b3951ca0', 'organization', 'Birth With Dignity', 'Birth With Dignity is an advocacy organization established to promote respectful maternity care, humanized childbirth practices, and the fundamental right to bodily autonomy for newborns and birthing parents. Grounded in the principles of informed consent and holistic health, the organization provides educational resources and support networks designed to empower families during the perinatal period. Its mission centers on reducing unnecessary medical interventions and ensuring that childbirth practices honor the physical integrity and dignity of both mother and child.

Within the discourse on infant genital autonomy and intactivism, Birth With Dignity emphasizes the protection of natural infant physiology, framing routine neonatal circumcision as a violation of basic bodily rights. The organization actively educates parents and maternity care providers about the functions of intact anatomy, the ethics of non-therapeutic surgical procedures on minors, and the importance of evidence-based care. By framing genital integrity as a natural extension of gentle, respectful birth rights, the group serves as a vital bridge between the natural birth community and the broader intactivist movement.

Through community workshops, educational literature, and collaboration with midwives, doulas, and healthcare professionals, Birth With Dignity has contributed to shifting clinical and cultural perspectives on infant care. Its persistent outreach advocates for institutional policies that protect infants from non-consensual procedures, fostering birthing environments where physical autonomy is prioritized from the moment of birth.', '', '', 'champion', 'An advocacy organization dedicated to humanizing childbirth and protecting infant bodily autonomy and genital integrity.', 1, '[{"name": "Ted Pong", "score": 12.253, "shared_docs": 4}, {"name": "Dick Mansfield", "score": 11.668, "shared_docs": 2}, {"name": "John Mark", "score": 11.668, "shared_docs": 2}, {"name": "Jed Diamond", "score": 9.253, "shared_docs": 2}, {"name": "George Denniston", "score": 8.73, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-15f0bad5', 'organization', 'RECAP', 'RECAP (Resource, Education, and Care for Adult Prepuce) is an organization established within the broader bodily autonomy and intactivist movement to address the physical, psychological, and anatomical consequences of male circumcision. Emerging alongside early advocacy and support networks, RECAP was formed to provide targeted educational resources, anatomical information, and peer support for individuals seeking to understand foreskin restoration and the physiological roles of the prepuce.', '', '', 'champion', 'An advocacy and educational organization dedicated to raising awareness about foreskin restoration, bodily autonomy, and the effects of male circumcision.', 1, '[{"name": "Ron Fisher", "score": 9.668, "shared_docs": 2}, {"name": "Ron Goldman", "score": 9.516, "shared_docs": 3}, {"name": "Thomas Ritter", "score": 9.083, "shared_docs": 2}, {"name": "American Urological Association", "score": 8.553, "shared_docs": 2}, {"name": "R. Wayne Griffiths", "score": 8.346, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-fed97f8f', 'person', 'Anne Briggs', 'Anne Briggs is an advocate for human rights and bodily autonomy, recognized for her active involvement in the intactivism movement. Her work primarily focuses on raising public awareness regarding the ethical, physiological, and psychological implications of routine infant circumcision. Through her educational initiatives and public engagement, Briggs has consistently argued against non-therapeutic genital alterations performed on minors without informed consent.

Throughout her trajectory in bodily autonomy activism, Briggs has collaborated with various human rights organizations and educational networks dedicated to ending non-consensual infant circumcision. She has contributed to international symposia, educational literature, and community support frameworks aimed at informing parents about intact anatomy, human rights principles, and the importance of preserving bodily integrity from birth.

Briggs'' contributions form part of the historical development of the modern genital autonomy movement. Her efforts have helped frame circumcision not merely as a routine cultural or medical decision, but as a critical issue concerning children''s rights, bodily integrity, and informed consent.', '', '', 'champion', 'Prominent genital autonomy advocate and contributor to intactivist educational outreach.', 0, '[{"name": "UNCIRC", "score": 9.96, "shared_docs": 2}, {"name": "Thomas J. Ritter", "score": 9.183, "shared_docs": 3}, {"name": "Rosemary Romberg", "score": 9.013, "shared_docs": 4}, {"name": "Fran Hosken", "score": 8.768, "shared_docs": 2}, {"name": "NOCIRC", "score": 8.265, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-46ff1356', 'organization', 'Hourglass Book Publishing', 'Hourglass Book Publishing is an independent publishing entity recognized for its role in disseminating literature on genital autonomy, foreskin restoration, and the critique of routine infant circumcision. The publishing house emerged as a key media platform within the intactivist movement during the late 20th century by specializing in titles that addressed the physical, psychological, and ethical dimensions of male circumcision.

The publisher is most widely recognized for bringing to print Jim Bigelow''s landmark 1992 book, "The Joy of Uncircumcising!: Restoring Your External Body Integrity." This publication served as one of the earliest comprehensive guidebooks on non-surgical foreskin restoration, providing both practical instructions and emotional validation for men seeking to recover foreskin tissue. By publishing Bigelow''s work, Hourglass Book Publishing helped establish a formal canon of educational materials for the growing foreskin restoration community.

Throughout its operations, Hourglass Book Publishing contributed significantly to the public availability of resources challenging the medicalization of infant circumcision. By providing an outlet for authors writing on bodily integrity and men''s health autonomy, the publisher played an influential supporting role in facilitating discussion and awareness surrounding intact care and restorative practices.', '', '', 'champion', 'An independent publishing house notable for producing foundational literature on foreskin restoration and genital autonomy.', 0, '[{"name": "Jim Bigelow", "score": 8.516, "shared_docs": 3}, {"name": "NOCIRC", "score": 8.166, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-83e532d1', 'person', 'Warren Smith', 'Warren Smith was an American intactivist and advocate for bodily autonomy best known for his foundational contributions to the non-surgical foreskin restoration movement. Frustrated by the physical and psychological consequences of routine infant circumcision, Smith sought practical methods for circumcised men to reclaim lost tissue, leading to his development of the widely adopted T-Tape technique in the late 20th century.

Smith''s T-Tape method utilized tailored medical tape to apply gentle, continuous tension to penile skin, encouraging tissue growth through continuous expansion. Recognizing the lack of accessible information on non-surgical restoration, he authored detailed instructional manuals and freely distributed them through early internet forums, bodily autonomy newsletters, and advocacy networks, helping to standardize restoration practices worldwide.

Beyond his technical innovations, Smith actively contributed to the broader intactivist movement by raising awareness about the ethical implications of non-consensual infant circumcision. His practical developments and educational efforts empowered countless individuals seeking physical recovery, leaving a lasting legacy within peer-support networks and genital integrity advocacy groups.', '', '', 'champion', 'Pioneering intactivist and inventor of the T-Tape non-surgical foreskin restoration method.', 0, '[{"name": "Ron Goldman", "score": 9.931, "shared_docs": 2}, {"name": "R. Wayne Griffiths", "score": 9.346, "shared_docs": 2}, {"name": "Circumcision Resource Center", "score": 9.005, "shared_docs": 2}, {"name": "Benjamin Spock", "score": 8.498, "shared_docs": 2}, {"name": "Rosemary Romberg", "score": 8.498, "shared_docs": 2}]');
