INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e3f0b9ae', 'organization', 'Peaceful Beginnings', 'Peaceful Beginnings is an advocacy organization dedicated to promoting infant bodily autonomy, gentle birth practices, and the prevention of routine neonatal circumcision. Established as part of the broader human rights movement surrounding childbirth and bodily integrity, the organization functions as an educational resource and support network for expectant parents, birth workers, and healthcare professionals committed to preserving intact human anatomy.

The organization primary focuses on providing evidence-based literature and practical guidance to help families navigate hospital protocols and societal pressures regarding newborn care. Through public outreach, educational materials, and workshops, Peaceful Beginnings emphasizes the natural physiological function of intact infants and advocates for informed consent in pediatric medicine. Its materials frequently assist parents in creating explicit birth plans that protect newborns from non-therapeutic genital alterations.

Within the sociological study of intactivism, Peaceful Beginnings illustrates the intersection between holistic birth philosophy and children''s rights advocacy. By integrating gentle birthing practices with clear education on genital autonomy, the organization has played a key role in empowering parents to resist institutional norms and uphold the bodily integrity of their children.', '', '', 'champion', 'Grassroots advocacy organization dedicated to promoting gentle birth practices and protecting infant bodily integrity.', 1, '[{"name": "Bergin & Garvey", "score": 10.46, "shared_docs": 3}, {"name": "Rosemary Romberg", "score": 9.29, "shared_docs": 9}, {"name": "NOCIRC", "score": 7.372, "shared_docs": 3}, {"name": "Edward Wallerstein", "score": 6.147, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-39fbfec9', 'person', 'Ron Fisher', 'Ron Fisher is an American activist and media producer recognized for his contributions to the genital autonomy and intactivism movements. Emerging as an outspoken advocate against routine infant circumcision in the United States during the late 20th century, Fisher dedicated his efforts to raising public awareness regarding the medical, ethical, and psychological dimensions of non-consensual genital alterations.', '', '', 'champion', 'American media producer and activist who leveraged public access television to advance genital autonomy and educational awareness.', 0, '[{"name": "Ron Goldman", "score": 9.668, "shared_docs": 2}, {"name": "RECAP", "score": 9.668, "shared_docs": 2}, {"name": "R. Wayne Griffiths", "score": 9.083, "shared_docs": 2}]');
