INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-69bf4912', 'organization', 'Mothering Magazine', 'Founded in 1976, Mothering Magazine was an influential American publication dedicated to natural childbirth, attachment parenting, and holistic family health. Long edited and published by Peggy O''Mara, the magazine provided an alternative perspective to conventional medicalized parenting practices, addressing topics such as home birth, breast-feeding, vaccination choices, and bodily integrity.

Within the discourse on circumcision and bodily autonomy, Mothering Magazine served as a crucial media platform by consistently challenging routine infant circumcision. At a time when mainstream medical literature and media rarely questioned the procedure, the magazine routinely published articles outlining the anatomical significance of the foreskin, discussing pain management and surgical risks, and highlighting the ethical considerations of non-consensual bodily modifications.

By providing space for intactivist scholars, medical professionals, and concerned parents to share research and advocacy, Mothering Magazine played a key role in integrating foreskin advocacy into the broader natural parenting movement. Its articles and educational resources helped normalize the choice to keep children intact and educated generations of prospective parents across North America.', '', '', 'champion', 'An influential natural parenting publication that served as a key media platform for educating parents on bodily autonomy and opposing routine infant circumcision.', 0, '');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-82617818', 'person', 'Martin S. Altschul', 'Martin S. Altschul is a legal scholar and author who has contributed to the critical discourse surrounding routine infant circumcision, bodily autonomy, and child rights. His work primarily focuses on the legal, ethical, and constitutional dimensions of performing non-therapeutic genital procedures on minors without their informed consent.

Through published articles and legal critiques, Altschul has evaluated the limits of parental decision-making authority regarding elective procedures. He argues that non-therapeutic neonatal circumcision infringes upon a child''s inherent right to bodily integrity and self-determination, placing these concerns within the broader context of constitutional protections and medical ethics.

Within the intactivist movement and legal advocacy circles, Altschul''s scholarship provides foundational arguments used to challenge the prevailing socio-legal acceptance of routine infant circumcision. His work remains a reference point for discussions on human rights law and bodily integrity in medical practice.', '', '', 'champion', 'Legal scholar and writer who contributed key legal and ethical critiques against routine neonatal circumcision.', 0, '[{"name": "Kaiser Hospital", "score": 11.668, "shared_docs": 2}, {"name": "Thomas E. Wiswell", "score": 8.751, "shared_docs": 3}, {"name": "American Academy of Pediatrics", "score": 5.303, "shared_docs": 3}]');
