INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-4e874df1', 'person', 'Wiswell', 'Dr. Thomas E. Wiswell was an American pediatrician, neonatologist, and medical researcher who played a pivotal role in the late 20th-century medical debates surrounding routine infant male circumcision. Serving in the United States Army Medical Corps and holding academic appointments at institutions such as Jefferson Medical College, Wiswell became one of the most widely cited figures in pediatric literature regarding non-therapeutic neonatal circumcision.

In the mid-1980s, Wiswell published a series of influential epidemiological studies analyzing large cohorts of military infants. His research suggested a statistically significant correlation between uncircumcised status and an increased risk of urinary tract infections (UTIs) during the first year of life. These findings directly contributed to shifting medical opinion, leading the American Academy of Pediatrics (AAP) to revise its 1975 stance against routine circumcision and publish a 1989 policy statement acknowledging potential medical benefits.

Wiswell''s work positioned him as a focal figure of critique among intactivists, bodily autonomy advocates, and dissenting medical scholars. Critics questioned the clinical significance and methodology of his UTI studies, asserting that medical risk reductions did not justify non-consensual surgical intervention on healthy infants. While Wiswell later adopted a more nuanced perspective on the procedure''s social and ethical dimensions, his early research remains a cornerstone of clinical arguments supporting infant circumcision.', '', '', 'critic', 'A prominent pediatrician and neonatologist whose 1980s research on urinary tract infections reshaped American medical policy in favor of routine infant circumcision.', 0, '[{"name": "Altschul", "score": 11.668, "shared_docs": 4}, {"name": "Winberg", "score": 11.405, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-a5f9da55', 'person', 'Altschul', 'Altschul is a scholar and psychoanalytic researcher whose work is cited in literature addressing the psychological and cultural dimensions of infant male circumcision. Through clinical and academic inquiry, Altschul explored the emotional defense mechanisms, particularly forms of psychological denial, that sustain societal and medical acceptance of routine non-therapeutic genital alterations.', '', '', 'champion', 'A psychoanalytic researcher whose academic work critiques the psychological denial surrounding routine infant circumcision.', 0, '[{"name": "Winberg", "score": 12.253, "shared_docs": 3}, {"name": "Wiswell", "score": 11.668, "shared_docs": 4}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-9451dffd', 'person', 'Dean Edell', 'Dean Edell is an American physician, author, and broadcast journalist best known as the host of ''The Dr. Dean Edell Show,'' a widely syndicated radio and television program that reached millions of household listeners nationwide. After graduating from Cornell University Medical College and practicing ophthalmology, Edell shifted his career toward medical media in the late 1970s. He became one of North America''s most recognizable medical commentators, known for his pragmatic, evidence-based, and consumer-friendly approach to health reporting.

Throughout his broadcasting career, Edell was a prominent mainstream medical voice opposing routine neonatal circumcision in the United States. At a time when the practice was largely unquestioned by the general public, he frequently used his platform to critique the lack of medical necessity for non-therapeutic infant circumcision, challenge medical orthodoxy, and emphasize the fundamental importance of bodily autonomy and informed consent.

Edell''s public stance brought significant visibility to the arguments against routine circumcision, helping bridge the gap between grassroots intactivist advocacy and mainstream medical discourse. By consistently encouraging parents to reconsider cultural assumptions about infant surgery, he played an influential role in raising public awareness regarding foreskin care and genital integrity.', '', '', 'champion', 'American physician and media personality who used his syndicated radio program to challenge routine infant circumcision and champion bodily autonomy.', 1, '[{"name": "Richard Steiner", "score": 9.99, "shared_docs": 2}, {"name": "New England Journal of Medicine", "score": 9.99, "shared_docs": 2}, {"name": "C. Everett Koop", "score": 9.405, "shared_docs": 2}, {"name": "Trudie London", "score": 9.183, "shared_docs": 2}, {"name": "Virginia Urologic Society", "score": 8.82, "shared_docs": 2}]');
