INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f21d2139', 'organization', 'American Atheists', 'American Atheists is a non-profit civil rights organization founded in 1963 by Madalyn Murray O''Hair, dedicated to defending the civil liberties of non-believers and maintaining the strict separation of church and state in the United States. Headquartered in Washington, D.C., the organization engages in public policy advocacy, civil litigation, education, and community outreach to challenge state-sponsored religion and promote secular governance.

Within the discourse on bodily autonomy and child welfare, American Atheists has intersected with the intactivist movement through its defense of individual human rights against religious overreach. The organization maintains that freedom of religion belongs to the individual and does not grant parents or religious institutions the authority to violate the bodily integrity of non-consenting minors. In this context, American Atheists frames non-therapeutic infant genital alterations as a fundamental human rights issue that intersects with secular ethics and pediatric medical rights.

Through public commentary, legal briefs, and educational campaigns, American Atheists has consistently opposed religious exemptions to child protection laws. By highlighting the legal and ethical conflicts between parental religious practice and a child''s right to physical autonomy, the organization has provided important secular support to broader efforts aiming to protect all children from non-consenting genital procedures.', '', '', 'champion', 'American civil rights organization advocating for church-state separation and the protection of children''s bodily autonomy from religious exemptions.', 0, '[{"name": "California Nurses'' Association", "score": 11.668, "shared_docs": 2}, {"name": "Marilyn Fayre Milos", "score": 8.194, "shared_docs": 3}, {"name": "Marilyn Milos", "score": 7.498, "shared_docs": 2}, {"name": "National Organization of Circumcision Information Resource Centers (NOCIRC)", "score": 6.103, "shared_docs": 2}, {"name": "American Academy of Pediatrics", "score": 4.718, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-afdd56c1', 'organization', 'International Symposia on Circumcision', 'The International Symposia on Circumcision were a series of landmark international academic and advocacy conferences established in 1989 to critically examine non-therapeutic genital cutting through multidisciplinary perspectives. Initially organized under the leadership of human rights advocates and organizations such as the National Organization of Circumcision Information Resource Centers (NOCIRC), the symposia convened medical doctors, bioethicists, legal scholars, psychologists, and human rights experts from around the globe to evaluate the medical, psychological, and legal dimensions of infant male circumcision and female genital cutting.

Over several iterations held across North America and Europe, the symposia served as a crucial global platform for presenting scholarly research that challenged long-standing medical justifications for routine neonatal circumcision. Presentations focused on topics such as the anatomical functions of the foreskin, the ethics of non-consensual medical interventions on minors, psychological trauma associated with early bodily alterations, and the application of international human rights law to genital integrity.

By publishing formal conference proceedings and generating academic literature, the International Symposia played a transformative role in framing genital autonomy as a fundamental human rights issue. The published volumes served as key reference texts for activists, researchers, and legal reformers, helping to bridge Grassroots intactivism with rigorous scholarly critique and shaping international discourse on bodily autonomy.', '', '', 'champion', 'A series of global academic conferences dedicated to critically examining circumcision through medical, legal, and human rights frameworks.', 1, '[{"name": "J. David Bigelow", "score": 11.405, "shared_docs": 2}, {"name": "Gerald A. Larue", "score": 10.99, "shared_docs": 2}, {"name": "Moshe Rothenberg", "score": 10.99, "shared_docs": 2}, {"name": "Donna Macris", "score": 10.405, "shared_docs": 4}, {"name": "Jeannine Parvati Baker", "score": 10.183, "shared_docs": 2}]');
