INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-43624d78', 'person', 'Phil Donahue', 'Phillip John Donahue was an influential American media personality, writer, and talk show host, best known as the creator and host of ''The Phil Donahue Show'' (later known simply as ''Donahue''). Running nationally from 1970 to 1996, his groundbreaking television program pioneered the audience-interactive daytime talk show format. Donahue was renowned for confronting controversial, taboo, and emerging social topics, using his platform to spark public debate on issues ranging from civil rights and feminism to medical ethics.', '', '', 'notable', 'Pioneering American talk show host who provided one of the first major national television platforms for discussions on routine infant circumcision and bodily autonomy.', 0, '[{"name": "National Organization of Circumcision Information Resource Centers (NO CIRC)", "score": 9.405, "shared_docs": 2}, {"name": "Marilyn Milos", "score": 8.235, "shared_docs": 4}]');
