INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-ee190b4e', 'person', 'Ed Barton', 'Ed Barton was an early American activist, author, and prominent figure in the foreskin restoration and genital autonomy movements during the late 20th century. Prompted by his own experience and a growing realization of the physical and psychological impacts of non-consensual infant circumcision, Barton dedicated his advocacy to supporting men seeking to regain bodily integrity through non-surgical foreskin restoration.

Barton made significant contributions to the movement''s literature and community organization. He documented restoration techniques, authored educational guides, and helped foster support networks where men could openly discuss the emotional and anatomical consequences of circumcision. His work focused on demystifying the anatomical functions of the foreskin while providing practical methodologies for physical restoration and psychological healing.

Through his writing and involvement with foundational organizations such as the National Organization of Restoring Men (NORM), Barton played a vital role in establishing foreskin restoration as a core facet of male genital autonomy advocacy. His contributions provided crucial educational materials that continue to inform discussions on bodily integrity and men''s health.', '', '', 'champion', 'Pioneering intactivist author and early leader in the foreskin restoration movement.', 0, '[{"name": "Michigan State University Libraries", "score": 10.99, "shared_docs": 3}, {"name": "Ronald F. Goldman", "score": 10.668, "shared_docs": 2}]');
