INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-389b967e', 'person', 'Ronald F. Goldman', 'Ronald F. Goldman, Ph.D., is an American psychologist, researcher, and author recognized for his extensive work on the psychological, emotional, and social consequences of routine infant male circumcision. As the founder and executive director of the Circumcision Resource Center in Boston, Massachusetts, Goldman has spent decades examining the behavioral impact of early bodily trauma, advocating for children''s bodily autonomy, and educating parents, healthcare providers, and the general public on the risks and ethical concerns surrounding non-therapeutic neonatal surgery.', '', '', 'champion', 'Psychologist, author, and founder of the Circumcision Resource Center known for his research on the psychological trauma of infant circumcision.', 0, '[{"name": "Ralph Nader", "score": 11.668, "shared_docs": 2}, {"name": "Karl Menninger", "score": 10.668, "shared_docs": 2}, {"name": "Ed Barton", "score": 10.668, "shared_docs": 2}, {"name": "Circumcision Resource Center", "score": 9.59, "shared_docs": 3}, {"name": "James DeMeo", "score": 8.931, "shared_docs": 3}]');
