INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-2f6f3785', 'person', 'Barry Ellsworth', 'Barry Ellsworth is a Canadian journalist and news correspondent who has covered North American social issues, medical ethics, and human rights developments for various media outlets and news agencies. Throughout his career, his reporting frequently addressed legal, medical, and cultural shifts surrounding public health and bodily autonomy.

Within the discourse on circumcision and intactivism, Ellsworth documented the rising visibility of opposition to routine infant circumcision. His news coverage highlighted activist campaigns, public demonstrations, and statements from medical organizations regarding the necessity and ethics of non-consensual neonatal procedures in Canada and North America.

Through his journalistic efforts, Ellsworth provided contemporary documentation of the debate between traditional medical practices and emerging bodily autonomy advocacy. His work served to chronicle both grassroots activism and policy responses within the international media landscape.', '', '', 'notable', 'A Canadian journalist and news correspondent who documented public debates and activism surrounding infant circumcision and bodily autonomy.', 0, '[{"name": "James Loewen", "score": 10.668, "shared_docs": 3}, {"name": "Lawrence Dillon", "score": 10.446, "shared_docs": 2}, {"name": "Dillonwood Productions", "score": 10.446, "shared_docs": 2}, {"name": "Tim Hammond", "score": 8.044, "shared_docs": 4}, {"name": "National Organization of Circumcision Information Resource Centers (NOCIRC)", "score": 6.103, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-fb83f993', 'person', 'Anastasios Zavales', 'Anastasios Zavales is an American activist, photojournalist, and advocate for genital autonomy who emerged as a key figure in the intactivist movement during the late 20th and early 21st centuries. He is widely recognized for founding the New York chapter of the National Organization of Restoring Men (NORM-NY), a peer support and educational group focused on helping men navigate non-surgical foreskin restoration and address the physical and emotional impacts of involuntary neonatal circumcision.', '', '', 'champion', 'Prominent American intactivist, foreskin restoration advocate, and founder of NORM-NY.', 1, '[{"name": "Ecumenics International", "score": 10.99, "shared_docs": 2}, {"name": "Zenas Baer", "score": 10.99, "shared_docs": 2}, {"name": "Miriam Pollack", "score": 9.575, "shared_docs": 2}, {"name": "Soraya Mire", "score": 9.253, "shared_docs": 2}, {"name": "Nurses for the Rights of the Child", "score": 9.253, "shared_docs": 2}]');
