INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-95d1e2a6', 'person', 'NOCIRC of Michigan', 'NOCIRC of Michigan operated as a regional chapter of the National Organization of Circumcision Information Resource Centers, serving as a localized advocacy and educational group within the Midwestern United States. The organization focused on raising public awareness regarding the ethical, legal, and physiological dimensions of routine male infant circumcision, providing resources to expectant parents, medical professionals, and the general public.

Through outreach campaigns, distribution of educational literature, and participation in community events, NOCIRC of Michigan sought to challenge mainstream medical norms and advocate for the protection of children''s bodily autonomy. The chapter offered guidance on normal intact anatomy care, highlighted the necessity of informed consent in medical procedures, and supported individuals questioning or resisting conventional practices surrounding newborn circumcision.

As part of the broader intactivist movement, NOCIRC of Michigan contributed to shifting regional discourse by framing male infant circumcision as a violation of physical integrity and human rights. Its work reflected a commitment to empowering parents with non-biased information and advancing the protection of bodily autonomy for children.', '', '', 'champion', 'Regional chapter of the National Organization of Circumcision Information Resource Centers dedicated to promoting genital autonomy in Michigan.', 0, '[{"name": "Norm Cohen", "score": 10.379, "shared_docs": 3}, {"name": "Edward Wallerstein", "score": 7.525, "shared_docs": 2}, {"name": "National Organization of Circumcision Information Resource Centers (NOCIRC)", "score": 6.103, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-da92c05d', 'organization', 'PBS', 'The Public Broadcasting Service (PBS) is an American non-profit public broadcaster and program distributor known for its educational programming, investigative journalism, and documentary films. Founded in 1969, PBS serves as a prominent media network across the United States, offering a platform for independent filmmakers, educational content, and national news reporting.

Within the discourse on circumcision and bodily autonomy, PBS has broadcast programming and news segments that address the medical, ethical, and cultural dimensions of routine infant circumcision. Coverage through news broadcasts and featured documentaries has examined shifting medical recommendations, parental decision-making, and debates surrounding bodily integrity and consent.

By providing journalistic coverage and airing public interest documentaries, PBS has served as a widely accessible medium through which perspectives from medical professionals, ethicists, and advocacy groups are presented to the general public.', '', '', 'notable', 'A major American public broadcaster that has covered issues of routine infant circumcision and bodily autonomy through documentaries and news programming.', 0, '[{"name": "American Psychological Association", "score": 10.99, "shared_docs": 2}, {"name": "Dillonwood Productions", "score": 10.768, "shared_docs": 3}, {"name": "Lawrence Dillon", "score": 10.183, "shared_docs": 2}, {"name": "Tim Hammond", "score": 7.366, "shared_docs": 3}]');
