INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-e93df284', 'person', 'Michel Odent', 'Michel Odent (born 1931) is a French obstetrician, surgeon, and author best known for introducing water birth practices into hospital settings and pioneering gentle birth techniques. After earning his medical degree at the University of Paris, Odent directed the surgical and maternity departments at the Pithiviers hospital in France from 1962 to 1985. There, he reshaped obstetrical care by creating low-intervention, home-like birthing environments designed to support the natural physiological processes of labor and delivery. He later established the Primal Health Research Centre in London to study the long-term health effects of environmental and physical events during the primal period of life.

Within the discourse on bodily autonomy and intactivism, Odent has been an influential medical figure opposing routine neonatal circumcision. Analyzing birth and early infancy through a lens of human ecology and neurobiology, he argued that infant circumcision represents an invasive surgical trauma that disrupts early mother-infant bonding and alters the delicate hormonal balance of the postpartum period. His work emphasizes the preservation of the newborn''s physical integrity and critiques medical cultures that normalized unnecessary operative procedures on infants.

Odent''s publications and research have been widely cited by bodily autonomy advocates and human rights organizations seeking clinical evidence against neonatal genital cutting. By linking intact genital anatomy to optimal primal health and mother-child attachment, Odent helped broaden the critique of routine infant circumcision from purely ethical and legal arguments to encompass holistic neurobiological and ecological perspectives.', '', '', 'champion', 'French obstetrician and birth pioneer who critiques routine neonatal circumcision as an unnecessary trauma disrupting primal health and bonding.', 1, '[{"name": "J. David Bigelow", "score": 10.531, "shared_docs": 2}, {"name": "Shelton Walden", "score": 10.531, "shared_docs": 2}, {"name": "Gerald A. Larue", "score": 10.116, "shared_docs": 2}, {"name": "Moshe Rothenberg", "score": 10.116, "shared_docs": 2}, {"name": "Martin Altschul", "score": 9.794, "shared_docs": 2}]');
