INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-69faa018', 'person', 'Wayne Hampton', 'Wayne Hampton was an early advocate for bodily autonomy and genital integrity, emerging as a notable figure in the American movement opposing routine infant circumcision during the late 20th century. Through his writing, public presentations, and grassroots networking, Hampton sought to challenge entrenched medical practices surrounding non-therapeutic neonatal circumcision and emphasize the principles of bodily self-determination and informed consent.

Hampton worked alongside other pioneering activists and organizations to broaden the public discourse around the ethical, anatomical, and psychological dimensions of infant male circumcision. His contributions focused on educating parents and healthcare professionals about the function of intact human anatomy, challenging common medical justifications for routine procedures, and offering resources for those seeking information on bodily integrity.

Within the historical archive of the intactivist movement, Hampton is recognized for his persistent efforts to organize, inform, and challenge dominant clinical paradigms. His activism helped lay early foundational support networks for individuals and families advocating for the protection of children''s natural bodily autonomy.', '', '', 'champion', 'Pioneering activist and advocate for bodily integrity in the American intactivist movement.', 0, '[{"name": "Duane Jorde", "score": 10.446, "shared_docs": 2}, {"name": "National Coalition of Free Men (NCFM)", "score": 9.768, "shared_docs": 3}, {"name": "Tim Hammond", "score": 6.558, "shared_docs": 2}, {"name": "National Organization of Circumcision Information Resource Centers (NOCIRC)", "score": 5.618, "shared_docs": 2}]');
