INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-644ea178', 'organization', 'National Coalition of Free Men (NCFM)', 'The National Coalition of Free Men (NCFM)—later known as the National Coalition for Men—was established in 1977 as a nonprofit educational and advocacy organization dedicated to examining how sex-based discrimination impacts men and boys. As one of the oldest civil rights organizations focused on men''s issues in the United States, NCFM addressed a wide range of legal, social, and cultural topics, including reproductive rights, family law, and physical integrity.

Within the discourse on circumcision and bodily autonomy, NCFM was an early organizational voice to articulate opposition to involuntary infant male circumcision. The group framed routine neonatal circumcision as a violation of equal protection and constitutional rights, arguing that young males were denied the same legal protections against non-consensual genital modification that were granted to females. Through public statements, educational literature, and legal commentary, NCFM highlighted the ethical implications of performing irreversible surgical procedures on infants without medical necessity or personal consent.

Throughout its history, NCFM maintained alignment with the broader intactivist movement by advocating for equal rights to bodily integrity regardless of sex or gender. By situating male circumcision within the larger context of sex-based legal discrepancies and children''s rights, the organization contributed significantly to early secular and rights-based critiques of routine infant circumcision in the United States.', '', '', 'champion', 'A pioneering men''s rights organization that historically framed infant male circumcision as a fundamental violation of equal rights and bodily autonomy.', 1, '[{"name": "NBC", "score": 10.405, "shared_docs": 2}, {"name": "Wayne Hampton", "score": 9.768, "shared_docs": 3}, {"name": "Steven Svoboda", "score": 9.668, "shared_docs": 2}, {"name": "Ronald Goldman", "score": 6.946, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-fb90a6b5', 'organization', 'National Coalition of Free Men', 'Founded in 1977, the National Coalition of Free Men (later renamed the National Coalition for Men) is one of the oldest advocacy and educational organizations in the United States dedicated to men''s rights and gender equality issues. The non-profit organization addresses a broad spectrum of legal, social, and ethical topics affecting men and boys, emphasizing equal protection under the law and non-discrimination.

Within the discourse on bodily autonomy, the organization has consistently taken a firm stance against non-therapeutic infant male circumcision. The coalition frames infant circumcision as a violation of fundamental human rights and physical integrity, arguing that minor males deserve the same legal protections against non-consensual genital alteration as minor females. Through educational publications and public statements, the group has repeatedly highlighted the ethical issues surrounding parental proxy consent and medical necessity in neonatal procedures.

Over the decades, the National Coalition of Free Men has aligned with the broader intactivist movement, supporting legal efforts, awareness campaigns, and commentary challenging routine circumcision practices. By linking male genital autonomy to broader conversations about men''s rights and constitutional equality, the organization helped integrate intactivist arguments into gender advocacy discourse.', '', '', 'champion', 'An early men''s rights advocacy organization that actively opposes routine infant male circumcision as a violation of bodily autonomy and equal rights.', 0, '[{"name": "Ray", "score": 10.99, "shared_docs": 2}]');
