INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-d0b6e8d1', 'person', 'Martin Altschul', 'Martin Altschul is an American activist and independent researcher who has contributed significantly to the discourse on bodily autonomy, genital integrity, and the ethical implications of routine infant circumcision. With a background in engineering and technical analysis, Altschul applied a methodical approach to evaluating the anatomical function of the natural foreskin and the physical impact of non-therapeutic circumcision, advocating for evidence-based discussion in medical and public spheres.', '', '', 'champion', 'American researcher and advocate for child bodily integrity and genital autonomy.', 0, '[{"name": "Shelton Walden", "score": 11.668, "shared_docs": 2}, {"name": "Charles A. Bonner", "score": 10.083, "shared_docs": 2}, {"name": "Attorneys for the Rights of the Child (ARC)", "score": 9.794, "shared_docs": 2}, {"name": "Michel Odent", "score": 9.794, "shared_docs": 2}, {"name": "Sheila Curran", "score": 9.446, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-0e5ab59d', 'person', 'Trudie London', 'Trudie London is a healthcare professional and activist who played a instrumental role in the British bodily autonomy movement as a key coordinator for the National Organization of Circumcision Information Resource Centers (NOCIRC) in the United Kingdom. Recognizing the lack of accessible, evidence-based information regarding routine infant circumcision, London dedicated her work to educating parents, midwives, and healthcare practitioners about the ethical and physiological consequences of non-therapeutic penile cutting.

Throughout her advocacy, London focused on promoting informed consent and safeguarding children''s rights to bodily integrity. Operating NOCIRC UK, she provided support to families questioning medicalized circumcision practices, disseminated educational literature, and countered prevailing medical misapprehensions surrounding the foreskin. Her efforts helped connect British advocates with the broader international intactivist network, fostering cross-border collaboration between activists in Europe and North America.

London''s contributions to the discourse around infant genital autonomy helped reinforce the professional and ethical shift away from non-consensual routine infant circumcision in the UK. Her legacy continues to be recognized within the historical study of bodily autonomy activism and child advocacy.', '', '', 'champion', 'Key coordinator of NOCIRC UK and long-standing advocate for infant genital autonomy in the United Kingdom.', 0, '[{"name": "Tatiana Bertschinger", "score": 11.768, "shared_docs": 4}, {"name": "Sara Pitta", "score": 11.183, "shared_docs": 4}, {"name": "Julia Attwood", "score": 11.031, "shared_docs": 3}, {"name": "Sheila Curran", "score": 10.282, "shared_docs": 5}, {"name": "Dean Edell", "score": 9.183, "shared_docs": 2}]');
