INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-4203d444', 'organization', 'Marin County Superior Court', 'The Marin County Superior Court is the trial court of general jurisdiction for Marin County, California, handling civil, criminal, and family law matters. Located in San Rafael, California, the court operates within the region that served as the historical headquarters for the modern American intactivist movement, notably where the National Organization of Circumcision Information Resource Centers (NOCIRC) was established in 1985. Consequently, the court''s docket has periodically intersected with legal actions, injunction requests, and family law disputes concerning genital autonomy and child welfare.

Within the discourse surrounding circumcision and bodily integrity, the Marin County Superior Court has functioned primarily as a forum for resolving high-conflict family law disputes, such as disagreements between separated or divorced parents regarding the non-therapeutic circumcision of minor children. In these cases, the court was tasked with evaluating arguments concerning parental rights, medical necessity, religious freedom, and the best interests of the child, frequently serving as an empirical case study for legal scholars and bodily autonomy advocates.

Although the court maintains a neutral judicial mandate, its rulings and proceedings hold significant value within sociological and legal archives of intactivism. The documentation of cases brought before the court illustrates how grass-roots advocacy and bioethical debates over pediatric surgical consent are tested and adjudicated within the American judicial system.', '', '', 'notable', 'A California state trial court that served as a legal forum for significant family law disputes and legal challenges concerning parental consent and infant circumcision.', 0, '[{"name": "Kelen Nelson", "score": 11.575, "shared_docs": 3}, {"name": "Alameda Superior Court", "score": 11.575, "shared_docs": 3}, {"name": "Kaiser Foundation Hospital", "score": 11.405, "shared_docs": 4}, {"name": "Permanente Medical Group", "score": 11.405, "shared_docs": 4}, {"name": "Adam London", "score": 10.853, "shared_docs": 5}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-56638592', 'person', 'Julia Attwood', 'Julia Attwood is a British researcher and advocate for bodily integrity who has contributed significantly to the discourse surrounding non-consensual infant male circumcision and genital autonomy. Her work has focused on highlighting the ethical, psychological, and physiological ramifications of routine neonatal circumcision, placing particular emphasis on child rights and informed consent within contemporary medical frameworks.

Throughout her involvement in the intactivist movement, Attwood has collaborated with non-profit organizations and support networks dedicated to foreskin restoration and education. Through published articles, analytical commentary, and community support work, she has sought to provide resources for individuals experiencing grief, trauma, or physical complications resulting from childhood circumcision.

Attwood''s advocacy emphasizes the universal application of bodily autonomy, arguing that irreversible genital alterations should be reserved until an individual can provide fully informed consent. Her contributions remain a notable reference point within the broader international dialogue on medical ethics, children''s rights, and genital integrity.', '', '', 'champion', 'British bodily autonomy advocate and researcher recognized for her contributions to intactivist literature and foreskin restoration support networks.', 0, '[{"name": "Tatiana Bertschinger", "score": 11.838, "shared_docs": 3}, {"name": "Sara Pitta", "score": 11.253, "shared_docs": 3}, {"name": "Trudie London", "score": 11.031, "shared_docs": 3}, {"name": "Sheila Curran", "score": 10.031, "shared_docs": 3}, {"name": "NO CIRC", "score": 9.553, "shared_docs": 2}]');
