INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-d228317c', 'person', 'National Organization of Circumcision Information Resource Centers (NO CIRC)', 'Founded in 1985 by nurse Marilyn Milos, the National Organization of Circumcision Information Resource Centers (NOCIRC) established itself as the first major non-profit advocacy organization in the United States dedicated to ending routine infant circumcision. Operating out of California, NOCIRC served as a foundational institution within the modern intactivist movement, seeking to inform the public, medical professionals, and lawmakers about the anatomical functions of the foreskin and the medical and ethical arguments against non-consensual genital alteration.', '', '', 'champion', 'Pioneering non-profit organization dedicated to opposing routine infant circumcision and advancing bodily autonomy rights.', 1, '[{"name": "NO CIRC", "score": 10.097, "shared_docs": 7}, {"name": "Phil Donahue", "score": 9.405, "shared_docs": 2}, {"name": "Marin County Superior Court", "score": 9.405, "shared_docs": 2}, {"name": "Trudie London", "score": 9.183, "shared_docs": 2}, {"name": "Adam London", "score": 8.531, "shared_docs": 2}]');
