INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-568a8128', 'organization', 'NO CIRC', 'The National Organization of Circumcision Information Resource Centers (NOCIRC), commonly referred to as NO CIRC, was established in 1985 by nurse Marilyn Milos as the first national anti-circumcision advocacy group in the United States. Formed to counter routine neonatal circumcision practices, the organization aimed to provide parents, healthcare professionals, and the public with evidence-based information regarding the functions of the foreskin, the risks associated with circumcision, and the ethical implications of non-therapeutic genital alterations performed on minors.

Throughout its history, NOCIRC operated as an international educational network, establishing local resource centers across the globe and publishing informational brochures, newsletters, and policy critiques. The organization periodically convened international symposia that brought together legal experts, medical professionals, bioethicists, and human rights advocates to examine circumcision through the lens of child protection, informed consent, and medical ethics.

NOCIRC played a seminal role in establishing the foundational framework of the modern intactivist movement. By challenging prevalent medical paradigms and reframing infant circumcision as a violation of physical integrity and fundamental rights, the organization significantly influenced public discourse and paved the way for subsequent bodily autonomy advocacy organizations worldwide.', '', '', 'champion', 'A pioneering non-profit organization dedicated to providing information on circumcision and advocating for genital autonomy and infants'' human rights.', 1, '[{"name": "NO CIRC (National Organization of Circumcision Information Resource Centers)", "score": 10.29, "shared_docs": 2}, {"name": "National Organization of Circumcision Information Resource Centers (NO CIRC)", "score": 10.097, "shared_docs": 7}, {"name": "Julia Attwood", "score": 9.553, "shared_docs": 2}, {"name": "Dean Edell", "score": 8.29, "shared_docs": 2}, {"name": "Marilyn Milos", "score": 7.12, "shared_docs": 4}]');
