INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-30430de3', 'organization', 'The Truth Seeker', 'Founded in 1873, The Truth Seeker is one of the oldest freethought and secularist publications in the United States. Historically dedicated to promoting rationalism, individual liberty, and skepticism toward religious and institutional dogmas, the periodical served as a prominent venue for alternative social, scientific, and medical discourse throughout the nineteenth and twentieth centuries.

Within the discourse on bodily autonomy, The Truth Seeker provided a critical early platform for secular and medical reform perspectives challenging routine infant circumcision. The publication featured essays and commentary that analyzed circumcision through the lens of individual rights, questioning both its religious origins and its routine adoption by the Western medical establishment as an unwarranted infringement upon bodily integrity.

By linking secular humanism with bodily sovereignty, the publication contributed to the early intellectual foundation of the modern intactivist movement. Its archived contributions reflect an enduring commitment to challenging traditional body modification practices in favor of personal self-determination and evidence-based ethics.', '', '', 'champion', 'Historic American freethought publication that provided an early secular platform for critiques of routine infant circumcision and body modification.', 0, '[{"name": "Women''s International Network News", "score": 11.253, "shared_docs": 2}, {"name": "James W. Prescott", "score": 9.516, "shared_docs": 3}, {"name": "National Organization of Circumcision Information Resource Centers (NOCIRC)", "score": 6.103, "shared_docs": 2}]');
