INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-f7bef021', 'person', 'Bill Schilling', 'Bill Schilling emerged as a notable voice within the American intactivist movement, advocating for fundamental bodily autonomy and the protection of children from non-consensual, non-therapeutic circumcision. His work centered on raising public awareness regarding the anatomical functions of the foreskin and challenging long-standing cultural and medical norms surrounding routine neonatal circumcision in North America.

Throughout his involvement in genital autonomy advocacy, Schilling contributed to community support networks and educational outreach. He became particularly recognized for his engagement with foreskin restoration communities, offering guidance, educational materials, and peer support to individuals seeking non-surgical options to address the physical and psychological impacts of infant circumcision.

Schilling''s advocacy underscored a human rights-based approach to bodily integrity, arguing that surgical interventions on healthy child genitalia violate basic ethical principles of medical consent. Through his long-term participation in public demonstrations, activism, and community organizing, he helped sustain dialogue surrounding male genital intactness and bodily self-determination.', '', '', 'champion', 'American human rights activist and prominent advocate for bodily integrity and foreskin restoration.', 0, '[{"name": "Bill P. James", "score": 11.668, "shared_docs": 4}, {"name": "Bill F. James", "score": 11.668, "shared_docs": 4}, {"name": "Uncircumcised Society of America - New York", "score": 11.668, "shared_docs": 2}, {"name": "Gene Sowder", "score": 11.446, "shared_docs": 4}, {"name": "USA - NY", "score": 10.379, "shared_docs": 3}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-b899b699', 'person', 'Gene Sowder', 'Gene Sowder was an early advocate and organizer within the foreskin restoration and bodily autonomy movements in the United States. Through his involvement with grassroots intactivist organizations, including the National Organization of Restoring Men (NORM), Sowder worked to raise public awareness about the physical and psychological consequences of infant male circumcision. He focused much of his efforts on creating supportive spaces for men seeking non-surgical foreskin restoration and processing emotional grief associated with involuntary genital alteration.

Sowder contributed significantly to the practical and educational facets of the restoration movement, sharing information on techniques, ethics, and bodily self-determination. His participation in regional and national gatherings helped connect isolated individuals with the broader intactivist community, fostering a network dedicated to promoting bodily integrity and challenging medicalized routine circumcision practices.', '', '', 'champion', 'Early foreskin restoration advocate and key organizer within the National Organization of Restoring Men (NORM).', 0, '[{"name": "Bill P. James", "score": 11.768, "shared_docs": 6}, {"name": "Bill F. James", "score": 11.768, "shared_docs": 6}, {"name": "Uncircumcised Society of America - New York", "score": 11.768, "shared_docs": 3}, {"name": "Bill Schilling", "score": 11.446, "shared_docs": 4}, {"name": "UNCUT DALLAS", "score": 11.183, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-c73f72e3', 'person', 'Bill P. James', 'Bill P. James is an advocate and writer who emerged within the American intactivist movement during the late twentieth century. Driven by a focus on human rights, bodily integrity, and medical ethics, he engaged in organized efforts to challenge the routine practice of non-therapeutic neonatal circumcision in the United States.

Throughout his involvement in bodily autonomy discourse, James contributed to grassroots educational campaigns, public symposiums, and analytical writings addressing the social, legal, and ethical dimensions of infant circumcision. His work often examined the boundary between parental authority and a child''s fundamental right to physical integrity, seeking to inform both healthcare professionals and the general public.

James''s contributions represent a significant chapter in the history of genital integrity activism, offering sociologists and legal scholars insights into the development of modern patient advocacy and the evolving debate surrounding routine infant surgeries.', '', '', 'champion', 'An American activist and writer recognized for his contributions to the movement for infant genital autonomy and human rights.', 0, '[{"name": "Bill F. James", "score": 11.99, "shared_docs": 6}, {"name": "Uncircumcised Society of America - New York", "score": 11.99, "shared_docs": 3}, {"name": "Gene Sowder", "score": 11.768, "shared_docs": 6}, {"name": "Bill Schilling", "score": 11.668, "shared_docs": 4}, {"name": "Ray", "score": 10.99, "shared_docs": 2}]');
INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-969a3fbe', 'person', 'Bill F. James', 'Bill F. James is an activist and author who contributed to the early movement for bodily autonomy and genital integrity, particularly focusing on non-surgical foreskin restoration and community education regarding intact care.

Through independent publishing and grassroots outreach, James compiled practical resources and documentation aimed at helping individuals navigate foreskin restoration. His work addressed both the physical aspects of restoration and the broader psychological considerations surrounding infant male circumcision, offering support to men seeking to reclaim bodily autonomy.

James''s writings helped lay the groundwork for peer-support networks and informational exchanges within the intactivist community during the late 20th century. His literature remains an important historical reference documenting the emergence of consumer-led foreskin restoration methodologies.', '', '', 'champion', 'An early intactivist author and advocate known for his foundational literature on foreskin restoration and bodily autonomy.', 0, '[{"name": "Bill P. James", "score": 11.99, "shared_docs": 6}, {"name": "Uncircumcised Society of America - New York", "score": 11.99, "shared_docs": 3}, {"name": "Gene Sowder", "score": 11.768, "shared_docs": 6}, {"name": "Bill Schilling", "score": 11.668, "shared_docs": 4}, {"name": "Ray", "score": 10.99, "shared_docs": 2}]');
