INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-d8a9cbf7', 'person', 'Mary Conant', 'Mary Conant emerged as a dedicated advocate within the North American genital autonomy movement, focusing on educating parents, healthcare providers, and the public about the ethical, medical, and human rights implications of routine infant circumcision. Her activism was rooted in the belief that every child possesses a fundamental right to bodily integrity and full bodily autonomy.

Throughout her involvement in the movement, Conant worked alongside pioneering organizations such as the National Organization of Circumcision Information Resource Centers (NOCIRC). In these capacities, she assisted in organizing educational campaigns, distributing evidence-based literature, and providing support to families seeking non-procedural alternatives for infant care. Her efforts aimed to counter widespread medicalized cultural norms surrounding neonatal circumcision.

Through her participation in community outreach, advocacy networks, and grassroots educational initiatives, Conant contributed to raising awareness about the importance of informed consent and intact care. Her work remains a recognized element of the broader history of intactivism and children''s rights advocacy.', '', '', 'champion', 'Prominent activist and advocate for children''s bodily integrity who contributed to early educational campaigns against infant circumcision.', 1, '[{"name": "Morris Sorrells", "score": 11.16, "shared_docs": 3}, {"name": "Laurie Evans", "score": 10.99, "shared_docs": 2}, {"name": "St. Vincent Hospital", "score": 10.99, "shared_docs": 2}, {"name": "David Llewellyn", "score": 10.99, "shared_docs": 2}, {"name": "Peter Ball", "score": 10.99, "shared_docs": 2}]');
