INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-519b68dd', 'person', 'Uncircumcised Society of America - New York', 'The Uncircumcised Society of America - New York was a regional advocacy and social organization formed to support uncircumcised men and challenge cultural norms surrounding routine infant circumcision in the United States. Operating during the late twentieth century, the group provided a public and social space for intact men to share experiences, access educational resources, and push back against societal stigmatization of intact male anatomy.

Through community meetings, distributed literature, and grassroots outreach, the New York chapter contributed to early foreskin advocacy by promoting positive body image and educating the public on the natural anatomy and function of the human foreskin. The organization served as an early peer-support network, offering a community for men navigating social and medical pressures surrounding circumcision in an era when non-circumcision was less common in American culture.

While largely operating as a localized community network, the Uncircumcised Society of America - New York played a notable role in the genealogy of modern intactivism. By framing foreskin preservation and genital integrity as essential components of bodily autonomy, the organization helped lay the groundwork for subsequent organized movements opposing involuntary routine non-therapeutic circumcision.', '', '', 'champion', 'An early regional support and advocacy network dedicated to promoting bodily autonomy and social acceptance for intact men.', 0, '[{"name": "Bill P. James", "score": 11.99, "shared_docs": 3}, {"name": "Bill F. James", "score": 11.99, "shared_docs": 3}, {"name": "Gene Sowder", "score": 11.768, "shared_docs": 3}, {"name": "Bill Schilling", "score": 11.668, "shared_docs": 2}, {"name": "USA - NY", "score": 11.116, "shared_docs": 3}]');
