INSERT OR IGNORE INTO entities (id, type, name, description, url, image_url, role, tagline, featured, see_also_json) VALUES ('entity-21eeb689', 'person', 'Duane Jorde', 'Duane Jorde is an American attorney and human rights advocate known for his legal advocacy and contributions to the movement against non-therapeutic infant circumcision. Grounded in a professional legal background, Jorde applied principles of constitutional law, bodily integrity, and children''s rights to challenge the social and medical conventions surrounding routine neonatal circumcision in the United States.

Throughout his activism, Jorde engaged with legal strategies and educational outreach aimed at protecting children from non-consensual bodily modifications. His work frequently emphasized the legal and ethical imperative of informed consent, arguing that male infants deserve the same legal protections against non-consensual genital alteration as other demographic groups.

Within the broader framework of intactivism, Jorde''s legal analyses provided valuable frameworks for framing male circumcision as a fundamental violation of individual rights. His contributions continue to be cited in sociological and legal discussions concerning children''s rights, medical ethics, and bodily autonomy.', '', '', 'champion', 'American attorney and advocate recognized for his legal contributions to the movement for genital autonomy.', 0, '[{"name": "Wayne Hampton", "score": 10.446, "shared_docs": 2}, {"name": "NOHARMM", "score": 8.609, "shared_docs": 2}, {"name": "Jim Bigelow", "score": 7.931, "shared_docs": 2}, {"name": "Tim Hammond", "score": 7.044, "shared_docs": 2}, {"name": "National Organization of Circumcision Information Resource Centers (NOCIRC)", "score": 6.688, "shared_docs": 3}]');
